'use client';

import React, { useState, useMemo } from 'react';
import {
  Activity,
  AlertTriangle,
  BarChart3,
  Building2,
  Eye,
  MapPin,
  Monitor,
  RotateCw,
  Users,
  Zap,
  Settings,
  Bell,
  Shield,
  TrendingUp,
  Database,
} from 'lucide-react';
import './globals.css';
import { canManageCompany } from '@autamedica/shared';
import { SessionSync } from '@/components/SessionSync';
import { UserProvider, useUser } from '@/components/providers/UserProvider';

interface RootLayoutProps {
  children: React.ReactNode;
}

function LayoutContent({ children }: RootLayoutProps) {
  const [activeProfile, setActiveProfile] = useState('emergency');
  const [notifications, _setNotifications] = useState(3);

  // Get user data from context
  const { companyName, adminName, userMemberRole } = useUser();

  const profiles = [
    {
      id: 'emergency',
      name: 'Emergencias',
      icon: <AlertTriangle className="w-4 h-4" />,
      color: 'bg-red-600',
      textColor: 'text-red-400'
    },
    {
      id: 'normal',
      name: 'Normal',
      icon: <Monitor className="w-4 h-4" />,
      color: 'bg-blue-600',
      textColor: 'text-blue-400'
    },
    {
      id: 'analysis',
      name: 'Análisis',
      icon: <BarChart3 className="w-4 h-4" />,
      color: 'bg-purple-600',
      textColor: 'text-purple-400'
    }
  ];

  if (profiles.length === 0) {
    throw new Error('No hay perfiles configurados para el panel de compañías');
  }

  const defaultProfile = profiles[0];

  const sidebarItems = useMemo(() => {
    const allItems = [
      { id: 'overview', icon: Eye, label: 'Vista General', count: 24 },
      { id: 'crisis-map', icon: MapPin, label: 'Mapa de Crisis', badge: 'LIVE' },
      { id: 'metrics', icon: Activity, label: 'Métricas', count: 8 },
      { id: 'network', icon: Zap, label: 'Red de Respuesta' },
      { id: 'staff', icon: Users, label: 'Personal Médico', count: 156, adminOnly: true },
      { id: 'marketplace', icon: Building2, label: 'Marketplace Médico', count: 47, badge: 'HOT' },
      { id: 'facilities', icon: Building2, label: 'Instalaciones', count: 12 },
      { id: 'alerts', icon: Bell, label: 'Alertas', count: notifications },
      { id: 'reports', icon: TrendingUp, label: 'Reportes' },
      { id: 'data', icon: Database, label: 'Base de Datos' },
      { id: 'security', icon: Shield, label: 'Seguridad', adminOnly: true },
      { id: 'settings', icon: Settings, label: 'Configuración', adminOnly: true },
    ];

    if (!userMemberRole) return []; // O un skeleton/loader

    return allItems.filter(item => {
      if (!item.adminOnly) return true;
      return canManageCompany(userMemberRole);
    });
  }, [userMemberRole, notifications]);

  const currentProfile = profiles.find((profile) => profile.id === activeProfile) ?? defaultProfile;

  return (
    <html lang="es">
      <body className="bg-gray-900 text-white font-sans antialiased">
        <SessionSync />
        <div className="min-h-screen bg-gradient-to-br from-gray-900 via-red-900 to-orange-900">
          {/* Header - Crisis Management Style */}
          <div className="bg-gray-800 border-b border-red-600 px-4 py-3 flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-2">
                <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center">
                  <AlertTriangle className="w-5 h-5 text-white" />
                </div>
                <span className="text-xl font-bold text-white">
                  {companyName} Crisis Control - {adminName}
                </span>
              </div>

              {/* Profile Selector */}
              <div className="flex items-center space-x-2">
                <span className="text-gray-400 text-sm">Perfil:</span>
                <div className="flex space-x-1">
                  {profiles.map((profile) => (
                    <button
                      key={profile.id}
                      onClick={() => setActiveProfile(profile.id)}
                      className={`px-3 py-1 rounded-md text-xs font-medium transition-colors ${
                        activeProfile === profile.id
                          ? `${profile.color} text-white`
                          : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                      }`}
                    >
                      <div className="flex items-center space-x-1">
                        {profile.icon}
                        <span>{profile.name}</span>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse"></div>
                <span className="text-green-400 text-sm font-medium">SISTEMA ACTIVO</span>
              </div>
              <div className="flex items-center space-x-2">
                <span className="text-gray-400 text-sm">Estado:</span>
                <span className={`${currentProfile.textColor} font-medium text-sm`}>
                  {currentProfile.name.toUpperCase()}
                </span>
              </div>
              <div className="text-gray-400 text-sm font-mono">
                {new Date().toLocaleTimeString()}
              </div>
            </div>
          </div>

          <div className="flex h-[calc(100vh-4rem)]">
            {/* Sidebar - Crisis Control Style */}
            <div className="w-64 bg-gray-800 border-r border-gray-700 flex flex-col">
              <div className="p-4 flex-1">
                <div className="mb-6">
                  <h3 className="text-white font-semibold mb-1 text-sm uppercase tracking-wider">
                    Centro de Control
                  </h3>
                  <p className="text-gray-400 text-xs">
                    Gestión integral de crisis sanitarias
                  </p>
                </div>

                <nav className="space-y-1">
                  {sidebarItems.map((item) => {
                    const IconComponent = item.icon;
                    return (
                      <div
                        key={item.id}
                        className="flex items-center justify-between p-3 rounded-lg hover:bg-gray-700 cursor-pointer group transition-colors"
                      >
                        <div className="flex items-center space-x-3">
                          <IconComponent className="w-4 h-4 text-orange-400 group-hover:text-red-400 transition-colors" />
                          <span className="text-gray-300 group-hover:text-white text-sm transition-colors">
                            {item.label}
                          </span>
                        </div>
                        {item.count !== undefined && (
                          <span className="bg-red-600 text-white text-xs px-2 py-1 rounded-full font-medium">
                            {item.count}
                          </span>
                        )}
                        {item.badge && (
                          <span className="bg-green-500 text-white text-xs px-2 py-0.5 rounded-full font-bold animate-pulse">
                            {item.badge}
                          </span>
                        )}
                      </div>
                    );
                  })}
                </nav>
              </div>

              {/* Emergency Status */}
              <div className="p-4 border-t border-gray-700">
                <div className="bg-red-600 p-3 rounded-lg">
                  <div className="flex items-center space-x-2 mb-2">
                    <AlertTriangle className="w-4 h-4 text-white" />
                    <span className="text-white font-semibold text-sm">Estado de Emergencia</span>
                  </div>
                  <div className="text-white text-xs space-y-1">
                    <div className="flex justify-between">
                      <span>Nivel de Alerta:</span>
                      <span className="font-bold">ALTO</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Incidentes Activos:</span>
                      <span className="font-bold">3</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Personal Disponible:</span>
                      <span className="font-bold">89%</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col">
              {/* Content */}
              <div className="flex-1 bg-gray-900">
                {children}
              </div>
            </div>
          </div>

          {/* Status Bar - Crisis Control */}
          <div className="bg-red-600 px-4 py-2 flex items-center justify-between text-white text-xs">
            <div className="flex items-center space-x-6">
              <span className="flex items-center space-x-2">
                <AlertTriangle className="w-4 h-4" />
                <span className="font-semibold">{companyName} Crisis Control</span>
              </span>
              <span className="text-red-200">|</span>
              <span className="flex items-center space-x-1">
                <div className="w-2 h-2 bg-green-300 rounded-full animate-pulse"></div>
                <span>3 Incidentes Activos</span>
              </span>
              <span className="text-red-200">|</span>
              <span>Personal: 156/175 disponible</span>
              <span className="text-red-200">|</span>
              <span className="flex items-center space-x-1">
                <RotateCw className="w-3 h-3 animate-spin" />
                <span>Actualizando en tiempo real</span>
              </span>
            </div>
            <div className="flex items-center space-x-4">
              <span className="flex items-center space-x-1">
                <Zap className="w-3 h-3" />
                <span>Red de Emergencia Activa</span>
              </span>
              <span className="text-red-200">|</span>
              <span className="flex items-center space-x-1">
                <div className="w-2 h-2 bg-green-300 rounded-full"></div>
                <span>Sistemas Operativos</span>
              </span>
              <span className="text-red-200">|</span>
              <span className="font-mono">
                {new Date().toLocaleString()}
              </span>
            </div>
          </div>
        </div>
      </body>
    </html>
  );
}

export default function RootLayout({ children }: RootLayoutProps) {
  return (
    <UserProvider>
      <LayoutContent>{children}</LayoutContent>
    </UserProvider>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  Activity,
  AlertTriangle,
  Building2,
  MapPin,
  Monitor,
  Users,
  Clock,
  CheckCircle,
  XCircle,
  AlertCircle,
  Briefcase,
} from 'lucide-react';
import MarketplaceDashboard from '../components/marketplace/MarketplaceDashboard';

export default function CompaniesHomePage() {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [crisisLevel, _setCrisisLevel] = useState('HIGH');
  const [activeIncidents, _setActiveIncidents] = useState(3);
  const [activeSection, setActiveSection] = useState<'crisis' | 'marketplace'>('crisis');

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const crisisMetrics = [
    {
      title: 'Incidentes Activos',
      value: activeIncidents,
      icon: AlertTriangle,
      color: 'text-red-400',
      bgColor: 'bg-red-600/20',
      status: 'critical'
    },
    {
      title: 'Personal Disponible',
      value: '156/175',
      percentage: 89,
      icon: Users,
      color: 'text-green-400',
      bgColor: 'bg-green-600/20',
      status: 'good'
    },
    {
      title: 'Instalaciones Operativas',
      value: '11/12',
      percentage: 92,
      icon: Building2,
      color: 'text-blue-400',
      bgColor: 'bg-blue-600/20',
      status: 'good'
    },
    {
      title: 'Nivel de Alerta',
      value: crisisLevel,
      icon: Monitor,
      color: 'text-orange-400',
      bgColor: 'bg-orange-600/20',
      status: 'warning'
    }
  ];

  const recentIncidents = [
    {
      id: 1,
      type: 'Brote de gripe',
      location: 'Edificio Norte - Piso 3',
      time: '14:30',
      status: 'active',
      severity: 'high',
      affected: 12
    },
    {
      id: 2,
      type: 'Accidente laboral',
      location: 'Almacén Principal',
      time: '13:15',
      status: 'contained',
      severity: 'medium',
      affected: 1
    },
    {
      id: 3,
      type: 'Emergencia cardíaca',
      location: 'Oficinas Ejecutivas',
      time: '11:45',
      status: 'resolved',
      severity: 'critical',
      affected: 1
    }
  ];

  const facilitiesStatus = [
    { name: 'Edificio Norte', status: 'operational', capacity: 95 },
    { name: 'Edificio Sur', status: 'operational', capacity: 87 },
    { name: 'Almacén Principal', status: 'limited', capacity: 45 },
    { name: 'Centro Médico', status: 'operational', capacity: 100 },
  ];

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'operational':
        return <CheckCircle className="w-4 h-4 text-green-400" />;
      case 'limited':
        return <AlertCircle className="w-4 h-4 text-yellow-400" />;
      case 'offline':
        return <XCircle className="w-4 h-4 text-red-400" />;
      default:
        return <Monitor className="w-4 h-4 text-gray-400" />;
    }
  };

  const getIncidentStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-red-600 text-white';
      case 'contained':
        return 'bg-yellow-600 text-white';
      case 'resolved':
        return 'bg-green-600 text-white';
      default:
        return 'bg-gray-600 text-white';
    }
  };

  return (
    <div className="p-6 space-y-6">
      {/* Section Navigation */}
      <div className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => setActiveSection('crisis')}
            className={`flex items-center space-x-2 px-4 py-2 rounded-lg transition-colors ${
              activeSection === 'crisis'
                ? 'bg-gray-800 text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            <AlertTriangle className="w-5 h-5" />
            <span>Centro de Control de Crisis</span>
          </button>
          <button
            onClick={() => setActiveSection('marketplace')}
            className={`flex items-center space-x-2 px-4 py-2 rounded-lg transition-colors ${
              activeSection === 'marketplace'
                ? 'bg-gray-800 text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            <Briefcase className="w-5 h-5" />
            <span>Marketplace Médico</span>
            <span className="bg-gray-500 text-white text-xs px-2 py-1 rounded-full font-bold">HOT</span>
          </button>
        </div>
      </div>

      {/* Crisis Management Section */}
      {activeSection === 'crisis' && (
        <>
          {/* Crisis Overview Header */}
          <div className="bg-white border border-gray-200 rounded-lg p-6 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h1 className="text-2xl font-bold text-gray-800 flex items-center space-x-2">
                <AlertTriangle className="w-6 h-6 text-gray-600" />
                <span>Centro de Control de Crisis</span>
              </h1>
              <div className="flex items-center space-x-4">
                <div className="flex items-center space-x-2">
                  <div className="w-3 h-3 bg-gray-600 rounded-full animate-pulse"></div>
                  <span className="text-gray-600 font-medium">ALERTA ACTIVA</span>
                </div>
                <div className="text-gray-500 font-mono">
                  {currentTime.toLocaleTimeString()}
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
              {crisisMetrics.map((metric, index) => {
                const IconComponent = metric.icon;
                return (
                  <div key={index} className={`${metric.bgColor} border border-gray-600 rounded-lg p-4`}>
                    <div className="flex items-center justify-between mb-2">
                      <IconComponent className={`w-5 h-5 ${metric.color}`} />
                      {metric.percentage && (
                        <span className={`text-xs px-2 py-1 rounded-full ${
                          metric.percentage >= 90 ? 'bg-green-600' :
                          metric.percentage >= 70 ? 'bg-yellow-600' : 'bg-red-600'
                        } text-white`}>
                          {metric.percentage}%
                        </span>
                      )}
                    </div>
                    <div className="mb-1">
                      <span className="text-2xl font-bold text-white">{metric.value}</span>
                    </div>
                    <div className="text-xs text-gray-400">{metric.title}</div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            {/* Crisis Map Panel */}
            <div className="xl:col-span-2">
              <div className="bg-gray-800 border border-gray-600 rounded-lg p-6">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-lg font-semibold text-white flex items-center space-x-2">
                    <MapPin className="w-5 h-5 text-orange-400" />
                    <span>Mapa de Crisis en Tiempo Real</span>
                  </h2>
                  <div className="flex items-center space-x-2">
                    <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
                    <span className="text-green-400 text-sm">LIVE</span>
                  </div>
                </div>

                {/* Simulated Map Area */}
                <div className="bg-gray-900 rounded-lg h-64 flex items-center justify-center border border-gray-700">
                  <div className="text-center">
                    <MapPin className="w-16 h-16 text-orange-400 mx-auto mb-4" />
                    <h3 className="text-white text-lg font-medium mb-2">Mapa Interactivo de Instalaciones</h3>
                    <p className="text-gray-400 text-sm">Vista en tiempo real de todos los incidentes y recursos</p>
                    <div className="mt-4 flex justify-center space-x-4">
                      <div className="flex items-center space-x-1">
                        <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                        <span className="text-red-400 text-xs">Crítico</span>
                      </div>
                      <div className="flex items-center space-x-1">
                        <div className="w-3 h-3 bg-yellow-500 rounded-full"></div>
                        <span className="text-yellow-400 text-xs">Advertencia</span>
                      </div>
                      <div className="flex items-center space-x-1">
                        <div className="w-3 h-3 bg-green-500 rounded-full"></div>
                        <span className="text-green-400 text-xs">Normal</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Activity Feed */}
            <div className="bg-gray-800 border border-gray-600 rounded-lg p-6">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center space-x-2">
                <Activity className="w-5 h-5 text-blue-400" />
                <span>Actividad Reciente</span>
              </h2>

              <div className="space-y-3">
                {recentIncidents.map((incident) => (
                  <div key={incident.id} className="bg-gray-700 rounded-lg p-3 border border-gray-600">
                    <div className="flex items-start justify-between mb-2">
                      <div>
                        <h4 className="text-white font-medium text-sm">{incident.type}</h4>
                        <p className="text-gray-400 text-xs">{incident.location}</p>
                      </div>
                      <span className={`text-xs px-2 py-1 rounded-full ${getIncidentStatusColor(incident.status)}`}>
                        {incident.status.toUpperCase()}
                      </span>
                    </div>
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-gray-400 flex items-center space-x-1">
                        <Clock className="w-3 h-3" />
                        <span>{incident.time}</span>
                      </span>
                      <span className="text-gray-400">
                        {incident.affected} {incident.affected === 1 ? 'persona afectada' : 'personas afectadas'}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Facilities Status */}
          <div className="bg-gray-800 border border-gray-600 rounded-lg p-6">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center space-x-2">
              <Building2 className="w-5 h-5 text-purple-400" />
              <span>Estado de Instalaciones</span>
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {facilitiesStatus.map((facility, index) => (
                <div key={index} className="bg-gray-700 rounded-lg p-4 border border-gray-600">
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="text-white font-medium text-sm">{facility.name}</h4>
                    {getStatusIcon(facility.status)}
                  </div>
                  <div className="mb-2">
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-gray-400">Capacidad</span>
                      <span className="text-white">{facility.capacity}%</span>
                    </div>
                    <div className="w-full bg-gray-600 rounded-full h-2">
                      <div
                        className={`h-2 rounded-full ${
                          facility.capacity >= 90 ? 'bg-green-500' :
                          facility.capacity >= 70 ? 'bg-yellow-500' : 'bg-red-500'
                        }`}
                        style={{ width: `${facility.capacity}%` }}
                      ></div>
                    </div>
                  </div>
                  <div className="text-xs">
                    <span className={`capitalize ${
                      facility.status === 'operational' ? 'text-green-400' :
                      facility.status === 'limited' ? 'text-yellow-400' : 'text-red-400'
                    }`}>
                      {facility.status === 'operational' ? 'Operativo' :
                       facility.status === 'limited' ? 'Limitado' : 'Fuera de servicio'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </>
      )}

      {/* Marketplace Section */}
      {activeSection === 'marketplace' && (
        <MarketplaceDashboard />
      )}
    </div>
  );
}

'use client';

import { useEffect } from 'react';
import { createBrowserClient } from '@supabase/ssr';

/**
 * SessionSync Component
 *
 * Handles session synchronization in development when redirecting from Auth Hub.
 * In localhost, cookies don't work across different ports, so we pass tokens via URL.
 *
 * This component:
 * 1. Checks for access_token and refresh_token in URL params
 * 2. Sets them in Supabase client
 * 3. Cleans up the URL
 * 4. Allows the app to continue normally
 */
export function SessionSync() {
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const urlParams = new URLSearchParams(window.location.search);
    const accessToken = urlParams.get('access_token');
    const refreshToken = urlParams.get('refresh_token');

    if (accessToken && refreshToken) {
      const supabase = createBrowserClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
      );

      // Set the session with the tokens from URL
      supabase.auth.setSession({
        access_token: accessToken,
        refresh_token: refreshToken,
      }).then(() => {
        // Clean up URL by removing tokens
        urlParams.delete('access_token');
        urlParams.delete('refresh_token');

        const newUrl = window.location.pathname + (urlParams.toString() ? `?${urlParams.toString()}` : '');
        window.history.replaceState({}, '', newUrl);
      });
    }
  }, []);

  return null;
}

'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { usePathname } from 'next/navigation';
import { ErrorBoundary } from './ErrorBoundary';

interface CompanyLayoutContextType {
  sidebarCollapsed: boolean;
  setSidebarCollapsed: (collapsed: boolean) => void;
  currentPath: string;
  breadcrumbs: BreadcrumbItem[];
  isLoading: boolean;
  setIsLoading: (loading: boolean) => void;
}

interface BreadcrumbItem {
  label: string;
  href: string;
  isActive?: boolean;
}

const CompanyLayoutContext = createContext<CompanyLayoutContextType | undefined>(undefined);

export function useCompanyLayout() {
  const context = useContext(CompanyLayoutContext);
  if (context === undefined) {
    throw new Error('useCompanyLayout must be used within a CompanyLayoutProvider');
  }
  return context;
}

interface CompanyLayoutProviderProps {
  children: React.ReactNode;
}

export function CompanyLayoutProvider({ children }: CompanyLayoutProviderProps) {
  const pathname = usePathname();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Generate breadcrumbs based on current path
  const generateBreadcrumbs = (path: string): BreadcrumbItem[] => {
    const segments = path.split('/').filter(Boolean);
    const breadcrumbs: BreadcrumbItem[] = [
      { label: 'Inicio', href: '/' }
    ];

    let currentPath = '';
    for (let i = 0; i < segments.length; i++) {
      const segment = segments[i];
      if (!segment) continue; // Skip undefined segments

      currentPath += `/${segment}`;

      // Map route segments to human-readable labels
      const labelMap: { [key: string]: string } = {
        'dashboard': 'Centro de Control',
        'staff': 'Personal Médico',
        'patients': 'Pacientes',
        'analytics': 'Analíticas',
        'appointments': 'Citas',
        'hiring': 'Contratación',
        'network': 'Red Hospitalaria',
        'communication': 'Comunicación B2C',
        'settings': 'Configuración',
        'marketplace': 'Marketplace',
        'reports': 'Reportes',
        'profile': 'Mi Perfil'
      };

      const label = labelMap[segment] || segment.charAt(0).toUpperCase() + segment.slice(1);
      breadcrumbs.push({
        label,
        href: currentPath,
        isActive: i === segments.length - 1
      });
    }

    return breadcrumbs;
  };

  const breadcrumbs = generateBreadcrumbs(pathname);

  // Handle responsive sidebar on mobile
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1024) {
        setSidebarCollapsed(false);
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const contextValue: CompanyLayoutContextType = {
    sidebarCollapsed,
    setSidebarCollapsed,
    currentPath: pathname,
    breadcrumbs,
    isLoading,
    setIsLoading,
  };

  return (
    <CompanyLayoutContext.Provider value={contextValue}>
      <ErrorBoundary>
        {children}
      </ErrorBoundary>
    </CompanyLayoutContext.Provider>
  );
}

'use client';

import React, { Component, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';
// import { Button } from '@altamedica/ui';
// Temporary workaround for TypeScript module resolution
import { Button } from '../../../../../packages/ui/dist/index.js';
import Link from 'next/link';

import { logger } from '@autamedica/shared';
import { ensureClientEnv } from '@autamedica/shared';
interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    logger.error('Error boundary caught an error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="min-h-[400px] flex items-center justify-center p-4">
          <div className="text-center max-w-md mx-auto">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <AlertTriangle className="w-8 h-8 text-red-600" />
            </div>
            <h2 className="text-xl font-semibold text-gray-900 mb-2">
              Algo salió mal
            </h2>
            <p className="text-gray-600 mb-6">
              Ha ocurrido un error inesperado. Por favor, intenta recargar la página o vuelve al inicio.
            </p>
            <div className="space-y-3">
              <Button 
                onClick={() => window.location.reload()}
                className="w-full flex items-center justify-center gap-2"
              >
                <RefreshCw className="w-4 h-4" />
                Recargar página
              </Button>
              <Link href="/dashboard">
                <Button className="w-full flex items-center justify-center gap-2 border border-gray-300 bg-white text-gray-700 hover:bg-gray-50">
                  <Home className="w-4 h-4" />
                  Ir al inicio
                </Button>
              </Link>
            </div>
            {ensureClientEnv('NODE_ENV') === 'development' && this.state.error && (
              <details className="mt-6 text-left">
                <summary className="cursor-pointer text-sm text-gray-500 hover:text-gray-700">
                  Detalles del error (solo en desarrollo)
                </summary>
                <pre className="mt-2 p-3 bg-gray-100 rounded text-xs overflow-auto">
                  {this.state.error.stack}
                </pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

// Error fallback component for suspense boundaries
interface ErrorFallbackProps {
  error: Error;
  resetErrorBoundary: () => void;
}

export function ErrorFallback({ error: _error, resetErrorBoundary }: ErrorFallbackProps) {
  return (
    <div className="min-h-[400px] flex items-center justify-center p-4">
      <div className="text-center max-w-md mx-auto">
        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
          <AlertTriangle className="w-8 h-8 text-red-600" />
        </div>
        <h2 className="text-xl font-semibold text-gray-900 mb-2">
          Error de carga
        </h2>
        <p className="text-gray-600 mb-6">
          No se pudo cargar este componente. Por favor, intenta de nuevo.
        </p>
        <div className="space-y-3">
          <Button 
            onClick={resetErrorBoundary}
            className="w-full flex items-center justify-center gap-2"
          >
            <RefreshCw className="w-4 h-4" />
            Intentar de nuevo
          </Button>
          <Link href="/dashboard">
            <Button className="w-full flex items-center justify-center gap-2 border border-gray-300 bg-white text-gray-700 hover:bg-gray-50">
              <Home className="w-4 h-4" />
              Ir al inicio
            </Button>
          </Link>
        </div>
      </div>
    </div>
  );
}

