                ${isSelected ? 'scale-150 ring-2 ring-amber-400' : ''}
                ${isHovered ? 'scale-125' : ''}
                hover:scale-125
              `}>
                {marker.type === 'job' ? (
                  <MapPin className="w-full h-full text-white p-0.5" />
