'use client'

import { useState } from 'react'
import type { JSX } from 'react'
import {
  Brain,
  Search,
  Calendar,
  Target,
  AlertTriangle,
  CheckCircle,
  Zap,
  Stethoscope,
  Activity,
  ChevronDown,
  ChevronRight
} from 'lucide-react'
import { useAIAnalysis } from '@/hooks'
import type { DiagnosticConfidence } from '@/types/medical'

interface AIHistoryTabProps {
  patientId: string | null
}

const CONFIDENCE_CONFIG: Record<DiagnosticConfidence, {
  label: string
  color: string
  icon: React.ElementType
}> = {
  alta: {
    label: 'Alta confianza',
    color: 'bg-green-500/20 text-green-300 border-green-500/30',
    icon: CheckCircle
  },
  media: {
    label: 'Confianza media',
    color: 'bg-yellow-500/20 text-yellow-300 border-yellow-500/30',
    icon: Target
  },
  baja: {
    label: 'Baja confianza',
    color: 'bg-red-500/20 text-red-300 border-red-500/30',
    icon: AlertTriangle
  }
}

export function AIHistoryTab({ patientId }: AIHistoryTabProps): JSX.Element {
  const [searchTerm, setSearchTerm] = useState('')
  const [expandedAnalysis, setExpandedAnalysis] = useState<string | null>(null)
  const [showNewAnalysisForm, setShowNewAnalysisForm] = useState(false)

  const { analyses, loading, error, createAnalysis } = useAIAnalysis(patientId)

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getConfidenceScore = (score: number): string => {
    return `${Math.round(score * 100)}%`
  }

  const filteredAnalyses = analyses.filter(analysis =>
    searchTerm === '' ||
    analysis.primary_diagnosis.condition.toLowerCase().includes(searchTerm.toLowerCase()) ||
    analysis.input_symptoms.some(symptom =>
      symptom.toLowerCase().includes(searchTerm.toLowerCase())
    )
  )

  if (loading && analyses.length === 0) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <div className="mb-4 h-8 w-8 animate-spin rounded-full border-2 border-emerald-400 border-t-transparent mx-auto"></div>
          <p className="text-slate-400">Cargando análisis de IA...</p>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center max-w-md">
          <AlertTriangle className="h-12 w-12 text-red-400 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-slate-200 mb-2">Error al cargar análisis</h3>
          <p className="text-slate-400">{error}</p>
        </div>
      </div>
    )
  }

  if (!patientId) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <Brain className="h-16 w-16 text-slate-500 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-slate-200 mb-2">Sin paciente seleccionado</h3>
          <p className="text-slate-400">Selecciona un paciente para ver su historial de IA</p>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col bg-[#0a1525]">

      {/* Header */}
      <div className="border-b border-slate-800/60 bg-[#111f36] p-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-xl font-bold text-slate-100 flex items-center gap-2">
              <Brain className="h-6 w-6 text-purple-400" />
              Historial de Análisis IA
              <span className="rounded-full bg-purple-500/20 px-2 py-1 text-xs font-medium text-purple-300 border border-purple-500/30">
                BETA
              </span>
            </h1>
            <p className="text-sm text-slate-400">
              {filteredAnalyses.length} análisis encontrado{filteredAnalyses.length !== 1 ? 's' : ''}
            </p>
          </div>

          <button
            onClick={() => setShowNewAnalysisForm(!showNewAnalysisForm)}
            className="flex items-center gap-2 rounded-lg border border-purple-600 bg-purple-600 px-4 py-2 text-sm font-medium text-white hover:bg-purple-700 transition"
          >
            <Brain className="h-4 w-4" />
            Nuevo Análisis IA
          </button>
        </div>

        {/* Búsqueda */}
        <div className="mt-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Buscar por diagnóstico o síntomas..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full rounded-lg border border-slate-700 bg-slate-800/40 pl-10 pr-4 py-2 text-sm text-slate-100 placeholder-slate-400 focus:border-purple-500 focus:outline-none focus:ring-1 focus:ring-purple-500"
            />
          </div>
        </div>
      </div>

      {/* Contenido */}
      <div className="flex-1 overflow-y-auto p-6">
        {filteredAnalyses.length === 0 ? (
          <div className="flex h-full items-center justify-center">
            <div className="text-center">
              <Brain className="h-16 w-16 text-slate-500 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-slate-200 mb-2">
                {analyses.length === 0 ? 'Sin análisis de IA' : 'No se encontraron resultados'}
              </h3>
              <p className="text-slate-400 mb-4">
                {analyses.length === 0
                  ? 'Este paciente aún no tiene análisis realizados por IA'
                  : 'No se encontraron análisis que coincidan con la búsqueda'
                }
              </p>
              {analyses.length === 0 && (
                <button
                  onClick={() => setShowNewAnalysisForm(true)}
                  className="flex items-center gap-2 rounded-lg bg-purple-600 px-4 py-2 text-sm font-medium text-white hover:bg-purple-700 transition mx-auto"
                >
                  <Brain className="h-4 w-4" />
                  Primer Análisis IA
                </button>
              )}
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredAnalyses.map((analysis) => {
              const isExpanded = expandedAnalysis === analysis.id
              const confidenceConfig = CONFIDENCE_CONFIG[analysis.primary_diagnosis.confidence]
              const ConfidenceIcon = confidenceConfig.icon

              return (
                <div
                  key={analysis.id}
                  className="rounded-lg border border-slate-800/60 bg-[#111f36] overflow-hidden"
                >
                  {/* Header del análisis */}
                  <div className="p-4">
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                          <span className={`rounded-full px-3 py-1 text-xs font-medium border ${confidenceConfig.color}`}>
                            <ConfidenceIcon className="inline h-3 w-3 mr-1" />
                            {confidenceConfig.label}
                          </span>
                          <div className="flex items-center gap-1 text-xs text-slate-400">
                            <Calendar className="h-3 w-3" />
                            {formatDate(analysis.created_at)}
                          </div>
                          <div className="flex items-center gap-1 text-xs text-slate-400">
                            <Zap className="h-3 w-3" />
                            {analysis.processing_time_ms}ms
                          </div>
                        </div>

                        <h3 className="text-lg font-semibold text-slate-100 mb-2">
                          {analysis.primary_diagnosis.condition}
                        </h3>

                        <div className="flex items-center gap-4 text-sm text-slate-400 mb-3">
                          <div className="flex items-center gap-1">
                            <Target className="h-4 w-4" />
                            <span>Confianza: {getConfidenceScore(analysis.confidence_score)}</span>
                          </div>
                          <div className="flex items-center gap-1">
                            <Activity className="h-4 w-4" />
                            <span>Modelo: {analysis.model_version}</span>
                          </div>
                        </div>

                        {/* Síntomas de entrada */}
                        <div className="flex flex-wrap gap-2">
                          {analysis.input_symptoms.map((symptom, index) => (
                            <span
                              key={index}
                              className="rounded-lg bg-slate-800/60 px-2 py-1 text-xs text-slate-300"
                            >
                              {symptom}
                            </span>
                          ))}
                        </div>
                      </div>

                      <button
                        onClick={() => setExpandedAnalysis(isExpanded ? null : analysis.id)}
                        className="flex items-center gap-2 rounded-lg border border-slate-700 bg-slate-800/40 px-3 py-2 text-sm text-slate-300 hover:bg-slate-800/60 transition"
                      >
                        Ver detalles
                        {isExpanded ? (
                          <ChevronDown className="h-4 w-4" />
                        ) : (
                          <ChevronRight className="h-4 w-4" />
                        )}
                      </button>
                    </div>

                    {/* Descripción del diagnóstico principal */}
                    <div className="rounded-lg bg-slate-900/40 p-3">
                      <p className="text-sm text-slate-300">{analysis.primary_diagnosis.description}</p>
                      {analysis.primary_diagnosis.icd_code && (
                        <p className="text-xs text-slate-400 mt-1">
                          Código ICD: {analysis.primary_diagnosis.icd_code}
                        </p>
                      )}
                    </div>
                  </div>

                  {/* Contenido expandido */}
                  {isExpanded && (
                    <div className="border-t border-slate-800/60 bg-slate-900/40 p-4">
                      <div className="space-y-6">

                        {/* Razonamiento del diagnóstico principal */}
                        <div>
                          <h4 className="text-sm font-semibold text-slate-300 mb-2 flex items-center gap-2">
                            <Stethoscope className="h-4 w-4" />
                            Razonamiento del Diagnóstico
                          </h4>
                          <p className="text-sm text-slate-400 bg-slate-800/40 rounded-lg p-3">
                            {analysis.primary_diagnosis.reasoning}
                          </p>
                        </div>

                        {/* Diagnósticos diferenciales */}
                        {analysis.differential_diagnoses.length > 0 && (
                          <div>
                            <h4 className="text-sm font-semibold text-slate-300 mb-3">
                              Diagnósticos Diferenciales
                            </h4>
                            <div className="space-y-2">
                              {analysis.differential_diagnoses.map((diagnosis, index) => {
                                const diffConfig = CONFIDENCE_CONFIG[diagnosis.confidence]
                                const DiffIcon = diffConfig.icon

                                return (
                                  <div key={index} className="rounded-lg border border-slate-700/60 bg-slate-800/40 p-3">
                                    <div className="flex items-start justify-between mb-2">
                                      <h5 className="font-medium text-slate-200">{diagnosis.condition}</h5>
                                      <div className="flex items-center gap-2">
                                        <span className={`rounded-full px-2 py-1 text-xs font-medium border ${diffConfig.color}`}>
                                          <DiffIcon className="inline h-3 w-3 mr-1" />
                                          {getConfidenceScore(diagnosis.probability)}
                                        </span>
                                      </div>
                                    </div>
                                    <p className="text-sm text-slate-400">{diagnosis.description}</p>
                                    {diagnosis.icd_code && (
                                      <p className="text-xs text-slate-500 mt-1">ICD: {diagnosis.icd_code}</p>
                                    )}
                                  </div>
                                )
                              })}
                            </div>
                          </div>
                        )}

                        {/* Sugerencias de tratamiento */}
                        {analysis.treatment_suggestions.length > 0 && (
                          <div>
                            <h4 className="text-sm font-semibold text-slate-300 mb-3">
                              Sugerencias de Tratamiento
                            </h4>
                            <div className="space-y-2">
                              {analysis.treatment_suggestions.map((suggestion, index) => (
                                <div key={index} className="rounded-lg border border-slate-700/60 bg-slate-800/40 p-3">
                                  <div className="flex items-start justify-between mb-2">
                                    <h5 className="font-medium text-slate-200">{suggestion.treatment}</h5>
                                    <span className={`rounded-full px-2 py-1 text-xs font-medium ${
                                      suggestion.priority === 'alta' ? 'bg-red-500/20 text-red-300 border border-red-500/30' :
                                      suggestion.priority === 'media' ? 'bg-yellow-500/20 text-yellow-300 border border-yellow-500/30' :
                                      'bg-green-500/20 text-green-300 border border-green-500/30'
                                    }`}>
                                      {suggestion.priority === 'alta' ? 'Alta prioridad' :
                                       suggestion.priority === 'media' ? 'Prioridad media' : 'Baja prioridad'}
                                    </span>
                                  </div>
                                  <p className="text-sm text-slate-400 mb-2">{suggestion.details}</p>
                                  <p className="text-xs text-slate-500">Tipo: {suggestion.type.replace('_', ' ')}</p>
                                  {suggestion.contraindications.length > 0 && (
                                    <div className="mt-2 rounded-lg bg-red-500/10 border border-red-500/30 p-2">
                                      <p className="text-xs text-red-300">
                                        <AlertTriangle className="inline h-3 w-3 mr-1" />
                                        Contraindicaciones: {suggestion.contraindications.join(', ')}
                                      </p>
                                    </div>
                                  )}
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Factores de riesgo */}
                        {analysis.risk_factors.length > 0 && (
                          <div>
                            <h4 className="text-sm font-semibold text-slate-300 mb-3">
                              Factores de Riesgo Identificados
                            </h4>
                            <div className="flex flex-wrap gap-2">
                              {analysis.risk_factors.map((factor, index) => (
                                <span
                                  key={index}
                                  className="rounded-lg bg-orange-500/20 px-3 py-1 text-xs font-medium text-orange-300 border border-orange-500/30"
                                >
                                  <AlertTriangle className="inline h-3 w-3 mr-1" />
                                  {factor}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Contexto adicional */}
                        {analysis.additional_context && (
                          <div>
                            <h4 className="text-sm font-semibold text-slate-300 mb-2">
                              Contexto Adicional
                            </h4>
                            <p className="text-sm text-slate-400 bg-slate-800/40 rounded-lg p-3">
                              {analysis.additional_context}
                            </p>
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * Componente de historial médico para el portal de médicos
 */

'use client'

import { useState } from 'react'
import type { JSX } from 'react'
import {
  FileText,
  Calendar,
  Search,
  Plus,
  Eye,
  AlertTriangle,
  Stethoscope,
  ChevronDown,
  Download
} from 'lucide-react'
import { useMedicalHistory } from '@/hooks'
import type { ConsultationType } from '@/types/medical'

interface MedicalHistoryTabProps {
  patientId: string | null
}

const CONSULTATION_TYPES: { value: ConsultationType; label: string; color: string }[] = [
  { value: 'general', label: 'General', color: 'bg-blue-500/20 text-blue-300 border-blue-500/30' },
  { value: 'seguimiento', label: 'Seguimiento', color: 'bg-green-500/20 text-green-300 border-green-500/30' },
  { value: 'urgencia', label: 'Urgencia', color: 'bg-red-500/20 text-red-300 border-red-500/30' },
  { value: 'especialidad', label: 'Especialidad', color: 'bg-purple-500/20 text-purple-300 border-purple-500/30' }
]

export function MedicalHistoryTab({ patientId }: MedicalHistoryTabProps): JSX.Element {
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedType, setSelectedType] = useState<ConsultationType | ''>('')
  const [expandedRecord, setExpandedRecord] = useState<string | null>(null)

  const { records, loading, error, loadMore, hasMore } = useMedicalHistory(patientId, {
    filters: {
      consultation_type: selectedType || undefined,
      diagnosis_contains: searchTerm || undefined
    }
  })

  const getConsultationTypeInfo = (type: ConsultationType) => {
    return CONSULTATION_TYPES.find(t => t.value === type) || CONSULTATION_TYPES[0]!
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  if (loading && records.length === 0) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <div className="mb-4 h-8 w-8 animate-spin rounded-full border-2 border-emerald-400 border-t-transparent mx-auto"></div>
          <p className="text-slate-400">Cargando historial médico...</p>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center max-w-md">
          <AlertTriangle className="h-12 w-12 text-red-400 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-slate-200 mb-2">Error al cargar historial</h3>
          <p className="text-slate-400">{error}</p>
        </div>
      </div>
    )
  }

  if (!patientId) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <FileText className="h-16 w-16 text-slate-500 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-slate-200 mb-2">Sin paciente seleccionado</h3>
          <p className="text-slate-400">Selecciona un paciente para ver su historial médico</p>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col bg-[#0a1525]">

      {/* Header con controles */}
      <div className="border-b border-slate-800/60 bg-[#111f36] p-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-xl font-bold text-slate-100">Historial Médico</h1>
            <p className="text-sm text-slate-400">
              {records.length} registro{records.length !== 1 ? 's' : ''} encontrado{records.length !== 1 ? 's' : ''}
            </p>
          </div>

          <div className="flex gap-3">
            <button className="flex items-center gap-2 rounded-lg border border-emerald-600 bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-700 transition">
              <Plus className="h-4 w-4" />
              Nueva Consulta
            </button>
            <button className="flex items-center gap-2 rounded-lg border border-slate-600 bg-slate-800/40 px-4 py-2 text-sm text-slate-300 hover:bg-slate-800/60 transition">
              <Download className="h-4 w-4" />
              Exportar
            </button>
          </div>
        </div>

        {/* Filtros */}
        <div className="mt-4 flex flex-col gap-3 sm:flex-row">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Buscar por diagnóstico, síntomas..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full rounded-lg border border-slate-700 bg-slate-800/40 pl-10 pr-4 py-2 text-sm text-slate-100 placeholder-slate-400 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500"
            />
          </div>

          <select
            value={selectedType}
            onChange={(e) => setSelectedType(e.target.value as ConsultationType | '')}
            className="rounded-lg border border-slate-700 bg-slate-800/40 px-3 py-2 text-sm text-slate-100 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500"
          >
            <option value="">Todos los tipos</option>
            {CONSULTATION_TYPES.map(type => (
              <option key={type.value} value={type.value}>
                {type.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Lista de registros */}
      <div className="flex-1 overflow-y-auto p-6">
        {records.length === 0 ? (
          <div className="flex h-full items-center justify-center">
            <div className="text-center">
              <FileText className="h-16 w-16 text-slate-500 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-slate-200 mb-2">Sin registros médicos</h3>
              <p className="text-slate-400 mb-4">
                {searchTerm || selectedType
                  ? 'No se encontraron registros con los filtros aplicados'
                  : 'Este paciente aún no tiene registros médicos'
                }
              </p>
              <button className="flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-700 transition mx-auto">
                <Plus className="h-4 w-4" />
                Crear Primera Consulta
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {records.map((record) => {
              const typeInfo = getConsultationTypeInfo(record.consultation_type)
              const isExpanded = expandedRecord === record.id

              return (
                <div
                  key={record.id}
                  className="rounded-lg border border-slate-800/60 bg-[#111f36] overflow-hidden"
                >
                  {/* Header del registro */}
                  <div className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                          <span className={`rounded-full px-3 py-1 text-xs font-medium border ${typeInfo.color}`}>
                            {typeInfo.label}
                          </span>
                          <div className="flex items-center gap-1 text-xs text-slate-400">
                            <Calendar className="h-3 w-3" />
                            {formatDate(record.consultation_date)}
                          </div>
                        </div>

                        <h3 className="text-lg font-semibold text-slate-100 mb-2">
                          {record.chief_complaint}
                        </h3>

                        <div className="flex items-center gap-4 text-sm text-slate-400">
                          <div className="flex items-center gap-1">
                            <Stethoscope className="h-4 w-4" />
                            <span>Diagnóstico: {record.diagnosis}</span>
                          </div>
                        </div>
                      </div>

                      <button
                        onClick={() => setExpandedRecord(isExpanded ? null : record.id)}
                        className="flex items-center gap-2 rounded-lg border border-slate-700 bg-slate-800/40 px-3 py-2 text-sm text-slate-300 hover:bg-slate-800/60 transition"
                      >
                        <Eye className="h-4 w-4" />
                        {isExpanded ? 'Ocultar' : 'Ver detalles'}
                        <ChevronDown className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                      </button>
                    </div>
                  </div>

                  {/* Contenido expandido */}
                  {isExpanded && (
                    <div className="border-t border-slate-800/60 bg-slate-900/40 p-4">
                      <div className="grid gap-4 lg:grid-cols-2">
                        <div>
                          <h4 className="text-sm font-semibold text-slate-300 mb-2">Síntomas</h4>
                          <div className="flex flex-wrap gap-2">
                            {record.symptoms.map((symptom, index) => (
                              <span
                                key={index}
                                className="rounded-lg bg-slate-800 px-2 py-1 text-xs text-slate-300"
                              >
                                {symptom}
                              </span>
                            ))}
                          </div>
                        </div>

                        <div>
                          <h4 className="text-sm font-semibold text-slate-300 mb-2">Plan de Tratamiento</h4>
                          <p className="text-sm text-slate-400">{record.treatment_plan}</p>
                        </div>

                        {record.follow_up_instructions && (
                          <div className="lg:col-span-2">
                            <h4 className="text-sm font-semibold text-slate-300 mb-2">Instrucciones de Seguimiento</h4>
                            <p className="text-sm text-slate-400">{record.follow_up_instructions}</p>
                          </div>
                        )}

                        {record.attachments.length > 0 && (
                          <div className="lg:col-span-2">
                            <h4 className="text-sm font-semibold text-slate-300 mb-2">Archivos Adjuntos</h4>
                            <div className="space-y-2">
                              {record.attachments.map((attachment) => (
                                <div
                                  key={attachment.id}
                                  className="flex items-center gap-3 rounded-lg border border-slate-700 bg-slate-800/40 p-3"
                                >
                                  <FileText className="h-4 w-4 text-slate-400" />
                                  <div className="flex-1">
                                    <p className="text-sm font-medium text-slate-300">{attachment.file_name}</p>
                                    <p className="text-xs text-slate-400">
                                      {(attachment.file_size / 1024).toFixed(1)} KB • {attachment.description}
                                    </p>
                                  </div>
                                  <button className="rounded-lg border border-slate-600 bg-slate-800/40 px-3 py-1 text-xs text-slate-300 hover:bg-slate-800/60 transition">
                                    Descargar
                                  </button>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              )
            })}

            {/* Botón cargar más */}
            {hasMore && (
              <div className="text-center pt-4">
                <button
                  onClick={loadMore}
                  disabled={loading}
                  className="rounded-lg border border-slate-600 bg-slate-800/40 px-6 py-2 text-sm text-slate-300 hover:bg-slate-800/60 transition disabled:opacity-50"
                >
                  {loading ? 'Cargando...' : 'Cargar más registros'}
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * Componente de prescripciones para el portal de médicos
 */

'use client'

import { useState } from 'react'
import type { JSX } from 'react'
import {
  Pill,
  Plus,
  Search,
  Calendar,
  Clock,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Pause,
  Edit3,
  Eye
} from 'lucide-react'
import { usePrescriptions } from '@/hooks'
import type { PrescriptionStatus } from '@/types/medical'

interface PrescriptionsTabProps {
  patientId: string | null
}

const STATUS_CONFIG: Record<PrescriptionStatus, {
  label: string
  icon: React.ElementType
  color: string
}> = {
  activa: {
    label: 'Activa',
    icon: CheckCircle,
    color: 'bg-green-500/20 text-green-300 border-green-500/30'
  },
  completada: {
    label: 'Completada',
    icon: CheckCircle,
    color: 'bg-blue-500/20 text-blue-300 border-blue-500/30'
  },
  cancelada: {
    label: 'Cancelada',
    icon: XCircle,
    color: 'bg-red-500/20 text-red-300 border-red-500/30'
  },
  pausada: {
    label: 'Pausada',
    icon: Pause,
    color: 'bg-yellow-500/20 text-yellow-300 border-yellow-500/30'
  }
}

export function PrescriptionsTab({ patientId }: PrescriptionsTabProps): JSX.Element {
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedStatus, setSelectedStatus] = useState<PrescriptionStatus | ''>('')
  const [showActiveOnly, setShowActiveOnly] = useState(false)

  const { prescriptions, loading, error, addPrescription, updatePrescription } = usePrescriptions(patientId, {
    filters: {
      medication_name: searchTerm || undefined,
      status: selectedStatus || undefined,
      active_only: showActiveOnly
    }
  })

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    })
  }

  const getDaysRemaining = (endDate: string | null): number | null => {
    if (!endDate) return null

    const end = new Date(endDate)
    const today = new Date()
    const diffTime = end.getTime() - today.getTime()
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24))

    return diffDays
  }

  const isExpiringSoon = (endDate: string | null): boolean => {
    const daysRemaining = getDaysRemaining(endDate)
    return daysRemaining !== null && daysRemaining <= 7 && daysRemaining >= 0
  }

  if (loading && prescriptions.length === 0) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <div className="mb-4 h-8 w-8 animate-spin rounded-full border-2 border-emerald-400 border-t-transparent mx-auto"></div>
          <p className="text-slate-400">Cargando prescripciones...</p>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center max-w-md">
          <AlertTriangle className="h-12 w-12 text-red-400 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-slate-200 mb-2">Error al cargar prescripciones</h3>
          <p className="text-slate-400">{error}</p>
        </div>
      </div>
    )
  }

  if (!patientId) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <Pill className="h-16 w-16 text-slate-500 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-slate-200 mb-2">Sin paciente seleccionado</h3>
          <p className="text-slate-400">Selecciona un paciente para ver sus prescripciones</p>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col bg-[#0a1525]">

      {/* Header con controles */}
      <div className="border-b border-slate-800/60 bg-[#111f36] p-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-xl font-bold text-slate-100">Prescripciones</h1>
            <p className="text-sm text-slate-400">
              {prescriptions.length} prescripción{prescriptions.length !== 1 ? 'es' : ''} encontrada{prescriptions.length !== 1 ? 's' : ''}
            </p>
          </div>

          <button className="flex items-center gap-2 rounded-lg border border-emerald-600 bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-700 transition">
            <Plus className="h-4 w-4" />
            Nueva Prescripción
          </button>
        </div>

        {/* Filtros */}
        <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-center">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Buscar medicamento..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full rounded-lg border border-slate-700 bg-slate-800/40 pl-10 pr-4 py-2 text-sm text-slate-100 placeholder-slate-400 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500"
            />
          </div>

          <select
            value={selectedStatus}
            onChange={(e) => setSelectedStatus(e.target.value as PrescriptionStatus | '')}
            className="rounded-lg border border-slate-700 bg-slate-800/40 px-3 py-2 text-sm text-slate-100 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500"
          >
            <option value="">Todos los estados</option>
            {Object.entries(STATUS_CONFIG).map(([status, config]) => (
              <option key={status} value={status}>
                {config.label}
              </option>
            ))}
          </select>

          <label className="flex items-center gap-2 text-sm text-slate-300">
            <input
              type="checkbox"
              checked={showActiveOnly}
              onChange={(e) => setShowActiveOnly(e.target.checked)}
              className="rounded border-slate-600 bg-slate-800 text-emerald-600 focus:ring-emerald-500"
            />
            Solo activas
          </label>
        </div>
      </div>

      {/* Lista de prescripciones */}
      <div className="flex-1 overflow-y-auto p-6">
        {prescriptions.length === 0 ? (
          <div className="flex h-full items-center justify-center">
            <div className="text-center">
              <Pill className="h-16 w-16 text-slate-500 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-slate-200 mb-2">Sin prescripciones</h3>
              <p className="text-slate-400 mb-4">
                {searchTerm || selectedStatus || showActiveOnly
                  ? 'No se encontraron prescripciones con los filtros aplicados'
                  : 'Este paciente aún no tiene prescripciones'
                }
              </p>
              <button className="flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-700 transition mx-auto">
                <Plus className="h-4 w-4" />
                Crear Primera Prescripción
              </button>
            </div>
          </div>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {prescriptions.map((prescription) => {
              const statusConfig = STATUS_CONFIG[prescription.status]
              const StatusIcon = statusConfig.icon
              const daysRemaining = getDaysRemaining(prescription.end_date)
              const expiringSoon = isExpiringSoon(prescription.end_date)

              return (
                <div
                  key={prescription.id}
                  className={`rounded-lg border border-slate-800/60 bg-[#111f36] p-4 ${
                    expiringSoon ? 'ring-2 ring-orange-500/50' : ''
                  }`}
                >
                  {/* Header */}
                  <div className="flex items-start justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <Pill className="h-5 w-5 text-emerald-400" />
                      <span className={`rounded-full px-2 py-1 text-xs font-medium border ${statusConfig.color}`}>
                        <StatusIcon className="inline h-3 w-3 mr-1" />
                        {statusConfig.label}
                      </span>
                    </div>

                    <div className="flex items-center gap-1">
                      <button className="rounded-lg border border-slate-700 bg-slate-800/40 p-1.5 text-slate-300 hover:bg-slate-800/60 transition">
                        <Edit3 className="h-3 w-3" />
                      </button>
                      <button className="rounded-lg border border-slate-700 bg-slate-800/40 p-1.5 text-slate-300 hover:bg-slate-800/60 transition">
                        <Eye className="h-3 w-3" />
                      </button>
                    </div>
                  </div>

                  {/* Medicamento */}
                  <div className="mb-3">
                    <h3 className="text-lg font-semibold text-slate-100 mb-1">
                      {prescription.medication_name}
                    </h3>
                    <p className="text-sm text-slate-400">{prescription.dosage}</p>
                  </div>

                  {/* Frecuencia y duración */}
                  <div className="space-y-2 mb-4">
                    <div className="flex items-center gap-2 text-sm">
                      <Clock className="h-4 w-4 text-slate-400" />
                      <span className="text-slate-300">{prescription.frequency}</span>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <Calendar className="h-4 w-4 text-slate-400" />
                      <span className="text-slate-300">{prescription.duration}</span>
                    </div>
                  </div>

                  {/* Fechas */}
                  <div className="border-t border-slate-800/60 pt-3">
                    <div className="grid grid-cols-2 gap-2 text-xs">
                      <div>
                        <p className="text-slate-400">Inicio</p>
                        <p className="text-slate-300">{formatDate(prescription.start_date)}</p>
                      </div>
                      <div>
                        <p className="text-slate-400">Fin</p>
                        <p className="text-slate-300">
                          {prescription.end_date ? formatDate(prescription.end_date) : 'Indefinido'}
                        </p>
                      </div>
                    </div>

                    {daysRemaining !== null && (
                      <div className="mt-2">
                        {daysRemaining > 0 ? (
                          <p className={`text-xs ${expiringSoon ? 'text-orange-300' : 'text-slate-400'}`}>
                            {expiringSoon && <AlertTriangle className="inline h-3 w-3 mr-1" />}
                            {daysRemaining} día{daysRemaining !== 1 ? 's' : ''} restante{daysRemaining !== 1 ? 's' : ''}
                          </p>
                        ) : daysRemaining === 0 ? (
                          <p className="text-xs text-orange-300">
                            <AlertTriangle className="inline h-3 w-3 mr-1" />
                            Expira hoy
                          </p>
                        ) : (
                          <p className="text-xs text-red-300">
                            Expiró hace {Math.abs(daysRemaining)} día{Math.abs(daysRemaining) !== 1 ? 's' : ''}
                          </p>
                        )}
                      </div>
                    )}
                  </div>

                  {/* Instrucciones */}
                  {prescription.instructions && (
                    <div className="mt-3 pt-3 border-t border-slate-800/60">
                      <p className="text-xs text-slate-400">Instrucciones:</p>
                      <p className="text-xs text-slate-300 mt-1 leading-relaxed">
                        {prescription.instructions}
                      </p>
                    </div>
                  )}

                  {/* Advertencias */}
                  {prescription.side_effects_warning && (
                    <div className="mt-2 rounded-lg bg-yellow-500/10 border border-yellow-500/30 p-2">
                      <p className="text-xs text-yellow-300 flex items-start gap-1">
                        <AlertTriangle className="h-3 w-3 mt-0.5 flex-shrink-0" />
                        {prescription.side_effects_warning}
                      </p>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import React, { useState, useCallback } from 'react';
import { DoctorInsert, DoctorEducation, MedicalCertification, WeeklySchedule } from '@autamedica/types';
import { LicenseValidationStep } from './LicenseValidationStep';
import { SpecialtySelectionStep } from './SpecialtySelectionStep';
import { EducationCertificationStep } from './EducationCertificationStep';
import { ScheduleSetupStep } from './ScheduleSetupStep';
import { ProfileCompletionStep } from './ProfileCompletionStep';

interface DoctorOnboardingWizardProps {
  userId: string;
  onComplete?: (doctorProfile: DoctorInsert) => void;
  onCancel?: () => void;
}

export type OnboardingStep =
  | 'license'
  | 'specialty'
  | 'education'
  | 'schedule'
  | 'profile'
  | 'complete';

export interface OnboardingData {
  // Paso 1: Licencia médica
  license_number: string;
  license_valid: boolean;

  // Paso 2: Especialidad
  specialty: string;
  subspecialty?: string;
  years_experience: number;

  // Paso 3: Educación y certificaciones
  education: DoctorEducation[];
  certifications: MedicalCertification[];

  // Paso 4: Horarios
  schedule: WeeklySchedule;
  consultation_fee?: number;
  accepted_insurance: string[];

  // Paso 5: Perfil final
  bio: string;
  languages: string[];
  phone?: string;
}

const STEPS: OnboardingStep[] = ['license', 'specialty', 'education', 'schedule', 'profile'];

export function DoctorOnboardingWizard({
  userId,
  onComplete,
  onCancel
}: DoctorOnboardingWizardProps) {
  const [currentStep, setCurrentStep] = useState<OnboardingStep>('license');
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<OnboardingData>>({
    education: [],
    certifications: [],
    schedule: {},
    accepted_insurance: [],
    languages: ['Spanish'],
    years_experience: 0
  });

  const updateFormData = useCallback((updates: Partial<OnboardingData>) => {
    setFormData(prev => ({ ...prev, ...updates }));
    setError(null);
  }, []);

  const goToNextStep = useCallback(() => {
    const nextIndex = currentStepIndex + 1;
    if (nextIndex < STEPS.length) {
      setCurrentStepIndex(nextIndex);
      setCurrentStep(STEPS[nextIndex]);
    } else {
      handleComplete();
    }
  }, [currentStepIndex]);

  const goToPreviousStep = useCallback(() => {
    const prevIndex = currentStepIndex - 1;
    if (prevIndex >= 0) {
      setCurrentStepIndex(prevIndex);
      setCurrentStep(STEPS[prevIndex]);
    }
  }, [currentStepIndex]);

  const handleComplete = async () => {
    try {
      setIsSubmitting(true);
      setError(null);

      // Validar que tenemos todos los datos necesarios
      if (!formData.license_number || !formData.specialty) {
        throw new Error('Faltan datos obligatorios: licencia médica y especialidad');
      }

      const doctorProfile: DoctorInsert = {
        user_id: userId,
        license_number: formData.license_number,
        specialty: formData.specialty,
        subspecialty: formData.subspecialty || null,
        years_experience: formData.years_experience || 0,
        education: formData.education || [],
        certifications: formData.certifications || [],
        schedule: formData.schedule || {},
        consultation_fee: formData.consultation_fee || null,
        accepted_insurance: formData.accepted_insurance || [],
        bio: formData.bio || '',
        languages: formData.languages || ['Spanish'],
        active: true
      };

      // Llamar API para crear perfil
      const response = await fetch('/api/profiles/doctors', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(doctorProfile)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Error al crear perfil de doctor');
      }

      const result = await response.json();

      // Notificar completación
      onComplete?.(doctorProfile);

      setCurrentStep('complete');

    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getStepTitle = (step: OnboardingStep): string => {
    switch (step) {
      case 'license': return 'Validación de Licencia Médica';
      case 'specialty': return 'Especialidad Médica';
      case 'education': return 'Educación y Certificaciones';
      case 'schedule': return 'Horarios y Consultas';
      case 'profile': return 'Perfil Profesional';
      case 'complete': return 'Perfil Completado';
      default: return 'Configuración';
    }
  };

  const renderCurrentStep = () => {
    switch (currentStep) {
      case 'license':
        return (
          <LicenseValidationStep
            licenseNumber={formData.license_number || ''}
            onUpdate={(license_number, license_valid) =>
              updateFormData({ license_number, license_valid })
            }
            onNext={goToNextStep}
            onCancel={onCancel}
          />
        );

      case 'specialty':
        return (
          <SpecialtySelectionStep
            specialty={formData.specialty || ''}
            subspecialty={formData.subspecialty}
            yearsExperience={formData.years_experience || 0}
            onUpdate={(specialty, subspecialty, years_experience) =>
              updateFormData({ specialty, subspecialty, years_experience })
            }
            onNext={goToNextStep}
            onBack={goToPreviousStep}
          />
        );

      case 'education':
        return (
          <EducationCertificationStep
            education={formData.education || []}
            certifications={formData.certifications || []}
            onUpdate={(education, certifications) =>
              updateFormData({ education, certifications })
            }
            onNext={goToNextStep}
            onBack={goToPreviousStep}
          />
        );

      case 'schedule':
        return (
          <ScheduleSetupStep
            schedule={formData.schedule || {}}
            consultationFee={formData.consultation_fee}
            acceptedInsurance={formData.accepted_insurance || []}
            onUpdate={(schedule, consultation_fee, accepted_insurance) =>
              updateFormData({ schedule, consultation_fee, accepted_insurance })
            }
            onNext={goToNextStep}
            onBack={goToPreviousStep}
          />
        );

      case 'profile':
        return (
          <ProfileCompletionStep
            bio={formData.bio || ''}
            languages={formData.languages || ['Spanish']}
            onUpdate={(bio, languages) =>
              updateFormData({ bio, languages })
            }
            onComplete={handleComplete}
            onBack={goToPreviousStep}
            isSubmitting={isSubmitting}
          />
        );

      case 'complete':
        return (
          <div className="text-center py-12">
            <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-6">
              <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <h2 className="text-2xl font-bold text-gray-900 mb-4">
              ¡Perfil de Doctor Completado!
            </h2>
            <p className="text-gray-600 mb-6">
              Tu perfil profesional ha sido creado exitosamente. Ahora puedes comenzar a atender pacientes.
            </p>
            <button
              onClick={() => window.location.reload()}
              className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 transition-colors"
            >
              Ir al Dashboard
            </button>
          </div>
        );

      default:
        return <div>Paso no encontrado</div>;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-3xl mx-auto px-4">
        {/* Header con progreso */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-2xl font-bold text-gray-900">
              Configuración de Perfil Médico
            </h1>
            <span className="text-sm text-gray-500">
              Paso {currentStepIndex + 1} de {STEPS.length}
            </span>
          </div>

          {/* Barra de progreso */}
          <div className="w-full bg-gray-200 rounded-full h-2 mb-4">
            <div
              className="bg-blue-600 h-2 rounded-full transition-all duration-300"
              style={{ width: `${((currentStepIndex + 1) / STEPS.length) * 100}%` }}
            />
          </div>

          <h2 className="text-lg font-semibold text-gray-800">
            {getStepTitle(currentStep)}
          </h2>
        </div>

        {/* Contenido del paso actual */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
              <div className="flex">
                <svg className="w-5 h-5 text-red-400 mr-2 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <p className="text-red-800 text-sm">{error}</p>
              </div>
            </div>
          )}

          {renderCurrentStep()}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { DoctorEducation, MedicalCertification } from '@autamedica/types';

interface EducationCertificationStepProps {
  education: DoctorEducation[];
  certifications: MedicalCertification[];
  onUpdate: (education: DoctorEducation[], certifications: MedicalCertification[]) => void;
  onNext: () => void;
  onBack: () => void;
}

export function EducationCertificationStep({
  education,
  certifications,
  onUpdate,
  onNext,
  onBack
}: EducationCertificationStepProps) {
  const [educationList, setEducationList] = useState<DoctorEducation[]>(education);
  const [certificationsList, setCertificationsList] = useState<MedicalCertification[]>(certifications);

  const addEducation = () => {
    const newEducation: DoctorEducation = {
      institution: '',
      degree: '',
      year: new Date().getFullYear(),
      specialization: ''
    };
    const updated = [...educationList, newEducation];
    setEducationList(updated);
    onUpdate(updated, certificationsList);
  };

  const updateEducation = (index: number, field: keyof DoctorEducation, value: string | number) => {
    const updated = educationList.map((edu, i) =>
      i === index ? { ...edu, [field]: value } : edu
    );
    setEducationList(updated);
    onUpdate(updated, certificationsList);
  };

  const removeEducation = (index: number) => {
    const updated = educationList.filter((_, i) => i !== index);
    setEducationList(updated);
    onUpdate(updated, certificationsList);
  };

  const addCertification = () => {
    const newCertification: MedicalCertification = {
      name: '',
      issuer: '',
      date_issued: new Date().toISOString().split('T')[0],
      certificate_number: ''
    };
    const updated = [...certificationsList, newCertification];
    setCertificationsList(updated);
    onUpdate(educationList, updated);
  };

  const updateCertification = (index: number, field: keyof MedicalCertification, value: string) => {
    const updated = certificationsList.map((cert, i) =>
      i === index ? { ...cert, [field]: value } : cert
    );
    setCertificationsList(updated);
    onUpdate(educationList, updated);
  };

  const removeCertification = (index: number) => {
    const updated = certificationsList.filter((_, i) => i !== index);
    setCertificationsList(updated);
    onUpdate(educationList, updated);
  };

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">
          Educación y Certificaciones
        </h3>
        <p className="text-gray-600">
          Agrega tu formación académica y certificaciones profesionales para generar confianza en los pacientes.
        </p>
      </div>

      {/* Sección de Educación */}
      <div>
        <div className="flex justify-between items-center mb-4">
          <h4 className="text-md font-medium text-gray-900">Educación Médica</h4>
          <button
            onClick={addEducation}
            className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            + Agregar
          </button>
        </div>

        {educationList.map((edu, index) => (
          <div key={index} className="border border-gray-200 rounded-lg p-4 mb-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Institución
                </label>
                <input
                  type="text"
                  value={edu.institution}
                  onChange={(e) => updateEducation(index, 'institution', e.target.value)}
                  placeholder="Universidad de Buenos Aires"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Título/Grado
                </label>
                <input
                  type="text"
                  value={edu.degree}
                  onChange={(e) => updateEducation(index, 'degree', e.target.value)}
                  placeholder="Médico"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Año de Graduación
                </label>
                <select
                  value={edu.year}
                  onChange={(e) => updateEducation(index, 'year', parseInt(e.target.value))}
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                >
                  {Array.from({ length: 50 }, (_, i) => new Date().getFullYear() - i).map(year => (
                    <option key={year} value={year}>{year}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Especialización (Opcional)
                </label>
                <input
                  type="text"
                  value={edu.specialization || ''}
                  onChange={(e) => updateEducation(index, 'specialization', e.target.value)}
                  placeholder="Medicina Interna"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <button
              onClick={() => removeEducation(index)}
              className="mt-2 text-red-600 text-sm hover:text-red-800"
            >
              Eliminar educación
            </button>
          </div>
        ))}

        {educationList.length === 0 && (
          <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
            <p className="text-gray-500">No has agregado educación médica</p>
            <button
              onClick={addEducation}
              className="mt-2 text-blue-600 hover:text-blue-800"
            >
              Agregar tu primera educación
            </button>
          </div>
        )}
      </div>

      {/* Sección de Certificaciones */}
      <div>
        <div className="flex justify-between items-center mb-4">
          <h4 className="text-md font-medium text-gray-900">Certificaciones Profesionales</h4>
          <button
            onClick={addCertification}
            className="px-3 py-1 text-sm bg-green-600 text-white rounded hover:bg-green-700"
          >
            + Agregar
          </button>
        </div>

        {certificationsList.map((cert, index) => (
          <div key={index} className="border border-gray-200 rounded-lg p-4 mb-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Nombre de la Certificación
                </label>
                <input
                  type="text"
                  value={cert.name}
                  onChange={(e) => updateCertification(index, 'name', e.target.value)}
                  placeholder="Certificación en Cardiología"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
