                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Número de Certificado (Opcional)
                </label>
                <input
                  type="text"
                  value={cert.certificate_number || ''}
                  onChange={(e) => updateCertification(index, 'certificate_number', e.target.value)}
                  placeholder="CERT-2024-001"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Fecha de Vencimiento (Opcional)
                </label>
                <input
                  type="date"
                  value={cert.expiry_date?.split('T')[0] || ''}
                  onChange={(e) => updateCertification(index, 'expiry_date', e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <button
              onClick={() => removeCertification(index)}
              className="mt-2 text-red-600 text-sm hover:text-red-800"
            >
              Eliminar certificación
            </button>
          </div>
        ))}

        {certificationsList.length === 0 && (
          <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
            <p className="text-gray-500">No has agregado certificaciones</p>
            <button
              onClick={addCertification}
              className="mt-2 text-green-600 hover:text-green-800"
            >
              Agregar tu primera certificación
            </button>
          </div>
        )}
      </div>

      {/* Información */}
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
        <div className="flex">
          <svg className="w-5 h-5 text-yellow-400 mr-2 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <p className="text-yellow-800 text-sm">
            <strong>Tip:</strong> Agregar tu educación y certificaciones ayuda a generar confianza en los pacientes.
            Puedes saltar este paso y agregar esta información más tarde desde tu perfil.
          </p>
        </div>
      </div>

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onBack}
          className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
        >
          Atrás
        </button>

        <button
          onClick={onNext}
          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          Continuar
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';

interface LicenseValidationStepProps {
  licenseNumber: string;
  onUpdate: (licenseNumber: string, isValid: boolean) => void;
  onNext: () => void;
  onCancel?: () => void;
}

const ARGENTINE_PROVINCES = [
  'Buenos Aires', 'CABA', 'Catamarca', 'Chaco', 'Chubut', 'Córdoba',
  'Corrientes', 'Entre Ríos', 'Formosa', 'Jujuy', 'La Pampa', 'La Rioja',
  'Mendoza', 'Misiones', 'Neuquén', 'Río Negro', 'Salta', 'San Juan',
  'San Luis', 'Santa Cruz', 'Santa Fe', 'Santiago del Estero',
  'Tierra del Fuego', 'Tucumán'
] as const;

type Province = typeof ARGENTINE_PROVINCES[number];

export function LicenseValidationStep({
  licenseNumber,
  onUpdate,
  onNext,
  onCancel
}: LicenseValidationStepProps) {
  const [license, setLicense] = useState(licenseNumber);
  const [selectedProvince, setSelectedProvince] = useState<Province | ''>('');
  const [isValidating, setIsValidating] = useState(false);
  const [validationResult, setValidationResult] = useState<{
    isValid: boolean;
    message: string;
    doctorInfo?: {
      name: string;
      specialty: string;
      status: string;
    };
  } | null>(null);

  // Validar formato de licencia según provincia
  const validateLicenseFormat = (licenseNum: string, province: string): boolean => {
    if (!licenseNum || !province) return false;

    // Formato básico: números de 4-8 dígitos
    const basicPattern = /^\d{4,8}$/;

    // Formato específico por provincia (ejemplos)
    const provincePatterns: Record<string, RegExp> = {
      'Buenos Aires': /^MP\d{4,6}$|^\d{4,6}$/i,
      'CABA': /^MN\d{4,6}$|^\d{4,6}$/i,
      'Córdoba': /^(MP|MN)\d{4,6}$|^\d{4,6}$/i,
      'Santa Fe': /^SF\d{4,6}$|^\d{4,6}$/i,
      'Mendoza': /^MD\d{4,6}$|^\d{4,6}$/i,
    };

    const pattern = provincePatterns[province] || basicPattern;
    return pattern.test(licenseNum);
  };

  // Simular validación con ENACOM/REFEPS (en producción sería API real)
  const validateLicenseWithRegistry = async (licenseNum: string, province: string) => {
    setIsValidating(true);
    setValidationResult(null);

    try {
      // Simular delay de API
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Simular validación (en producción sería llamada a API de ENACOM)
      const isValidFormat = validateLicenseFormat(licenseNum, province);

      if (!isValidFormat) {
        setValidationResult({
          isValid: false,
          message: `Formato de licencia inválido para ${province}. Verifica el número ingresado.`
        });
        return;
      }

      // Simular diferentes resultados para demo
      const mockResults = [
        {
          isValid: true,
          message: 'Licencia médica verificada exitosamente',
          doctorInfo: {
            name: 'Dr. Juan Pérez',
            specialty: 'Medicina Interna',
            status: 'Activa'
          }
        },
        {
          isValid: false,
          message: 'Licencia no encontrada en el registro nacional. Verifica los datos.'
        },
        {
          isValid: false,
          message: 'Licencia encontrada pero está suspendida. Contacta al colegio médico.'
        }
      ];

      // Para demo, usar primer resultado (válido) si la licencia tiene más de 4 dígitos
      const result = licenseNum.length >= 5 ? mockResults[0] : mockResults[1];

      setValidationResult(result);
      onUpdate(licenseNum, result.isValid);

    } catch (error) {
      setValidationResult({
        isValid: false,
        message: 'Error al validar licencia. Intenta nuevamente.'
      });
    } finally {
      setIsValidating(false);
    }
  };

  const handleLicenseChange = (value: string) => {
    setLicense(value);
    setValidationResult(null);
    if (value !== licenseNumber) {
      onUpdate(value, false);
    }
  };

  const handleValidate = () => {
    if (!license.trim()) {
      setValidationResult({
        isValid: false,
        message: 'Por favor ingresa tu número de licencia médica'
      });
      return;
    }

    if (!selectedProvince) {
      setValidationResult({
        isValid: false,
        message: 'Por favor selecciona la provincia donde está registrada tu licencia'
      });
      return;
    }

    validateLicenseWithRegistry(license.trim(), selectedProvince);
  };

  const canProceed = validationResult?.isValid === true;

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">
          Validación de Licencia Médica
        </h3>
        <p className="text-gray-600">
          Para verificar tu identidad profesional, necesitamos validar tu licencia médica
          con el registro nacional (ENACOM/REFEPS).
        </p>
      </div>

      <div className="space-y-4">
        {/* Provincia */}
        <div>
          <label htmlFor="province" className="block text-sm font-medium text-gray-700 mb-2">
            Provincia de Registro
          </label>
          <select
            id="province"
            value={selectedProvince}
            onChange={(e) => setSelectedProvince(e.target.value as Province)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            disabled={isValidating}
          >
            <option value="">Selecciona una provincia</option>
            {ARGENTINE_PROVINCES.map(province => (
              <option key={province} value={province}>
                {province}
              </option>
            ))}
          </select>
        </div>

        {/* Número de licencia */}
        <div>
          <label htmlFor="license" className="block text-sm font-medium text-gray-700 mb-2">
            Número de Licencia Médica
          </label>
          <input
            type="text"
            id="license"
            value={license}
            onChange={(e) => handleLicenseChange(e.target.value)}
            placeholder="Ej: MP12345, 123456"
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            disabled={isValidating}
          />
          <p className="text-xs text-gray-500 mt-1">
            Ingresa tu número de matrícula profesional tal como aparece en tu documento
          </p>
        </div>

        {/* Botón de validación */}
        <button
          onClick={handleValidate}
          disabled={isValidating || !license.trim() || !selectedProvince}
          className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
        >
          {isValidating ? (
            <>
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
              </svg>
              Validando con ENACOM...
            </>
          ) : (
            'Validar Licencia Médica'
          )}
        </button>
      </div>

      {/* Resultado de validación */}
      {validationResult && (
        <div className={`p-4 rounded-lg ${
          validationResult.isValid
            ? 'bg-green-50 border border-green-200'
            : 'bg-red-50 border border-red-200'
        }`}>
          <div className="flex">
            {validationResult.isValid ? (
              <svg className="w-5 h-5 text-green-400 mr-2 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            ) : (
              <svg className="w-5 h-5 text-red-400 mr-2 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            )}
            <div>
              <p className={`text-sm font-medium ${
                validationResult.isValid ? 'text-green-800' : 'text-red-800'
              }`}>
                {validationResult.message}
              </p>
              {validationResult.doctorInfo && (
                <div className="mt-2 text-sm text-green-700">
                  <p><strong>Nombre:</strong> {validationResult.doctorInfo.name}</p>
                  <p><strong>Especialidad:</strong> {validationResult.doctorInfo.specialty}</p>
                  <p><strong>Estado:</strong> {validationResult.doctorInfo.status}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onCancel}
          className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
        >
          Cancelar
        </button>

        <button
          onClick={onNext}
          disabled={!canProceed}
          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          Continuar
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';

interface ProfileCompletionStepProps {
  bio: string;
  languages: string[];
  onUpdate: (bio: string, languages: string[]) => void;
  onComplete: () => void;
  onBack: () => void;
  isSubmitting: boolean;
}

const AVAILABLE_LANGUAGES = [
  'Spanish',
  'English',
  'Portuguese',
  'Italian',
  'French',
  'German',
  'Chinese',
  'Arabic',
  'Russian',
  'Japanese',
  'Korean'
] as const;

export function ProfileCompletionStep({
  bio,
  languages,
  onUpdate,
  onComplete,
  onBack,
  isSubmitting
}: ProfileCompletionStepProps) {
  const [currentBio, setCurrentBio] = useState(bio);
  const [selectedLanguages, setSelectedLanguages] = useState<string[]>(languages);
  const [showLanguageDropdown, setShowLanguageDropdown] = useState(false);

  const updateBio = (newBio: string) => {
    setCurrentBio(newBio);
    onUpdate(newBio, selectedLanguages);
  };

  const toggleLanguage = (language: string) => {
    const updated = selectedLanguages.includes(language)
      ? selectedLanguages.filter(lang => lang !== language)
      : [...selectedLanguages, language];
    setSelectedLanguages(updated);
    onUpdate(currentBio, updated);
  };

  const bioCharacterCount = currentBio.length;
  const maxBioLength = 500;

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">
          Completa tu Perfil Profesional
        </h3>
        <p className="text-gray-600">
          Agrega una biografía profesional y los idiomas que hablas para completar tu perfil.
        </p>
      </div>

      {/* Biografía profesional */}
      <div>
        <label htmlFor="bio" className="block text-sm font-medium text-gray-700 mb-2">
          Biografía Profesional
        </label>
        <textarea
          id="bio"
          value={currentBio}
          onChange={(e) => updateBio(e.target.value)}
          placeholder="Cuéntanos sobre tu experiencia médica, áreas de interés, filosofía de atención al paciente..."
          rows={6}
          maxLength={maxBioLength}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none"
        />
        <div className="flex justify-between items-center mt-1">
          <p className="text-xs text-gray-500">
            Una buena biografía ayuda a los pacientes a conocerte y generar confianza
          </p>
          <span className={`text-xs ${bioCharacterCount > maxBioLength * 0.9 ? 'text-red-500' : 'text-gray-500'}`}>
            {bioCharacterCount}/{maxBioLength}
          </span>
        </div>
      </div>

      {/* Idiomas */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Idiomas que Hablas
        </label>

        <div className="relative">
          <button
            onClick={() => setShowLanguageDropdown(!showLanguageDropdown)}
            className="w-full px-3 py-2 text-left border border-gray-300 rounded-lg hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          >
            <div className="flex justify-between items-center">
              <span className="text-gray-700">
                {selectedLanguages.length > 0
                  ? `${selectedLanguages.length} idioma${selectedLanguages.length > 1 ? 's' : ''} seleccionado${selectedLanguages.length > 1 ? 's' : ''}`
                  : 'Seleccionar idiomas...'
                }
              </span>
              <svg
                className={`w-5 h-5 text-gray-400 transition-transform ${showLanguageDropdown ? 'rotate-180' : ''}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </div>
          </button>

          {showLanguageDropdown && (
            <div className="absolute z-10 w-full mt-1 border border-gray-200 rounded-lg p-2 bg-white shadow-lg max-h-48 overflow-y-auto">
              {AVAILABLE_LANGUAGES.map(language => (
                <label key={language} className="flex items-center px-3 py-2 hover:bg-gray-50 rounded cursor-pointer">
                  <input
                    type="checkbox"
                    checked={selectedLanguages.includes(language)}
                    onChange={() => toggleLanguage(language)}
                    className="mr-3"
                  />
                  <span className="text-gray-900">{language}</span>
                </label>
              ))}
            </div>
          )}
        </div>

        {selectedLanguages.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-2">
            {selectedLanguages.map(language => (
              <span
                key={language}
                className="inline-flex items-center px-3 py-1 rounded-full text-sm bg-blue-100 text-blue-800"
              >
                {language}
                <button
                  onClick={() => toggleLanguage(language)}
                  className="ml-2 text-blue-600 hover:text-blue-800"
                >
                  ×
                </button>
              </span>
            ))}
          </div>
        )}

        <p className="text-xs text-gray-500 mt-2">
          Los pacientes pueden filtrar médicos por idioma disponible
        </p>
      </div>

      {/* Preview del perfil */}
      {(currentBio || selectedLanguages.length > 0) && (
        <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
          <h4 className="text-sm font-medium text-gray-900 mb-3">Vista Previa del Perfil</h4>

          {currentBio && (
            <div className="mb-3">
              <p className="text-sm text-gray-700 leading-relaxed">{currentBio}</p>
            </div>
          )}

          {selectedLanguages.length > 0 && (
            <div>
              <p className="text-xs text-gray-500 mb-1">Idiomas:</p>
              <div className="flex flex-wrap gap-1">
                {selectedLanguages.map(language => (
                  <span
                    key={language}
                    className="inline-flex items-center px-2 py-1 rounded text-xs bg-gray-200 text-gray-700"
                  >
                    {language}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Información de finalización */}
      <div className="bg-green-50 border border-green-200 rounded-lg p-4">
        <div className="flex">
          <svg className="w-5 h-5 text-green-400 mr-2 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
          <div>
            <p className="text-green-800 text-sm">
              <strong>¡Casi terminamos!</strong> Al completar este paso, tu perfil médico estará listo
              y podrás comenzar a recibir pacientes en AutaMedica.
            </p>
            <p className="text-green-700 text-sm mt-1">
              Podrás editar toda esta información desde tu dashboard en cualquier momento.
            </p>
          </div>
        </div>
      </div>

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onBack}
          disabled={isSubmitting}
          className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors disabled:opacity-50"
        >
          Atrás
        </button>

        <button
          onClick={onComplete}
          disabled={isSubmitting}
          className="px-8 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center"
        >
          {isSubmitting ? (
            <>
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
              </svg>
              Creando perfil...
            </>
          ) : (
            'Completar Perfil Médico'
          )}
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { WeeklySchedule, DaySchedule } from '@autamedica/types';

interface ScheduleSetupStepProps {
  schedule: WeeklySchedule;
  consultationFee?: number;
  acceptedInsurance: string[];
  onUpdate: (schedule: WeeklySchedule, consultationFee?: number, acceptedInsurance?: string[]) => void;
  onNext: () => void;
  onBack: () => void;
}

const DAYS = [
  { key: 'monday', label: 'Lunes' },
  { key: 'tuesday', label: 'Martes' },
  { key: 'wednesday', label: 'Miércoles' },
  { key: 'thursday', label: 'Jueves' },
  { key: 'friday', label: 'Viernes' },
  { key: 'saturday', label: 'Sábado' },
  { key: 'sunday', label: 'Domingo' }
] as const;

const COMMON_INSURANCE = [
  'OSDE',
  'Swiss Medical',
  'Medicus',
  'IOMA',
  'PAMI',
  'Galeno',
  'Medifé',
  'Hospital Italiano',
  'Hospital Alemán',
  'CEMIC',
  'Obra Social Empleados de Comercio',
  'OSECAC',
  'OSPLAD',
  'OSPEDYC'
] as const;

export function ScheduleSetupStep({
  schedule,
  consultationFee,
  acceptedInsurance,
  onUpdate,
  onNext,
  onBack
}: ScheduleSetupStepProps) {
  const [weeklySchedule, setWeeklySchedule] = useState<WeeklySchedule>(schedule);
  const [fee, setFee] = useState<number>(consultationFee || 0);
  const [insurance, setInsurance] = useState<string[]>(acceptedInsurance);
  const [showInsuranceDropdown, setShowInsuranceDropdown] = useState(false);

  const updateDaySchedule = (day: keyof WeeklySchedule, daySchedule: DaySchedule | undefined) => {
    const updated = { ...weeklySchedule, [day]: daySchedule };
    setWeeklySchedule(updated);
    onUpdate(updated, fee, insurance);
  };

  const toggleInsurance = (insuranceName: string) => {
    const updated = insurance.includes(insuranceName)
      ? insurance.filter(name => name !== insuranceName)
      : [...insurance, insuranceName];
    setInsurance(updated);
    onUpdate(weeklySchedule, fee, updated);
  };

  const updateFee = (newFee: number) => {
    setFee(newFee);
    onUpdate(weeklySchedule, newFee, insurance);
  };

  const DayScheduleEditor = ({ day, label }: { day: keyof WeeklySchedule; label: string }) => {
    const daySchedule = weeklySchedule[day];
    const isActive = !!daySchedule;

    return (
      <div className="border border-gray-200 rounded-lg p-4">
        <div className="flex items-center justify-between mb-3">
          <label className="flex items-center">
            <input
              type="checkbox"
              checked={isActive}
              onChange={(e) => {
                if (e.target.checked) {
                  updateDaySchedule(day, { start: '09:00', end: '17:00' });
                } else {
                  updateDaySchedule(day, undefined);
                }
              }}
              className="mr-2"
            />
            <span className="font-medium text-gray-900">{label}</span>
          </label>
        </div>

