'use client';

import React, { useState } from 'react';

interface SpecialtySelectionStepProps {
  specialty: string;
  subspecialty?: string;
  yearsExperience: number;
  onUpdate: (specialty: string, subspecialty?: string, yearsExperience?: number) => void;
  onNext: () => void;
  onBack: () => void;
