  ]
};

export function SpecialtySelectionStep({
  specialty,
  subspecialty,
  yearsExperience,
  onUpdate,
  onNext,
  onBack
}: SpecialtySelectionStepProps) {
  const [selectedSpecialty, setSelectedSpecialty] = useState(specialty);
  const [selectedSubspecialty, setSelectedSubspecialty] = useState(subspecialty || '');
  const [experience, setExperience] = useState(yearsExperience);
  const [showSubspecialties, setShowSubspecialties] = useState(false);

  const availableSubspecialties = selectedSpecialty ? SUBSPECIALTIES[selectedSpecialty] || [] : [];

  const handleSpecialtyChange = (newSpecialty: string) => {
    setSelectedSpecialty(newSpecialty);
    setSelectedSubspecialty(''); // Reset subspecialty cuando cambia especialidad
    setShowSubspecialties(false);
    onUpdate(newSpecialty, '', experience);
  };

  const handleSubspecialtyChange = (newSubspecialty: string) => {
    setSelectedSubspecialty(newSubspecialty);
    onUpdate(selectedSpecialty, newSubspecialty, experience);
  };

  const handleExperienceChange = (newExperience: number) => {
    setExperience(newExperience);
    onUpdate(selectedSpecialty, selectedSubspecialty, newExperience);
  };

  const handleNext = () => {
    if (!selectedSpecialty) {
      alert('Por favor selecciona una especialidad médica');
      return;
    }
    onNext();
  };

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-gray-900 mb-2">
          Especialidad Médica
        </h3>
        <p className="text-gray-600">
          Selecciona tu especialidad principal y años de experiencia profesional.
        </p>
      </div>

      <div className="space-y-4">
        {/* Especialidad principal */}
        <div>
          <label htmlFor="specialty" className="block text-sm font-medium text-gray-700 mb-2">
            Especialidad Principal <span className="text-red-500">*</span>
          </label>
          <select
            id="specialty"
            value={selectedSpecialty}
            onChange={(e) => handleSpecialtyChange(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">Selecciona una especialidad</option>
            {MEDICAL_SPECIALTIES.map(spec => (
              <option key={spec} value={spec}>
                {spec}
              </option>
            ))}
          </select>
        </div>

        {/* Subspecialidad */}
        {selectedSpecialty && availableSubspecialties.length > 0 && (
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Subspecialidad (Opcional)
            </label>
            <div className="space-y-2">
              <button
                type="button"
                onClick={() => setShowSubspecialties(!showSubspecialties)}
                className="w-full px-3 py-2 text-left border border-gray-300 rounded-lg hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <div className="flex justify-between items-center">
                  <span className={selectedSubspecialty ? 'text-gray-900' : 'text-gray-500'}>
                    {selectedSubspecialty || 'Seleccionar subspecialidad...'}
                  </span>
                  <svg
                    className={`w-5 h-5 text-gray-400 transition-transform ${showSubspecialties ? 'rotate-180' : ''}`}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg>
                </div>
              </button>

              {showSubspecialties && (
                <div className="border border-gray-200 rounded-lg p-2 bg-gray-50 max-h-40 overflow-y-auto">
                  <div
                    className="px-3 py-2 hover:bg-white rounded cursor-pointer text-gray-600"
                    onClick={() => {
                      handleSubspecialtyChange('');
                      setShowSubspecialties(false);
                    }}
                  >
                    Sin subspecialidad
                  </div>
                  {availableSubspecialties.map(subspec => (
                    <div
                      key={subspec}
                      className="px-3 py-2 hover:bg-white rounded cursor-pointer"
                      onClick={() => {
                        handleSubspecialtyChange(subspec);
                        setShowSubspecialties(false);
                      }}
                    >
                      {subspec}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Años de experiencia */}
        <div>
          <label htmlFor="experience" className="block text-sm font-medium text-gray-700 mb-2">
            Años de Experiencia Profesional <span className="text-red-500">*</span>
          </label>
          <select
            id="experience"
            value={experience}
            onChange={(e) => handleExperienceChange(parseInt(e.target.value))}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          >
            <option value={0}>Recién graduado</option>
            <option value={1}>1 año</option>
            <option value={2}>2 años</option>
            <option value={3}>3 años</option>
            <option value={4}>4 años</option>
            <option value={5}>5 años</option>
            {Array.from({ length: 15 }, (_, i) => i + 6).map(year => (
              <option key={year} value={year}>
                {year} años
              </option>
            ))}
            <option value={21}>Más de 20 años</option>
          </select>
        </div>

        {/* Información adicional sobre especialidades */}
        {selectedSpecialty && (
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex">
              <svg className="w-5 h-5 text-blue-400 mr-2 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <div>
                <p className="text-blue-800 text-sm">
                  <strong>Especialidad seleccionada:</strong> {selectedSpecialty}
                </p>
                {selectedSubspecialty && (
                  <p className="text-blue-700 text-sm mt-1">
                    <strong>Subspecialidad:</strong> {selectedSubspecialty}
                  </p>
                )}
                <p className="text-blue-700 text-sm mt-1">
                  Esta información aparecerá en tu perfil público y ayudará a los pacientes a encontrarte.
                </p>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onBack}
          className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
        >
          Atrás
        </button>

        <button
          onClick={handleNext}
          disabled={!selectedSpecialty}
          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          Continuar
        </button>
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { CreditCard, Lock, Shield, CheckCircle, AlertCircle, Loader } from 'lucide-react'

interface PaymentMethod {
  id: string
  type: 'credit_card' | 'debit_card'
  last_four_digits: string
  payment_method_id: string
  issuer: {
    id: string
    name: string
  }
  security_code?: {
    length: number
    card_location: string
  }
}

interface MercadoPagoCheckoutProps {
  _planId: string
  amount: number
  currency: string
  description: string
  onSuccess: (paymentData: any) => void
  onError: (error: any) => void
  onPending?: (paymentData: any) => void
}

interface MercadoPagoSubscriptionManagerProps {
  currentPlanId: string
  onPlanChange: (newPlanId: string) => void
}

export function MercadoPagoCheckout({
  _planId,
  amount,
  currency,
  description,
  onSuccess,
  onError,
  onPending
}: MercadoPagoCheckoutProps) {
  const [isLoading, setIsLoading] = useState(false)
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([])
  const [selectedPaymentMethod, setSelectedPaymentMethod] = useState<string>('')
  const [cardData, setCardData] = useState({
    cardNumber: '',
    expirationDate: '',
    securityCode: '',
    cardholderName: '',
    identificationType: 'DNI',
    identificationNumber: ''
  })

  useEffect(() => {
    initializeMercadoPago()
    loadSavedPaymentMethods()
  }, [])

  const initializeMercadoPago = async () => {
    try {
      // En producción, esto se cargaría desde las variables de entorno
      const publicKey = 'TEST-your-public-key'

      // Simulación de inicialización del SDK
      // logger.info('Inicializando MercadoPago SDK con clave:', publicKey)

      // En implementación real:
      // await window.MercadoPago.initialize({ locale: 'es-AR', environment: 'sandbox' })
      // await window.MercadoPago.setPublishableKey(publicKey)
    } catch (error) {
      logger.error('Error inicializando MercadoPago:', error)
      onError(error)
    }
  }

  const loadSavedPaymentMethods = async () => {
    try {
      // Simulación de carga de métodos de pago guardados
      const mockPaymentMethods: PaymentMethod[] = [
        {
          id: 'pm_1',
          type: 'credit_card',
          last_four_digits: '4321',
          payment_method_id: 'visa',
          issuer: {
            id: '25',
            name: 'Visa'
          },
          security_code: {
            length: 3,
            card_location: 'back'
          }
        }
      ]

      setPaymentMethods(mockPaymentMethods)
    } catch (error) {
      logger.error('Error cargando métodos de pago:', error)
    }
  }

  const processPayment = async () => {
    if (!selectedPaymentMethod && !cardData.cardNumber) {
      onError({ message: 'Debe seleccionar o agregar un método de pago' })
      return
    }

    setIsLoading(true)

    try {
      // Simulación del proceso de pago con MercadoPago
      await new Promise(resolve => setTimeout(resolve, 2000))

      const paymentData = {
        id: 'payment_' + Date.now(),
        status: 'approved',
        status_detail: 'accredited',
        operation_type: 'regular_payment',
        date_approved: new Date().toISOString(),
        transaction_amount: amount,
        currency_id: currency,
        description,
        payment_method_id: selectedPaymentMethod || 'visa',
        payer: {
          id: 'payer_' + Date.now(),
          email: 'medico@autamedica.com'
        }
      }

      // Simular diferentes resultados
      const random = Math.random()
      if (random > 0.8) {
        // 20% chance de error
        throw new Error('Error en el procesamiento del pago')
      } else if (random > 0.7) {
        // 10% chance de pendiente
        onPending?.({ ...paymentData, status: 'pending' })
      } else {
        // 70% chance de éxito
        onSuccess(paymentData)
      }
    } catch (error) {
      onError(error)
    } finally {
      setIsLoading(false)
    }
  }

  const formatCardNumber = (value: string) => {
    const v = value.replace(/\s+/g, '').replace(/[^0-9]/gi, '')
    const matches = v.match(/\d{4,16}/g)
    const match = matches?.[0] || ''
    const parts = []
    for (let i = 0, len = match.length; i < len; i += 4) {
      parts.push(match.substring(i, i + 4))
    }
    if (parts.length) {
      return parts.join(' ')
    } else {
      return v
    }
  }

  return (
    <div className="space-y-6">
      {/* Métodos de pago guardados */}
      {paymentMethods.length > 0 && (
        <div>
          <h3 className="text-lg font-medium text-slate-100 mb-3">Métodos de pago guardados</h3>
          <div className="space-y-2">
            {paymentMethods.map((method) => (
              <div
                key={method.id}
                onClick={() => setSelectedPaymentMethod(method.id)}
                className={`p-4 border rounded-lg cursor-pointer transition-colors ${
                  selectedPaymentMethod === method.id
                    ? 'border-emerald-500 bg-emerald-500/10'
                    : 'border-slate-700 hover:border-slate-600'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <CreditCard className="w-5 h-5 text-slate-400" />
                    <div>
                      <p className="text-slate-100 font-medium">
                        {method.issuer.name} •••• {method.last_four_digits}
                      </p>
                      <p className="text-slate-400 text-sm">
                        {method.type === 'credit_card' ? 'Tarjeta de crédito' : 'Tarjeta de débito'}
                      </p>
                    </div>
                  </div>
                  {selectedPaymentMethod === method.id && (
                    <CheckCircle className="w-5 h-5 text-emerald-400" />
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Agregar nueva tarjeta */}
      <div>
        <h3 className="text-lg font-medium text-slate-100 mb-3">
          {paymentMethods.length > 0 ? 'Agregar nueva tarjeta' : 'Información de la tarjeta'}
        </h3>

        <div className="grid gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              Número de tarjeta
            </label>
            <input
              type="text"
              value={cardData.cardNumber}
              onChange={(e) => setCardData(prev => ({
                ...prev,
                cardNumber: formatCardNumber(e.target.value)
              }))}
              placeholder="1234 5678 9012 3456"
              className="w-full px-3 py-2 bg-slate-800/60 border border-slate-700 rounded-lg text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500"
              maxLength={19}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Fecha de vencimiento
              </label>
              <input
                type="text"
                value={cardData.expirationDate}
                onChange={(e) => {
                  let value = e.target.value.replace(/\D/g, '')
                  if (value.length >= 2) {
                    value = value.substring(0, 2) + '/' + value.substring(2, 4)
                  }
                  setCardData(prev => ({ ...prev, expirationDate: value }))
                }}
                placeholder="MM/AA"
                className="w-full px-3 py-2 bg-slate-800/60 border border-slate-700 rounded-lg text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500"
                maxLength={5}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Código de seguridad
