import React, { useState, useEffect, useRef } from 'react';
import {
  Video,
  VideoOff,
  Mic,
  MicOff,
  PhoneOff,
  Monitor
} from 'lucide-react';
import { logger } from '@autamedica/shared';

// React 19 compatibility for Lucide icons
const VideoIcon = Video as any;
const VideoOffIcon = VideoOff as any;
const MicIcon = Mic as any;
const MicOffIcon = MicOff as any;
const PhoneOffIcon = PhoneOff as any;
const MonitorIcon = Monitor as any;

interface PatientData {
  id: string;
  name: string;
  age: number;
  gender: string;
}

interface IntegratedDoctorVideoCallProps {
  sessionId: string;
  patientData: PatientData;
}

export default function IntegratedDoctorVideoCall({
  sessionId,
  patientData
}: IntegratedDoctorVideoCallProps) {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(false);
  const [isConnected, setIsConnected] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    // Initialize camera
    const initCamera = async () => {
      try {
        const mediaStream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: true
        });
        setStream(mediaStream);
        setIsConnected(true);

        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
      } catch (error) {
        logger.error('Error accessing camera:', error);
      }
    };

    initCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const toggleMute = () => {
    if (stream) {
      stream.getAudioTracks().forEach(track => {
        track.enabled = isMuted;
      });
      setIsMuted(!isMuted);
    }
  };

  const toggleVideo = () => {
    if (stream) {
      stream.getVideoTracks().forEach(track => {
        track.enabled = isVideoOff;
      });
      setIsVideoOff(!isVideoOff);
    }
  };

  const endCall = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
      setIsConnected(false);
    }
  };

  return (
    <div className="h-full p-6 flex flex-col">
      {/* Video call area */}
      <div className="bg-gray-800 rounded-lg overflow-hidden h-96 mb-6 relative">
        {stream ? (
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className={`w-full h-full object-cover ${isVideoOff ? 'opacity-0' : ''}`}
            style={{ transform: 'scaleX(-1)' }}
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <div className="text-center">
              <VideoOffIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-300">Cámara no activada</p>
            </div>
          </div>
        )}

        {/* Video controls */}
        <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2">
          <div className="flex items-center space-x-4 bg-gray-900/80 backdrop-blur-sm px-6 py-3 rounded-full">
            <button
              onClick={toggleMute}
              className={`p-3 rounded-full transition-colors ${
                isMuted ? 'bg-red-500 hover:bg-red-600' : 'bg-blue-500 hover:bg-blue-600'
              }`}
            >
              {isMuted ? <MicOffIcon className="w-5 h-5 text-white" /> : <MicIcon className="w-5 h-5 text-white" />}
            </button>

            <button
              onClick={toggleVideo}
              className={`p-3 rounded-full transition-colors ${
                isVideoOff ? 'bg-red-500 hover:bg-red-600' : 'bg-blue-500 hover:bg-blue-600'
              }`}
            >
              {isVideoOff ? <VideoOffIcon className="w-5 h-5 text-white" /> : <VideoIcon className="w-5 h-5 text-white" />}
            </button>

            <button className="p-3 rounded-full bg-purple-500 hover:bg-purple-600 transition-colors">
              <MonitorIcon className="w-5 h-5 text-white" />
            </button>

            <button
              onClick={endCall}
              className="p-3 rounded-full bg-red-500 hover:bg-red-600 transition-colors"
            >
              <PhoneOffIcon className="w-5 h-5 text-white" />
            </button>
          </div>
        </div>

        {/* Status overlay */}
        {stream && (
          <div className="absolute top-4 left-4 bg-gray-900/80 backdrop-blur-sm px-3 py-2 rounded-lg">
            <div className="flex items-center space-x-3 text-sm text-white">
              <span className="text-green-400">● HD</span>
              <span>|</span>
              <span className="text-blue-400">45ms</span>
              <span>|</span>
              <span className={isConnected ? 'text-green-400' : 'text-yellow-400'}>
                {isConnected ? 'Conectado' : 'Conectando...'}
              </span>
            </div>
          </div>
        )}
      </div>

      {/* Patient info */}
      <div className="bg-gray-800 rounded-lg p-4">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-white font-semibold">{patientData.name}</h3>
            <p className="text-gray-400">{patientData.age} años • Consulta General</p>
            <p className="text-gray-500 text-xs">Sesión: {sessionId}</p>
          </div>
          <div className="flex items-center space-x-4">
            <div className="text-center">
              <div className="text-green-400 font-bold">HD</div>
              <div className="text-gray-500 text-xs">Calidad</div>
            </div>
            <div className="text-center">
              <div className="text-blue-400 font-bold">15:30</div>
              <div className="text-gray-500 text-xs">Duración</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  listAppointments,
  createAppointment,
  updateAppointment,
  deleteAppointment,
  type Appointment,
  type NewAppointment,
  type PatchAppointment,
} from '@/lib/repos/appointments';

type Status = 'idle' | 'loading' | 'error' | 'success';

export function useAppointments() {
  const [status, setStatus] = useState<Status>('idle');
  const [error, setError] = useState<string | null>(null);
  const [rows, setRows] = useState<Appointment[]>([]);

  const refresh = useCallback(async () => {
    try {
      setStatus('loading'); setError(null);
      const data = await listAppointments();
      setRows(data);
      setStatus('success');
    } catch (e: any) {
      setStatus('error'); setError(e?.message ?? 'Error');
    }
  }, []);

  useEffect(() => { void refresh(); }, [refresh]);

  const create = useCallback(async (input: NewAppointment) => {
    const created = await createAppointment(input);
    setRows(prev => [...prev, created]);
    return created;
  }, []);

  const patch = useCallback(async (id: string, p: PatchAppointment) => {
    const updated = await updateAppointment(id, p);
    setRows(prev => prev.map(r => r.id === id ? updated : r));
    return updated;
  }, []);

  const remove = useCallback(async (id: string) => {
    await deleteAppointment(id);
    setRows(prev => prev.filter(r => r.id !== id));
  }, []);

  return useMemo(() => ({
    status, error, rows, refresh, create, patch, remove,
  }), [status, error, rows, refresh, create, patch, remove]);
}

/**
 * Hook migrado al sistema híbrido
 *
 * CAMBIOS:
 * - Usa selectActive() en lugar de supabase directo
 * - Datos retornados en camelCase automáticamente
 * - Auto-filtrado de soft-deleted (deleted_at IS NULL)
 * - Mantiene simulación de IA para pruebas
 */

import { useEffect, useState, useCallback } from 'react'
import { selectActive, logger } from '@autamedica/shared'
import { createBrowserClient } from '@autamedica/auth/client'
import type {
  AIAnalysis,
  UseAIAnalysisResult,
  UUID,
  AIDiagnosis,
  AITreatmentSuggestion
} from '@/types/medical'

// Tipo UI (camelCase) para AIAnalysis
interface UiAIAnalysis {
  id: string;
  patientId: string;
  doctorId: string;
  medicalRecordId: string | null;
  inputSymptoms: string[];
  inputText: string;
  additionalContext: string | null;
  primaryDiagnosis: AIDiagnosis;
  differentialDiagnoses: AIDiagnosis[];
  treatmentSuggestions: AITreatmentSuggestion[];
  riskFactors: string[];
  modelVersion: string;
  confidenceScore: number;
  processingTimeMs: number;
  active: boolean;
  createdAt: string;
  deletedAt: string | null;
}

export function useAIAnalysis(patientId: UUID | null): UseAIAnalysisResult {
  const [analyses, setAnalyses] = useState<AIAnalysis[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchAnalyses = useCallback(async () => {
    if (!patientId) {
      setAnalyses([])
      return
    }

    setLoading(true)
    setError(null)

    try {
      // Sistema híbrido: selectActive() retorna camelCase automáticamente
      const allAnalyses = await selectActive<UiAIAnalysis>('ai_analyses', '*', {
        orderBy: { column: 'created_at', ascending: false }
      });

      // Filtrar por patient_id
      const filtered = allAnalyses.filter(a => a.patientId === patientId);

      setAnalyses(filtered as unknown as AIAnalysis[])

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error desconocido'
      setError(`Error al cargar análisis de IA: ${errorMessage}`)
      logger.error('[useAIAnalysis] Error:', err)
    } finally {
      setLoading(false)
    }
  }, [patientId])

  const createAnalysis = useCallback(async (input: {
    symptoms: string[]
    text: string
    context?: string
  }): Promise<AIAnalysis | null> => {
    if (!patientId) {
      throw new Error('ID de paciente requerido')
    }

    setLoading(true)
    setError(null)

    try {
      const supabase = createBrowserClient()

      // Obtener información del doctor actual
      const { data: { user }, error: userError } = await supabase.auth.getUser()
      if (userError || !user) {
        throw new Error('Usuario no autenticado')
      }

      const startTime = Date.now()

      // Simular análisis de IA (en producción, esto sería una llamada a la API de IA)
      const mockAnalysis = await simulateAIAnalysis(input)

      const processingTime = Date.now() - startTime

      const newAnalysis = {
        patient_id: patientId,
        doctor_id: user.id,
        medical_record_id: null,
        input_symptoms: input.symptoms,
        input_text: input.text,
        additional_context: input.context || null,
        primary_diagnosis: mockAnalysis.primary_diagnosis,
        differential_diagnoses: mockAnalysis.differential_diagnoses,
        treatment_suggestions: mockAnalysis.treatment_suggestions,
        risk_factors: mockAnalysis.risk_factors,
        model_version: 'autamedica-ai-v1.0',
        confidence_score: mockAnalysis.confidence_score,
        processing_time_ms: processingTime,
        created_at: new Date().toISOString()
      }

      // Nota: En un entorno de producción real, esto se guardaría en la base de datos
      // Por ahora, solo agregamos a la lista local para pruebas
      const mockData = {
        ...newAnalysis,
        id: crypto.randomUUID()
      }

      // Agregar a la lista local
      setAnalyses(prev => [mockData, ...prev])

      return mockData

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error desconocido'
      setError(`Error al crear análisis de IA: ${errorMessage}`)
      logger.error('[useAIAnalysis] createAnalysis error:', err)
      throw err
    } finally {
      setLoading(false)
    }
  }, [patientId])

  const refresh = useCallback(async () => {
    await fetchAnalyses()
  }, [fetchAnalyses])

  useEffect(() => {
    fetchAnalyses()
  }, [fetchAnalyses])

  return {
    analyses,
    loading,
    error,
    createAnalysis
  }
}

// Simulación de análisis de IA médica
async function simulateAIAnalysis(input: {
  symptoms: string[]
  text: string
  context?: string
}): Promise<{
  primary_diagnosis: AIDiagnosis
  differential_diagnoses: AIDiagnosis[]
  treatment_suggestions: AITreatmentSuggestion[]
  risk_factors: string[]
  confidence_score: number
}> {
  // Simular delay de procesamiento
  await new Promise(resolve => setTimeout(resolve, 1500))

  const symptoms = input.symptoms.join(' ').toLowerCase()

  // Lógica básica de diagnóstico basada en síntomas comunes
  let primaryDiagnosis: AIDiagnosis
  let differentialDiagnoses: AIDiagnosis[]
  let treatments: AITreatmentSuggestion[]
  let riskFactors: string[]

  if (symptoms.includes('fiebre') || symptoms.includes('tos')) {
    primaryDiagnosis = {
      condition: 'Infección respiratoria viral',
      icd_code: 'J06.9',
      description: 'Infección del tracto respiratorio superior de origen viral',
      confidence: 'alta',
      probability: 0.85,
      reasoning: 'Los síntomas de fiebre y tos son característicos de infecciones virales del tracto respiratorio'
    }

    differentialDiagnoses = [
      {
        condition: 'COVID-19',
        icd_code: 'U07.1',
        description: 'Enfermedad por coronavirus 2019',
        confidence: 'media',
        probability: 0.65,
        reasoning: 'Los síntomas pueden ser compatibles con COVID-19, requiere confirmación'
      },
      {
        condition: 'Gripe estacional',
        icd_code: 'J11.1',
        description: 'Gripe debida a virus no identificado con otras manifestaciones respiratorias',
        confidence: 'media',
        probability: 0.60,
        reasoning: 'Los síntomas son típicos de gripe estacional'
      }
    ]

    treatments = [
      {
        treatment: 'Reposo y hidratación',
        type: 'medidas_generales',
        priority: 'alta',
        details: 'Reposo en cama, abundante hidratación con líquidos tibios',
        contraindications: []
      },
      {
        treatment: 'Paracetamol 500mg cada 8 horas',
        type: 'medicacion',
        priority: 'media',
        details: 'Para control de fiebre y dolor, no exceder 3g/día',
        contraindications: ['Enfermedad hepática grave', 'Alergia al paracetamol']
      }
    ]

    riskFactors = ['Deshidratación', 'Complicaciones respiratorias', 'Propagación a contactos']
  } else {
    primaryDiagnosis = {
      condition: 'Consulta médica general',
      icd_code: 'Z00.0',
      description: 'Examen médico general',
      confidence: 'media',
      probability: 0.70,
      reasoning: 'Síntomas requieren evaluación médica general para diagnóstico preciso'
    }

    differentialDiagnoses = []
    treatments = [
      {
        treatment: 'Evaluación médica presencial',
        type: 'referencia',
        priority: 'alta',
        details: 'Se recomienda consulta presencial para evaluación completa',
        contraindications: []
      }
    ]

    riskFactors = ['Diagnóstico tardío por falta de evaluación presencial']
  }

  return {
    primary_diagnosis: primaryDiagnosis,
    differential_diagnoses: differentialDiagnoses,
    treatment_suggestions: treatments,
    risk_factors: riskFactors,
    confidence_score: primaryDiagnosis.probability
  }
}

