export interface UseActiveSessionResult {
  session: ActiveSessionData | null
  loading: boolean
  error: string | null
  startSession: (patientId: UUID, sessionType: ActiveSessionData['sessionType']) => Promise<void>
  endSession: () => Promise<void>
}

