  const [session, setSession] = useState<ActiveSessionData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchActiveSession = async () => {
    setLoading(true)
    setError(null)

    try {
      // Para pruebas, usar datos de invitado con UUIDs válidos
      // En producción, esto consultaría la base de datos real
      await createGuestSession()
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error desconocido'
      setError(`Error al cargar sesión activa: ${errorMessage}`)
      logger.error('[useActiveSession] Error:', err)

      // Fallback a sesión de invitado
      await createGuestSession()
    } finally {
      setLoading(false)
    }
  }

  const createGuestSession = async () => {
    // Usar datos de invitado con UUID válido predefinido
    const guestSessionId = crypto.randomUUID()

    setSession({
      patientId: DEMO_PATIENT_ID,
      sessionId: guestSessionId,
      sessionType: 'general',
      startTime: new Date().toISOString(),
      status: 'en_progreso'
    })
  }

  const startSession = async (patientId: UUID, sessionType: ActiveSessionData['sessionType']) => {
    try {
      const sessionId = crypto.randomUUID()
      const startTime = new Date().toISOString()

      setSession({
        patientId,
        sessionId,
        sessionType,
        startTime,
        status: 'en_progreso'
      })

      // En producción, esto insertaría en la base de datos real
      // logger.info('Sesión iniciada:', { patientId, sessionType })

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error desconocido'
      setError(`Error al iniciar sesión: ${errorMessage}`)
      throw err
    }
  }

  const endSession = async () => {
    if (!session) return

    try {
      setSession(null)

      // En producción, esto actualizaría la base de datos real
      // logger.info('Sesión finalizada')

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error desconocido'
      setError(`Error al finalizar sesión: ${errorMessage}`)
      throw err
    }
  }

  useEffect(() => {
    fetchActiveSession()
  }, [])

  return {
    session,
    loading,
    error,
    startSession,
    endSession
  }
}

'use client'

import { useState, useEffect } from 'react'
import { createBrowserClient } from '@autamedica/auth/client'

interface AuthenticatedUser {
  id: string
  email: string
  role: 'doctor' | 'patient' | 'company_admin' | 'platform_admin'
  profile?: {
    full_name?: string
    first_name?: string
    last_name?: string
    specialties?: string[]
    medical_license?: string
  }
}

interface UseAuthenticatedUserReturn {
  user: AuthenticatedUser | null
  loading: boolean
  error: string | null
  refreshUser: () => Promise<void>
}

export function useAuthenticatedUser(): UseAuthenticatedUserReturn {
  const [user, setUser] = useState<AuthenticatedUser | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [isClient, setIsClient] = useState(false)

  // Initialize client safely after hydration
  useEffect(() => {
    setIsClient(true)
  }, [])

  const supabase = isClient ? createBrowserClient() : null

  const fetchUserProfile = async (userId: string, userEmail: string) => {
    if (!supabase) return null

    try {
      // Get user from auth.users
      const { data: authUser } = await supabase.auth.getUser()

      if (!authUser.user) {
        throw new Error('No authenticated user found')
      }

      // Get role from user_metadata or app_metadata
      const role = authUser.user.user_metadata?.role ||
                  authUser.user.app_metadata?.role ||
                  'doctor' // Default for doctors app

      // Try to get profile from public.profiles table
      const { data: profile, error: profileError } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single()

      if (profileError && profileError.code !== 'PGRST116') {
        logger.warn('Error fetching profile:', profileError.message)
      }

      const authenticatedUser: AuthenticatedUser = {
        id: userId,
        email: userEmail,
        role: role as AuthenticatedUser['role'],
        profile: profile || {
          full_name: authUser.user.user_metadata?.full_name,
          first_name: authUser.user.user_metadata?.first_name,
          last_name: authUser.user.user_metadata?.last_name,
          specialties: authUser.user.user_metadata?.specialties,
          medical_license: authUser.user.user_metadata?.medical_license
        }
      }

      return authenticatedUser

    } catch (err) {
      logger.error('Error fetching user profile:', err)
      throw err
    }
  }

  const refreshUser = async () => {
    if (!supabase) {
      setLoading(false)
      return
    }

    try {
      setLoading(true)
      setError(null)

      const { data: { user: authUser } } = await supabase.auth.getUser()

      if (!authUser) {
        setUser(null)
        return
      }

      const userProfile = await fetchUserProfile(authUser.id, authUser.email!)
      setUser(userProfile)

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error loading user'
      setError(errorMessage)
      logger.error('Error in refreshUser:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (!supabase) return

    refreshUser()

    // Listen for auth state changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        // logger.info('Auth state changed:', event, session?.user?.id)

        if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
          if (session?.user) {
            try {
              const userProfile = await fetchUserProfile(session.user.id, session.user.email!)
              setUser(userProfile)
            } catch (err) {
              const errorMessage = err instanceof Error ? err.message : 'Error loading user'
              setError(errorMessage)
            }
          }
        } else if (event === 'SIGNED_OUT') {
          setUser(null)
          setError(null)
        }

        setLoading(false)
      }
    )

    return () => {
      subscription.unsubscribe()
    }
  }, [supabase])

  return {
    user,
    loading,
    error,
    refreshUser
  }
}

'use client'

import { useState, useEffect } from 'react'
import { createBrowserClient } from '@autamedica/auth/client'
import { logger } from '@autamedica/shared'

interface AppointmentStats {
  activeCount: number
  todayCount: number
  nextAppointment: {
    time: string
    patientName: string
  } | null
}

interface UseDoctorStatsReturn {
  stats: AppointmentStats | null
  loading: boolean
  error: string | null
  refresh: () => Promise<void>
}

/**
 * Hook para obtener estadísticas de consultas del doctor autenticado
 *
 * - Consultas activas
 * - Consultas del día
 * - Próxima consulta
 */
export function useDoctorStats(doctorId?: string): UseDoctorStatsReturn {
  const [stats, setStats] = useState<AppointmentStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [isClient, setIsClient] = useState(false)

  useEffect(() => {
    setIsClient(true)
  }, [])

  const supabase = isClient ? createBrowserClient() : null

  const fetchStats = async () => {
    if (!supabase || !doctorId) {
      setLoading(false)
      return
    }

    try {
      setLoading(true)
      setError(null)

      // Get today's date range
      const today = new Date()
      const startOfDay = new Date(today.setHours(0, 0, 0, 0)).toISOString()
      const endOfDay = new Date(today.setHours(23, 59, 59, 999)).toISOString()
      const now = new Date().toISOString()

      // Query appointments for this doctor
      const { data: appointments, error: apptError } = await supabase
        .from('appointments')
        .select(`
          id,
          scheduled_at,
          status,
          patient:patients!inner(
            profile:profiles!inner(
              full_name,
              first_name,
              last_name
            )
          )
        `)
        .eq('doctor_id', doctorId)
        .gte('scheduled_at', startOfDay)
        .order('scheduled_at', { ascending: true })

      if (apptError) {
        throw apptError
      }

      // Calculate stats
      const activeAppointments = appointments?.filter(apt =>
        apt.status === 'scheduled' || apt.status === 'in_progress'
      ) || []

      const todayAppointments = appointments?.filter(apt =>
        apt.scheduled_at >= startOfDay && apt.scheduled_at <= endOfDay
      ) || []

      // Find next appointment
      const nextAppt = appointments?.find(apt =>
        apt.scheduled_at >= now &&
        (apt.status === 'scheduled' || apt.status === 'confirmed')
      )

      const nextAppointment = nextAppt ? {
        time: new Date(nextAppt.scheduled_at).toLocaleTimeString('es-AR', {
          hour: '2-digit',
          minute: '2-digit'
        }),
        patientName: nextAppt.patient?.profile?.full_name ||
                    `${nextAppt.patient?.profile?.first_name || ''} ${nextAppt.patient?.profile?.last_name || ''}`.trim() ||
                    'Paciente'
      } : null

      setStats({
        activeCount: activeAppointments.length,
        todayCount: todayAppointments.length,
        nextAppointment
      })

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Error loading stats'
      setError(errorMessage)
      logger.error('Error in useDoctorStats:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (!supabase || !doctorId) return

    fetchStats()

    // Refresh stats every 60 seconds
    const interval = setInterval(fetchStats, 60000)

    return () => clearInterval(interval)
  }, [supabase, doctorId])

  return {
    stats,
    loading,
    error,
    refresh: fetchStats
  }
}

