    try {
      await admin.from('patient_ai_chats').insert({ user_id: userId, message, intent, confidence, used_pattern: usedPattern, reply_preview: replyPreview })
    } catch (e) {
      logger.warn('[AI] telemetry insert skipped:', (e as any)?.message || e)
    }
    return NextResponse.json({ ok: true })
  } catch (e: any) {
    logger.error('[AI] telemetry error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { ensureClientEnv, ensureServerEnv, logger } from '@autamedica/shared'
import { getUserIdFromRequest } from '@/lib/server/auth'
import { buildPatientContext, persistPatientContextFiles } from '@/lib/ai/context-builder'

export const runtime = 'nodejs'

export async function POST(request: Request) {
  try {
    const userId = await getUserIdFromRequest()
    if (!userId) return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 })

    const body = await request.json().catch(() => ({}))
    const profile = body?.profile as Record<string, unknown> | undefined
    const patient = body?.patient as Record<string, unknown> | undefined
    if (!profile && !patient) return NextResponse.json({ ok: false, error: 'no_updates' }, { status: 400 })

    const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL')
    const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY')
    const admin = createClient(url, serviceKey)

    // Apply profile updates
    if (profile && Object.keys(profile).length > 0) {
      try {
        const snake: any = {}
        if ('firstName' in profile) snake.first_name = (profile as any).firstName
        if ('lastName' in profile) snake.last_name = (profile as any).lastName
        if ('phone' in profile) snake.phone = (profile as any).phone
        if ('fullName' in profile) snake.full_name = (profile as any).fullName
        if ('email' in profile) snake.email = (profile as any).email

        // First try modern schema columns
        const upd = await admin.from('profiles').update(snake).eq('id', userId).select('*').single()
        if (upd.error) throw upd.error
      } catch (err: any) {
        // Fallback legacy: collapse to full_name if needed
        const fullName = (
          ((profile as any)?.fullName as string | undefined) ??
          [
            (profile as any)?.firstName as string | undefined,
            (profile as any)?.lastName as string | undefined,
          ]
            .filter(Boolean)
            .join(' ')
            .trim()
        ) || null
        const legacy = await admin.from('profiles').update({ full_name: fullName }).eq('id', userId).select('*').single()
        if (legacy.error) {
          logger.error('[AI] update profile failed', legacy.error)
          return NextResponse.json({ ok: false, error: legacy.error.message || 'profile_update_failed' }, { status: 400 })
        }
      }
    }

    // Apply patient updates (optional, tolerate schema diffs)
    if (patient && Object.keys(patient).length > 0) {
      const snake: any = {}
      if ('heightCm' in patient) snake.height_cm = (patient as any).heightCm
      if ('weightKg' in patient) snake.weight_kg = (patient as any).weightKg
      if ('bloodType' in patient) snake.blood_type = (patient as any).bloodType
      if ('gender' in patient) snake.gender = (patient as any).gender
      if ('birthDate' in patient) snake.birth_date = (patient as any).birthDate

      try {
        const upd = await admin.from('patients').update(snake).eq('user_id', userId).select('*').maybeSingle()
        if (upd.error) throw upd.error
        if (!upd.data) {
          await admin.from('patients').upsert({ user_id: userId, ...snake }, { onConflict: 'user_id' })
        }
      } catch (err: any) {
        // Swallow if table/columns unavailable
        logger.warn('[AI] patients update skipped:', err?.message || err)
      }
    }

    // Rebuild and persist context files
    const ctx = await buildPatientContext(userId, admin)
    const persisted = await persistPatientContextFiles(userId, ctx, admin)

    return NextResponse.json({ ok: true, data: { summary: ctx.summary, storage: persisted } })
  } catch (e: any) {
    logger.error('[AI] update error', e)
    return NextResponse.json({ ok: false, error: e?.message || 'internal_error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { ensureClientEnv, ensureServerEnv, logger } from '@autamedica/shared'
import { getUserIdFromRequest } from '@/lib/server/auth'

export const runtime = 'nodejs'

const TOTAL_SECTIONS = 13
const KNOWN_SECTIONS = [
  'personal_data',
  'emergency_contact',
  'medical_history',
  'family_history',
  'allergies',
  'current_medications',
  'chronic_conditions',
  'surgical_history',
  'hospitalizations',
  'gynecological_history',
  'lifestyle',
  'mental_health',
  'consent',
]

function toBoolean(value: unknown, fallback = false) {
  if (typeof value === 'boolean') return value
  if (typeof value === 'string') {
    const v = value.toLowerCase().trim()
    if (v === 'true') return true
    if (v === 'false') return false
  }
  return fallback
}

function buildSupabaseAdmin() {
  const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL')
  const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY')
  return createClient(url, serviceKey)
}

async function ensureAnamnesisRecord(admin: ReturnType<typeof buildSupabaseAdmin>, patientId: string) {
  const existing = await admin
    .from('anamnesis')
    .select('*')
    .eq('patient_id', patientId)
    .is('deleted_at', null)
    .maybeSingle()

  if (existing.data) {
    return existing.data
  }

  const insert = await admin
    .from('anamnesis')
    .insert({ patient_id: patientId, status: 'in_progress' })
    .select('*')
    .single()

  if (insert.error) throw insert.error
  return insert.data
}

function computeProgress(sections: any[]) {
  const completed = sections.filter((s) => toBoolean(s.completed))
  const completedIds = completed.map((s) => s.section)
  const pending = KNOWN_SECTIONS.filter((section) => !completedIds.includes(section))
  const completion = TOTAL_SECTIONS > 0 ? Math.round((completed.length / TOTAL_SECTIONS) * 100) : 0

  return {
    completion_percentage: completion,
    completed_sections: completedIds,
    pending_sections: pending,
    total_sections: TOTAL_SECTIONS,
  }
}

export async function GET() {
  try {
    const userId = await getUserIdFromRequest()
    if (!userId) {
      return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 })
    }

    const admin = buildSupabaseAdmin()
    const anamnesis = await ensureAnamnesisRecord(admin, userId)

    const sectionsRes = await admin
      .from('anamnesis_sections')
      .select('*')
      .eq('anamnesis_id', anamnesis.id)
      .order('updated_at', { ascending: true })

    if (sectionsRes.error) throw sectionsRes.error

    const sections = sectionsRes.data ?? []
    const progress = computeProgress(sections)

    // ensure completion percentage stays in sync
    if (anamnesis.completion_percentage !== progress.completion_percentage) {
      await admin
        .from('anamnesis')
        .update({ completion_percentage: progress.completion_percentage, sections_status: { completed: progress.completed_sections } })
        .eq('id', anamnesis.id)
    }

    return NextResponse.json({ ok: true, data: { anamnesis: { ...anamnesis, completion_percentage: progress.completion_percentage }, sections, progress } })
  } catch (e) {
    logger.error('[Anamnesis] GET error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

export async function POST(request: Request) {
  try {
    const userId = await getUserIdFromRequest()
    if (!userId) {
      return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 })
    }

    const body = await request.json().catch(() => ({}))
    const section = typeof body?.stepId === 'string' ? body.stepId : null
    const data = body?.data ?? {}
    const markCompleted = toBoolean(body?.completed, false)

    if (!section) {
      return NextResponse.json({ ok: false, error: 'missing_step' }, { status: 400 })
    }

    const admin = buildSupabaseAdmin()
    const anamnesis = await ensureAnamnesisRecord(admin, userId)

    const upsert = await admin
      .from('anamnesis_sections')
      .upsert(
        {
          anamnesis_id: anamnesis.id,
          section,
          data,
          completed: markCompleted,
          completed_at: markCompleted ? new Date().toISOString() : null,
        },
        { onConflict: 'anamnesis_id,section' }
      )
      .select('*')
      .single()

    if (upsert.error) throw upsert.error

    const sectionsRes = await admin
      .from('anamnesis_sections')
      .select('*')
      .eq('anamnesis_id', anamnesis.id)
      .order('updated_at', { ascending: true })

    if (sectionsRes.error) throw sectionsRes.error

    const sections = sectionsRes.data ?? []
    const progress = computeProgress(sections)

    await admin
      .from('anamnesis')
      .update({ completion_percentage: progress.completion_percentage, sections_status: { completed: progress.completed_sections } })
      .eq('id', anamnesis.id)

    return NextResponse.json({ ok: true, data: { section: upsert.data, progress } })
  } catch (e) {
    logger.error('[Anamnesis] POST error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

export async function PATCH(request: Request) {
  try {
    const userId = await getUserIdFromRequest()
    if (!userId) {
      return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 })
    }

    const body = await request.json().catch(() => ({}))
    const updates: Record<string, unknown> = {}

    if (typeof body?.status === 'string') {
      updates.status = body.status
      if (body.status === 'completed' && !body.completed_at) {
        updates.completed_at = new Date().toISOString()
      }
    }

    if (typeof body?.completion_percentage === 'number') {
      updates.completion_percentage = Math.min(100, Math.max(0, Math.round(body.completion_percentage)))
    }

    if (body?.completed_at) {
      updates.completed_at = body.completed_at
    }

    if (Object.keys(updates).length === 0) {
      return NextResponse.json({ ok: false, error: 'no_updates' }, { status: 400 })
    }

    const admin = buildSupabaseAdmin()
    const anamnesis = await ensureAnamnesisRecord(admin, userId)

    const updateRes = await admin
      .from('anamnesis')
      .update(updates)
      .eq('id', anamnesis.id)
      .select('*')
      .single()

    if (updateRes.error) throw updateRes.error

    return NextResponse.json({ ok: true, data: updateRes.data })
  } catch (e) {
    logger.error('[Anamnesis] PATCH error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

/**
 * API Routes para gestión individual de citas
 * GET /api/appointments/[id] - Obtener cita específica
 * PATCH /api/appointments/[id] - Actualizar cita
 * DELETE /api/appointments/[id] - Cancelar cita
 */

import { NextRequest, NextResponse } from 'next/server';
import { createRouteHandlerClient } from '@autamedica/auth/server';
import { cookies } from 'next/headers';
import type { UpdateAppointmentInput } from '@/types/appointment';
import { logger } from '@autamedica/shared';
import { mapAppointment, mapTypeToDb, computeEndTime } from '../utils';
type RouteContext = {
  params: Promise<{ id: string }>;
};

/**
 * GET /api/appointments/[id]
 * Obtiene una cita específica
 */
export async function GET(
  request: NextRequest,
  context: RouteContext
) {
  try {
    const { id } = await context.params;
    const cookieStore = await cookies();
    const supabase = createRouteHandlerClient(cookieStore);

    // Verificar autenticación
    const { data: { session }, error: authError } = await supabase.auth.getSession();

    if (authError || !session) {
      return NextResponse.json(
        { error: 'No autorizado' },
        { status: 401 }
      );
    }

    const userId = session.user.id;

    // Obtener patient_id
    const { data: patient, error: patientError } = await supabase
      .from('patients')
      .select('id')
      .eq('user_id', userId)
      .single();

    if (patientError || !patient) {
      return NextResponse.json(
        { error: 'Paciente no encontrado' },
        { status: 404 }
      );
    }

    // Obtener la cita
    const { data: appointment, error: appointmentError } = await supabase
      .from('appointments')
      .select(`
        *,
        doctor:doctors (
          id,
          first_name,
          last_name,
          specialty,
          profile_picture_url
        )
      `)
      .eq('id', id)
      .eq('patient_id', patient.id)
      .single();

    if (appointmentError || !appointment) {
      return NextResponse.json(
        { error: 'Cita no encontrada' },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      data: mapAppointment(appointment as any),
    });
  } catch (error) {
    logger.error('[GET /api/appointments/[id]] Error:', error);
    return NextResponse.json(
      { error: 'Error interno del servidor' },
      { status: 500 }
    );
  }
}

/**
 * PATCH /api/appointments/[id]
 * Actualiza una cita existente
 */
export async function PATCH(
  request: NextRequest,
  context: RouteContext
) {
  try {
    const { id } = await context.params;
    const cookieStore = await cookies();
    const supabase = createRouteHandlerClient(cookieStore);

    // Verificar autenticación
    const { data: { session }, error: authError } = await supabase.auth.getSession();

    if (authError || !session) {
      return NextResponse.json(
        { error: 'No autorizado' },
        { status: 401 }
      );
    }

    const userId = session.user.id;

    // Obtener patient_id
    const { data: patient, error: patientError } = await supabase
      .from('patients')
      .select('id')
      .eq('user_id', userId)
      .single();

    if (patientError || !patient) {
      return NextResponse.json(
        { error: 'Paciente no encontrado' },
        { status: 404 }
      );
    }

    // Verificar que la cita pertenece al paciente
    const { data: existingAppointment, error: checkError } = await supabase
      .from('appointments')
      .select('id, start_time, duration_minutes')
      .eq('id', id)
      .eq('patient_id', patient.id)
      .single();

    if (checkError || !existingAppointment) {
      return NextResponse.json(
        { error: 'Cita no encontrada' },
        { status: 404 }
      );
    }

    // Parsear body
    const body: UpdateAppointmentInput = await request.json();

    // Actualizar la cita
    const updates: Record<string, any> = {
      updated_at: new Date().toISOString(),
    };

    let effectiveStart = existingAppointment?.start_time || null;
    let effectiveDuration = existingAppointment?.duration_minutes ?? 30;

    if (body.scheduled_at) {
      const startIso = new Date(body.scheduled_at).toISOString();
      updates.start_time = startIso;
      effectiveStart = startIso;
    }

    if (body.duration_minutes !== undefined) {
      updates.duration_minutes = body.duration_minutes;
      effectiveDuration = body.duration_minutes;
    }

    if (effectiveStart) {
      updates.end_time = computeEndTime(effectiveStart, effectiveDuration);
    }

    if (body.status) updates.status = body.status;
    if (body.type) updates.type = mapTypeToDb(body.type);
    if (body.notes !== undefined) updates.notes = body.notes;
    if (body.reason !== undefined) updates.reason = body.reason;
    if (body.meeting_url !== undefined) updates.meeting_url = body.meeting_url;
    if (body.location !== undefined) updates.location = body.location;

    const { data: updatedAppointment, error: updateError } = await supabase
      .from('appointments')
      .update(updates)
      .eq('id', id)
      .select(`
        *,
        doctor:doctors (
          id,
          first_name,
          last_name,
          specialty,
          profile_picture_url
        )
      `)
      .single();

    if (updateError) {
      logger.error('[PATCH /api/appointments/[id]] Error:', updateError);
      return NextResponse.json(
        { error: 'Error al actualizar la cita', details: updateError.message },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      data: mapAppointment(updatedAppointment as any),
    });
  } catch (error) {
    logger.error('[PATCH /api/appointments/[id]] Error:', error);
    return NextResponse.json(
      { error: 'Error interno del servidor' },
      { status: 500 }
    );
  }
}

/**
 * DELETE /api/appointments/[id]
 * Cancela una cita (soft delete, cambia status a 'cancelled')
 */
export async function DELETE(
  request: NextRequest,
  context: RouteContext
) {
  try {
    const { id } = await context.params;
    const cookieStore = await cookies();
    const supabase = createRouteHandlerClient(cookieStore);

    // Verificar autenticación
    const { data: { session }, error: authError } = await supabase.auth.getSession();

    if (authError || !session) {
      return NextResponse.json(
        { error: 'No autorizado' },
        { status: 401 }
      );
    }

    const userId = session.user.id;

    // Obtener patient_id
    const { data: patient, error: patientError } = await supabase
      .from('patients')
      .select('id')
      .eq('user_id', userId)
      .single();

    if (patientError || !patient) {
      return NextResponse.json(
        { error: 'Paciente no encontrado' },
        { status: 404 }
      );
    }

    // Cancelar la cita (soft delete)
    const { data: cancelledAppointment, error: cancelError } = await supabase
      .from('appointments')
      .update({
        status: 'cancelled',
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .eq('patient_id', patient.id)
      .select()
      .single();

    if (cancelError || !cancelledAppointment) {
      return NextResponse.json(
        { error: 'Cita no encontrada o ya cancelada' },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      message: 'Cita cancelada exitosamente',
      data: mapAppointment(cancelledAppointment as any),
    });
  } catch (error) {
    logger.error('[DELETE /api/appointments/[id]] Error:', error);
    return NextResponse.json(
      { error: 'Error interno del servidor' },
      { status: 500 }
    );
  }
}

/**
 * API Routes para gestión de citas médicas
 * GET /api/appointments - Obtener citas del paciente actual
 * POST /api/appointments - Crear nueva cita
 */

import { NextRequest, NextResponse } from 'next/server';
import { createRouteHandlerClient } from '@autamedica/auth/server';
import { cookies } from 'next/headers';
import type { CreateAppointmentInput } from '@/types/appointment';
import { logger } from '@autamedica/shared';
import { computeEndTime, mapAppointment, mapTypeToDb, type DbAppointmentRow } from './utils';
/**
 * GET /api/appointments
 * Obtiene todas las citas del paciente autenticado
 */
export async function GET(request: NextRequest) {
  try {
    const cookieStore = await cookies();
    const supabase = createRouteHandlerClient(cookieStore);

    // Verificar autenticación
    const { data: { session }, error: authError } = await supabase.auth.getSession();

    if (authError || !session) {
      return NextResponse.json(
        { error: 'No autorizado' },
        { status: 401 }
      );
    }

    const userId = session.user.id;

    // Obtener patient_id del usuario
    const { data: patient, error: patientError } = await supabase
      .from('patients')
      .select('id')
      .eq('user_id', userId)
      .single();

    if (patientError || !patient) {
      return NextResponse.json(
        { error: 'Paciente no encontrado' },
        { status: 404 }
      );
    }

    // Obtener citas del paciente con información del doctor
    const { data: appointments, error: appointmentsError } = await supabase
      .from('appointments')
      .select(`
        *,
        doctor:doctors (
          id,
          first_name,
          last_name,
          specialty,
          profile_picture_url
        )
      `)
      .eq('patient_id', patient.id)
      .order('start_time', { ascending: false });

    if (appointmentsError) {
      logger.error('[GET /api/appointments] Error:', appointmentsError);
      return NextResponse.json(
        { error: 'Error al obtener citas' },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      data: (appointments || []).map(mapAppointment),
    });
  } catch (error) {
    logger.error('[GET /api/appointments] Unexpected error:', error);
    return NextResponse.json(
      { error: 'Error interno del servidor' },
      { status: 500 }
    );
  }
}

/**
 * POST /api/appointments
 * Crea una nueva cita para el paciente autenticado
 */
export async function POST(request: NextRequest) {
  try {
    const cookieStore = await cookies();
    const supabase = createRouteHandlerClient(cookieStore);

    // Verificar autenticación
    const { data: { session }, error: authError } = await supabase.auth.getSession();

    if (authError || !session) {
      return NextResponse.json(
        { error: 'No autorizado' },
        { status: 401 }
      );
    }

    const userId = session.user.id;

    // Obtener patient_id del usuario
    const { data: patient, error: patientError } = await supabase
      .from('patients')
      .select('id')
      .eq('user_id', userId)
      .single();

    if (patientError || !patient) {
      return NextResponse.json(
        { error: 'Paciente no encontrado' },
        { status: 404 }
      );
    }

    // Parsear body de la request
    const body: CreateAppointmentInput = await request.json();

    // Validar campos requeridos
    if (!body.scheduled_at) {
      return NextResponse.json(
        { error: 'El campo scheduled_at es requerido' },
        { status: 400 }
      );
    }

    const startDate = new Date(body.scheduled_at);
    if (Number.isNaN(startDate.getTime())) {
      return NextResponse.json(
        { error: 'scheduled_at no tiene un formato válido' },
        { status: 400 }
      );
    }

    const duration = body.duration_minutes && body.duration_minutes > 0 ? body.duration_minutes : 30;
    const startIso = startDate.toISOString();
    const endIso = computeEndTime(startIso, duration);

    // Crear la cita
    const appointmentData = {
      patient_id: patient.id,
      doctor_id: body.doctor_id || null,
      start_time: startIso,
      end_time: endIso,
      duration_minutes: duration,
      type: mapTypeToDb(body.type || 'telemedicine'),
      status: 'scheduled' as const,
      notes: body.notes || null,
      reason: body.reason || null,
      meeting_url: body.meeting_url || null,
      location: body.location || null,
    };

    const { data: appointment, error: insertError } = await supabase
      .from('appointments')
      .insert(appointmentData)
      .select(`
        *,
        doctor:doctors (
          id,
          first_name,
          last_name,
          specialty,
          profile_picture_url
        )
      `)
      .single();

    if (insertError) {
      logger.error('[POST /api/appointments] Insert error:', insertError);
      return NextResponse.json(
        { error: 'Error al crear la cita', details: insertError.message },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      data: mapAppointment(appointment as DbAppointmentRow),
    }, { status: 201 });
  } catch (error) {
    logger.error('[POST /api/appointments] Unexpected error:', error);
    return NextResponse.json(
      { error: 'Error interno del servidor' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
