    const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
    const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY');
    const admin = createClient(url, serviceKey);

    const prefix = `${userId}/`;
    const { data: objects, error } = await admin.storage.from(BUCKET).list(prefix, { limit: 100, offset: 0 });
    if (error) throw error;

    const list = Array.isArray(objects) ? objects : [];
    return NextResponse.json({ ok: true, data: { files: list.map(o => ({
      name: o.name,
      path: prefix + o.name,
      size: o.metadata?.size ?? null,
      lastModified: o.updated_at ?? null,
      contentType: o.metadata?.mimetype ?? null,
    })) } });
  } catch (e: any) {
    logger.error('[API] files GET error', e);
    return NextResponse.json({ ok: false, error: e?.message || 'internal_error' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const userId = await getUserIdFromRequest();
    if (!userId) return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 });
    const body = await request.json().catch(() => ({}));
    const filename: string | undefined = body?.filename;
    if (!filename) return NextResponse.json({ ok: false, error: 'filename_required' }, { status: 400 });

    const suggestedPath = `${userId}/${Date.now()}-${filename}`;
    // Client will upload using supabase-js (browser) to storage.from(BUCKET).upload(suggestedPath, file)
    return NextResponse.json({ ok: true, data: { bucket: BUCKET, path: suggestedPath } });
  } catch (e: any) {
    logger.error('[API] files POST error', e);
    return NextResponse.json({ ok: false, error: e?.message || 'internal_error' }, { status: 500 });
  }
}

export async function DELETE(request: Request) {
  try {
    const userId = await getUserIdFromRequest();
    if (!userId) return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 });
    const body = await request.json().catch(() => ({}));
    const path: string | undefined = body?.path;
    if (!path?.startsWith(`${userId}/`)) return NextResponse.json({ ok: false, error: 'invalid_path' }, { status: 400 });

    const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
    const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY');
    const admin = createClient(url, serviceKey);
    const { error } = await admin.storage.from(BUCKET).remove([path]);
    if (error) throw error;
    return NextResponse.json({ ok: true });
  } catch (e: any) {
    logger.error('[API] files DELETE error', e);
    return NextResponse.json({ ok: false, error: e?.message || 'internal_error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createServerClient } from '@supabase/ssr';
import { createClient } from '@supabase/supabase-js';
import { ensureClientEnv, ensureServerEnv, logger } from '@autamedica/shared';

export const runtime = 'nodejs';

export async function POST() {
  try {
    const cookieStore = await cookies();
    const anonUrl = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
    const anonKey = ensureClientEnv('NEXT_PUBLIC_SUPABASE_ANON_KEY');
    const supabase = createServerClient(anonUrl, anonKey, {
      cookies: {
        get(name: string) { return cookieStore.get(name)?.value; },
        set() { return undefined; },
        remove() { return undefined; },
      },
    });

    // Try auth via Authorization: Bearer <token> header first (works in dev across ports)
    const authHeader = (await import('next/headers')).headers().get('authorization');
    let userId: string | null = null;
    if (authHeader?.toLowerCase().startsWith('bearer ')) {
      const token = authHeader.slice(7);
      try {
        const adminTmp = createClient(anonUrl, ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY'));
        const { data: userRes, error: userErr } = await adminTmp.auth.getUser(token);
        if (!userErr && userRes?.user) userId = userRes.user.id;
      } catch (_) { void 0 }
    }

    if (!userId) {
      const { data: userData, error: userErr } = await supabase.auth.getUser();
      if (!userErr && userData.user) {
        userId = userData.user.id;
      }
    }

    if (!userId) {
      return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 });
    }
    const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
    const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY');
    const admin = createClient(url, serviceKey);

    // Ensure profiles row (id PK) exists with minimal fields
    try {
      const { data: exists } = await admin
        .from('profiles')
        .select('id')
        .eq('id', userId)
        .maybeSingle();
      if (!exists) {
        await admin
          .from('profiles')
          .insert({ id: userId })
          .throwOnError();
      }
    } catch (e) {
      logger.error('[API] ensure profile failed (profiles)', e as Error);
      return NextResponse.json({ ok: false, error: 'profiles_failed' }, { status: 400 });
    }

    // Optionally ensure patients row exists if table is present
    try {
      await admin.from('patients').upsert({ user_id: userId, active: true }, { onConflict: 'user_id', ignoreDuplicates: false });
    } catch {
      // ignore if table or constraint is different in this instance
    }

    return NextResponse.json({ ok: true });
  } catch (err) {
    logger.error('[API] profile ensure error', err as Error);
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { cookies, headers } from 'next/headers';
import { createServerClient } from '@supabase/ssr';
import { createClient } from '@supabase/supabase-js';
import { ensureClientEnv, ensureServerEnv, logger } from '@autamedica/shared';
import { buildProfileUpdatePayload } from '@/lib/zod/profiles';
import { buildPatientUpdatePayload } from '@/lib/zod/patients';
import { buildPatientContext, persistPatientContextFiles } from '@/lib/ai/context-builder';

export const runtime = 'nodejs';

async function getUserIdFromRequest(): Promise<string | null> {
  const anonUrl = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
  const anonKey = ensureClientEnv('NEXT_PUBLIC_SUPABASE_ANON_KEY');
  const cookieStore = await cookies();
  const supabase = createServerClient(anonUrl, anonKey, {
    cookies: {
      get(name: string) { return cookieStore.get(name)?.value; },
      set() { return undefined; },
      remove() { return undefined; },
    },
  });

  // Prefer bearer token in dev (ports different)
  const authHeader = (await headers()).get('authorization');
  if (authHeader?.toLowerCase().startsWith('bearer ')) {
    const token = authHeader.slice(7);
    try {
      const adminTmp = createClient(anonUrl, ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY'));
      const { data: userRes } = await adminTmp.auth.getUser(token);
      if (userRes?.user) return userRes.user.id;
    } catch (_) { void 0 }
  }

  const { data: userData } = await supabase.auth.getUser();
  return userData.user?.id ?? null;
}

export async function PATCH(request: Request) {
  try {
    const userId = await getUserIdFromRequest();
    if (!userId) return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 });

    const body = await request.json().catch(() => ({}));
    const { profile, patient } = body ?? {};

    const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
    const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY');
    const admin = createClient(url, serviceKey);

    let updatedProfile: any = null;
    let updatedPatient: any = null;

    // Update profiles
    if (profile) {
      const snake = buildProfileUpdatePayload(profile);
      try {
        // First try modern schema
        const upd = await admin.from('profiles').update(snake).eq('id', userId).select('*').single();
        if (upd.error) throw upd.error;
        updatedProfile = upd.data;
      } catch (err: any) {
        // Fallback to legacy: full_name
        const fullName = [profile.firstName, profile.lastName].filter(Boolean).join(' ').trim() || null;
        const legacy = await admin.from('profiles').update({ full_name: fullName }).eq('id', userId).select('*').single();
        if (legacy.error) {
          logger.error('[API] profile update failed', legacy.error);
          return NextResponse.json({ ok: false, error: legacy.error.message || 'profile_update_failed' }, { status: 400 });
        }
        updatedProfile = legacy.data;
      }
    }

    // Update patients (optional)
    if (patient) {
      const snake = buildPatientUpdatePayload(patient) as any;
      try {
        const upd = await admin.from('patients').update(snake).eq('user_id', userId).select('*').maybeSingle();
        if (upd.error) throw upd.error;
        if (!upd.data) {
          // create if missing
          const ins = await admin.from('patients').upsert({ user_id: userId, ...snake }, { onConflict: 'user_id' }).select('*').maybeSingle();
          if (ins.error) throw ins.error;
          updatedPatient = ins.data;
        } else {
          updatedPatient = upd.data;
        }
      } catch (err: any) {
        // Ignore if table not present or columns differ
        logger.warn('[API] patients update skipped:', err?.message || err);
      }
    }

    // Fire-and-forget: resincronizar contexto y archivos personalizados
    try {
      const ctx = await buildPatientContext(userId, admin);
      await persistPatientContextFiles(userId, ctx, admin);
    } catch (e) {
      logger.warn('[API] context resync after profile update failed:', (e as any)?.message || e);
    }

    return NextResponse.json({ ok: true, data: { profile: updatedProfile, patient: updatedPatient } });
  } catch (e: any) {
    logger.error('[API] profile PATCH error', e);
    return NextResponse.json({ ok: false, error: e?.message || 'internal_error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server'
import { cookies } from 'next/headers'
import { createRouteHandlerClient } from '@autamedica/auth/server'
import { logger } from '@autamedica/shared'

export async function POST(request: Request, { params }: { params: { sessionId: string } }) {
  try {
    const cookieStore = await cookies()
    const supabase = createRouteHandlerClient(cookieStore)
    const sessionId = params.sessionId

    const body = await request.json().catch(() => ({})) as { event_type?: string; event_data?: any }
    const eventType = typeof body.event_type === 'string' ? body.event_type.trim() : ''
    const eventData = body.event_data ?? null

    if (!eventType) {
      return NextResponse.json({ ok: false, error: 'event_type_required' }, { status: 400 })
    }

    const res = await supabase
      .from('telemedicine_session_events')
      .insert({
        session_id: sessionId,
        event_type: eventType,
        event_data: eventData,
      })

    if (res.error) throw res.error

    return NextResponse.json({ ok: true })
  } catch (e) {
    logger.error('[Telemedicina] events POST error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { cookies } from 'next/headers'
import { createRouteHandlerClient } from '@autamedica/auth/server'
import { logger, getOptionalClientEnv, ensureServerEnv } from '@autamedica/shared'
import { randomUUID } from 'node:crypto'

const ICE_SERVERS = [
  { urls: 'stun:stun.l.google.com:19302' },
]

function getSignalingUrl(): string {
  const clientUrl = getOptionalClientEnv?.('NEXT_PUBLIC_SIGNALING_SERVER_URL') ?? null
  const serverUrl = getOptionalClientEnv?.('SIGNALING_SERVER_URL') ?? null
  return clientUrl ?? serverUrl ?? 'wss://telemedicina.autamedica.com'
}

type DbTelemedicineSession = {
  id: string
  patient_id: string
  doctor_id: string
  status: string
  scheduled_at: string | null
  started_at: string | null
  ended_at: string | null
  room_id: string | null
  created_at: string
  updated_at: string
}

type SessionPayload = {
  session_id: string
  room_id: string
  status: string
  scheduled_at: string | null
  started_at: string | null
  ended_at: string | null
}

type StartResponse = {
  session: SessionPayload
  signaling: {
    room_id: string
    server_url: string
    ice_servers: Array<{ urls: string | string[]; username?: string; credential?: string }>
  }
}

function mapSession(row: DbTelemedicineSession): SessionPayload {
  return {
    session_id: row.id,
    room_id: row.room_id ?? '',
    status: row.status,
    scheduled_at: row.scheduled_at,
    started_at: row.started_at,
    ended_at: row.ended_at,
  }
}

async function resolvePatientId(supabase: ReturnType<typeof createRouteHandlerClient>, userId: string) {
  const { data, error } = await supabase
    .from('patients')
    .select('id')
    .eq('user_id', userId)
    .single()

  if (error || !data) throw new Error('patient_not_found')
  return data.id as string
}

function sanitizeUuid(input: unknown): string | null {
  if (typeof input === 'string' && input.trim().length > 0) return input.trim()
  return null
}

function getSignalingServiceUrl(): string | null {
  try {
    return ensureServerEnv('SIGNALING_SERVICE_URL')
  } catch {
    return null
  }
}

async function requestLiveKitPayload(
  signalingUrl: string,
  payload: { consultationId: string; patientId: string; doctorId: string }
): Promise<{ token: string; url: string; roomName?: string } | null> {
  try {
    const response = await fetch(`${signalingUrl.replace(/\/$/, '')}/api/consultations/create`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })

    if (!response.ok) {
      const text = await response.text().catch(() => '')
      throw new Error(`signaling_error_${response.status}: ${text}`)
    }

    const json = await response.json()
    const data = json?.data
    if (data?.patientToken && data?.livekitUrl) {
      return {
        token: data.patientToken,
        url: data.livekitUrl,
        roomName: data.roomName,
      }
    }
    return null
  } catch (err) {
    logger.error('[Telemedicina] LiveKit handshake failed', err)
    return null
  }
}

async function markAppointmentStatus(
  supabase: ReturnType<typeof createRouteHandlerClient>,
  appointmentId: string | null,
  status: 'in_progress' | 'completed'
) {
  if (!appointmentId) return
  const updates: Record<string, unknown> = { status }
  if (status === 'completed') {
    updates.updated_at = new Date().toISOString()
  } else if (status === 'in_progress') {
    updates.updated_at = new Date().toISOString()
  }
  await supabase
    .from('appointments')
    .update(updates)
    .eq('id', appointmentId)
}

export async function POST(request: Request) {
  try {
    const cookieStore = await cookies()
    const supabase = createRouteHandlerClient(cookieStore)

    const {
      data: { session: authSession },
    } = await supabase.auth.getSession()

    if (!authSession) {
      return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 })
    }

    const body = await request.json().catch(() => ({})) as { doctor_id?: string; appointment_id?: string }
    const doctorId = sanitizeUuid(body.doctor_id)
    if (!doctorId) {
      return NextResponse.json({ ok: false, error: 'doctor_id_required' }, { status: 400 })
    }

    const patientId = await resolvePatientId(supabase, authSession.user.id)
    const signalingUrl = getSignalingServiceUrl()

    const existing = await supabase
      .from('telemedicine_sessions')
      .select('*')
      .eq('patient_id', patientId)
      .eq('doctor_id', doctorId)
      .eq('status', 'in_progress')
      .limit(1)
      .single()

    if (existing.data) {
      const participantsRes = await supabase
        .from('telemedicine_room_participants')
        .select('*')
        .eq('room_id', existing.data.room_id || '')

      const eventsRes = await supabase
        .from('telemedicine_session_events')
        .select('*')
        .eq('session_id', existing.data.id)
        .order('created_at', { ascending: false })
        .limit(50)

      const livekit = signalingUrl
        ? await requestLiveKitPayload(signalingUrl, {
            consultationId: existing.data.id,
            patientId,
            doctorId,
          })
        : null

      return NextResponse.json({
        ok: true,
        data: {
          session: mapSession(existing.data as DbTelemedicineSession),
          signaling: {
            room_id: existing.data.room_id || '',
            server_url: getSignalingUrl(),
            ice_servers: ICE_SERVERS,
          },
          participants: participantsRes.data ?? [],
          events: eventsRes.data ?? [],
          livekit,
        } satisfies StartResponse,
      })
    }

    const appointmentId = sanitizeUuid(body.appointment_id)
    if (appointmentId) {
      const conflict = await supabase
        .from('telemedicine_sessions')
        .select('id, status')
        .eq('appointment_id', appointmentId)
        .maybeSingle()

      if (conflict.data && conflict.data.status === 'in_progress') {
        return NextResponse.json({ ok: false, error: 'session_already_started' }, { status: 409 })
      }
    }

    const roomId = `room_${Date.now()}_${randomUUID()}`
    const nowIso = new Date().toISOString()

    const insertPayload = {
      appointment_id: appointmentId,
      patient_id: patientId,
      doctor_id: doctorId,
      status: 'in_progress',
      scheduled_at: nowIso,
      started_at: nowIso,
      room_id: roomId,
    }

    const inserted = await supabase
      .from('telemedicine_sessions')
      .insert(insertPayload)
      .select('*')
      .single()

    if (inserted.error || !inserted.data) {
      logger.error('[Telemedicina] Error creando sesión', inserted.error)
      return NextResponse.json({ ok: false, error: 'session_create_failed' }, { status: 500 })
    }

    await markAppointmentStatus(supabase, appointmentId, 'in_progress')

    const livekit = signalingUrl
      ? await requestLiveKitPayload(signalingUrl, {
          consultationId: inserted.data.id,
          patientId,
          doctorId,
        })
      : null

    return NextResponse.json({
      ok: true,
      data: {
        session: mapSession(inserted.data as DbTelemedicineSession),
        signaling: {
          room_id: roomId,
          server_url: getSignalingUrl(),
          ice_servers: ICE_SERVERS,
        },
        participants: [],
        events: [],
        livekit,
      } satisfies StartResponse,
    })
  } catch (e) {
    logger.error('[Telemedicina] POST error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

export async function GET(request: Request) {
  try {
    const cookieStore = await cookies()
    const supabase = createRouteHandlerClient(cookieStore)
    const url = new URL(request.url)
    const sessionId = url.searchParams.get('sessionId')

    const {
      data: { session: authSession },
    } = await supabase.auth.getSession()

    if (!authSession) {
      return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 })
    }

    let query = supabase
      .from('telemedicine_sessions')
      .select('*')

    if (sessionId) {
      query = query.eq('id', sessionId)
    } else {
      query = query
        .or(`patient_id.eq.${authSession.user.id},doctor_id.eq.${authSession.user.id}`)
        .order('created_at', { ascending: false })
        .limit(1)
    }

    const sessionRes = await query.maybeSingle()

    if (sessionRes.error) throw sessionRes.error
    if (!sessionRes.data) {
      return NextResponse.json({ ok: true, data: null })
    }

    const sessionRow = sessionRes.data as DbTelemedicineSession

    const participantsRes = await supabase
      .from('telemedicine_room_participants')
      .select('*')
      .eq('room_id', sessionRow.room_id || '')

    const eventsRes = await supabase
      .from('telemedicine_session_events')
      .select('*')
      .eq('session_id', sessionRow.id)
      .order('created_at', { ascending: false })
      .limit(50)

    if (participantsRes.error) throw participantsRes.error
    if (eventsRes.error) throw eventsRes.error

    const signalingUrl = getSignalingServiceUrl()
    const shouldRequestLivekit =
      signalingUrl &&
      sessionRow.status === 'in_progress' &&
      Boolean(sessionRow.patient_id) &&
      Boolean(sessionRow.doctor_id)

    const livekit = shouldRequestLivekit
      ? await requestLiveKitPayload(signalingUrl!, {
          consultationId: sessionRow.id,
          patientId: String(sessionRow.patient_id),
          doctorId: String(sessionRow.doctor_id),
        })
      : null

    return NextResponse.json({
      ok: true,
      data: {
        session: mapSession(sessionRow),
        participants: participantsRes.data ?? [],
        events: eventsRes.data ?? [],
        signaling: {
          room_id: sessionRow.room_id ?? '',
          server_url: getSignalingUrl(),
          ice_servers: ICE_SERVERS,
        },
        livekit,
      },
    })
  } catch (e) {
    logger.error('[Telemedicina] GET error', e)
    return NextResponse.json({ ok: false, error: 'internal_error' }, { status: 500 })
  }
}

'use client'

import { useEffect, useMemo, useState } from 'react'
import { useRouter } from 'next/navigation'
import { UnifiedVideoCall } from '@autamedica/telemedicine'
import { AuthProvider, useAuth } from '@autamedica/auth/react'
import { getClientEnvOrDefault, logger } from '@autamedica/shared'

interface CallPageClientProps {
  roomId: string
}

const REQUIRE_AUTH = getClientEnvOrDefault('NEXT_PUBLIC_REQUIRE_AUTH', 'false') === 'true'

export function CallPageClient({ roomId }: CallPageClientProps) {
  return (
    <AuthProvider>
      <PatientCallContent roomId={roomId} />
    </AuthProvider>
  )
}

function PatientCallContent({ roomId }: { roomId: string }) {
  const router = useRouter()
  const { session, loading } = useAuth()
  const [isReady, setIsReady] = useState(false)

  // Handlers and memoized values BEFORE early returns (React hooks rules)
  const handleCallEnd = () => {
    router.push('/appointments')
  }

  const handleCallStart = () => {
    // logger.info('[UnifiedVideoCall][patient] start')
  }

  const handleStatusChange = (_status: string) => {
    // logger.info('[UnifiedVideoCall][patient] status:', status)
  }

  const handleError = (error: unknown) => {
    logger.error('[UnifiedVideoCall][patient] error:', error)
  }

  const { userId, userName } = useMemo(() => {
    if (session) {
      return {
        userId: session.user.id,
        userName: session.user.email || 'Paciente'
      }
    }

    return {
      userId: `dev-patient-${roomId}`,
      userName: 'Paciente de prueba'
    }
  }, [session, roomId])

  useEffect(() => {
    if (loading) return

    if (!session) {
      if (REQUIRE_AUTH) {
        const defaultAuthOrigin = window.location.hostname === 'localhost'
          ? 'http://localhost:3000'
          : 'https://www.autamedica.com'
        const authOrigin = getClientEnvOrDefault(
          'NEXT_PUBLIC_APP_URL',
          defaultAuthOrigin
        )
        const loginUrl = new URL('/auth/login', authOrigin)
        loginUrl.searchParams.set('portal', 'patients')
        loginUrl.searchParams.set('returnTo', `${window.location.origin}/call/${roomId}`)
        window.location.href = loginUrl.toString()
      } else {
        logger.warn('[UnifiedVideoCall][patient] sin sesión; usando identidad de desarrollo')
        setIsReady(true)
      }
      return
    }

    if (session.user.role !== 'patient') {
      router.push('/')
      return
    }

    setIsReady(true)
  }, [session, loading, router, roomId])

  if (loading || !isReady) {
    return (
      <div className="min-h-screen bg-[#161b22] flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#4fd1c5] mx-auto mb-4"></div>
          <p className="text-white">Preparando videollamada...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#161b22] overflow-hidden">
      <UnifiedVideoCall
        roomId={roomId}
        userId={userId}
        userType="patient"
        userName={userName}
        theme="patient"
        onCallEnd={handleCallEnd}
        onCallStart={handleCallStart}
        onStatusChange={handleStatusChange}
        onError={handleError}
        className="h-screen"
      />
    </div>
  )
}

