            </select>
          </div>

          {/* Motivo */}
          <div>
            <label className="block text-sm font-medium text-stone-700 mb-2">
              Motivo de la Consulta
            </label>
            <input
              type="text"
              value={formData.reason || ''}
              onChange={(e) =>
                setFormData({ ...formData, reason: e.target.value })
              }
              placeholder="Ej: Consulta general, dolor de cabeza..."
              className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-stone-800 focus:border-transparent"
            />
          </div>

          {/* Notas adicionales */}
          <div>
            <label className="block text-sm font-medium text-stone-700 mb-2">
              Notas Adicionales (opcional)
            </label>
            <textarea
              value={formData.notes || ''}
              onChange={(e) =>
                setFormData({ ...formData, notes: e.target.value })
              }
              rows={3}
              placeholder="Información adicional que el médico deba saber..."
              className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-stone-800 focus:border-transparent resize-none"
            />
          </div>

          {/* Buttons */}
          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              disabled={loading}
              className="flex-1 px-4 py-2 text-stone-700 bg-stone-100 rounded-lg hover:bg-stone-200 transition-colors disabled:opacity-50"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex-1 px-4 py-2 text-white bg-stone-800 rounded-lg hover:bg-stone-900 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? 'Creando...' : 'Crear Cita'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { createCallService } from '@autamedica/telemedicine'
import type { InviteMessage } from '@autamedica/telemedicine'
import { logger } from '@autamedica/shared'

interface IncomingCallHandlerProps {
  patientId: string
  patientName?: string
}

export function IncomingCallHandler({ patientId, patientName: _patientName = 'Paciente' }: IncomingCallHandlerProps) {
  const [incomingCall, setIncomingCall] = useState<InviteMessage | null>(null)
  const [isConnecting, setIsConnecting] = useState(false)
  const router = useRouter()

  useEffect(() => {
    if (!patientId) return

    const callService = createCallService()

    // Subscribe to calls where this patient is the recipient and status is 'ringing'
    const setupCallListener = async () => {
      try {
        // Subscribe to new calls for this patient
        const subscription = callService.subscribeToUserCalls(patientId, 'patient', (call) => {
          logger.info('[IncomingCallHandler] New call received:', call)

          if (call.status === 'ringing') {
            // Transform call data to InviteMessage format for UI compatibility
            const inviteMessage: InviteMessage = {
              type: 'invite',
              callId: call.id,
              roomId: call.room_id,
              from: { doctorId: call.doctor_id, name: 'Doctor' },
              to: { patientId: call.patient_id }
            }
            setIncomingCall(inviteMessage)
          } else if (call.status === 'canceled') {
            // Call was canceled, hide modal
            setIncomingCall(null)
            setIsConnecting(false)
          }
        })

        return subscription
      } catch (error) {
        logger.error('[IncomingCallHandler] Failed to setup call listener:', error)
        return () => {}
      }
    }

    let subscription: (() => void) | null = null
    setupCallListener().then(sub => { subscription = sub })

    return () => {
      if (subscription) subscription()
    }
  }, [patientId])

  const handleAccept = async () => {
    if (!incomingCall) return

    setIsConnecting(true)

    try {
      const callService = createCallService()

      // Update call status to 'accepted' - realtime will handle UI updates
      await callService.updateCallStatus(incomingCall.callId, 'accepted')

      // Navigate to call room
      router.push(`/call/${incomingCall.roomId}?callId=${incomingCall.callId}`)

    } catch (error) {
      logger.error('[IncomingCallHandler] Failed to accept call:', error)
      setIsConnecting(false)
    }
  }

  const handleDecline = async () => {
    if (!incomingCall) return

    try {
      const callService = createCallService()

      // Update call status to 'declined' - realtime will handle UI updates
      await callService.updateCallStatus(incomingCall.callId, 'declined', 'patient_declined')

      // Hide modal immediately for better UX
      setIncomingCall(null)

    } catch (error) {
      logger.error('[IncomingCallHandler] Failed to decline call:', error)
    }
  }

  // Don't render anything if no incoming call
  if (!incomingCall) return null

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full">

        {/* Doctor avatar/icon */}
        <div className="text-center mb-6">
          <div className="w-20 h-20 mx-auto bg-blue-100 rounded-full flex items-center justify-center mb-4">
            <svg className="w-10 h-10 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
            </svg>
          </div>

          <h2 className="text-xl font-semibold text-gray-800 mb-2">
            Llamada entrante
          </h2>

          <p className="text-gray-600">
            {incomingCall.from.name || 'Doctor'} te está llamando
          </p>
        </div>

        {/* Animated call indicator */}
        <div className="flex justify-center mb-6">
          <div className="flex space-x-1">
            <div className="w-2 h-2 bg-green-500 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-green-500 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
            <div className="w-2 h-2 bg-green-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
          </div>
        </div>

        {/* Action buttons */}
        <div className="flex space-x-3">
          <button
            onClick={handleDecline}
            disabled={isConnecting}
            className="flex-1 bg-red-600 hover:bg-red-700 disabled:opacity-50 text-white py-3 px-4 rounded-lg flex items-center justify-center space-x-2"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
            <span>Rechazar</span>
          </button>

          <button
            onClick={handleAccept}
            disabled={isConnecting}
            className="flex-1 bg-green-600 hover:bg-green-700 disabled:opacity-50 text-white py-3 px-4 rounded-lg flex items-center justify-center space-x-2"
          >
            {isConnecting ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                <span>Conectando...</span>
              </>
            ) : (
              <>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
                </svg>
                <span>Aceptar</span>
              </>
            )}
          </button>
        </div>

        {/* Call info */}
        <div className="mt-4 text-center text-xs text-gray-500">
          Llamada ID: {incomingCall.callId.slice(-8)}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { logger } from '@autamedica/shared'
import { patientsEnv } from '@/lib/env'

interface IncomingCall {
  id: string
  roomId: string
  doctorId: string
  doctorName?: string
  timestamp: string
}

interface IncomingCallModalProps {
  onAccept: (callId: string, roomId: string) => void
  onDecline: (callId: string) => void
}

export function IncomingCallModal({ onAccept, onDecline }: IncomingCallModalProps) {
  const [incomingCall, setIncomingCall] = useState<IncomingCall | null>(null)
  const [isVisible, setIsVisible] = useState(false)
  const router = useRouter()

  useEffect(() => {
    // Listen for incoming calls via WebSocket
    const signalingUrl = patientsEnv.signalingUrl
    if (!signalingUrl) return

    // Get current user ID from Supabase session
    const getCurrentUserId = async () => {
      try {
        const { createBrowserClient } = await import('@autamedica/auth')
        const supabase = createBrowserClient()
        const { data: { session } } = await supabase.auth.getSession()
        return session?.user?.id
      } catch (error) {
        logger.error('Error getting user ID:', error)
        return null
      }
    }

    const setupWebSocket = async () => {
      const userId = await getCurrentUserId()
      if (!userId) {
        logger.warn('⚠️ No user ID available for WebSocket connection')
        return
      }

      try {
        const ws = new WebSocket(`${signalingUrl}?userId=${userId}&userType=patient`)

        ws.onopen = () => {
          // logger.info('🔗 Connected to signaling server as patient')
        }

        ws.onmessage = (event) => {
          try {
            const message = JSON.parse(event.data)
            // logger.info('📞 Received signaling message:', message)

            // Handle incoming call invitation
            if (message.type === 'call-invitation') {
              const { callId, roomId, doctorId, doctorName } = message.data

              setIncomingCall({
                id: callId,
                roomId,
                doctorId,
                doctorName: doctorName || 'Doctor',
                timestamp: new Date().toISOString()
              })
              setIsVisible(true)

              // Auto-dismiss after 30 seconds
              setTimeout(() => {
                setIsVisible(false)
                setIncomingCall(null)
              }, 30000)
            }

            // Handle call cancellation
            if (message.type === 'call-cancelled') {
              setIsVisible(false)
              setIncomingCall(null)
            }

          } catch (error) {
            logger.error('Error parsing signaling message:', error)
          }
        }

        ws.onclose = (event) => {
          logger.info('🔌 Disconnected from signaling server', {
            code: event.code,
            reason: event.reason
          })
          // Only reconnect if it's not a permanent failure
          if (event.code !== 1000 && event.code !== 1001) {
            setTimeout(setupWebSocket, 5000)
          }
        }

        ws.onerror = (error) => {
          logger.warn('⚠️ WebSocket connection failed. Signaling server may be unavailable.', {
            url: signalingUrl,
            error: error
          })
        }

        return ws
      } catch (error) {
        logger.warn('⚠️ Failed to create WebSocket connection:', {
          url: signalingUrl,
          error: error instanceof Error ? error.message : String(error)
        })
      }
    }

    setupWebSocket()
  }, [])

  const handleAccept = async () => {
    if (!incomingCall) return

    try {
      // Update call status to 'accepted' via Edge Function
      const { createBrowserClient } = await import('@autamedica/auth')
      const supabase = createBrowserClient()
      const { data: { session } } = await supabase.auth.getSession()

      if (!session?.access_token) {
        logger.error('No session token available')
        return
      }

      const response = await fetch(`${patientsEnv.supabase.url}/functions/v1/update-call-status`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${session.access_token}`,
          'Content-Type': 'application/json',
          'apikey': patientsEnv.supabase.anonKey,
        },
        body: JSON.stringify({
          callId: incomingCall.id,
          status: 'accepted',
          reason: 'Patient accepted the call'
        })
      })

      if (response.ok) {
        // logger.info('✅ Call accepted successfully')

        // Close modal
        setIsVisible(false)

        // Navigate to call page
        router.push(`/call/${incomingCall.roomId}?callId=${incomingCall.id}`)

        // Notify parent component
        onAccept(incomingCall.id, incomingCall.roomId)
      } else {
        logger.error('❌ Failed to accept call:', await response.text())
      }

    } catch (error) {
      logger.error('❌ Error accepting call:', error)
    } finally {
      setIncomingCall(null)
    }
  }

  const handleDecline = async () => {
    if (!incomingCall) return

    try {
      // Update call status to 'declined' via Edge Function
      const { createBrowserClient } = await import('@autamedica/auth')
      const supabase = createBrowserClient()
      const { data: { session } } = await supabase.auth.getSession()

      if (!session?.access_token) {
        logger.error('No session token available')
        return
      }

      const response = await fetch(`${patientsEnv.supabase.url}/functions/v1/update-call-status`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${session.access_token}`,
          'Content-Type': 'application/json',
          'apikey': patientsEnv.supabase.anonKey,
        },
        body: JSON.stringify({
          callId: incomingCall.id,
          status: 'declined',
          reason: 'Patient declined the call'
        })
      })

      if (response.ok) {
        // logger.info('✅ Call declined successfully')

        // Notify parent component
        onDecline(incomingCall.id)
      } else {
        logger.error('❌ Failed to decline call:', await response.text())
      }

    } catch (error) {
      logger.error('❌ Error declining call:', error)
    } finally {
      setIsVisible(false)
      setIncomingCall(null)
    }
  }

  if (!isVisible || !incomingCall) {
    return null
  }

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full mx-auto overflow-hidden animate-bounce">
        {/* Header */}
        <div className="bg-gradient-to-r from-blue-500 to-blue-600 text-white p-6 text-center">
          <div className="w-20 h-20 bg-white/20 rounded-full mx-auto mb-4 flex items-center justify-center">
            <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M18 10c0 3.866-3.582 7-8 7a8.841 8.841 0 01-4.083-.98L2 17l1.338-3.123C2.493 12.767 2 11.434 2 10c0-3.866 3.582-7 8-7s8 3.134 8 7zM7 9H5v2h2V9zm8 0h-2v2h2V9zM9 9h2v2H9V9z" clipRule="evenodd" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold">Llamada Entrante</h2>
          <p className="text-blue-100 mt-1">Video consulta médica</p>
        </div>

        {/* Content */}
        <div className="p-6 text-center">
          <div className="mb-6">
            <div className="w-16 h-16 bg-gray-200 rounded-full mx-auto mb-3 flex items-center justify-center">
              <svg className="w-8 h-8 text-gray-500" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" />
              </svg>
            </div>
            <h3 className="text-xl font-semibold text-gray-900">
              Dr. {incomingCall.doctorName}
            </h3>
            <p className="text-gray-600 text-sm mt-1">
              Quiere iniciar una video consulta
            </p>
          </div>

          {/* Call Info */}
          <div className="bg-gray-50 rounded-lg p-4 mb-6">
            <div className="text-xs text-gray-500 mb-1">ID de Llamada</div>
            <div className="font-mono text-sm text-gray-700 break-all">
              {incomingCall.id.substring(0, 8)}...
            </div>
          </div>

          {/* Action Buttons */}
          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={handleDecline}
              className="bg-red-500 hover:bg-red-600 text-white font-semibold py-3 px-6 rounded-xl transition-colors flex items-center justify-center space-x-2"
            >
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M3.707 2.293a1 1 0 00-1.414 1.414l6.921 6.922c.05.062.105.118.168.167l6.91 6.911a1 1 0 001.415-1.414l-.675-.675a9.001 9.001 0 00-.668-11.982C14.729 1.1 12.486 0 10 0C7.515 0 5.271 1.1 3.636 2.636L3.707 2.293z" clipRule="evenodd" />
              </svg>
              <span>Rechazar</span>
            </button>

            <button
              onClick={handleAccept}
              className="bg-green-500 hover:bg-green-600 text-white font-semibold py-3 px-6 rounded-xl transition-colors flex items-center justify-center space-x-2"
            >
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                <path d="M2 3a1 1 0 011-1h2.153a1 1 0 01.986.836l.74 4.435a1 1 0 01-.54 1.06l-1.548.773a11.037 11.037 0 006.105 6.105l.774-1.548a1 1 0 011.059-.54l4.435.74a1 1 0 01.836.986V17a1 1 0 01-1 1h-2C7.82 18 2 12.18 2 5V3z" />
              </svg>
              <span>Aceptar</span>
            </button>
          </div>

          {/* Timeout indicator */}
          <div className="mt-4 text-xs text-gray-500">
            La llamada se cancelará automáticamente en 30 segundos
          </div>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useRef, useEffect } from 'react';
import { Send, User, Bot, Loader2, Sparkles } from 'lucide-react';
import { usePatientScreenings } from '@/hooks/usePatientScreenings';
import { getONNXService, initializeONNX } from '@/lib/ai/onnx-service';
import type { PatientContext } from '@/lib/ai/medical-qa';
import { logger } from '@autamedica/shared';
import { usePatientSession } from '@/hooks/usePatientSession';
import { computeAgeFromIso, normalizeGender } from '@/lib/demographics';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  processingTime?: number;
  confidence?: number;
}

export function AutaChatbot() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: '¡Hola! Soy **Auta**, tu asistente de salud inteligente potenciada por IA. Tengo acceso completo a tu historial médico, medicamentos, citas y screenings preventivos. ¿En qué puedo ayudarte hoy? 🏥',
      timestamp: new Date(),
    },
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [aiReady, setAiReady] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Construir contexto del paciente desde datos reales
  const { user, profile } = usePatientSession();

  // Estados del servidor
  const [serverName, setServerName] = useState<string | null>(null);
  const [serverEmail, setServerEmail] = useState<string | null>(null);
  const [serverBirthDate, setServerBirthDate] = useState<string | null>(null);
  const [serverGender, setServerGender] = useState<string | null>(null);
  const [serverBloodType, setServerBloodType] = useState<string | null>(null);
  const [serverHeightCm, setServerHeightCm] = useState<number | null>(null);
  const [serverWeightKg, setServerWeightKg] = useState<number | null>(null);
  const [userPatterns, setUserPatterns] = useState<Array<{ pattern: string; intent: string; active?: boolean }>>([]);
  const [userFaqs, setUserFaqs] = useState<Array<{ question: string; answer: string; active?: boolean }>>([]);

  // Obtener datos del paciente
  // Derivar edad y género reales para screenings
  const realAge = computeAgeFromIso(serverBirthDate) ?? computeAgeFromIso((profile as any)?.birthDate) ?? 52;
  const realGender = normalizeGender(serverGender || (profile as any)?.gender) ?? 'male';
  const { screenings, stats, achievements } = usePatientScreenings(realAge, realGender);

  // Inicializar ONNX service
  useEffect(() => {
    const init = async () => {
      try {
        await initializeONNX();
        setAiReady(true);
        // logger.info('✅ Auta AI initialized with ONNX');
      } catch (error) {
        const msg = (error as any)?.message || String(error || '');
        logger.warn(`Auta ONNX init falló (fallback): ${msg}`);
        setAiReady(true); // Continuar con modo fallback
      }
    };
    init();
  }, []);

  // Cargar contexto del servidor (summary) y, si está vacío, intentar sincronizar una vez
  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const res = await fetch('/api/ai/context', { cache: 'no-store' });
        if (res.ok) {
          const json = await res.json();
          const s = json?.data?.summary;
          if (!cancelled && s) {
            setServerName(typeof s.name === 'string' && s.name.trim() ? s.name : null);
            setServerEmail(typeof s.email === 'string' && s.email.trim() ? s.email : null);
            setServerBirthDate(s.birthDate ?? null)
            setServerGender(s.gender ?? null)
            setServerBloodType(s.bloodType ?? null)
            setServerHeightCm(typeof s.heightCm === 'number' ? s.heightCm : (typeof s.heightCm === 'string' ? Number(s.heightCm) : null))
            setServerWeightKg(typeof s.weightKg === 'number' ? s.weightKg : (typeof s.weightKg === 'string' ? Number(s.weightKg) : null))
          }
          // Si faltan datos clave, intentar sincronizar una vez
          if ((!s?.name || !s?.email) && !cancelled) {
            try {
              const sync = await fetch('/api/ai/context/sync', { method: 'POST' });
              if (sync.ok) {
                const again = await fetch('/api/ai/context', { cache: 'no-store' });
                if (again.ok) {
                  const next = await again.json();
                  const ns = next?.data?.summary;
                  if (!cancelled && ns) {
                    setServerName(typeof ns.name === 'string' && ns.name.trim() ? ns.name : null);
                    setServerEmail(typeof ns.email === 'string' && ns.email.trim() ? ns.email : null);
                    setServerBirthDate(ns.birthDate ?? null)
                    setServerGender(ns.gender ?? null)
                    setServerBloodType(ns.bloodType ?? null)
                    setServerHeightCm(typeof ns.heightCm === 'number' ? ns.heightCm : (typeof ns.heightCm === 'string' ? Number(ns.heightCm) : null))
                    setServerWeightKg(typeof ns.weightKg === 'number' ? ns.weightKg : (typeof ns.weightKg === 'string' ? Number(ns.weightKg) : null))
                  }
                }
              }
            } catch {}
          }
        }
      } catch (e) {
        logger.warn('No se pudo cargar contexto del servidor', e);
      }
      // Cargar patrones y FAQs del usuario
      try {
        const res2 = await fetch('/api/ai/patterns', { cache: 'no-store' })
        if (res2.ok) {
          const json = await res2.json()
          if (!cancelled) {
            const ps = Array.isArray(json?.data?.patterns) ? json.data.patterns : []
            const fs = Array.isArray(json?.data?.faqs) ? json.data.faqs : []
            setUserPatterns(ps.map((p: any) => ({ pattern: String(p.pattern || ''), intent: String(p.intent || ''), active: p.active !== false })))
            setUserFaqs(fs.map((f: any) => ({ question: String(f.question || ''), answer: String(f.answer || ''), active: f.active !== false })))
          }
        }
      } catch (e) {
        logger.warn('No se pudieron cargar patrones/FAQs', e)
      }
    };
    load();
    return () => { cancelled = true };
  }, []);
  const computedName = [profile?.firstName, profile?.lastName].filter(Boolean).join(' ').trim();
  const metaName = (user?.user_metadata as any)?.full_name as string | undefined;
  const emailLocal = user?.email?.split('@')[0];
  const fallbackName = computedName || metaName || emailLocal || null;
  const fallbackEmail = user?.email || null;
  const userName = serverName ?? fallbackName;
  const userEmail = serverEmail ?? fallbackEmail;

  const buildPatientContext = (): PatientContext => {
    return {
      profile: {
        name: userName,
        email: userEmail,
      },
      demographics: {
        birthDate: serverBirthDate,
        gender: serverGender,
        bloodType: serverBloodType,
        heightCm: serverHeightCm,
        weightKg: serverWeightKg,
      },
      medications: [
        {
          name: 'Lisinopril',
          dosage: '10mg',
          frequency: '1 vez al día',
          nextDose: '8:00 AM'
        },
        {
          name: 'Metformina',
          dosage: '500mg',
          frequency: '2 veces al día',
          nextDose: '2:00 PM'
        },
      ],
      vitals: {
        bloodPressure: { systolic: 120, diastolic: 80, date: 'Hace 2 horas' },
        heartRate: { bpm: 72, date: 'Hace 2 horas' }
      },
      appointments: [
        { date: '15 de octubre', doctor: 'Dr. García', specialty: 'Cardiología', status: 'scheduled' },
        { date: '20 de octubre', doctor: 'Dr. Rodríguez', specialty: 'Urología', status: 'scheduled' },
      ],
      screenings: screenings.map(s => ({
        name: s.title,
        status: s.status === 'overdue' ? 'due' : s.status === 'due_soon' ? 'upcoming' : 'completed',
        lastCompleted: s.last_done_date,
        nextDue: s.next_due_date
      })),
      allergies: ['Penicilina'],
      progress: {
        level: Math.floor(achievements.filter(a => a.earned).length / 2) + 1,
        streak: 15,
        completedScreenings: stats.upToDate,
        totalScreenings: stats.total
      }
    };
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Procesar query con ONNX AI Service
  const handleSend = async () => {
    if (!input.trim() || !aiReady) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    const query = input;
    setInput('');
    setIsTyping(true);

    try {
      const patientContext = buildPatientContext();

      // 1) Intento rápido: FAQs del usuario (respuesta directa)
      const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/\p{Diacritic}+/gu, '')
      const qn = norm(query)
      const faq = userFaqs.find(f => f.active !== false && qn.includes(norm(f.question)))
      if (faq) {
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: faq.answer,
          timestamp: new Date(),
        }
        // Registrar telemetría
        fetch('/api/ai/telemetry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: query, intent: 'faq', confidence: 0.99, usedPattern: true, replyPreview: faq.answer.slice(0, 140) }) }).catch(() => {})
        // Simular typing breve
        setTimeout(() => {
          setMessages(prev => [...prev, assistantMessage])
          setIsTyping(false)
        }, Math.min(Math.max(faq.answer.length * 3, 300), 1000))
        return
      }

      // 2) Intento con patrones del usuario → clasificación fija
      const pat = userPatterns.find(p => p.active !== false && qn.includes(norm(p.pattern)))
      if (pat) {
        const classification = { intent: pat.intent as any, confidence: 0.99, keywords: [] }
        const response = medicalQA.generateResponse(classification, patientContext)
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: response.text,
          timestamp: new Date(),
          confidence: classification.confidence,
        }
        fetch('/api/ai/telemetry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: query, intent: classification.intent, confidence: classification.confidence, usedPattern: true, replyPreview: response.text.slice(0, 140) }) }).catch(() => {})
        const typingDelay = Math.min(Math.max(response.text.length * 5, 400), 1200)
        setTimeout(() => {
          setMessages(prev => [...prev, assistantMessage])
          setIsTyping(false)
        }, typingDelay)
        return
      }

      // 3) Fallback: ONNX/Reglas
      const onnxService = getONNXService();
      const { response, classification, processingTime } = await onnxService.processQuery(query, patientContext);

      // Crear mensaje de respuesta
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text,
        timestamp: new Date(),
        processingTime,
        confidence: classification.confidence
      };

      // Telemetría
      fetch('/api/ai/telemetry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: query, intent: classification.intent, confidence: classification.confidence, usedPattern: false, replyPreview: response.text.slice(0, 140) }) }).catch(() => {})

      // Simular typing natural delay
      const typingDelay = Math.min(Math.max(response.text.length * 5, 500), 1500);
      setTimeout(() => {
        setMessages(prev => [...prev, assistantMessage]);
        setIsTyping(false);

        // Log para debugging (solo en desarrollo)
        if (process.env.NODE_ENV === 'development') {
          logger.info('🤖 Auta AI Response:', {
            intent: classification.intent,
            confidence: classification.confidence,
            processingTime: `${processingTime.toFixed(2)}ms`,
            keywords: classification.keywords
          });
        }
      }, typingDelay);

    } catch (error) {
      logger.error('Error processing query:', error);

      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: '⚠️ Lo siento, tuve un problema procesando tu pregunta. ¿Podrías reformularla?',
        timestamp: new Date(),
      };

      setTimeout(() => {
        setMessages(prev => [...prev, errorMessage]);
        setIsTyping(false);
      }, 500);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-full flex-col">
      {/* AI Status Header */}
      <div className="border-b border-stone-200 bg-gradient-to-r from-stone-50 to-white px-4 py-2">
        <div className="flex items-center gap-2">
          <Sparkles className={`h-4 w-4 ${aiReady ? 'text-green-600' : 'text-stone-400'}`} />
          <span className="text-xs font-medium text-stone-700">
            {aiReady ? 'IA Médica Activa' : 'Inicializando IA...'}
          </span>
          {aiReady && (
            <span className="ml-auto text-[10px] text-stone-500">
              Desarrollada por E.M Medicina UBA
            </span>
          )}
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 space-y-4 overflow-y-auto p-4">
        {messages.map((message) => (
          <div
            key={message.id}
            className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`flex max-w-[85%] gap-2 ${message.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
              {/* Avatar */}
              <div
                className={`flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full ${
                  message.role === 'user'
                    ? 'bg-stone-200 text-stone-700'
                    : 'bg-gradient-to-br from-stone-600 to-stone-800 text-white'
                }`}
              >
                {message.role === 'user' ? (
                  <User className="h-4 w-4" />
                ) : (
                  <Bot className="h-4 w-4" />
                )}
              </div>

              {/* Message bubble */}
              <div
                className={`rounded-2xl px-4 py-2.5 ${
                  message.role === 'user'
                    ? 'bg-stone-800 text-white'
                    : 'border border-stone-200 bg-white text-stone-900'
                }`}
              >
                <div
                  className="whitespace-pre-wrap text-sm"
                  dangerouslySetInnerHTML={{
                    __html: message.content
                      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                      .replace(/\n/g, '<br />')
                  }}
                />
                <p className={`mt-1 text-[10px] ${message.role === 'user' ? 'text-white/60' : 'text-stone-500'}`}>
                  {message.timestamp.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}
                </p>
