'use client'

import React, { useEffect, useState } from 'react'
import { Camera, Mic, Monitor, RefreshCw } from 'lucide-react'

interface MediaPickerProps {
  onMediaReady: (stream: MediaStream) => void
  onError?: (error: Error) => void
}

export default function MediaPicker({ onMediaReady, onError }: MediaPickerProps) {
  const [cameras, setCameras] = useState<MediaDeviceInfo[]>([])
  const [microphones, setMicrophones] = useState<MediaDeviceInfo[]>([])
  const [selectedCamera, setSelectedCamera] = useState<string>('')
  const [selectedMic, setSelectedMic] = useState<string>('')
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string>('')
  const [useScreenShare, setUseScreenShare] = useState(false)

  // Load saved preferences
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const savedCamera = localStorage.getItem('am_video_device')
      const savedMic = localStorage.getItem('am_audio_device')
      if (savedCamera) setSelectedCamera(savedCamera)
      if (savedMic) setSelectedMic(savedMic)
    }
  }, [])

  // Enumerate devices
  const loadDevices = async () => {
    try {
      // Request permissions first to get device labels
      await navigator.mediaDevices.getUserMedia({ audio: true, video: true })
        .then(s => s.getTracks().forEach(t => t.stop()))
        .catch(() => {}) // Ignore if fails, just try to enumerate

      const devices = await navigator.mediaDevices.enumerateDevices()

      const cams = devices.filter(d => d.kind === 'videoinput')
      const mics = devices.filter(d => d.kind === 'audioinput')

      setCameras(cams)
      setMicrophones(mics)

      // Auto-select first device if none selected
      if (!selectedCamera && cams.length > 0) {
        setSelectedCamera(cams[0].deviceId)
      }
      if (!selectedMic && mics.length > 0) {
        setSelectedMic(mics[0].deviceId)
      }
    } catch (err) {
      logger.error('Error enumerating devices:', err)
      setError('No se pudieron detectar dispositivos')
    }
  }

  useEffect(() => {
    loadDevices()

    // Listen for device changes
    navigator.mediaDevices.addEventListener('devicechange', loadDevices)
    return () => {
      navigator.mediaDevices.removeEventListener('devicechange', loadDevices)
    }
  }, [])

  // Progressive constraints fallback
  const getMediaWithFallback = async () => {
    setIsLoading(true)
    setError('')

    // Define progressive fallback constraints
    const constraints: MediaStreamConstraints[] = [
      // Try selected devices first
      {
        audio: selectedMic ? { deviceId: { exact: selectedMic } } : true,
        video: selectedCamera ? { deviceId: { exact: selectedCamera } } : true
      },
      // Try any devices
      {
        audio: true,
        video: true
      },
      // Try with lower resolution
      {
        audio: true,
        video: { width: { ideal: 640 }, height: { ideal: 480 } }
      },
      // Try front camera specifically
      {
        audio: true,
        video: { facingMode: 'user' }
      },
      // Try audio only
      {
        audio: true,
        video: false
      }
    ]

    for (const constraint of constraints) {
      try {
        // logger.info('Trying constraints:', constraint)
        const stream = await navigator.mediaDevices.getUserMedia(constraint)

        // Save successful device selection
        if (selectedCamera) localStorage.setItem('am_video_device', selectedCamera)
        if (selectedMic) localStorage.setItem('am_audio_device', selectedMic)

        onMediaReady(stream)
        setIsLoading(false)
        setError('')
        return
      } catch (err: any) {
        logger.error('Failed with constraint:', constraint, err)

        // Continue trying if it's a constraint error
        if (err.name === 'OverconstrainedError' || err.name === 'NotFoundError') {
          continue
        }

        // For AbortError or NotReadableError, device might be in use
        if (err.name === 'AbortError' || err.name === 'NotReadableError') {
          setError('La cámara está siendo usada por otra aplicación')
          continue
        }
      }
    }

    // All constraints failed
    setError('No se pudo acceder a la cámara/micrófono')
    setIsLoading(false)
    onError?.(new Error('Media access failed'))
  }

  // Screen share as fallback
  const startScreenShare = async () => {
    setIsLoading(true)
    setError('')

    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        video: true,
        audio: false
      })

      // Try to add audio from microphone
      if (selectedMic) {
        try {
          const audioStream = await navigator.mediaDevices.getUserMedia({
            audio: selectedMic ? { deviceId: { exact: selectedMic } } : true,
            video: false
          })

          // Combine streams
          audioStream.getAudioTracks().forEach(track => {
            stream.addTrack(track)
          })
        } catch (err) {
          // logger.info('Could not add audio to screen share:', err)
        }
      }

      onMediaReady(stream)
      setIsLoading(false)
      setError('')
    } catch (err: any) {
      setError('No se pudo compartir la pantalla')
      setIsLoading(false)
      onError?.(err)
    }
  }

  return (
    <div className="bg-white rounded-lg shadow-lg p-4 space-y-4">
      <h3 className="font-semibold text-gray-800">Configuración de Medios</h3>

      {error && (
        <div className="bg-red-100 border border-red-400 text-red-700 px-3 py-2 rounded text-sm">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Camera selector */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            <Camera className="inline w-4 h-4 mr-1" />
            Cámara
          </label>
          <select
            value={selectedCamera}
            onChange={(e) => setSelectedCamera(e.target.value)}
            disabled={useScreenShare || cameras.length === 0}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Seleccionar cámara...</option>
            {cameras.map(cam => (
              <option key={cam.deviceId} value={cam.deviceId}>
                {cam.label || `Cámara ${cam.deviceId.substring(0, 8)}`}
              </option>
            ))}
          </select>
        </div>

        {/* Microphone selector */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            <Mic className="inline w-4 h-4 mr-1" />
            Micrófono
          </label>
          <select
            value={selectedMic}
            onChange={(e) => setSelectedMic(e.target.value)}
            disabled={microphones.length === 0}
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Seleccionar micrófono...</option>
            {microphones.map(mic => (
              <option key={mic.deviceId} value={mic.deviceId}>
                {mic.label || `Micrófono ${mic.deviceId.substring(0, 8)}`}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Screen share option */}
      <label className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          checked={useScreenShare}
          onChange={(e) => setUseScreenShare(e.target.checked)}
          className="rounded"
        />
        <Monitor className="w-4 h-4" />
        Usar compartir pantalla en lugar de cámara
      </label>

      {/* Action buttons */}
      <div className="flex gap-2">
        <button
          onClick={useScreenShare ? startScreenShare : getMediaWithFallback}
          disabled={isLoading}
          className={`flex-1 px-4 py-2 rounded-md text-white font-medium transition-colors ${
            isLoading
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700'
          }`}
        >
          {isLoading ? (
            <>
              <RefreshCw className="inline w-4 h-4 mr-2 animate-spin" />
              Conectando...
            </>
          ) : useScreenShare ? (
            <>
              <Monitor className="inline w-4 h-4 mr-2" />
              Compartir Pantalla
            </>
          ) : (
            <>
              <Camera className="inline w-4 h-4 mr-2" />
              Activar Cámara
            </>
          )}
        </button>

        <button
          onClick={loadDevices}
          className="px-3 py-2 border border-gray-300 rounded-md hover:bg-gray-50"
          title="Recargar dispositivos"
        >
          <RefreshCw className="w-4 h-4" />
        </button>
      </div>

      {/* Audio only option */}
      <div className="text-center">
        <button
          onClick={() => {
            const getAudioOnly = async () => {
              setIsLoading(true)
              setError('')
              try {
                const audioStream = await navigator.mediaDevices.getUserMedia({
                  audio: selectedMic ? { deviceId: { exact: selectedMic } } : true,
                  video: false
                })
                onMediaReady(audioStream)
                setIsLoading(false)
              } catch (err: any) {
                setError('No se pudo acceder al micrófono')
                setIsLoading(false)
                onError?.(err)
              }
            }
            getAudioOnly()
          }}
          disabled={isLoading}
          className="text-sm text-gray-600 hover:text-blue-600 underline"
        >
          <Mic className="inline w-4 h-4 mr-1" />
          Continuar solo con audio (sin video)
        </button>
      </div>

      {/* Help text */}
      <div className="text-xs text-gray-500">
        {cameras.length === 0 && microphones.length === 0 ? (
          <p>No se detectaron dispositivos. Verifica los permisos del navegador.</p>
        ) : (
          <p>
            Si la cámara falla, intenta: 1) Cerrar otras apps que la usen, 2) Usar compartir pantalla,
            3) Reiniciar el navegador
          </p>
        )}
      </div>
    </div>
  )
}

'use client'

import React, { useState, useEffect, useRef, useCallback } from 'react'
import {
  Video,
  VideoOff,
  Mic,
  MicOff,
  PhoneOff,
  PhoneIncoming,
  Phone,
  User,
  Clock,
  X,
  Settings
} from 'lucide-react'
import MediaPicker from './MediaPicker'

interface SimplePatientVideoCallProps {
  roomId: string
  patientName?: string
}

type CallStatus = 'waiting' | 'incoming' | 'connecting' | 'connected' | 'ended'

export default function SimplePatientVideoCall({
  roomId,
  patientName: _patientName = 'Paciente'
}: SimplePatientVideoCallProps) {
  const [callStatus, setCallStatus] = useState<CallStatus>('waiting')
  const [isMuted, setIsMuted] = useState(false)
  const [isVideoOff, setIsVideoOff] = useState(false)
  const [callDuration, setCallDuration] = useState(0)
  const [stream, setStream] = useState<MediaStream | null>(null)
  const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null)
  const [callerName, setCallerName] = useState('Dr. García')
  const [showMediaPicker, setShowMediaPicker] = useState(false)
  const [mediaError, setMediaError] = useState(false)

  // Stable userId stored in sessionStorage
  const [userId] = useState(() => {
    if (typeof window === 'undefined') return `patient-${Date.now()}`
    const stored = sessionStorage.getItem('patientUserId')
    if (stored) return stored
    const newId = `patient-${Date.now()}-${Math.random().toString(36).substring(7)}`
    sessionStorage.setItem('patientUserId', newId)
    return newId
  })
  const [currentOffer, setCurrentOffer] = useState<RTCSessionDescriptionInit | null>(null)

  const localVideoRef = useRef<HTMLVideoElement>(null)
  const remoteVideoRef = useRef<HTMLVideoElement>(null)
  const timerRef = useRef<NodeJS.Timeout | null>(null)
  const ringtoneRef = useRef<HTMLAudioElement | null>(null)
  const peerConnectionRef = useRef<RTCPeerConnection | null>(null)
  const seenMessagesRef = useRef(new Set<string>())
  const pendingIceCandidatesRef = useRef<RTCIceCandidateInit[]>([])

  // Ensure remote stream is rendered once the element exists
  useEffect(() => {
    const remoteVideoEl = remoteVideoRef.current
    if (!remoteVideoEl) return

    remoteVideoEl.srcObject = remoteStream
    if (remoteStream) {
      remoteVideoEl
        .play()
        .catch(() => {
          /* autoplay might be blocked – ignore */
        })
    }
  }, [remoteStream, callStatus])

  // Crear peer connection
  const createPeerConnection = () => {
    // Close existing connection if any
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close()
      peerConnectionRef.current = null
    }

    pendingIceCandidatesRef.current.length = 0

    const pc = new RTCPeerConnection({
      iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'stun:stun1.l.google.com:19302' }
      ],
      iceTransportPolicy: 'all',
      bundlePolicy: 'max-bundle',
      rtcpMuxPolicy: 'require'
    })

    // Handle incoming remote stream
    pc.ontrack = (event) => {
      // logger.info('Received remote stream track:', event.track.kind)
      if (event.streams?.[0]) {
        // logger.info('Setting remote stream')
        setRemoteStream(event.streams[0])
        if (remoteVideoRef.current) {
          remoteVideoRef.current.srcObject = event.streams[0]
        }
      }
    }

    // Handle ICE candidates
    pc.onicecandidate = async (event) => {
      if (event.candidate) {
        // logger.info('Sending ICE candidate')
        const signalingBase = 'http://localhost:8787'
        try {
          await fetch(`${signalingBase}/api/message`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              from: userId,
              roomId,
              type: 'ice-candidate',
              data: { candidate: event.candidate }
            })
          })
        } catch (error) {
          logger.error('Error sending ICE candidate:', error)
        }
      }
    }

    // Connection state monitoring
    pc.onconnectionstatechange = () => {
      // logger.info('Connection state:', pc.connectionState)
      if (pc.connectionState === 'failed') {
        logger.error('WebRTC connection failed')
        setMediaError(true)
      }
    }

    peerConnectionRef.current = pc
    return pc
  }

  // Conectar al servidor de señalización HTTP
  useEffect(() => {
    const signalingBase = 'http://localhost:8787'
    let pollInterval: NodeJS.Timeout | null = null
    let isActive = true

    // Join room
    const joinRoom = async () => {
      if (!isActive) return

      try {
        const response = await fetch(`${signalingBase}/api/join`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            userId,
            roomId,
            userType: 'patient'
          })
        })

        if (response.ok && isActive) {
          // logger.info('Conectado a la sala de espera:', roomId)
          startPolling()
        }
      } catch (error) {
        logger.error('Error al unirse a la sala:', error)
      }
    }

    // Poll for messages
    const startPolling = () => {
      if (pollInterval) clearInterval(pollInterval)

      pollInterval = setInterval(async () => {
        if (!isActive) return

        try {
          const response = await fetch(
            `${signalingBase}/api/poll?userId=${userId}&roomId=${roomId}`
          )

          if (response.ok && isActive) {
            const data = await response.json()
            if (data.messages && data.messages.length > 0) {
              for (const msg of data.messages) {
                // Ignore our own messages and user events
                if (msg.from === userId || msg.type === 'user-joined' || msg.type === 'user-left') {
                  continue
                }

                // De-duplicate messages
                const msgKey = `${msg.type}-${msg.from}-${msg.timestamp}`
                if (seenMessagesRef.current.has(msgKey)) {
                  continue
                }
                seenMessagesRef.current.add(msgKey)

                // Clean old messages from seen set (keep last 100)
                if (seenMessagesRef.current.size > 100) {
                  const entries = Array.from(seenMessagesRef.current)
                  seenMessagesRef.current = new Set(entries.slice(-50))
                }

                // logger.info('Mensaje recibido:', msg)

                // Recibir llamada entrante
                if (msg.type === 'incoming-call') {
                  setCallStatus('incoming')
                  setCallerName(msg.data?.doctorName || 'Dr. García')
                  // Reproducir sonido de llamada
                  playRingtone()
                }

                // Handle WebRTC offer from doctor
                if (msg.type === 'webrtc-offer') {
                  // logger.info('Received WebRTC offer')
                  setCurrentOffer(msg.data.offer)
                }

                // Handle ICE candidates from doctor
                if (msg.type === 'ice-candidate' && peerConnectionRef.current) {
                  // logger.info('Received ICE candidate')

                  if (!msg.data?.candidate) {
                    logger.warn('ICE candidate payload missing candidate data')
                    continue
                  }

                  try {
                    const pc = peerConnectionRef.current
                    const candidateInit = msg.data.candidate as RTCIceCandidateInit

                    if (pc.remoteDescription) {
                      await pc.addIceCandidate(new RTCIceCandidate(candidateInit))
                    } else {
                      // logger.info('Remote description not set yet, queueing ICE candidate')
                      pendingIceCandidatesRef.current.push(candidateInit)
                    }
                  } catch (err) {
                    logger.error('Failed to add ICE candidate:', err)
                  }
                }

                // La llamada fue terminada por el doctor
                if (msg.type === 'call-ended') {
                  handleCallEnd()
                }
              }
            }
          }
        } catch (error) {
          logger.error('Error en polling:', error)
        }
      }, 1000) // Poll every second
    }

    joinRoom()

    return () => {
      isActive = false

      // Leave room on unmount
      if (pollInterval) clearInterval(pollInterval)

      fetch(`${signalingBase}/api/leave`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, roomId })
      }).catch(console.error)

      // Cleanup peer connection
      if (peerConnectionRef.current) {
        peerConnectionRef.current.close()
        peerConnectionRef.current = null
      }
    }
  }, [roomId, userId]) // Don't include volatile state to avoid reconnects

  // Inicializar cámara y micrófono cuando se acepta la llamada
  const initMedia = async (): Promise<MediaStream | null> => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: true
      })

      setStream(mediaStream)
      setMediaError(false)

      if (localVideoRef.current) {
        localVideoRef.current.srcObject = mediaStream
      }

      return mediaStream
    } catch (error: any) {
      logger.error('Error al acceder a la cámara:', error)
      setMediaError(true)
      setShowMediaPicker(true)

      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({
          video: false,
          audio: true
        })
        setStream(audioStream)
        setMediaError(false)

        if (localVideoRef.current) {
          localVideoRef.current.srcObject = audioStream
        }

        return audioStream
      } catch (err) {
        logger.error('Failed to get even audio:', err)
        return null
      }
    }
  }

  // Handle media ready from MediaPicker
  const handleMediaReady = (mediaStream: MediaStream) => {
    setStream(mediaStream)
    setMediaError(false)
    setShowMediaPicker(false)

    if (localVideoRef.current) {
      localVideoRef.current.srcObject = mediaStream
    }

    // Add stream to peer connection if it exists
    if (peerConnectionRef.current && mediaStream) {
      mediaStream.getTracks().forEach(track => {
        peerConnectionRef.current!.addTrack(track, mediaStream)
      })
    }
  }

  // Cleanup media streams
  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop())
      }
      if (remoteStream) {
        remoteStream.getTracks().forEach(track => track.stop())
      }
    }
  }, [stream, remoteStream])

  // Timer de duración de llamada
  const startCallTimer = useCallback(() => {
    if (timerRef.current) return
    timerRef.current = setInterval(() => {
      setCallDuration(prev => prev + 1)
    }, 1000)
  }, [])

  const stopCallTimer = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current)
      timerRef.current = null
    }
    setCallDuration(0)
  }, [])

  // Formatear duración
  const formatDuration = (seconds: number) => {
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  // Reproducir tono de llamada
  const playRingtone = () => {
    // Simular sonido de llamada con beep del navegador
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)()
    const oscillator = audioContext.createOscillator()
    const gainNode = audioContext.createGain()

    oscillator.connect(gainNode)
    gainNode.connect(audioContext.destination)

    oscillator.frequency.value = 440
    oscillator.type = 'sine'
    gainNode.gain.value = 0.3

    oscillator.start()
    setTimeout(() => oscillator.stop(), 500)
  }

  const processOffer = useCallback(
    async (offer: RTCSessionDescriptionInit) => {
      const pc = peerConnectionRef.current

      if (!pc) {
        logger.warn('processOffer called but no peer connection is ready yet')
        return
      }

      if (pc.currentRemoteDescription) {
        // logger.info('Remote description already set, skipping duplicate offer')
        return
      }

      try {
        await pc.setRemoteDescription(new RTCSessionDescription(offer))

        if (pendingIceCandidatesRef.current.length) {
          // logger.info('Applying queued ICE candidates...')
          const queuedCandidates = [...pendingIceCandidatesRef.current]
          pendingIceCandidatesRef.current.length = 0

          for (const candidateInit of queuedCandidates) {
            try {
              await pc.addIceCandidate(new RTCIceCandidate(candidateInit))
            } catch (candidateError) {
              logger.error('Failed to add queued ICE candidate:', candidateError)
            }
          }
        }

        const answer = await pc.createAnswer()
        await pc.setLocalDescription(answer)

        const localDescription = pc.localDescription
        if (!localDescription) {
          throw new Error('Local description missing after setLocalDescription')
        }

        const signalingBase = 'http://localhost:8787'
        await fetch(`${signalingBase}/api/message`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            from: userId,
            roomId,
            type: 'webrtc-answer',
            data: { answer: localDescription }
          })
        })

        // logger.info('Answer sent successfully')
        setCallStatus('connected')
        startCallTimer()
        setCurrentOffer(null)
      } catch (error) {
        logger.error('Error processing offer:', error)
        setMediaError(true)
        setShowMediaPicker(true)
      }
    },
    [roomId, startCallTimer, userId]
  )

  // Aceptar llamada
  const acceptCall = async () => {
    stopRingtone()
    setCallStatus('connecting')

    try {
      let mediaStream = stream
      if (!mediaStream) {
        mediaStream = await initMedia()
      }

      if (!mediaStream) {
        throw new Error('No media stream available after initialization')
      }

      const pc = createPeerConnection()

      // logger.info('Adding tracks to peer connection:')
      mediaStream.getTracks().forEach(track => {
        pc.addTrack(track, mediaStream)
        // logger.info(`  - Added ${track.kind} track: ${track.label}`)
      })

      const signalingBase = 'http://localhost:8787'
      await fetch(`${signalingBase}/api/message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from: userId,
          roomId,
          type: 'patient-joined',
          data: {}
        })
      })

      if (currentOffer) {
        // logger.info('Offer already available, processing immediately')
        await processOffer(currentOffer)
      } else {
        // logger.info('Awaiting offer from doctor to complete handshake')
      }
    } catch (error) {
      logger.error('Error al aceptar llamada:', error)
      setMediaError(true)
      setShowMediaPicker(true)
      if (peerConnectionRef.current) {
        peerConnectionRef.current.close()
        peerConnectionRef.current = null
      }
      setCallStatus('incoming')
    }
  }

  // Process offers that arrive after the patient already accepted the call
  useEffect(() => {
    if (callStatus !== 'connecting') return
    if (!currentOffer) return

    void processOffer(currentOffer)
  }, [callStatus, currentOffer, processOffer])

  // Rechazar llamada
  const rejectCall = async () => {
    stopRingtone()
    setCallStatus('waiting')

    const signalingBase = 'http://localhost:8787'

    try {
      await fetch(`${signalingBase}/api/message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from: userId,
          roomId,
          type: 'call-rejected',
          data: {}
        })
      })
    } catch (error) {
      logger.error('Error al rechazar llamada:', error)
    }
  }

  // Finalizar llamada
  const endCall = async () => {
    handleCallEnd()

    const signalingBase = 'http://localhost:8787'

    try {
      await fetch(`${signalingBase}/api/message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from: userId,
          roomId,
          type: 'call-ended',
          data: {}
        })
      })
    } catch (error) {
      logger.error('Error al finalizar llamada:', error)
    }
  }

  // Manejar fin de llamada
  const handleCallEnd = () => {
    setCallStatus('ended')
    stopCallTimer()
    stopRingtone()

    // Cleanup peer connection
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close()
      peerConnectionRef.current = null
    }

    // Detener media streams
    if (stream) {
      stream.getTracks().forEach(track => track.stop())
    }
    if (remoteStream) {
      remoteStream.getTracks().forEach(track => track.stop())
    }

    // Clear remote stream
    setRemoteStream(null)
    if (remoteVideoRef.current) {
      remoteVideoRef.current.srcObject = null
    }

    // Reiniciar estado después de 2 segundos
    setTimeout(() => {
      setCallStatus('waiting')
      setStream(null)
      setCurrentOffer(null)
    }, 2000)
  }

  // Detener tono de llamada
  const stopRingtone = () => {
    if (ringtoneRef.current) {
      ringtoneRef.current.pause()
      ringtoneRef.current.currentTime = 0
    }
  }

  // Toggle mute
  const toggleMute = () => {
    if (stream) {
      const audioTrack = stream.getAudioTracks()[0]
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled
        setIsMuted(!audioTrack.enabled)
      }
    }
  }

  // Toggle video
  const toggleVideo = () => {
    if (stream) {
      const videoTrack = stream.getVideoTracks()[0]
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled
        setIsVideoOff(!videoTrack.enabled)
      }
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-6 flex justify-between items-start">
          <div>
          <h1 className="text-3xl font-bold text-gray-800 mb-2">Portal del Paciente</h1>
          <div className="flex items-center gap-4 text-gray-600">
            <span>Sala de espera: {roomId}</span>
            {callStatus === 'connected' && (
              <span className="flex items-center gap-1">
                <Clock className="w-4 h-4" />
                {formatDuration(callDuration)}
              </span>
            )}
          </div>
          </div>
          {/* Settings button for media configuration */}
          {callStatus === 'waiting' && (
            <button
              onClick={() => setShowMediaPicker(!showMediaPicker)}
              className="p-2 bg-white rounded-lg shadow hover:shadow-md transition-shadow"
              title="Configurar cámara y micrófono"
            >
              <Settings className="w-5 h-5 text-gray-600" />
            </button>
          )}
        </div>

        {/* Media Picker Modal */}
        {showMediaPicker && (
          <div className="mb-6">
            <MediaPicker
              onMediaReady={handleMediaReady}
              onError={(error) => {
                logger.error('MediaPicker error:', error)
                setMediaError(true)
              }}
            />
          </div>
        )}

        {/* Modal de llamada entrante */}
        {callStatus === 'incoming' && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center">
            <div className="bg-white rounded-2xl shadow-2xl p-8 max-w-md w-full mx-4 animate-bounce">
              <div className="text-center">
                <div className="mb-6">
                  <div className="w-24 h-24 bg-green-100 rounded-full mx-auto flex items-center justify-center animate-pulse">
                    <PhoneIncoming className="w-12 h-12 text-green-600 animate-bounce" />
                  </div>
                </div>

                <h2 className="text-2xl font-bold text-gray-800 mb-2">Llamada entrante</h2>
                <p className="text-lg text-gray-600 mb-6">{callerName} te está llamando</p>

                <div className="flex gap-4 justify-center">
                  <button
                    onClick={acceptCall}
                    className="bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg flex items-center gap-2 transition-colors"
                  >
                    <Phone className="w-5 h-5" />
                    Aceptar
                  </button>
                  <button
                    onClick={rejectCall}
                    className="bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg flex items-center gap-2 transition-colors"
                  >
                    <X className="w-5 h-5" />
                    Rechazar
                  </button>
                </div>

                {mediaError && (
                  <div className="mt-4 text-sm text-orange-600">
                    ⚠️ Problema con la cámara. Se abrirá el selector de dispositivos.
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Estado de la llamada */}
        <div className="mb-4">
          {callStatus === 'waiting' && (
            <div className="bg-blue-100 border border-blue-300 rounded-lg p-4 flex items-center gap-2">
              <Clock className="w-5 h-5 text-blue-600" />
              <span className="text-gray-700">Esperando llamada del doctor...</span>
            </div>
          )}
          {callStatus === 'connecting' && (
            <div className="bg-yellow-100 border border-yellow-300 rounded-lg p-4 flex items-center gap-2">
              <Clock className="w-5 h-5 text-yellow-600" />
              <span className="text-gray-700">Conectando con {callerName}...</span>
            </div>
          )}
          {callStatus === 'connected' && (
            <div className="bg-green-100 border border-green-300 rounded-lg p-4 flex items-center gap-2">
              <Phone className="w-5 h-5 text-green-600" />
              <span className="text-gray-700">En consulta con {callerName}</span>
            </div>
          )}
          {callStatus === 'ended' && (
            <div className="bg-gray-100 border border-gray-300 rounded-lg p-4 flex items-center gap-2">
              <PhoneOff className="w-5 h-5 text-gray-600" />
              <span className="text-gray-700">Llamada finalizada</span>
            </div>
          )}
        </div>

        {/* Videos - mostrar cuando la conexión está en curso o establecida */}
        {(callStatus === 'connecting' || callStatus === 'connected') && (
          <>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
              {/* Video remoto (Doctor) */}
              <div className="relative bg-white rounded-xl shadow-lg overflow-hidden aspect-video">
                <video
                  ref={remoteVideoRef}
                  autoPlay
                  playsInline
                  className="w-full h-full object-cover"
                />
                {callStatus === 'connecting' && !remoteStream && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-white">
                    <Clock className="w-10 h-10 text-gray-400 mb-2 animate-spin" />
                    <span className="text-sm text-gray-500">Esperando video del doctor...</span>
                  </div>
                )}
                <div className="absolute bottom-2 left-2 bg-black/50 text-white px-3 py-1 rounded">
                  <span className="text-sm">{callerName}</span>
                </div>
              </div>

              {/* Video local */}
              <div className="relative bg-white rounded-xl shadow-lg overflow-hidden aspect-video">
                <video
                  ref={localVideoRef}
                  autoPlay
                  muted
                  playsInline
                  className="w-full h-full object-cover"
                />
                {(isVideoOff || !stream?.getVideoTracks().length) && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-200">
                    <VideoOff className="w-12 h-12 text-gray-500 mb-2" />
                    <span className="text-sm text-gray-600">Cámara desactivada</span>
                    <button
                      onClick={() => setShowMediaPicker(true)}
                      className="mt-2 text-blue-600 hover:text-blue-800 underline text-sm"
                    >
                      Configurar cámara
                    </button>
                  </div>
                )}
                <div className="absolute bottom-2 left-2 bg-black/50 text-white px-3 py-1 rounded">
                  <span className="text-sm">Tú</span>
                </div>
              </div>
            </div>

            {/* Controles de llamada */}
            <div className="flex justify-center gap-4">
              <button
                onClick={toggleMute}
                className={`p-4 rounded-full transition-colors ${
                  isMuted
                    ? 'bg-red-600 hover:bg-red-700 text-white'
                    : 'bg-white hover:bg-gray-100 text-gray-700 shadow-md'
                }`}
              >
                {isMuted ? <MicOff className="w-6 h-6" /> : <Mic className="w-6 h-6" />}
              </button>

              <button
                onClick={toggleVideo}
                className={`p-4 rounded-full transition-colors ${
                  isVideoOff
                    ? 'bg-red-600 hover:bg-red-700 text-white'
                    : 'bg-white hover:bg-gray-100 text-gray-700 shadow-md'
                }`}
              >
                {isVideoOff ? <VideoOff className="w-6 h-6" /> : <Video className="w-6 h-6" />}
              </button>

              <button
                onClick={endCall}
                className="p-4 bg-red-600 hover:bg-red-700 text-white rounded-full transition-colors shadow-md"
              >
                <PhoneOff className="w-6 h-6" />
              </button>
            </div>
          </>
        )}

        {/* Sala de espera cuando no hay llamada */}
        {callStatus === 'waiting' && (
          <div className="bg-white rounded-xl shadow-lg p-8 text-center">
            <User className="w-24 h-24 text-gray-400 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-gray-700 mb-2">Sala de Espera Virtual</h2>
            <p className="text-gray-500">
              Tu doctor te llamará cuando esté listo para la consulta.
            </p>
            <p className="text-sm text-gray-400 mt-4">
              Por favor, mantén tu cámara y micrófono listos.
            </p>
            {mediaError && (
              <div className="mt-4 p-3 bg-yellow-100 border border-yellow-400 rounded-lg text-sm text-yellow-800">
                <p>⚠️ Problema detectado con la cámara.</p>
                <button
                  onClick={() => setShowMediaPicker(true)}
                  className="mt-2 text-blue-600 hover:text-blue-800 underline"
                >
                  Configurar dispositivos manualmente
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { ChangeEvent, FormEvent, useEffect, useMemo, useState } from 'react';
import type { Profile } from '@/lib/zod/profiles';
import type {
  Patient,
  PatientProfileUpdateInput,
} from '@/lib/zod/patients';
import type { ProfileUpdateInput } from '@/lib/zod/profiles';

export interface PatientProfileFormPayload {
  profile: ProfileUpdateInput;
  patient: PatientProfileUpdateInput;
}

interface PatientProfileFormProps {
  profile: Profile | null;
  patient: Patient | null;
  isSaving: boolean;
  onCancel: () => void;
  onSubmit: (payload: PatientProfileFormPayload) => Promise<void> | void;
}

interface FormState {
  firstName: string;
  lastName: string;
  phone: string;
  birthDate: string;
  gender: string;
  bloodType: string;
  heightCm: string;
  weightKg: string;
  emergencyName: string;
  emergencyRelationship: string;
  emergencyPhone: string;
  emergencyEmail: string;
}

const GENDER_OPTIONS: Array<{ value: string; label: string }> = [
  { value: 'male', label: 'Masculino' },
  { value: 'female', label: 'Femenino' },
  { value: 'other', label: 'Otro' },
  { value: 'prefer_not_to_say', label: 'Prefiero no decirlo' },
];

const BLOOD_TYPES = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];

function buildInitialState(profile: Profile | null, patient: Patient | null): FormState {
  return {
    firstName: profile?.firstName ?? '',
    lastName: profile?.lastName ?? '',
    phone: profile?.phone ?? '',
    birthDate: patient?.birthDate ?? '',
    gender: patient?.gender ?? 'prefer_not_to_say',
    bloodType: patient?.bloodType ?? '',
    heightCm: patient?.heightCm ? String(patient.heightCm) : '',
    weightKg: patient?.weightKg ? String(patient.weightKg) : '',
    emergencyName: patient?.emergencyContact?.name ?? '',
    emergencyRelationship: patient?.emergencyContact?.relationship ?? '',
    emergencyPhone: patient?.emergencyContact?.phone ?? '',
    emergencyEmail: patient?.emergencyContact?.email ?? '',
  };
}

export function PatientProfileForm({
  profile,
  patient,
  isSaving,
  onCancel,
  onSubmit,
}: PatientProfileFormProps) {
  const [formState, setFormState] = useState<FormState>(() => buildInitialState(profile, patient));

  useEffect(() => {
    setFormState(buildInitialState(profile, patient));
  }, [profile, patient]);

  const handleChange = (field: keyof FormState) => (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = event.target.value;
    setFormState(prev => ({ ...prev, [field]: value }));
  };

  const payload = useMemo<PatientProfileFormPayload>(() => {
    const toNullable = (value: string) => (value.trim().length > 0 ? value.trim() : null);

    const parseNumber = (value: string) => {
      const trimmed = value.trim();
      if (!trimmed) return null;
      const parsed = Number(trimmed);
      return Number.isFinite(parsed) ? parsed : null;
    };

    const emergencyFields = {
      name: toNullable(formState.emergencyName),
      relationship: toNullable(formState.emergencyRelationship),
      phone: toNullable(formState.emergencyPhone),
      email: toNullable(formState.emergencyEmail),
    };

    const hasEmergencyData = Object.values(emergencyFields).some(value => value);

    return {
      profile: {
        firstName: toNullable(formState.firstName),
        lastName: toNullable(formState.lastName),
        phone: toNullable(formState.phone),
      },
      patient: {
        birthDate: toNullable(formState.birthDate),
        gender: formState.gender ? (formState.gender as PatientProfileUpdateInput['gender']) : null,
        bloodType: formState.bloodType ? (formState.bloodType as PatientProfileUpdateInput['bloodType']) : null,
        heightCm: parseNumber(formState.heightCm),
        weightKg: parseNumber(formState.weightKg),
        emergencyContact: hasEmergencyData ? emergencyFields : null,
      },
    };
  }, [formState]);

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await onSubmit(payload);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-8">
      <section className="card-ivory p-6 space-y-4">
        <h2 className="heading-3">Información personal</h2>
        <div className="grid md:grid-cols-2 gap-4">
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Nombre</span>
            <input
              type="text"
              value={formState.firstName}
              onChange={handleChange('firstName')}
              className="input-ivory"
              placeholder="Tu nombre"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Apellido</span>
            <input
              type="text"
              value={formState.lastName}
              onChange={handleChange('lastName')}
              className="input-ivory"
              placeholder="Tu apellido"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Teléfono</span>
            <input
              type="tel"
              value={formState.phone}
              onChange={handleChange('phone')}
              className="input-ivory"
              placeholder="Ej: +54 11 1234 5678"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Fecha de nacimiento</span>
            <input
              type="date"
              value={formState.birthDate ?? ''}
              onChange={handleChange('birthDate')}
              className="input-ivory"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Género</span>
            <select
              value={formState.gender}
              onChange={handleChange('gender')}
              className="input-ivory"
            >
              {GENDER_OPTIONS.map(option => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Tipo de sangre</span>
            <select
              value={formState.bloodType}
              onChange={handleChange('bloodType')}
              className="input-ivory"
            >
              <option value="">Seleccioná una opción</option>
              {BLOOD_TYPES.map(type => (
                <option key={type} value={type}>
                  {type}
                </option>
              ))}
            </select>
          </label>
        </div>
      </section>

      <section className="card-ivory p-6 space-y-4">
        <h2 className="heading-3">Medidas y salud</h2>
        <div className="grid md:grid-cols-2 gap-4">
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Altura (cm)</span>
            <input
              type="number"
              inputMode="numeric"
              min="0"
              value={formState.heightCm}
              onChange={handleChange('heightCm')}
              className="input-ivory"
              placeholder="Ej: 170"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Peso (kg)</span>
            <input
              type="number"
              inputMode="decimal"
              min="0"
              step="0.1"
              value={formState.weightKg}
              onChange={handleChange('weightKg')}
              className="input-ivory"
              placeholder="Ej: 70"
            />
          </label>
        </div>
      </section>

      <section className="card-ivory p-6 space-y-4">
        <h2 className="heading-3">Contacto de emergencia</h2>
        <div className="grid md:grid-cols-2 gap-4">
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Nombre completo</span>
            <input
              type="text"
              value={formState.emergencyName}
              onChange={handleChange('emergencyName')}
              className="input-ivory"
              placeholder="Nombre y apellido"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Relación</span>
            <input
              type="text"
              value={formState.emergencyRelationship}
              onChange={handleChange('emergencyRelationship')}
              className="input-ivory"
              placeholder="Ej: Madre, pareja"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Teléfono</span>
            <input
              type="tel"
              value={formState.emergencyPhone}
              onChange={handleChange('emergencyPhone')}
              className="input-ivory"
              placeholder="Número de contacto"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-label text-stone-600">Email</span>
            <input
              type="email"
              value={formState.emergencyEmail}
              onChange={handleChange('emergencyEmail')}
              className="input-ivory"
              placeholder="Correo de contacto"
            />
          </label>
        </div>
      </section>

      <div className="flex items-center justify-end gap-3">
        <button
          type="button"
          onClick={onCancel}
          className="btn-secondary-ivory px-5 py-2 text-sm"
          disabled={isSaving}
        >
          Cancelar
        </button>
        <button
          type="submit"
          className="btn-primary-ivory px-6 py-2 text-sm"
          disabled={isSaving}
        >
          {isSaving ? 'Guardando…' : 'Guardar cambios'}
        </button>
      </div>
    </form>
  );
}

'use client';

import React, { createContext, useContext, useState } from 'react';

interface PatientPortalContextType {
  isFocusMode: boolean;
  setFocusMode: (focus: boolean) => void;
  activePanel: string | null;
  setActivePanel: (panel: string | null) => void;
  isQuickActionsVisible: boolean;
  setQuickActionsVisible: (visible: boolean) => void;
}

const PatientPortalContext = createContext<PatientPortalContextType | null>(null);

export function usePatientPortal() {
  const context = useContext(PatientPortalContext);
  if (!context) {
    throw new Error('usePatientPortal must be used within PatientPortalProvider');
  }
  return context;
}

interface PatientPortalProviderProps {
  children: React.ReactNode;
}

export function PatientPortalProvider({ children }: PatientPortalProviderProps) {
  const [isFocusMode, setFocusMode] = useState(false);
  const [activePanel, setActivePanel] = useState<string | null>(null);
  const [isQuickActionsVisible, setQuickActionsVisible] = useState(false);

  const value = {
    isFocusMode,
    setFocusMode,
    activePanel,
    setActivePanel,
    isQuickActionsVisible,
    setQuickActionsVisible,
  };

  return (
    <PatientPortalContext.Provider value={value}>
      {children}
    </PatientPortalContext.Provider>
  );
}

interface PatientPortalShellProps {
  children: React.ReactNode;
  className?: string;
}

export function PatientPortalShell({ children, className = '' }: PatientPortalShellProps) {
  const { isFocusMode } = usePatientPortal();

  return (
    <div
      className={`min-h-screen bg-gradient-to-br from-gray-900 via-black to-gray-800 text-white ${
        isFocusMode ? 'overflow-hidden' : ''
      } ${className}`}
    >
      <div className={`flex flex-col h-screen ${isFocusMode ? 'p-2' : 'p-4'}`}>
        {children}
      </div>

      {/* Focus mode overlay */}
      {isFocusMode && (
        <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-40 pointer-events-none" />
      )}
    </div>
  );
}

