type PatientRootLayoutProps = {
  children: ReactNode
}

export function PatientRootLayout({ children }: PatientRootLayoutProps): JSX.Element {
  const _pathname = usePathname()
  const [themeId, setThemeId] = useState<ThemeId>('autamedica')
  const [_fontScale, _setFontScale] = useState<FontScale>('md')
  const [_highContrast, _setHighContrast] = useState(false)
  const [_clock, setClock] = useState(() => formatClock(new Date()))

  useEffect(() => {
    const interval = setInterval(() => {
      setClock(formatClock(new Date()))
    }, 60_000)

    return () => clearInterval(interval)
  }, [])

  const theme = THEMES[themeId]

  const _cssVariables = useMemo(() => {
    return {
      '--patient-bg': theme.background,
      '--patient-surface': theme.surface,
      '--patient-border': theme.border,
      '--patient-primary': theme.primary,
      '--patient-primary-soft': theme.primarySoft,
      '--patient-text': theme.text,
      '--patient-text-muted': theme.textMuted,
    } satisfies CSSProperties
  }, [theme])

  const _mainClasses = clsx(
    'flex-1 overflow-y-auto px-6 py-6',
    FONT_SCALE_CLASS[_fontScale],
  )

  const _handleThemeChange = (event: ChangeEvent<HTMLSelectElement>) => {
    setThemeId(event.target.value as ThemeId)
  }

  // Simplificado: solo envolver con providers, sin UI propia
  // AuthProvider ya está en el root layout (layout.tsx)
  return (
    <ErrorBoundary>
      <PatientPortalProvider>
        {children}
      </PatientPortalProvider>
    </ErrorBoundary>
  )
}

'use client';

import { useState } from 'react';
import type {
  CreateMedicalConditionInput,
  CreateMedicalAllergyInput,
  ConditionStatus,
  AllergySeverity,
  FamilyRelationship
} from '@autamedica/types';

interface AnamnesisFormProps {
  onSubmit: (data: AnamnesisFormData) => void;
  className?: string;
}

interface AnamnesisFormData {
  personalHistory: {
    conditions: CreateMedicalConditionInput[];
    allergies: CreateMedicalAllergyInput[];
    medications: {
      name: string;
      dosage: string;
      frequency: string;
      indication?: string;
    }[];
    surgeries: {
      name: string;
      date: string;
      complications?: string;
    }[];
  };
  familyHistory: CreateMedicalConditionInput[];
  socialHistory: {
    smoking: 'never' | 'former' | 'current';
    alcohol: 'never' | 'occasional' | 'regular' | 'excessive';
    exercise: 'sedentary' | 'light' | 'moderate' | 'intense';
    diet: 'poor' | 'fair' | 'good' | 'excellent';
    occupation: string;
    stress: 'low' | 'moderate' | 'high';
  };
  reviewOfSystems: {
    [system: string]: {
      symptoms: string[];
      notes?: string;
    };
  };
}

export function AnamnesisForm({ onSubmit, className = '' }: AnamnesisFormProps) {
  const [currentSection, setCurrentSection] = useState(0);
  const [formData, setFormData] = useState<AnamnesisFormData>({
    personalHistory: {
      conditions: [],
      allergies: [],
      medications: [],
      surgeries: []
    },
    familyHistory: [],
    socialHistory: {
      smoking: 'never',
      alcohol: 'never',
      exercise: 'sedentary',
      diet: 'fair',
      occupation: '',
      stress: 'moderate'
    },
    reviewOfSystems: {}
  });

  const sections = [
    { title: 'Historia Personal', icon: '🏥' },
    { title: 'Historia Familiar', icon: '👨‍👩‍👧‍👦' },
    { title: 'Historia Social', icon: '🌍' },
    { title: 'Revisión por Sistemas', icon: '🔍' },
    { title: 'Resumen', icon: '📋' }
  ];

  const handleNextSection = () => {
    if (currentSection < sections.length - 1) {
      setCurrentSection(currentSection + 1);
    }
  };

  const handlePrevSection = () => {
    if (currentSection > 0) {
      setCurrentSection(currentSection - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(formData);
  };

  const addCondition = (type: 'personal' | 'family') => {
    const newCondition: CreateMedicalConditionInput = {
      patient_id: '' as any, // Will be set by parent
      name: '',
      status: 'active' as ConditionStatus,
      is_chronic: false,
      is_family_history: type === 'family',
      family_relationship: type === 'family' ? 'mother' as FamilyRelationship : undefined
    };

    if (type === 'personal') {
      setFormData(prev => ({
        ...prev,
        personalHistory: {
          ...prev.personalHistory,
          conditions: [...prev.personalHistory.conditions, newCondition]
        }
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        familyHistory: [...prev.familyHistory, newCondition]
      }));
    }
  };

  const addAllergy = () => {
    const newAllergy: CreateMedicalAllergyInput = {
      patient_id: '' as any, // Will be set by parent
      allergen: '',
      allergen_type: 'medication',
      severity: 'mild' as AllergySeverity
    };

    setFormData(prev => ({
      ...prev,
      personalHistory: {
        ...prev.personalHistory,
        allergies: [...prev.personalHistory.allergies, newAllergy]
