                </select>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const renderFamilyHistory = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-medium text-white">Historia Familiar</h3>
        <button
          onClick={() => addCondition('family')}
