            `,
          }
        },
        {
          popover: {
            title: '🎉 ¡Listo para comenzar!',
            description: `
              <div style="text-align: center; padding: 0.5rem 0;">
                <p style="margin-bottom: 1rem; font-size: 1.1rem; font-weight: 600;">Ya conoces AutaMedica 🚀</p>
                <div style="background: #f0fdf4; border: 2px solid #86efac; border-radius: 0.5rem; padding: 1rem; margin: 1rem 0;">
                  <p style="font-weight: 600; color: #166534; margin-bottom: 0.5rem;">✅ Recuerda lo esencial:</p>
                  <ul style="text-align: left; margin: 0.5rem 0; padding-left: 1.5rem; font-size: 0.9rem; color: #15803d;">
                    <li>💾 <strong>Auto-guardado:</strong> Tu información se guarda automáticamente</li>
                    <li>🔒 <strong>Privacidad total:</strong> Controla quién ve tu historial</li>
                    <li>🎥 <strong>Video disponible:</strong> Consultas médicas cuando necesites</li>
                    <li>🏆 <strong>Gamificación:</strong> Gana puntos cuidando tu salud</li>
                    <li>💬 <strong>Comunidad:</strong> Comparte experiencias con otros pacientes</li>
                    <li>📞 <strong>Soporte 24/7:</strong> Auta AI siempre disponible</li>
                  </ul>
                </div>
                <p style="margin-top: 1rem; font-size: 1.2rem; color: #059669; font-weight: 700;">¡Empecemos a cuidar tu salud! 🌟</p>
                <p style="margin-top: 0.5rem; font-size: 0.85rem; color: #64748b;">Puedes volver a ver este tutorial desde el botón "Tutorial" abajo a la izquierda</p>
              </div>
            `,
          }
        }
      ],

      onDestroyStarted: () => {
        // Marcar onboarding como completado
        localStorage.setItem('autamedica_onboarding_completed', 'true');
        setHasSeenOnboarding(true);
        driverObj.destroy();
      }
    });

    driverObj.drive();
  };

  // Botón flotante para reiniciar el onboarding
  if (hasSeenOnboarding) {
    return (
      <button
        onClick={startOnboarding}
        className="fixed bottom-4 left-4 z-50 flex items-center gap-2 px-4 py-2 bg-stone-800 hover:bg-stone-700 text-white rounded-full shadow-lg hover:shadow-xl transition-all hover:scale-105"
        title="Ver tutorial de nuevo"
      >
        <span className="text-xl">🎓</span>
        <span className="text-sm font-medium">Tutorial</span>
      </button>
    );
  }

  return null;
}

'use client';

import { useState, useMemo } from 'react';
import { Calculator, User, Calendar, AlertCircle, CheckCircle2, Clock, Info, ChevronDown, ChevronUp } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { getRecommendedScreenings, groupScreeningsByCategory, CATEGORY_COLORS, CATEGORY_LABELS } from '@/data/screenings';

interface PersonalizedScreeningCalculatorProps {
  defaultAge?: number;
  defaultGender?: 'male' | 'female';
  onCalculate?: (age: number, gender: 'male' | 'female') => void;
}

export function PersonalizedScreeningCalculator({
  defaultAge,
  defaultGender,
  onCalculate
}: PersonalizedScreeningCalculatorProps) {
  const [age, setAge] = useState<string>(defaultAge?.toString() || '');
  const [gender, setGender] = useState<'male' | 'female' | ''>(defaultGender || '');
  const [hasCalculated, setHasCalculated] = useState(false);
  const [expandedItems, setExpandedItems] = useState<Record<string, boolean>>({});
  const [isFormCollapsed, setIsFormCollapsed] = useState(false);

  const handleCalculate = () => {
    if (age && gender) {
      setHasCalculated(true);
      setIsFormCollapsed(true); // Colapsar formulario al calcular
      onCalculate?.(parseInt(age), gender);
    }
  };

  const toggleExpanded = (screeningId: string) => {
    setExpandedItems(prev => ({
      ...prev,
      [screeningId]: !prev[screeningId]
    }));
  };

  const recommendedScreenings = useMemo(() => {
    if (!age || !gender || !hasCalculated) return [];
    return getRecommendedScreenings(parseInt(age), gender);
  }, [age, gender, hasCalculated]);

  const groupedScreenings = useMemo(() => {
    if (recommendedScreenings.length === 0) return {};
    return groupScreeningsByCategory(recommendedScreenings);
  }, [recommendedScreenings]);

  const getIconComponent = (iconName: string) => {
    const Icon = (LucideIcons as any)[iconName] || LucideIcons.Circle;
    return Icon;
  };

  const urgentScreenings = recommendedScreenings.filter(s => s.urgency === 'high');
  const mediumScreenings = recommendedScreenings.filter(s => s.urgency === 'medium');

  return (
    <div className="bg-gradient-to-br from-stone-50 to-white rounded-xl border-2 border-stone-300 p-6 shadow-lg">
      {/* Header - Clickeable cuando hay resultados */}
      <button
        onClick={() => hasCalculated && setIsFormCollapsed(!isFormCollapsed)}
        className={`w-full flex items-center justify-between gap-3 mb-6 ${hasCalculated ? 'cursor-pointer hover:opacity-80' : 'cursor-default'} transition-opacity`}
      >
        <div className="flex items-center gap-3">
          <Calculator className="h-6 w-6 text-stone-700" />
          <div className="text-left">
            <h2 className="heading-2">Calculadora Personalizada</h2>
            <p className="text-sm text-stone-600">
              {hasCalculated
                ? `${age} años - ${gender === 'male' ? 'Masculino' : 'Femenino'}`
                : 'Descubrí qué controles te corresponden según tu edad y género'}
            </p>
          </div>
        </div>
        {hasCalculated && (
          isFormCollapsed ? (
            <ChevronDown className="h-5 w-5 text-stone-700 flex-shrink-0" />
          ) : (
            <ChevronUp className="h-5 w-5 text-stone-700 flex-shrink-0" />
          )
        )}
      </button>

      {/* Form - Colapsable */}
      {!isFormCollapsed && (
        <div className="transition-all duration-300 ease-in-out">
          <div className="grid md:grid-cols-2 gap-4 mb-6">
            {/* Age input */}
            <div>
              <label htmlFor="age-input" className="block text-sm font-semibold text-stone-700 mb-2">
                <Calendar className="inline h-4 w-4 mr-1" />
                Tu edad
              </label>
              <input
                id="age-input"
                type="number"
                min="1"
                max="120"
                value={age}
                onChange={(e) => setAge(e.target.value)}
                placeholder="Ej: 45"
                className="w-full px-4 py-3 rounded-lg border-2 border-stone-300 focus:border-stone-800 focus:ring-2 focus:ring-stone-200 transition-colors text-lg font-semibold"
              />
            </div>

            {/* Gender selector */}
            <div>
              <label className="block text-sm font-semibold text-stone-700 mb-2">
                <User className="inline h-4 w-4 mr-1" />
                Género
              </label>
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => setGender('male')}
                  className={`px-4 py-3 rounded-lg border-2 font-semibold transition-all ${
                    gender === 'male'
                      ? 'bg-stone-800 text-white border-stone-900 shadow-md'
                      : 'bg-white text-stone-700 border-stone-300 hover:border-stone-400'
                  }`}
                >
                  👨 Masculino
                </button>
                <button
                  onClick={() => setGender('female')}
                  className={`px-4 py-3 rounded-lg border-2 font-semibold transition-all ${
                    gender === 'female'
                      ? 'bg-stone-800 text-white border-stone-900 shadow-md'
                      : 'bg-white text-stone-700 border-stone-300 hover:border-stone-400'
                  }`}
                >
                  👩 Femenino
                </button>
              </div>
            </div>
          </div>

          {/* Calculate button */}
          <button
            onClick={handleCalculate}
            disabled={!age || !gender}
            className={`w-full py-3 rounded-lg font-bold text-lg transition-all ${
              !age || !gender
                ? 'bg-stone-300 text-stone-500 cursor-not-allowed'
                : 'bg-stone-800 hover:bg-stone-900 text-white shadow-md hover:shadow-lg'
            }`}
          >
            🔍 Ver mis controles recomendados
          </button>
        </div>
      )}

      {/* Results */}
      {hasCalculated && recommendedScreenings.length > 0 && (
        <div className="mt-6 space-y-4">
          {/* Summary cards - compactas */}
          <div className="grid md:grid-cols-3 gap-3">
            <div className="bg-red-50 border-2 border-red-200 rounded-lg p-3">
              <AlertCircle className="h-5 w-5 text-red-600 mb-1" />
              <p className="text-xl font-bold text-red-900">{urgentScreenings.length}</p>
              <p className="text-xs text-red-700 font-semibold">Prioritarios</p>
            </div>
            <div className="bg-amber-50 border-2 border-amber-200 rounded-lg p-3">
              <Clock className="h-5 w-5 text-amber-600 mb-1" />
              <p className="text-xl font-bold text-amber-900">{mediumScreenings.length}</p>
              <p className="text-xs text-amber-700 font-semibold">Importantes</p>
            </div>
            <div className="bg-green-50 border-2 border-green-200 rounded-lg p-3">
              <CheckCircle2 className="h-5 w-5 text-green-600 mb-1" />
              <p className="text-xl font-bold text-green-900">{recommendedScreenings.length}</p>
              <p className="text-xs text-green-700 font-semibold">Total</p>
            </div>
          </div>

          {/* Alert for important screenings - compacto */}
          {urgentScreenings.length > 0 && (
            <div className="bg-red-50 border-2 border-red-300 rounded-lg p-3">
              <div className="flex items-start gap-2">
                <AlertCircle className="h-4 w-4 text-red-600 flex-shrink-0 mt-0.5" />
                <div>
                  <h4 className="font-bold text-red-900 mb-0.5 text-sm">
                    ¡Tenés {urgentScreenings.length} control{urgentScreenings.length > 1 ? 'es' : ''} prioritario{urgentScreenings.length > 1 ? 's' : ''}!
                  </h4>
                  <p className="text-xs text-red-800">
                    Estos estudios son fundamentales para tu salud. Agenda una consulta con tu médico.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Screenings by category */}
          <div>
            <h3 className="text-lg font-bold text-stone-900 mb-3">
              Tus Controles Recomendados
            </h3>
            <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-stone-300 scrollbar-track-stone-100">
              {Object.entries(groupedScreenings).map(([category, screenings]) => {
                if (screenings.length === 0) return null;
                const colors = CATEGORY_COLORS[category as keyof typeof CATEGORY_COLORS];
                const label = CATEGORY_LABELS[category as keyof typeof CATEGORY_LABELS];

                return (
                  <div key={category}>
                    <h4 className={`font-bold text-base mb-2 ${colors.text}`}>
                      {label} ({screenings.length})
                    </h4>
                    <div className="grid gap-2">
                      {screenings.map(screening => {
                        const Icon = getIconComponent(screening.icon);
                        const isExpanded = expandedItems[screening.id] || false;

                        return (
                          <div
                            key={screening.id}
                            className={`${colors.bg} border-2 ${colors.border} rounded-lg p-2.5`}
                          >
                            <div className="flex items-start gap-2.5">
                              {/* Icon - más pequeño */}
                              <div className={`flex-shrink-0 w-8 h-8 rounded-full ${colors.bg} border-2 ${colors.border} flex items-center justify-center`}>
                                <Icon className={`h-4 w-4 ${colors.text}`} />
                              </div>

                              {/* Content */}
                              <div className="flex-1 min-w-0">
                                <div className="flex items-start justify-between gap-2 mb-0.5">
                                  <h5 className={`font-bold ${colors.text} text-sm leading-tight`}>
                                    {screening.name}
                                  </h5>
                                  {screening.urgency === 'high' && (
                                    <span className="px-1.5 py-0.5 bg-red-100 text-red-700 text-[9px] font-bold rounded-full whitespace-nowrap">
                                      PRIORITARIO
                                    </span>
                                  )}
                                </div>

                                <p className="text-[11px] text-stone-600 mb-1.5 line-clamp-2">
                                  {screening.description}
                                </p>

                                {/* Detalles compactos */}
                                <div className="flex flex-wrap gap-x-2.5 gap-y-0.5 mb-1.5 text-[10px] text-stone-600">
                                  <div className="flex items-center gap-0.5">
                                    <Clock className="h-2.5 w-2.5" />
                                    <span>{screening.frequency}</span>
                                  </div>
                                  <div className="flex items-center gap-0.5">
                                    <Calendar className="h-2.5 w-2.5" />
                                    <span>{screening.startAge}+ años</span>
                                  </div>
                                  {screening.coverage === 'total' && (
                                    <span className="px-1 py-0.5 bg-green-100 text-green-700 font-semibold rounded text-[9px]">
                                      ✅ 100%
                                    </span>
                                  )}
                                </div>

                                {/* Botón para expandir detalles */}
                                <button
                                  onClick={() => toggleExpanded(screening.id)}
                                  className="text-[10px] text-stone-700 hover:text-stone-900 font-medium underline"
                                >
                                  {isExpanded ? '▼ Ver menos' : '▶ Ver más detalles'}
                                </button>

                                {/* Detalles expandibles */}
                                {isExpanded && (
                                  <div className="mt-3 pt-3 border-t border-stone-200 space-y-2">
                                    {/* Benefits */}
                                    <div>
                                      <p className="text-[10px] font-bold text-stone-700 mb-1">BENEFICIOS:</p>
                                      <ul className="text-[11px] text-stone-600 space-y-0.5">
                                        {screening.benefits.slice(0, 3).map((benefit, idx) => (
                                          <li key={idx} className="flex items-start gap-1.5">
                                            <CheckCircle2 className="h-3 w-3 text-green-600 flex-shrink-0 mt-0.5" />
                                            <span>{benefit}</span>
                                          </li>
                                        ))}
                                      </ul>
                                    </div>

                                    {/* Special cases */}
                                    {screening.specialCases && screening.specialCases.length > 0 && (
                                      <div className="bg-blue-50 border border-blue-200 rounded p-1.5">
                                        <div className="flex items-start gap-1.5">
                                          <Info className="h-3 w-3 text-blue-600 flex-shrink-0 mt-0.5" />
                                          <div className="text-[11px] text-blue-800">
                                            <strong>Nota:</strong> {screening.specialCases[0]}
                                          </div>
                                        </div>
                                      </div>
                                    )}
                                  </div>
                                )}
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Call to action */}
          <div className="bg-stone-800 text-white rounded-xl p-6 text-center">
            <h4 className="text-xl font-bold mb-2">¿Listo para cuidar tu salud?</h4>
            <p className="mb-4 text-stone-200">
              Programa una cita con tu médico para realizar estos controles
            </p>
            <button className="btn-primary-ivory px-6 py-3 text-lg font-bold">
              📅 Agendar consulta médica
            </button>
          </div>
        </div>
      )}

      {/* No results message */}
      {hasCalculated && recommendedScreenings.length === 0 && (
        <div className="mt-8 bg-blue-50 border-2 border-blue-200 rounded-xl p-6 text-center">
          <Info className="h-12 w-12 text-blue-600 mx-auto mb-3" />
          <p className="text-blue-900 font-semibold">
            No se encontraron screenings recomendados para esta edad y género.
          </p>
          <p className="text-sm text-blue-700 mt-2">
            Esto puede ser normal. Consulta con tu médico para recomendaciones personalizadas.
          </p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Clock, ChevronDown, ChevronUp } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { getAgeMilestones, SCREENINGS_DATABASE, CATEGORY_COLORS, type Screening } from '@/data/screenings';

interface ScreeningTimelineProps {
  currentAge?: number;
  gender?: 'male' | 'female';
}

export function ScreeningTimeline({ currentAge, gender }: ScreeningTimelineProps) {
  const [expandedAges, setExpandedAges] = useState<Set<number>>(new Set());
  const milestones = getAgeMilestones();

  const toggleAge = (age: number) => {
    setExpandedAges(prev => {
      const next = new Set(prev);
      if (next.has(age)) {
        next.delete(age);
      } else {
        next.add(age);
      }
      return next;
    });
  };

  const getScreeningsStartingAtAge = (age: number): Screening[] => {
    return SCREENINGS_DATABASE.filter(s => {
      // Filtro por género
      if (gender && s.gender !== 'all' && s.gender !== gender) {
        return false;
      }
      return s.startAge === age;
    });
  };

  const getScreeningsEndingAtAge = (age: number): Screening[] => {
    return SCREENINGS_DATABASE.filter(s => {
      if (gender && s.gender !== 'all' && s.gender !== gender) {
        return false;
      }
      return s.endAge === age;
    });
  };

  const getIconComponent = (iconName: string) => {
    const Icon = (LucideIcons as any)[iconName] || LucideIcons.Circle;
    return Icon;
  };

  return (
    <div className="bg-white rounded-xl border-2 border-stone-300 p-6 shadow-lg">
      <div className="flex items-center gap-3 mb-6">
        <Clock className="h-6 w-6 text-stone-700" />
        <div>
          <h2 className="heading-2">Línea de Tiempo de Salud Preventiva</h2>
          <p className="text-sm text-stone-600">¿Qué estudios me corresponden a cada edad?</p>
        </div>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-2 mb-6 pb-6 border-b border-stone-200">
        <span className="text-sm font-medium text-stone-700">Categorías:</span>
        {Object.entries(CATEGORY_COLORS).map(([category, colors]) => (
          <span
            key={category}
            className={`px-3 py-1 rounded-full text-xs font-semibold ${colors.bg} ${colors.text} border ${colors.border}`}
          >
            {category.charAt(0).toUpperCase() + category.slice(1)}
          </span>
        ))}
      </div>

      {/* Timeline */}
      <div className="relative">
        {/* Vertical line */}
        <div className="absolute left-8 top-0 bottom-0 w-0.5 bg-stone-300" />

        <div className="space-y-4">
          {milestones.map((age, index) => {
            const startingScreenings = getScreeningsStartingAtAge(age);
            const endingScreenings = getScreeningsEndingAtAge(age);
            const isExpanded = expandedAges.has(age);
            const isCurrentAge = currentAge === age;
            const isPastAge = currentAge !== undefined && age < currentAge;
            const isFutureAge = currentAge !== undefined && age > currentAge;

            if (startingScreenings.length === 0 && endingScreenings.length === 0) {
              return null;
            }

            return (
              <div key={age} className="relative">
                {/* Age marker */}
                <div className="flex items-start gap-4">
                  {/* Circle */}
                  <div
                    className={`relative z-10 flex-shrink-0 w-16 h-16 rounded-full flex items-center justify-center font-bold text-lg border-4 shadow-md ${
                      isCurrentAge
                        ? 'bg-stone-800 text-white border-stone-900'
                        : isPastAge
                        ? 'bg-stone-200 text-stone-600 border-stone-300'
                        : 'bg-white text-stone-800 border-stone-400'
                    }`}
                  >
                    {age}
                  </div>

                  {/* Content */}
                  <div className="flex-1 pb-4">
                    <button
                      onClick={() => toggleAge(age)}
                      className="w-full text-left bg-stone-50 hover:bg-stone-100 rounded-xl p-4 border-2 border-stone-200 transition-colors"
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <h3 className="font-bold text-stone-900 mb-1">
                            {age} años
                            {isCurrentAge && (
                              <span className="ml-2 px-2 py-0.5 bg-stone-800 text-white text-xs rounded-full">
                                TU EDAD
                              </span>
                            )}
                          </h3>
                          <p className="text-sm text-stone-600">
                            {startingScreenings.length > 0 && (
                              <span className="text-green-700 font-semibold">
                                +{startingScreenings.length} nuevo{startingScreenings.length > 1 ? 's' : ''}
                              </span>
                            )}
                            {startingScreenings.length > 0 && endingScreenings.length > 0 && ' · '}
                            {endingScreenings.length > 0 && (
                              <span className="text-amber-700 font-semibold">
                                {endingScreenings.length} finaliza{endingScreenings.length > 1 ? 'n' : ''}
                              </span>
                            )}
                          </p>
                        </div>
                        {isExpanded ? (
                          <ChevronUp className="h-5 w-5 text-stone-600" />
                        ) : (
                          <ChevronDown className="h-5 w-5 text-stone-600" />
                        )}
                      </div>
                    </button>

                    {/* Expanded content */}
                    {isExpanded && (
                      <div className="mt-4 space-y-3">
                        {startingScreenings.length > 0 && (
                          <div>
                            <h4 className="text-sm font-semibold text-green-700 mb-2">
                              ✅ Comienzan a esta edad:
                            </h4>
                            <div className="space-y-2">
                              {startingScreenings.map(screening => {
                                const Icon = getIconComponent(screening.icon);
                                const colors = CATEGORY_COLORS[screening.category];
                                return (
                                  <div
                                    key={screening.id}
                                    className={`p-3 rounded-lg border ${colors.bg} ${colors.border}`}
                                  >
                                    <div className="flex items-start gap-3">
                                      <Icon className={`h-5 w-5 ${colors.text} flex-shrink-0 mt-0.5`} />
                                      <div className="flex-1">
                                        <h5 className={`font-semibold ${colors.text}`}>
                                          {screening.shortName}
                                        </h5>
                                        <p className="text-xs text-stone-600 mt-1">
                                          {screening.description}
                                        </p>
                                        <div className="flex items-center gap-4 mt-2 text-xs">
                                          <span className="text-stone-700">
                                            <strong>Frecuencia:</strong> {screening.frequency}
                                          </span>
                                          {screening.endAge && (
                                            <span className="text-stone-700">
                                              <strong>Hasta:</strong> {screening.endAge} años
                                            </span>
                                          )}
                                        </div>
                                      </div>
                                    </div>
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        )}

                        {endingScreenings.length > 0 && (
                          <div>
                            <h4 className="text-sm font-semibold text-amber-700 mb-2">
                              ⚠️ Finalizan a esta edad:
                            </h4>
                            <div className="space-y-2">
                              {endingScreenings.map(screening => {
                                const Icon = getIconComponent(screening.icon);
                                return (
                                  <div
                                    key={screening.id}
                                    className="p-3 rounded-lg bg-amber-50 border border-amber-200"
                                  >
                                    <div className="flex items-center gap-3">
                                      <Icon className="h-5 w-5 text-amber-600" />
                                      <span className="text-sm font-medium text-amber-800">
                                        {screening.shortName}
                                      </span>
                                    </div>
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Footer tip */}
      <div className="mt-6 pt-6 border-t border-stone-200">
        <p className="text-sm text-stone-600 text-center">
          💡 <strong>Tip:</strong> Haz clic en cada edad para ver qué estudios comienzan o finalizan
        </p>
      </div>
    </div>
  );
}

'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, X, User } from 'lucide-react'

export interface ChatMessage {
  id: string
  senderId: string
  senderName: string
  senderRole: 'doctor' | 'patient'
  message: string
  timestamp: Date
  isLocal?: boolean
}

export interface ChatPanelProps {
  messages: ChatMessage[]
  localUserId: string
  localUserName: string
  onSendMessage: (message: string) => void | Promise<void>
  onClose: () => void
  isOpen: boolean
  className?: string
}

/**
 * ChatPanel - Panel lateral de chat para videoconsulta
 *
 * Features:
 * - Mensajes en tiempo real con timestamps
 * - Scroll automático a nuevos mensajes
 * - Indicador de mensajes propios vs remotos
 * - Badge de rol (Doctor/Paciente)
 * - Auto-focus en input al abrir
 * - Loading state al enviar mensaje
 *
 * @example
 * <ChatPanel
 *   messages={chatMessages}
 *   localUserId={currentUser.id}
 *   localUserName={currentUser.name}
 *   onSendMessage={handleSendMessage}
 *   onClose={() => setChatOpen(false)}
 *   isOpen={isChatOpen}
 * />
 */
export function ChatPanel({
  messages,
  localUserId,
  localUserName,
  onSendMessage,
  onClose,
  isOpen,
  className = '',
}: ChatPanelProps) {
  const [input, setInput] = useState('')
  const [isSending, setIsSending] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  // Auto-scroll a nuevos mensajes
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  // Auto-focus al abrir
  useEffect(() => {
    if (isOpen) {
      inputRef.current?.focus()
    }
  }, [isOpen])

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = input.trim()
    if (!trimmed || isSending) return

    setIsSending(true)
    try {
      await onSendMessage(trimmed)
      setInput('')
    } finally {
      setIsSending(false)
    }
  }

  const formatTime = (date: Date) => {
    return new Intl.DateTimeFormat('es-AR', {
      hour: '2-digit',
      minute: '2-digit',
    }).format(date)
  }

  if (!isOpen) return null

  return (
    <div className={`flex flex-col h-full bg-gray-900 rounded-2xl overflow-hidden shadow-2xl ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 bg-gray-800 border-b border-gray-700">
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-white font-semibold">Chat</span>
          <span className="text-gray-400 text-sm">({messages.length})</span>
        </div>
        <button
          onClick={onClose}
          className="p-1 hover:bg-gray-700 rounded-lg transition-colors"
          aria-label="Cerrar chat"
        >
          <X className="w-5 h-5 text-gray-400" />
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3 scrollbar-thin scrollbar-thumb-gray-700 scrollbar-track-transparent">
        {messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-500 gap-2">
            <User className="w-12 h-12 opacity-50" />
            <p className="text-sm">No hay mensajes aún</p>
            <p className="text-xs text-gray-600">Envía el primer mensaje</p>
          </div>
        ) : (
          messages.map((msg) => {
            const isLocal = msg.senderId === localUserId || msg.isLocal
            return (
              <div
                key={msg.id}
                className={`flex ${isLocal ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[75%] ${isLocal ? 'order-2' : 'order-1'}`}>
                  {/* Sender Info */}
                  <div className={`flex items-center gap-2 mb-1 ${isLocal ? 'justify-end' : 'justify-start'}`}>
                    <span className="text-xs text-gray-400">{formatTime(msg.timestamp)}</span>
                    <span className="text-xs font-medium text-gray-300">{msg.senderName}</span>
                    {msg.senderRole === 'doctor' && (
                      <span className="text-xs text-emerald-400 font-semibold px-1.5 py-0.5 bg-emerald-500/20 rounded">
                        Doctor
                      </span>
                    )}
                  </div>

                  {/* Message Bubble */}
                  <div
                    className={`px-4 py-2.5 rounded-2xl ${
                      isLocal
                        ? 'bg-blue-600 text-white rounded-tr-sm'
                        : 'bg-gray-800 text-gray-100 rounded-tl-sm'
                    }`}
                  >
                    <p className="text-sm whitespace-pre-wrap break-words">{msg.message}</p>
                  </div>
                </div>
              </div>
            )
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <form onSubmit={handleSend} className="flex items-center gap-2 px-4 py-3 bg-gray-800 border-t border-gray-700">
        <input
          ref={inputRef}
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Escribe un mensaje..."
          disabled={isSending}
          className="flex-1 px-4 py-2.5 bg-gray-900 text-white rounded-xl border border-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
          maxLength={500}
        />
        <button
          type="submit"
          disabled={!input.trim() || isSending}
          className="p-2.5 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-700 disabled:cursor-not-allowed text-white rounded-xl transition-colors"
          aria-label="Enviar mensaje"
        >
          {isSending ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
          ) : (
            <Send className="w-5 h-5" />
          )}
        </button>
      </form>
    </div>
  )
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import React from 'react';
import { usePatientPortal } from '@/components/layout/PatientPortalShell';
import { usePatientSession } from '@/hooks/usePatientSession';
import { useVideoCall } from '@/hooks/useVideoCall';
import { useTelemedicine } from '@/hooks';
import { useMockRemoteStream } from '@/hooks/useMockRemoteStream';
import { useRealRemoteStream } from '@/hooks/useRealRemoteStream';
import { VideoLayout, ViewModeSelector } from '@/components/telemedicine/VideoLayout';
import { VideoControls } from '@/components/telemedicine/VideoControls';
import type { EnhancedVideoCallProps, VideoViewMode, PIPPosition } from '@/types/telemedicine';
import { logger, featureFlags } from '@autamedica/shared';
import {
  LiveKitRoom,
  VideoConference,
  RoomAudioRenderer,
  ControlBar,
} from '@livekit/components-react';
import '@livekit/components-styles';

/**
 * Componente principal de videollamada refactorizado
 * Versión modular con hooks y componentes separados
 * INTEGRADO con Supabase para registro de sesiones
 */
export function EnhancedVideoCall({ roomId = 'patient-room', sessionId, className = '' }: EnhancedVideoCallProps & { sessionId?: string }) {
  // Context del portal
  const { isFocusMode, setFocusMode } = usePatientPortal();

  // Sesión del paciente
  const { currentSession, formattedDuration } = usePatientSession();

  // Custom hook para lógica de video
  const videoCall = useVideoCall();

  // Hook de telemedicina para Supabase
  const telemedicine = useTelemedicine(sessionId);
  const joinedRef = useRef(false);
  const isLiveKitEnabled = featureFlags.USE_LIVEKIT && !featureFlags.USE_MOCK_VIDEO;
  const liveKitConfig = isLiveKitEnabled ? telemedicine.livekit : null;

  const handleLiveKitConnected = useCallback(async () => {
    if (joinedRef.current) return;
    try {
      const joined = await telemedicine.joinSession('patient');
      if (!joined) return;
      joinedRef.current = true;
      await telemedicine.logEvent('call_started', 'LiveKit room connected');
    } catch (error) {
      logger.error('[EnhancedVideoCall] LiveKit onConnected error', error);
    }
  }, [telemedicine]);

  const handleLiveKitDisconnected = useCallback(async () => {
    if (!joinedRef.current) return;
    joinedRef.current = false;
    try {
      await telemedicine.leaveSession();
      await telemedicine.logEvent('call_ended', 'Room disconnected');
    } catch (error) {
      logger.error('[EnhancedVideoCall] LiveKit onDisconnected error', error);
    }
  }, [telemedicine]);

  // Estados locales de UI
  const [showControls, setShowControls] = useState(true);
  const [showQualityOverlay, setShowQualityOverlay] = useState(false);
  const [mouseTimer, setMouseTimer] = useState<NodeJS.Timeout | null>(null);

  // Estados de layout
  const [viewMode, setViewMode] = useState<VideoViewMode>('speaker');
  const [pipPosition, setPipPosition] = useState<PIPPosition>('bottom-right');

  // Remote stream - usa mock en desarrollo, LiveKit en producción
  // Controlado por feature flag NEXT_PUBLIC_USE_MOCK_VIDEO
  const mockStream = featureFlags.USE_MOCK_VIDEO
    ? useMockRemoteStream(videoCall.callStatus === 'live')
    : null;

  // TODO: Pasar remoteParticipant de LiveKit cuando esté disponible
  const realStream = !featureFlags.USE_MOCK_VIDEO
    ? useRealRemoteStream(undefined) // Pasar remoteParticipant aquí
    : null;

  const remoteStream = featureFlags.USE_MOCK_VIDEO ? mockStream : realStream;

  // Calidad de la llamada
  // Auto-activar focus mode durante llamadas
  useEffect(() => {
    if (videoCall.callStatus === 'live') {
      setShowQualityOverlay(true);
      setFocusMode(true);
      const timer = setTimeout(() => setShowQualityOverlay(false), 3000);
      return () => clearTimeout(timer);
    } else {
      setFocusMode(false);
    }
  }, [videoCall.callStatus, setFocusMode]);

  // Registrar eventos de sesión en Supabase
  useEffect(() => {
    if (isLiveKitEnabled) return;
    if (!telemedicine.session) return;

    // Registrar cambios de estado de la llamada
    const logEvent = async (eventType: string, details: string) => {
      try {
        await telemedicine.logEvent(eventType, details);
      } catch (error) {
        logger.error('Error logging telemedicine event:', error);
      }
    };

    if (videoCall.callStatus === 'live' && !joinedRef.current) {
      telemedicine.joinSession('patient');
      joinedRef.current = true;
      logEvent('call_started', 'Video call initiated successfully');
    } else if (videoCall.callStatus === 'ended' && joinedRef.current) {
      logEvent('call_ended', 'Video call ended by patient');
      telemedicine.leaveSession();
      joinedRef.current = false;
    }
  }, [isLiveKitEnabled, telemedicine, videoCall.callStatus]);

  useEffect(() => {
    if (!telemedicine.session) {
      joinedRef.current = false;
    }
  }, [telemedicine.session]);

  useEffect(() => {
    return () => {
      if (!joinedRef.current) return;
      joinedRef.current = false;
      void telemedicine.leaveSession();
      if (isLiveKitEnabled) {
        void telemedicine.logEvent('call_ended', 'Component unmounted');
      }
    };
  }, [isLiveKitEnabled, telemedicine]);

  // Auto-ocultar controles en focus mode
  useEffect(() => {
    const handleMouseMove = () => {
      setShowControls(true);
      if (mouseTimer) clearTimeout(mouseTimer);

      const timer = setTimeout(() => {
        if (videoCall.callStatus === 'live' && isFocusMode) {
          setShowControls(false);
        }
      }, 3000);

      setMouseTimer(timer);
    };

    if (isFocusMode) {
      window.addEventListener('mousemove', handleMouseMove);
      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        if (mouseTimer) clearTimeout(mouseTimer);
      };
    }
  }, [isFocusMode, videoCall.callStatus, mouseTimer]);

  // Handlers de UI
  const handleToggleVideo = async () => {
    await videoCall.toggleVideo();
    const state = !videoCall.isVideoEnabled;
    telemedicine.logEvent('video_toggled', `enabled:${state}`);
  };

  const handleToggleAudio = async () => {
    await videoCall.toggleAudio();
    const state = !videoCall.isMuted;
    telemedicine.logEvent('audio_toggled', `enabled:${state}`);
  };

  const handleToggleScreenShare = async () => {
    await videoCall.toggleScreenShare();
    telemedicine.logEvent('screen_share_toggled');
  };

  const handleSwapVideos = () => {
    // Swap será manejado internamente por VideoLayout
    // logger.info('[EnhancedVideoCall] Videos swapped');
  };

  const handlePIPPositionChange = (position: PIPPosition) => {
    setPipPosition(position);
  };

  const handleViewModeChange = (mode: VideoViewMode) => {
    setViewMode(mode);
  };

  if (isLiveKitEnabled) {
    return (
      <div className={`flex min-h-0 flex-1 flex-col text-white ${className}`}>
        <div className={`call-area ${isFocusMode ? 'gap-3' : 'gap-4'} flex min-h-0 flex-1 flex-col`}>
          {telemedicine.session && (
            <div className="mb-2 flex items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-white/80">
              <span>
                Sesión #{telemedicine.session.session_id.slice(0, 8)} · Estado: <strong>{telemedicine.session.status}</strong>
              </span>
              <span>
                Participantes: {telemedicine.participants.length} · Último evento: {telemedicine.events[0]?.event_type ?? 'ninguno'}
              </span>
            </div>
          )}

          <section className="call-area__videoCard relative flex min-h-0 flex-1 flex-col">
            <div className="relative flex min-h-0 flex-1 overflow-hidden rounded-lg bg-black">
              {liveKitConfig ? (
                <LiveKitRoom
                  token={liveKitConfig.token}
                  serverUrl={liveKitConfig.url}
                  connect
                  video
                  audio
                  onConnected={() => {
                    void handleLiveKitConnected();
                  }}
                  onDisconnected={() => {
                    void handleLiveKitDisconnected();
                  }}
                  className="absolute inset-0 flex flex-col"
                >
                  <RoomAudioRenderer />
                  <VideoConference />
                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent p-4">
                    <div className="mx-auto max-w-3xl">
                      <ControlBar
                        variation="minimal"
                        controls={{
                          microphone: true,
                          camera: true,
                          screenShare: false,
                          chat: true,
                          leave: true,
                        }}
                      />
                    </div>
                  </div>
                </LiveKitRoom>
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900">
                  {telemedicine.loading ? (
                    <div className="text-center">
                      <div className="mx-auto mb-4 h-12 w-12 animate-spin rounded-full border-2 border-t-transparent border-white/60" />
                      <p className="text-white/80">Preparando tu videoconsulta...</p>
                    </div>
                  ) : (
                    <div className="text-center space-y-4">
                      <p className="text-white/80">LiveKit activo, esperando token de sesión.</p>
                      <button
                        onClick={() => {
                          void telemedicine.refreshSession();
                        }}
                        className="rounded-lg bg-gradient-to-r from-blue-600 to-purple-600 px-6 py-3 font-semibold text-white shadow-lg transition hover:from-blue-500 hover:to-purple-500 focus:outline-none focus:ring-2 focus:ring-blue-400/50"
                      >
                        Reintentar conexión
                      </button>
                    </div>
                  )}
                </div>
              )}
            </div>
          </section>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex min-h-0 flex-1 flex-col text-white ${className}`}>
      <div className={`call-area ${isFocusMode ? 'gap-3' : 'gap-4'} flex min-h-0 flex-1 flex-col`}>
        {telemedicine.session && (
          <div className="mb-2 flex items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-white/80">
            <span>
              Sesión #{telemedicine.session.session_id.slice(0, 8)} · Estado: <strong>{telemedicine.session.status}</strong>
            </span>
            <span>
              Participantes: {telemedicine.participants.length} · Último evento:{' '}
              {telemedicine.events[0]?.event_type ?? 'ninguno'}
            </span>
          </div>
        )}

        <section className="call-area__videoCard relative flex min-h-0 flex-1 flex-col">
          <div className="relative flex min-h-0 flex-1 overflow-hidden rounded-lg">
            {videoCall.callStatus === 'live' ? (
              <VideoLayout
                localStream={videoCall.localStream}
                remoteStream={remoteStream}
                isLocalVideoEnabled={videoCall.isVideoEnabled}
                isRemoteVideoEnabled={true}
                viewMode={viewMode}
                pipPosition={pipPosition}
                onSwapVideos={handleSwapVideos}
                onPIPPositionChange={handlePIPPositionChange}
                className="absolute inset-0"
              />
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900">
                <div className="text-center">
                  <h2 className="mb-2 text-2xl font-bold">Videoconsulta Médica</h2>
                  <p className="mb-6 text-white/70">Presiona el botón para iniciar tu consulta</p>
                  <button
                    onClick={videoCall.startCall}
                    className="rounded-lg bg-gradient-to-r from-blue-600 to-purple-600 px-6 py-3 font-semibold transition-all shadow-lg hover:from-blue-500 hover:to-purple-500 hover:shadow-xl"
                  >
                    Iniciar Videoconsulta
                  </button>
                </div>
              </div>
            )}

            {videoCall.callStatus === 'live' && (
              <div className="absolute top-4 right-4 z-30">
                <ViewModeSelector currentMode={viewMode} onChange={handleViewModeChange} />
              </div>
            )}

            {videoCall.callStatus === 'live' && (
              <div className="absolute bottom-0 left-0 right-0 z-20 flex items-center justify-center pb-4">
                <VideoControls
                  isMuted={videoCall.isMuted}
                  isVideoEnabled={videoCall.isVideoEnabled}
                  isScreenSharing={videoCall.isScreenSharing}
                  showControls={showControls}
                  isFocusMode={isFocusMode}
                  onToggleAudio={handleToggleAudio}
                  onToggleVideo={handleToggleVideo}
                  onToggleScreenShare={handleToggleScreenShare}
                  onEndCall={async () => {
                    await telemedicine.logEvent('call_ended', 'Video call ended by button');
                    await telemedicine.leaveSession();
                    videoCall.endCall();
                  }}
                />
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { MicOff, VideoOff, Signal, User } from 'lucide-react'

export interface Participant {
  id: string
  name: string
  role: 'doctor' | 'patient'
  isVideoEnabled: boolean
  isAudioEnabled: boolean
  connectionQuality?: 'excellent' | 'good' | 'fair' | 'poor'
  videoTrack?: MediaStreamTrack
  audioTrack?: MediaStreamTrack
}

export interface ParticipantGridProps {
  participants: Participant[]
  localParticipant?: Participant
  className?: string
}

function ParticipantTile({ participant, isLocal = false }: { participant: Participant; isLocal?: boolean }) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [hasVideo, setHasVideo] = useState(false)

  useEffect(() => {
    if (!videoRef.current || !participant.videoTrack) return

    const stream = new MediaStream([participant.videoTrack])
    videoRef.current.srcObject = stream
    videoRef.current.play().catch(console.error)
    setHasVideo(true)

    return () => {
      if (videoRef.current) {
        videoRef.current.srcObject = null
      }
    }
  }, [participant.videoTrack])

  const qualityColors = {
    excellent: 'text-green-500',
    good: 'text-blue-500',
    fair: 'text-yellow-500',
    poor: 'text-red-500',
  }

  const qualityColor = participant.connectionQuality ? qualityColors[participant.connectionQuality] : 'text-gray-500'

  return (
    <div className="relative bg-gray-900 rounded-2xl overflow-hidden aspect-video shadow-2xl">
      {/* Video Stream */}
      {participant.isVideoEnabled && hasVideo ? (
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted={isLocal}
          className="w-full h-full object-cover"
        />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-br from-gray-800 to-gray-900">
          <div className="flex flex-col items-center gap-4">
            <div className="w-24 h-24 rounded-full bg-blue-600/20 flex items-center justify-center">
              <User className="w-12 h-12 text-blue-400" />
            </div>
            <p className="text-gray-300 font-medium">{participant.name}</p>
          </div>
        </div>
      )}

      {/* Overlays */}
      <div className="absolute inset-0 pointer-events-none">
        {/* Top Bar: Name + Connection Quality */}
        <div className="absolute top-4 left-4 right-4 flex items-center justify-between">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-black/60 backdrop-blur-sm rounded-full">
            <span className="text-white text-sm font-medium">{participant.name}</span>
            {isLocal && (
              <span className="text-xs text-blue-400 font-semibold">(Tú)</span>
            )}
            {participant.role === 'doctor' && (
              <span className="text-xs text-emerald-400 font-semibold px-2 py-0.5 bg-emerald-500/20 rounded-full">
                Doctor
              </span>
            )}
          </div>

          {participant.connectionQuality && (
            <div className={`flex items-center gap-1 px-2 py-1 bg-black/60 backdrop-blur-sm rounded-full ${qualityColor}`}>
              <Signal className="w-4 h-4" />
            </div>
          )}
        </div>

        {/* Bottom Bar: Media Status */}
        <div className="absolute bottom-4 right-4 flex items-center gap-2">
          {!participant.isVideoEnabled && (
            <div className="p-2 bg-red-600/80 backdrop-blur-sm rounded-full">
              <VideoOff className="w-4 h-4 text-white" />
            </div>
          )}
          {!participant.isAudioEnabled && (
            <div className="p-2 bg-red-600/80 backdrop-blur-sm rounded-full">
              <MicOff className="w-4 h-4 text-white" />
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * ParticipantGrid - Grid responsivo de participantes en videollamada
 *
 * Layouts automáticos:
 * - 1 participante: Full screen
 * - 2 participantes: 2 columnas
 * - 3-4 participantes: Grid 2x2
 * - 5-6 participantes: Grid 2x3
 * - 7+ participantes: Grid 3x3
 *
 * Features:
 * - Indicadores de conexión (excellent/good/fair/poor)
 * - Estados de video/audio por participante
 * - Badge de rol (Doctor)
 * - Indicador "Tú" para participante local
 * - Video placeholders con avatar
 *
 * @example
 * <ParticipantGrid
 *   localParticipant={localUser}
 *   participants={remoteParticipants}
 * />
 */
export function ParticipantGrid({
  participants,
  localParticipant,
  className = '',
}: ParticipantGridProps) {
  const allParticipants = localParticipant
    ? [localParticipant, ...participants]
    : participants

  const count = allParticipants.length

  // Grid layout automático según cantidad de participantes
  const gridClass =
    count === 1
      ? 'grid-cols-1'
      : count === 2
        ? 'grid-cols-1 md:grid-cols-2'
        : count <= 4
          ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-2'
          : count <= 6
            ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3'
            : 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3'

  return (
    <div className={`grid gap-4 ${gridClass} ${className}`}>
      {allParticipants.map((participant) => (
        <ParticipantTile
          key={participant.id}
          participant={participant}
          isLocal={localParticipant?.id === participant.id}
        />
      ))}
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Maximize, Grid3x3, Sidebar } from 'lucide-react';
import { RemoteVideoStream } from './RemoteVideoStream';
import { LocalVideoPIP } from './LocalVideoPIP';
import { VideoQualityIndicator } from './VideoQualityIndicator';
import type { VideoLayoutProps, VideoViewMode, PIPPosition } from '@/types/telemedicine';

/**
 * Layout maestro para videoconsultas con 2 participantes
 *
 * Modos de visualización:
 * - speaker: Video grande del médico + PIP del paciente (default)
 * - grid: Ambos videos del mismo tamaño lado a lado
 * - sidebar: Médico grande a la izquierda, paciente sidebar derecha
 *
 * Features:
 * - Swap videos (intercambiar grande ↔ pequeño)
 * - Cambiar modo de visualización
 * - PIP draggable a 4 esquinas
 * - Indicadores de calidad
 * - Responsive
 */
export function VideoLayout({
  localStream,
  remoteStream,
  isLocalVideoEnabled,
  isRemoteVideoEnabled,
  viewMode = 'speaker',
  pipPosition = 'bottom-right',
  onSwapVideos,
  onPIPPositionChange,
  className = '',
}: VideoLayoutProps) {
  const [isSwapped, setIsSwapped] = useState(false);

  // Handler para intercambiar videos
  const handleSwap = () => {
    setIsSwapped(!isSwapped);
    onSwapVideos();
  };

  // Renderizar según modo de visualización
  switch (viewMode) {
    case 'grid':
      return (
        <GridLayout
          localStream={localStream}
          remoteStream={remoteStream}
          isLocalVideoEnabled={isLocalVideoEnabled}
          isRemoteVideoEnabled={isRemoteVideoEnabled}
          className={className}
        />
      );

    case 'sidebar':
      return (
        <SidebarLayout
          localStream={localStream}
          remoteStream={remoteStream}
          isLocalVideoEnabled={isLocalVideoEnabled}
          isRemoteVideoEnabled={isRemoteVideoEnabled}
          isSwapped={isSwapped}
          className={className}
        />
      );

    case 'speaker':
    default:
      return (
        <SpeakerLayout
          localStream={localStream}
          remoteStream={remoteStream}
          isLocalVideoEnabled={isLocalVideoEnabled}
          isRemoteVideoEnabled={isRemoteVideoEnabled}
          isSwapped={isSwapped}
          pipPosition={pipPosition}
          onSwap={handleSwap}
          onPIPPositionChange={onPIPPositionChange}
          className={className}
        />
      );
  }
}

/**
 * Layout Speaker: Video grande + PIP pequeño (DEFAULT)
 */
function SpeakerLayout({
  localStream,
  remoteStream,
  isLocalVideoEnabled,
  isRemoteVideoEnabled,
  isSwapped,
  pipPosition,
  onSwap,
  onPIPPositionChange,
  className,
}: {
  localStream: MediaStream | null;
  remoteStream: MediaStream | null;
  isLocalVideoEnabled: boolean;
  isRemoteVideoEnabled: boolean;
  isSwapped: boolean;
  pipPosition: PIPPosition;
  onSwap: () => void;
  onPIPPositionChange: (pos: PIPPosition) => void;
  className: string;
}) {
  // Si está swapped, invertir cuál es grande y cuál es PIP
  const mainStream = isSwapped ? localStream : remoteStream;
  const mainVideoEnabled = isSwapped ? isLocalVideoEnabled : isRemoteVideoEnabled;
  const mainParticipantName = isSwapped ? 'Tú (Paciente)' : 'Dr. García';
  const mainParticipantRole = isSwapped ? 'Paciente' : 'Médico Especialista';

  const pipStream = isSwapped ? remoteStream : localStream;
  const pipVideoEnabled = isSwapped ? isRemoteVideoEnabled : isLocalVideoEnabled;

  return (
    <div className={`relative w-full h-full ${className}`}>
      {/* Video principal (fullscreen) */}
      <RemoteVideoStream
        remoteStream={mainStream}
        isVideoEnabled={mainVideoEnabled}
        participantName={mainParticipantName}
        participantRole={mainParticipantRole}
        className="absolute inset-0"
      />

      {/* PIP (flotante en esquina) */}
      <LocalVideoPIP
        localStream={pipStream}
        isVideoEnabled={pipVideoEnabled}
        position={pipPosition}
        isDraggable
        onPositionChange={onPIPPositionChange}
        onSwap={onSwap}
      />

      {/* Indicador de calidad (top center) */}
      <div className="absolute top-4 left-1/2 transform -translate-x-1/2 z-20">
        <VideoQualityIndicator
          quality="auto"
          bitrate={1200}
          latency={45}
          packetLoss={0.5}
        />
      </div>
    </div>
  );
}

/**
 * Layout Grid: Ambos videos del mismo tamaño
 */
function GridLayout({
  localStream,
  remoteStream,
  isLocalVideoEnabled,
  isRemoteVideoEnabled,
  className,
}: {
  localStream: MediaStream | null;
  remoteStream: MediaStream | null;
  isLocalVideoEnabled: boolean;
  isRemoteVideoEnabled: boolean;
  className: string;
}) {
  return (
    <div className={`grid grid-cols-1 md:grid-cols-2 gap-4 h-full ${className}`}>
      {/* Video del médico */}
      <RemoteVideoStream
        remoteStream={remoteStream}
        isVideoEnabled={isRemoteVideoEnabled}
        participantName="Dr. García"
        participantRole="Médico Especialista"
      />

      {/* Video del paciente */}
      <RemoteVideoStream
        remoteStream={localStream}
        isVideoEnabled={isLocalVideoEnabled}
        participantName="Tú (Paciente)"
        participantRole="Paciente"
      />
    </div>
  );
}

/**
 * Layout Sidebar: Principal a la izquierda, secundario sidebar derecha
 */
function SidebarLayout({
  localStream,
  remoteStream,
  isLocalVideoEnabled,
  isRemoteVideoEnabled,
  isSwapped,
  className,
}: {
  localStream: MediaStream | null;
  remoteStream: MediaStream | null;
  isLocalVideoEnabled: boolean;
  isRemoteVideoEnabled: boolean;
  isSwapped: boolean;
  className: string;
}) {
  const mainStream = isSwapped ? localStream : remoteStream;
  const mainVideoEnabled = isSwapped ? isLocalVideoEnabled : isRemoteVideoEnabled;
  const mainName = isSwapped ? 'Tú (Paciente)' : 'Dr. García';
  const mainRole = isSwapped ? 'Paciente' : 'Médico Especialista';

  const sideStream = isSwapped ? remoteStream : localStream;
  const sideVideoEnabled = isSwapped ? isRemoteVideoEnabled : isLocalVideoEnabled;
  const sideName = isSwapped ? 'Dr. García' : 'Tú (Paciente)';
  const sideRole = isSwapped ? 'Médico Especialista' : 'Paciente';

  return (
    <div className={`flex gap-4 h-full ${className}`}>
      {/* Video principal (2/3 del ancho) */}
      <div className="flex-1">
        <RemoteVideoStream
          remoteStream={mainStream}
          isVideoEnabled={mainVideoEnabled}
          participantName={mainName}
          participantRole={mainRole}
