      </div>

      {/* Sidebar (1/3 del ancho) */}
      <div className="w-80 hidden lg:block">
        <RemoteVideoStream
          remoteStream={sideStream}
          isVideoEnabled={sideVideoEnabled}
          participantName={sideName}
          participantRole={sideRole}
        />
