'use client';

import { useState, useEffect, useCallback } from 'react';
import type { AnamnesisSection } from '@autamedica/types';
import { logger } from '@autamedica/shared';

type ApiAnamnesis = {
  id: string;
  patient_id: string;
  status: string;
  completion_percentage: number;
  sections_status: Record<string, unknown>;
  created_at: string;
  updated_at: string;
  completed_at?: string | null;
};

type ApiSection = {
  id: string;
  anamnesis_id: string;
  section: string;
  data: Record<string, unknown>;
  completed: boolean;
  completed_at?: string | null;
  updated_at: string;
};

type ApiProgress = {
  completion_percentage: number;
  completed_sections: string[];
  pending_sections: string[];
  total_sections: number;
};

interface ApiResponse {
  anamnesis: ApiAnamnesis;
  sections: ApiSection[];
  progress: ApiProgress;
}

export interface AnamnesisState {
  anamnesis: ApiAnamnesis | null;
  sections: ApiSection[];
  progress: ApiProgress | null;
}

interface UseAnamnesisReturn {
  anamnesis: ApiAnamnesis | null;
  sections: ApiSection[];
  progress: ApiProgress | null;
  loading: boolean;
  error: string | null;
  createAnamnesis: (initial?: Partial<ApiAnamnesis>) => Promise<ApiAnamnesis | null>;
  updateAnamnesis: (update: Partial<ApiAnamnesis>) => Promise<boolean>;
  updateSection: (section: AnamnesisSection, data: any) => Promise<boolean>;
  refreshAnamnesis: () => Promise<void>;
}

/**
 * Hook para gestionar la anamnesis del paciente
 *
 * @example
 * ```tsx
 * const { anamnesis, sections, progress, updateSection } = useAnamnesis();
 *
 * const handleSaveSection = async (sectionName, data) => {
 *   await updateSection(sectionName, data);
 * };
 * ```
 */
export function useAnamnesis(): UseAnamnesisReturn {
  const [anamnesis, setAnamnesis] = useState<ApiAnamnesis | null>(null);
  const [sections, setSections] = useState<ApiSection[]>([]);
  const [progress, setProgress] = useState<ApiProgress | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchAnamnesis = useCallback(async (): Promise<ApiResponse | null> => {
    try {
      setLoading(true);
      setError(null);
      const res = await fetch('/api/anamnesis', { credentials: 'include' });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'No se pudo cargar la anamnesis');
      }

      const json = (await res.json()) as { ok: boolean; data: ApiResponse };
      if (!json?.ok) throw new Error('Respuesta inválida');

      setAnamnesis(json.data.anamnesis);
      setSections(json.data.sections);
      setProgress(json.data.progress);
      return json.data;
    } catch (err) {
      logger.error('Error fetching anamnesis:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  // Create new anamnesis
  const createAnamnesis = useCallback(async (initial?: Partial<ApiAnamnesis>): Promise<ApiAnamnesis | null> => {
    try {
      const current = await fetchAnamnesis();
      if (initial && Object.keys(initial).length > 0) {
        await fetch('/api/anamnesis', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(initial),
          credentials: 'include',
        });
        const updated = await fetchAnamnesis();
        return updated?.anamnesis ?? current?.anamnesis ?? null;
      }
      return current?.anamnesis ?? null;
    } catch (err) {
      logger.error('Error creating anamnesis:', err);
      setError(err instanceof Error ? err.message : 'Error al crear anamnesis');
      return null;
    }
  }, [fetchAnamnesis]);

  // Update anamnesis
  const updateAnamnesis = useCallback(async (update: Partial<ApiAnamnesis>): Promise<boolean> => {
    try {
      const res = await fetch('/api/anamnesis', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(update),
        credentials: 'include',
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'Error al actualizar anamnesis');
      }
      await fetchAnamnesis();
      return true;
    } catch (err) {
      logger.error('Error updating anamnesis:', err);
      setError(err instanceof Error ? err.message : 'Error al actualizar anamnesis');
      return false;
    }
  }, [fetchAnamnesis]);

  // Update section
  const updateSection = useCallback(async (
    section: AnamnesisSection,
    data: any
  ): Promise<boolean> => {
    try {
      const res = await fetch('/api/anamnesis', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ stepId: section, data, completed: true }),
        credentials: 'include',
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'Error al actualizar sección');
      }
      const json = await res.json().catch(() => null);
      if (json?.data?.progress) {
        setProgress(json.data.progress);
      }
      await fetchAnamnesis();
      return true;
    } catch (err) {
      logger.error('Error updating section:', err);
      setError(err instanceof Error ? err.message : 'Error al actualizar sección');
      return false;
    }
  }, [fetchAnamnesis]);

  // Refresh data
  const refreshAnamnesis = useCallback(async () => {
    await fetchAnamnesis();
  }, [fetchAnamnesis]);

  // Initial fetch
  useEffect(() => {
    fetchAnamnesis();
  }, [fetchAnamnesis]);

  return {
    anamnesis,
    sections,
    progress,
    loading,
    error,
    createAnamnesis,
    updateAnamnesis,
    updateSection,
    refreshAnamnesis,
  };
}

/**
 * Hook para gestión de citas médicas del paciente
 */

'use client';

import { useState, useCallback, useEffect } from 'react';
import type {
  AppointmentWithDoctor,
  CreateAppointmentInput,
  UpdateAppointmentInput,
} from '@/types/appointment';

interface UseAppointmentsResult {
  appointments: AppointmentWithDoctor[];
  loading: boolean;
  error: string | null;
  createAppointment: (data: CreateAppointmentInput) => Promise<AppointmentWithDoctor | null>;
  updateAppointment: (id: string, data: UpdateAppointmentInput) => Promise<AppointmentWithDoctor | null>;
  cancelAppointment: (id: string) => Promise<boolean>;
  refreshAppointments: () => Promise<void>;
}

export function useAppointments(): UseAppointmentsResult {
  const [appointments, setAppointments] = useState<AppointmentWithDoctor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  /**
   * Obtener todas las citas del paciente
   */
  const refreshAppointments = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/appointments');

      if (!response.ok) {
        throw new Error('Error al cargar las citas');
      }

      const result = await response.json();

      if (result.success) {
        setAppointments(result.data || []);
      } else {
        throw new Error(result.error || 'Error desconocido');
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Error al cargar las citas';
      setError(message);
      console.error('[useAppointments] Error:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  /**
   * Crear una nueva cita
   */
  const createAppointment = useCallback(async (
    data: CreateAppointmentInput
  ): Promise<AppointmentWithDoctor | null> => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/appointments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Error al crear la cita');
      }

      const result = await response.json();

      if (result.success && result.data) {
        // Agregar la nueva cita al estado
        setAppointments(prev => [result.data, ...prev]);
        return result.data;
      }

      throw new Error('Error al crear la cita');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Error al crear la cita';
      setError(message);
      console.error('[useAppointments] Create error:', err);
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  /**
   * Actualizar una cita existente
   */
  const updateAppointment = useCallback(async (
    id: string,
    data: UpdateAppointmentInput
  ): Promise<AppointmentWithDoctor | null> => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/appointments/${id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Error al actualizar la cita');
      }

      const result = await response.json();

      if (result.success && result.data) {
        // Actualizar la cita en el estado
        setAppointments(prev =>
          prev.map(apt => (apt.id === id ? result.data : apt))
        );
        return result.data;
      }

      throw new Error('Error al actualizar la cita');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Error al actualizar la cita';
      setError(message);
      console.error('[useAppointments] Update error:', err);
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  /**
   * Cancelar una cita
   */
  const cancelAppointment = useCallback(async (id: string): Promise<boolean> => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/appointments/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Error al cancelar la cita');
      }

      const result = await response.json();

      if (result.success) {
        // Actualizar estado local
        setAppointments(prev =>
          prev.map(apt =>
            apt.id === id ? { ...apt, status: 'cancelled' as const } : apt
          )
        );
        return true;
      }

      throw new Error('Error al cancelar la cita');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Error al cancelar la cita';
      setError(message);
      console.error('[useAppointments] Cancel error:', err);
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  // Cargar citas al montar el componente
  useEffect(() => {
    refreshAppointments();
  }, [refreshAppointments]);

  return {
    appointments,
    loading,
    error,
    createAppointment,
    updateAppointment,
    cancelAppointment,
    refreshAppointments,
  };
}

import { useState, useEffect, useCallback } from 'react';
import type {
  HealthCenter,
  HealthCenterWithDistance,
  HealthCenterSearchFilters,
  Coordinates
} from '@autamedica/types';
import { calculateDistance, sortByDistance, formatDistance, estimateTravelTime } from '@autamedica/types';
import { useSupabase } from '@autamedica/auth/react';
import { logger } from '@autamedica/shared';

interface UseHealthCentersOptions {
  filters?: HealthCenterSearchFilters;
  autoDetectLocation?: boolean;
}

interface UseHealthCentersResult {
  centers: HealthCenterWithDistance[];
  isLoading: boolean;
  error: string | null;
  userLocation: Coordinates | null;
  requestLocation: () => Promise<void>;
  searchNearby: (location: Coordinates, radiusKm?: number) => Promise<void>;
  refetch: () => Promise<void>;
}

export function useHealthCentersGeolocation(
  options: UseHealthCentersOptions = {}
): UseHealthCentersResult {
  const supabase = useSupabase();
  const [centers, setCenters] = useState<HealthCenterWithDistance[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [userLocation, setUserLocation] = useState<Coordinates | null>(null);

  // Request user's location
  const requestLocation = useCallback(async () => {
    try {
      setError(null);

      if (!navigator.geolocation) {
        throw new Error('Geolocalización no soportada por este navegador');
      }

      return new Promise<void>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            const coords: Coordinates = {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude
            };
            setUserLocation(coords);
            resolve();
          },
          (err) => {
            logger.error('Error getting location:', err);
            setError('No se pudo obtener tu ubicación. Por favor, permite el acceso a la ubicación.');
            reject(err);
          },
          {
            enableHighAccuracy: true,
            timeout: 10000,
            maximumAge: 300000 // 5 minutes
          }
        );
      });
    } catch (err) {
      logger.error('Geolocation error:', err);
      setError(err instanceof Error ? err.message : 'Error de geolocalización');
    }
  }, []);

  // Search nearby centers
  const searchNearby = useCallback(async (
    location: Coordinates,
    radiusKm: number = 50
  ) => {
    try {
      setIsLoading(true);
      setError(null);

      // Build query
      let query = supabase
        .from('health_centers')
        .select('*')
        .eq('offers_ive_ile', true);

      // Apply filters
      if (options.filters?.type && options.filters.type.length > 0) {
        query = query.in('type', options.filters.type);
      }

      if (options.filters?.offers_medication_method !== undefined) {
        query = query.eq('offers_medication_method', options.filters.offers_medication_method);
      }

      if (options.filters?.offers_surgical_method !== undefined) {
        query = query.eq('offers_surgical_method', options.filters.offers_surgical_method);
      }

      if (options.filters?.accepts_walk_ins !== undefined) {
        query = query.eq('accepts_walk_ins', options.filters.accepts_walk_ins);
      }

      if (options.filters?.has_24h_service !== undefined) {
        query = query.eq('has_24h_service', options.filters.has_24h_service);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      // Calculate distances and filter by radius
      const centersWithDistance: HealthCenterWithDistance[] = (data || [])
        .map((center: any) => {
          const centerCoords: Coordinates = {
            latitude: center.coordinates.latitude,
            longitude: center.coordinates.longitude
          };

          const distance = calculateDistance(location, centerCoords);

          return {
            ...center,
            distance_km: Number(distance.toFixed(2)),
            travel_time_minutes: estimateTravelTime(distance, 'driving')
          } as HealthCenterWithDistance;
        })
        .filter(center => {
          const maxDistance = options.filters?.max_distance_km || radiusKm;
          return center.distance_km <= maxDistance;
        });

      // Sort by distance
      const sortedCenters = sortByDistance(centersWithDistance);

      // Apply max results limit
      const maxResults = 10;
      const limitedCenters = sortedCenters.slice(0, maxResults);

      setCenters(limitedCenters);
    } catch (err) {
      logger.error('Error searching health centers:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  }, [supabase, options.filters]);

  // Fetch all centers (fallback when no location available)
  const fetchAllCenters = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);

      const query = supabase
        .from('health_centers')
        .select('*')
        .eq('offers_ive_ile', true)
        .limit(10);

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      // Map to HealthCenterWithDistance (distance_km = 0 when no location)
      const centersData: HealthCenterWithDistance[] = (data || []).map((center: any) => ({
        ...center,
        distance_km: 0,
        travel_time_minutes: undefined
      }));

      setCenters(centersData);
    } catch (err) {
      logger.error('Error fetching health centers:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  }, [supabase]);

  const refetch = useCallback(async () => {
    if (userLocation) {
      await searchNearby(userLocation);
    } else {
      await fetchAllCenters();
    }
  }, [userLocation, searchNearby, fetchAllCenters]);

  // Auto-detect location on mount if enabled
  useEffect(() => {
    const initLocation = async () => {
      if (options.autoDetectLocation) {
        try {
          await requestLocation();
        } catch (err) {
          // Fallback to all centers if location denied
          await fetchAllCenters();
        }
      } else {
        await fetchAllCenters();
      }
    };

    initLocation();
  }, [options.autoDetectLocation, requestLocation, fetchAllCenters]);

  // Search nearby when location is available
  useEffect(() => {
    if (userLocation) {
      searchNearby(userLocation);
    }
  }, [userLocation, searchNearby]);

  return {
    centers,
    isLoading,
    error,
    userLocation,
    requestLocation,
    searchNearby,
    refetch
  };
}

// Hook para obtener detalles de un centro específico
export function useHealthCenterById(centerId: string | null) {
  const supabase = useSupabase();
  const [center, setCenter] = useState<HealthCenter | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!centerId) {
      setCenter(null);
      setIsLoading(false);
      return;
    }

    const fetchCenter = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const { data, error: fetchError } = await supabase
          .from('health_centers')
          .select('*')
          .eq('id', centerId)
          .single();

        if (fetchError) throw fetchError;

        setCenter(data as HealthCenter);
      } catch (err) {
        logger.error('Error fetching health center:', err);
        setError(err instanceof Error ? err.message : 'Error desconocido');
      } finally {
        setIsLoading(false);
      }
    };

    fetchCenter();
  }, [centerId, supabase]);

  return { center, isLoading, error };
}

// Helper para formatear información del centro
export function formatHealthCenterInfo(center: HealthCenterWithDistance) {
  return {
    name: center.name,
    type: getHealthCenterTypeLabel(center.type),
    address: formatAddressForDisplay(center.address),
    distance: formatDistance(center.distance_km),
    travelTime: center.travel_time_minutes
      ? `${center.travel_time_minutes} min`
      : undefined,
    phone: center.phone,
    methods: {
      medication: center.offers_medication_method,
      surgical: center.offers_surgical_method
    },
    features: {
      walkIns: center.accepts_walk_ins,
      service24h: center.has_24h_service,
      psychologicalSupport: center.offers_psychological_support
    }
  };
}

function getHealthCenterTypeLabel(type: string): string {
  const labels: Record<string, string> = {
    public_hospital: 'Hospital Público',
    health_center: 'Centro de Salud',
    caps: 'CAPS',
    clinic: 'Clínica Privada',
    ngo: 'ONG'
  };
  return labels[type] || type;
}

function formatAddressForDisplay(address: any): string {
  if (!address) return '';

  const parts = [
    address.street,
    address.number,
    address.city,
    address.state
  ].filter(Boolean);

  return parts.join(', ');
}

import { useState, useEffect, useCallback, useRef } from 'react';
import type {
  MedicalMessage,
  MedicalChatInsert,
  MedicalMessageInsert,
  MedicalChatWithLastMessage,
  ChatStatusType
} from '@autamedica/types';
import { useSupabase } from '@autamedica/auth/react';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { logger } from '@autamedica/shared';

interface UseMedicalChatsOptions {
  patientId?: string;
  activeOnly?: boolean;
}

interface UseMedicalChatsResult {
  chats: MedicalChatWithLastMessage[];
  isLoading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
  createChat: (data: MedicalChatInsert) => Promise<{ success: boolean; chatId?: string; error?: any }>;
  updateChatStatus: (chatId: string, status: ChatStatusType) => Promise<{ success: boolean; error?: any }>;
}

export function useMedicalChats(
  options: UseMedicalChatsOptions = {}
): UseMedicalChatsResult {
  const supabase = useSupabase();
  const [chats, setChats] = useState<MedicalChatWithLastMessage[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchChats = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Build query
      let query = supabase
        .from('medical_chats')
        .select(`
          *,
          specialist:reproductive_health_specialists!inner (
            doctor:doctors!inner (
              first_name,
              last_name
            )
          ),
          messages:medical_messages (
            content,
            author_type,
            created_at,
            is_read
          )
        `);

      // Apply filters
      if (options.patientId) {
        query = query.eq('patient_id', options.patientId);
      }

      if (options.activeOnly) {
        query = query.in('status', ['active', 'waiting_response']);
      }

      // Order by last message
      query = query.order('last_message_at', { ascending: false });

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      // Transform data
      const transformedData: MedicalChatWithLastMessage[] = (data || []).map((item: any) => {
        const messages = item.messages || [];
        const lastMessage = messages.length > 0 ? messages[messages.length - 1] : null;
        const unreadCount = messages.filter((m: any) => !m.is_read && m.author_type !== 'patient').length;

        return {
          id: item.id,
          patient_id: item.patient_id,
          specialist_id: item.specialist_id,
          appointment_id: item.appointment_id,
          status: item.status,
          subject: item.subject,
          is_urgent: item.is_urgent,
          last_message_at: item.last_message_at,
          created_at: item.created_at,
          updated_at: item.updated_at,
          last_message_content: lastMessage?.content || '',
          last_message_author: lastMessage?.author_type || 'system',
          unread_count: unreadCount,
          specialist_name: `Dr. ${item.specialist?.doctor?.first_name || ''} ${item.specialist?.doctor?.last_name || ''}`.trim()
        };
      });

      setChats(transformedData);
    } catch (err) {
      logger.error('Error fetching medical chats:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  }, [supabase, options.patientId, options.activeOnly]);

  const createChat = useCallback(async (data: MedicalChatInsert) => {
    try {

      const insertData = {
        patient_id: data.patient_id,
        specialist_id: data.specialist_id,
        subject: data.subject,
        is_urgent: data.is_urgent || false,
        status: 'active' as ChatStatusType,
        last_message_at: new Date().toISOString(),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };

      const { data: result, error: insertError } = await supabase
        .from('medical_chats')
        .insert(insertData)
        .select()
        .single();

      if (insertError) throw insertError;

      // Refetch to update list
      await fetchChats();

      return {
        success: true,
        chatId: result?.id
      };
    } catch (err) {
      logger.error('Error creating chat:', err);
      return {
        success: false,
        error: err
      };
    }
  }, [supabase, fetchChats]);

  const updateChatStatus = useCallback(async (
    chatId: string,
    status: ChatStatusType
  ) => {
    try {

      const { error: updateError } = await supabase
        .from('medical_chats')
        .update({
          status,
          updated_at: new Date().toISOString()
        })
        .eq('id', chatId);

      if (updateError) throw updateError;

      // Refetch to update list
      await fetchChats();

      return { success: true };
    } catch (err) {
      logger.error('Error updating chat status:', err);
      return {
        success: false,
        error: err
      };
    }
  }, [supabase, fetchChats]);

  useEffect(() => {
    fetchChats();
  }, [fetchChats]);

  return {
    chats,
    isLoading,
    error,
    refetch: fetchChats,
    createChat,
    updateChatStatus
  };
}

// Hook para mensajes de un chat específico con Realtime
interface UseChatMessagesResult {
  messages: MedicalMessage[];
  isLoading: boolean;
  error: string | null;
  sendMessage: (content: string, contentType?: 'text' | 'image' | 'document') => Promise<{ success: boolean; error?: any }>;
  markAsRead: (messageId: string) => Promise<void>;
}

export function useChatMessages(
  chatId: string | null,
  userId: string | null
): UseChatMessagesResult {
  const supabase = useSupabase();
  const [messages, setMessages] = useState<MedicalMessage[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const channelRef = useRef<RealtimeChannel | null>(null);

  const fetchMessages = useCallback(async () => {
    if (!chatId) {
      setMessages([]);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      const { data, error: fetchError } = await supabase
        .from('medical_messages')
        .select('*')
        .eq('chat_id', chatId)
        .order('created_at', { ascending: true });

      if (fetchError) throw fetchError;

      setMessages((data || []) as MedicalMessage[]);
    } catch (err) {
      logger.error('Error fetching messages:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  }, [supabase, chatId]);

  const sendMessage = useCallback(async (
    content: string,
    contentType: 'text' | 'image' | 'document' = 'text'
  ) => {
    if (!chatId || !userId) {
      return {
        success: false,
        error: 'Missing chatId or userId'
      };
    }

    try {

      const messageData: MedicalMessageInsert = {
        chat_id: chatId,
        author_type: 'patient',
        author_id: userId,
        content_type: contentType,
        content,
        attachment_url: undefined
      };

      const { error: insertError } = await supabase
        .from('medical_messages')
        .insert({
          ...messageData,
          is_read: false,
          created_at: new Date().toISOString()
        });

      if (insertError) throw insertError;

      // Update chat's last_message_at
      await supabase
        .from('medical_chats')
        .update({
          last_message_at: new Date().toISOString(),
          status: 'waiting_response',
          updated_at: new Date().toISOString()
        })
        .eq('id', chatId);

      return { success: true };
    } catch (err) {
      logger.error('Error sending message:', err);
      return {
        success: false,
        error: err
      };
    }
  }, [supabase, chatId, userId]);

  const markAsRead = useCallback(async (messageId: string) => {
    try {

      await supabase
        .from('medical_messages')
        .update({
          is_read: true,
          read_at: new Date().toISOString()
        })
        .eq('id', messageId);
    } catch (err) {
      logger.error('Error marking message as read:', err);
    }
  }, [supabase]);

  // Setup Realtime subscription
  useEffect(() => {
    if (!chatId || !supabase) return;

    const channel = supabase
      .channel(`medical_chat:${chatId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'medical_messages',
          filter: `chat_id=eq.${chatId}`
        },
        (payload) => {
          // logger.info('New message received:', payload);
          const newMessage = payload.new as MedicalMessage;
          setMessages((prev) => [...prev, newMessage]);
        }
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [supabase, chatId]);

  useEffect(() => {
    fetchMessages();
  }, [fetchMessages]);

  return {
    messages,
    isLoading,
    error,
    sendMessage,
    markAsRead
  };
}

import { useState, useEffect, useCallback } from 'react'
import { useSupabase } from '@autamedica/auth/react'
import { logger } from '@autamedica/shared'
import type {
  MedicalHistoryTimeline,
  MedicalHistorySummary,
  PatientId
} from '@autamedica/types'

export function useMedicalHistory(patientId?: PatientId) {
  const supabase = useSupabase()
  const [summary, setSummary] = useState<MedicalHistorySummary | null>(null)
  const [timeline, setTimeline] = useState<MedicalHistoryTimeline | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchMedicalHistory = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)

      // Get current user session
      const { data: { user } } = await supabase.auth.getUser()

      if (!user) {
        throw new Error('No authenticated user found')
      }

      const userId = patientId || (user.id as PatientId)

      // Fetch medical records
      const { data: medicalRecords, error: recordsError } = await supabase
        .from('medical_records')
        .select('*')
        .eq('patient_id', userId)
        .is('deleted_at', null)
        .order('created_at', { ascending: false })

      if (recordsError) throw recordsError

      // Fetch from anamnesis table for chronic conditions and allergies
      const { data: anamnesisData } = await supabase
        .from('anamnesis')
        .select('*')
        .eq('patient_id', userId)
        .single()

      // Build summary from data
      const activeMedications = medicalRecords?.filter(r =>
        r.record_type === 'prescription' && r.status === 'active'
      ) || []

      const recentDiagnoses = medicalRecords?.filter(r =>
        r.record_type === 'diagnosis'
      ) || []

      const summaryData: MedicalHistorySummary = {
        patient_id: userId,
        active_conditions_count: recentDiagnoses.length,
        active_medications_count: activeMedications.length,
        known_allergies_count: 0, // Will be populated from anamnesis if available
        last_encounter_date: medicalRecords?.[0]?.created_at || new Date().toISOString(),
        chronic_conditions: recentDiagnoses.map(d => ({
          condition: d.title,
          diagnosed_date: d.created_at,
          icd10_code: d.icd10_code || undefined,
          status: 'active' as const
        })),
        critical_allergies: [],
        current_medications: activeMedications.map(m => ({
          medication_name: m.title,
          dosage: m.dosage || 'No especificado',
          frequency: m.frequency || 'Según indicación médica',
          start_date: m.created_at,
          route: m.route || 'oral'
        }))
      }

      // Build timeline
      const timelineData: MedicalHistoryTimeline = {
        patient_id: userId,
        sections: {
          conditions: recentDiagnoses.map(r => ({
            id: r.id,
            condition: r.title,
            diagnosed_date: r.created_at,
            icd10_code: r.icd10_code || undefined,
            status: 'active' as const,
            notes: r.notes || undefined
          })),
          allergies: [],
          medications: activeMedications.map(m => ({
            id: m.id,
            medication_name: m.title,
            dosage: m.dosage || 'No especificado',
            frequency: m.frequency || 'Según indicación médica',
            route: m.route || 'oral',
            start_date: m.created_at,
            end_date: m.end_date || null,
            prescribing_doctor: m.doctor_id || undefined,
            reason: m.notes || 'No especificado'
          })),
          procedures: medicalRecords?.filter(r => r.record_type === 'procedure').map(p => ({
            id: p.id,
            procedure_name: p.title,
            date: p.created_at,
            provider: p.doctor_id || undefined,
            facility: p.facility || undefined,
            outcome: p.outcome || undefined
          })) || [],
          encounters: medicalRecords?.filter(r => r.record_type === 'encounter' || r.record_type === 'note').map(e => ({
            id: e.id,
            date: e.created_at,
            type: 'consultation' as const,
            provider: e.doctor_id || undefined,
            reason: e.title,
            diagnosis: e.diagnosis || undefined,
            notes: e.notes || undefined
          })) || [],
          immunizations: []
        }
      }

      setSummary(summaryData)
      setTimeline(timelineData)

    } catch (err) {
      logger.error('Error fetching medical history:', err)
      setError(err instanceof Error ? err.message : 'Error loading medical history')
    } finally {
      setLoading(false)
    }
  }, [supabase, patientId])

  useEffect(() => {
    fetchMedicalHistory()
  }, [fetchMedicalHistory])

  const addCondition = async (condition: any) => {
    try {
      const res = await fetch('/api/medical-history/conditions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          condition: condition.condition,
          icd10_code: condition.icd10_code,
          notes: condition.notes,
        }),
      })
      if (!res.ok) throw new Error('Failed to add condition')
      await fetchMedicalHistory()
    } catch (error) {
      logger.error('Error adding condition:', error)
      setError('Error adding medical condition')
    }
  }

  const addMedication = async (medication: any) => {
    try {
      const res = await fetch('/api/medical-history/medications', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          medication_name: medication.medication_name,
          dosage: medication.dosage,
          frequency: medication.frequency,
          route: medication.route,
          reason: medication.reason,
          end_date: medication.end_date ?? null,
        }),
      })
      if (!res.ok) throw new Error('Failed to add medication')
      await fetchMedicalHistory()
    } catch (error) {
      logger.error('Error adding medication:', error)
      setError('Error adding medication')
    }
  }

  const addAllergy = async (allergy: any) => {
    try {
      const res = await fetch('/api/medical-history/allergies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          allergen: allergy.allergen,
          type: allergy.type,
          severity: allergy.severity,
          reaction: allergy.reaction,
          notes: allergy.notes,
        }),
      })
      if (!res.ok) throw new Error('Failed to add allergy')
      await fetchMedicalHistory()
    } catch (error) {
      logger.error('Error adding allergy:', error)
      setError('Error adding allergy')
    }
  }

  return {
    summary,
    timeline,
    loading,
    error,
    refresh: fetchMedicalHistory,
    addCondition,
    addMedication,
    addAllergy
  }
}

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import type { User } from '@supabase/supabase-js';
import { logger } from '@autamedica/shared';
import { useSupabase } from '@autamedica/auth/react';
import { safeParseProfile, type Profile } from '@/lib/zod/profiles';
import { parsePatient, type Patient } from '@/lib/zod/patients';

interface PatientSessionState {
  user: User | null;
  profile: Profile | null;
  patient: Patient | null;
  loading: boolean;
  error: string | null;
}

const INITIAL_STATE: PatientSessionState = {
  user: null,
  profile: null,
  patient: null,
  loading: true,
  error: null,
};

function ensureEmail(user: User): string {
  const candidate = user.email ?? (user.user_metadata as Record<string, unknown> | undefined)?.email;
  if (typeof candidate === 'string' && candidate.length > 0) {
    return candidate;
  }
  return `${user.id}@patients.autamedica.local`;
}

export interface UsePatientSessionResult extends PatientSessionState {
  refresh: () => Promise<void>;
  signOut: () => Promise<void>;
}

export function usePatientSession(): UsePatientSessionResult {
  const supabase = useSupabase();
  const [state, setState] = useState<PatientSessionState>(INITIAL_STATE);
  const isMountedRef = useRef(false);

  const safeSetState = useCallback(
    (updater: (prev: PatientSessionState) => PatientSessionState) => {
      if (isMountedRef.current) {
        setState(updater);
      }
    },
    [],
  );

  const fetchOrCreateProfile = useCallback(
    async (user: User): Promise<Profile> => {
      if (!supabase) {
        throw new Error('Supabase client not available');
      }

      const email = ensureEmail(user);

      // Intento 1: esquema nuevo (user_id)
      let { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('user_id', user.id)
        .maybeSingle();

      // Si la columna no existe o no hay fila, intentar esquema legacy (id)
      if ((error && error.code !== 'PGRST116') || (!data && !error)) {
        const tryLegacy = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .maybeSingle();
        data = tryLegacy.data as any;
        error = tryLegacy.error as any;
      }

      if (error && error.code !== 'PGRST116') {
        throw error;
      }

      let profileRow: any = data ?? null;
      // Normalizar id -> user_id si fuese legacy
      if (profileRow && !profileRow.user_id && profileRow.id) {
        profileRow = { ...profileRow, user_id: profileRow.id };
      }

      if (!profileRow) {
        // Intentar insertar con user_id; si falla por columna, probar con id
        let inserted: any = null;
        let insertError: any = null;
        const insert = await supabase
          .from('profiles')
          .insert({
            user_id: user.id,
            email,
            role: 'patient',
            external_id: user.id,
          })
          .select('*')
          .single();
        inserted = insert.data;
        insertError = insert.error;

        if (insertError) {
          // Reintentar esquema legacy
          const legacy = await supabase
            .from('profiles')
            .insert({
              id: user.id,
              email,
              role: 'patient',
              external_id: user.id,
            })
            .select('*')
            .single();
          inserted = legacy.data;
          insertError = legacy.error;
        }

        if (insertError) {
          throw insertError;
        }

        profileRow = inserted;
      } else {
        const updates: Record<string, unknown> = {};

        if (!profileRow.email) {
          updates.email = email;
        }

        // Evitar escribir columnas que podrían no existir en ciertos esquemas (role/external_id)

        if (Object.keys(updates).length > 0) {
          // Update por user_id o por id según exista
          const updateTry = await supabase
            .from('profiles')
            .update(updates)
            .eq(profileRow.user_id ? 'user_id' : 'id', user.id)
            .select('*')
            .single();
          const updated = updateTry.data as any;
          const updateError = updateTry.error as any;

          if (updateError) {
            throw updateError;
          }

          profileRow = updated;
        }
      }
      // Parse robusto: intentar zod; si falla, normalizar mínimamente
      const parsed = safeParseProfile(profileRow);
      if (parsed) return parsed;
      return {
        userId: profileRow.user_id ?? profileRow.id,
        email: profileRow.email ?? email,
        role: (profileRow.role as any) ?? 'patient',
        firstName: (profileRow.first_name as any) ?? null,
        lastName: (profileRow.last_name as any) ?? null,
        phone: (profileRow.phone as any) ?? null,
        avatarUrl: (profileRow.avatar_url as any) ?? null,
        active: (profileRow.active as any) ?? null,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        deletedAt: null,
      } as unknown as Profile;
    },
    [supabase],
  );

  const fetchOrCreatePatient = useCallback(
    async (userId: string): Promise<Patient | null> => {
      if (!supabase) {
        throw new Error('Supabase client not available');
      }

      const { data, error } = await supabase
        .from('patients')
        .select('*')
        .eq('user_id', userId)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') {
        throw error;
      }

      let patientRow = data ?? null;

      if (!patientRow) {
        const { data: inserted, error: insertError } = await supabase
          .from('patients')
          .insert({
            user_id: userId,
            active: true,
          })
          .select('*');

        if (insertError) {
          throw insertError;
        }

        if (Array.isArray(inserted) && inserted.length > 0) {
          patientRow = inserted[0];
        } else if (inserted && !Array.isArray(inserted)) {
          patientRow = inserted as Record<string, unknown>;
        }
      }

      return patientRow ? parsePatient(patientRow) : null;
    },
    [supabase],
  );

  const refresh = useCallback(async () => {
    // SSR guard: Don't try to fetch session during server-side rendering
    if (!supabase) {
      if (typeof window === 'undefined') {
        safeSetState(prev => ({ ...prev, loading: false }));
      }
      return;
    }

    safeSetState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const { data: sessionData, error: sessionError } = await supabase.auth.getSession();

      if (sessionError) {
        throw sessionError;
      }

      const session = sessionData.session;

      if (!session?.user) {
        safeSetState(() => ({ ...INITIAL_STATE, loading: false, error: null }));
        return;
      }

      const user = session.user;
      const profile = await fetchOrCreateProfile(user);

      if (profile.role && profile.role !== 'patient') {
        safeSetState(() => ({
          user,
          profile,
          patient: null,
          loading: false,
          error: 'Tu cuenta no tiene acceso al portal de pacientes.',
        }));
        return;
      }

      const patient = await fetchOrCreatePatient(user.id);

      safeSetState(() => ({
        user,
        profile,
        patient,
        loading: false,
        error: null,
      }));
    } catch (error) {
      logger.error('[usePatientSession] Failed to sync session', error);
      safeSetState(prev => ({
        ...prev,
        loading: false,
        error: 'No pudimos cargar tu sesión. Intentá nuevamente.',
      }));
    }
  }, [fetchOrCreatePatient, fetchOrCreateProfile, safeSetState, supabase]);

  useEffect(() => {
    isMountedRef.current = true;

    // SSR guard
    if (typeof window === 'undefined') {
      safeSetState(prev => ({ ...prev, loading: false }));
      return () => {
        isMountedRef.current = false;
      };
    }

    return () => {
      isMountedRef.current = false;
    };
  }, [safeSetState]);

  useEffect(() => {
    if (!supabase) {
      return;
    }

    refresh();

    const { data } = supabase.auth.onAuthStateChange((event, session) => {
      if (!isMountedRef.current) {
        return;
      }

      if (event === 'SIGNED_OUT') {
        safeSetState(() => ({ ...INITIAL_STATE, loading: false }));
        return;
      }

      if (session?.user) {
        refresh();
      }
    });

    return () => {
      data.subscription.unsubscribe();
    };
  }, [refresh, safeSetState, supabase]);

  const signOut = useCallback(async () => {
    if (!supabase) return;
    await supabase.auth.signOut();
    safeSetState(() => ({ ...INITIAL_STATE, loading: false }));
  }, [safeSetState, supabase]);

  return {
    ...state,
    refresh,
    signOut,
  };
}

import { useState, useEffect, useCallback } from 'react';
import type {
  PreventiveScreening,
  PatientScreeningWithDetails,
  ScreeningRecommendation,
  ScreeningStatusType,
  PatientScreeningInsert
} from '@autamedica/types';
import { useSupabase } from '@autamedica/auth/react';
import { logger } from '@autamedica/shared';

interface UsePreventiveScreeningsOptions {
  patientId?: string;
  status?: ScreeningStatusType[];
  categoryFilter?: string;
  includeCompleted?: boolean;
}

interface UsePreventiveScreeningsResult {
  // Screenings del paciente
  myScreenings: PatientScreeningWithDetails[];

  // Recomendaciones personalizadas
  recommendations: ScreeningRecommendation[];

  // Estados de carga
  isLoading: boolean;
  isLoadingRecommendations: boolean;
  error: string | null;

  // Acciones
  scheduleScreening: (screeningId: string, scheduledDate: Date) => Promise<{ success: boolean; error?: any }>;
  markAsCompleted: (patientScreeningId: string, resultSummary?: string) => Promise<{ success: boolean; error?: any }>;
  cancelScreening: (patientScreeningId: string) => Promise<{ success: boolean; error?: any }>;
  refetch: () => Promise<void>;
}

export function usePreventiveScreenings(
  options: UsePreventiveScreeningsOptions = {}
): UsePreventiveScreeningsResult {
  const supabase = useSupabase();
  const [myScreenings, setMyScreenings] = useState<PatientScreeningWithDetails[]>([]);
  const [recommendations, setRecommendations] = useState<ScreeningRecommendation[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingRecommendations, setIsLoadingRecommendations] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch screenings del paciente
  const fetchMyScreenings = useCallback(async () => {
    if (!options.patientId) {
      setMyScreenings([]);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      // Build query
      let query = supabase
        .from('patient_screenings')
        .select(`
          *,
          screening:preventive_screenings!inner (
            id,
            name,
            category,
            description,
            target_gender,
            min_age,
            max_age,
            recommended_frequency,
            is_mandatory,
            estimated_cost_ars,
            covered_by_public_health,
            requires_specialist,
            preparation_instructions
          ),
          assigned_doctor:doctors (
            id,
            first_name,
            last_name
          )
        `)
        .eq('patient_id', options.patientId);

      // Apply filters
      if (options.status && options.status.length > 0) {
        query = query.in('status', options.status);
      }

      if (options.categoryFilter) {
        query = query.eq('screening.category', options.categoryFilter);
      }

      if (!options.includeCompleted) {
        query = query.neq('status', 'completed');
      }

      // Order by urgency
      query = query.order('next_due_date', { ascending: true, nullsFirst: false });

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      // Transform data
      const transformedData: PatientScreeningWithDetails[] = (data || []).map((item: any) => ({
        id: item.id,
        patient_id: item.patient_id,
        screening_id: item.screening_id,
        status: item.status,
        scheduled_date: item.scheduled_date,
        completed_date: item.completed_date,
        next_due_date: item.next_due_date,
        assigned_doctor_id: item.assigned_doctor_id,
        notes: item.notes,
        result_summary: item.result_summary,
        created_at: item.created_at,
        updated_at: item.updated_at,
        screening: item.screening,
        assigned_doctor: item.assigned_doctor ? {
          id: item.assigned_doctor.id,
          first_name: item.assigned_doctor.first_name,
          last_name: item.assigned_doctor.last_name,
          specialty: '' // TODO: Add specialty when available
        } : null
      }));

      setMyScreenings(transformedData);
    } catch (err) {
      logger.error('Error fetching patient screenings:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  }, [supabase, options.patientId, options.status, options.categoryFilter, options.includeCompleted]);

  // Fetch recommendations usando función SQL
  const fetchRecommendations = useCallback(async () => {
    if (!options.patientId) {
      setRecommendations([]);
      setIsLoadingRecommendations(false);
      return;
    }

    try {
      setIsLoadingRecommendations(true);

      // Llamar función SQL que calcula recomendaciones
      const { data, error: rpcError } = await supabase.rpc('get_recommended_screenings', {
        patient_id_param: options.patientId,
        include_overdue: true
      });

      if (rpcError) throw rpcError;

      // Transform to ScreeningRecommendation format
      const transformedRecommendations: ScreeningRecommendation[] = await Promise.all(
        (data || []).map(async (item: any) => {
          // Fetch full screening details
          const { data: screeningData } = await supabase
            .from('preventive_screenings')
            .select('*')
            .eq('id', item.screening_id)
            .single();

          return {
            screening: screeningData as PreventiveScreening,
            is_due: item.status === 'overdue' || item.status === 'not_started',
            urgency: item.urgency as 'low' | 'medium' | 'high',
            reason: item.reason,
            next_due_date: item.next_due_date
          };
        })
      );

      setRecommendations(transformedRecommendations);
    } catch (err) {
      logger.error('Error fetching recommendations:', err);
      // No setear error aquí para no bloquear el resto de la UI
    } finally {
      setIsLoadingRecommendations(false);
    }
  }, [supabase, options.patientId]);

  // Schedule a screening
  const scheduleScreening = useCallback(async (
    screeningId: string,
    scheduledDate: Date
  ) => {
    if (!options.patientId) {
      return { success: false, error: 'Patient ID required' };
    }

    try {

      // Check if patient_screening already exists
      const { data: existing } = await supabase
        .from('patient_screenings')
        .select('id')
        .eq('patient_id', options.patientId)
        .eq('screening_id', screeningId)
        .single();

      if (existing) {
        // Update existing
        const { error: updateError } = await supabase
          .from('patient_screenings')
          .update({
            status: 'scheduled',
            scheduled_date: scheduledDate.toISOString(),
            updated_at: new Date().toISOString()
          })
          .eq('id', existing.id);

        if (updateError) throw updateError;
      } else {
        // Create new
        const insertData: PatientScreeningInsert = {
          patient_id: options.patientId,
          screening_id: screeningId,
          status: 'scheduled',
          scheduled_date: scheduledDate.toISOString(),
          completed_date: null,
          next_due_date: null,
          assigned_doctor_id: null,
          notes: null,
          result_summary: null
        };

        const { error: insertError } = await supabase
          .from('patient_screenings')
          .insert(insertData);

        if (insertError) throw insertError;
      }

      // Refetch data
      await fetchMyScreenings();
      await fetchRecommendations();

      return { success: true };
    } catch (err) {
      logger.error('Error scheduling screening:', err);
      return { success: false, error: err };
    }
  }, [supabase, options.patientId, fetchMyScreenings, fetchRecommendations]);

  // Mark screening as completed
  const markAsCompleted = useCallback(async (
    patientScreeningId: string,
    resultSummary?: string
  ) => {
    try {

      // Get screening details to calculate next due date
      const { data: screening } = await supabase
        .from('patient_screenings')
        .select('screening:preventive_screenings!inner(recommended_frequency)')
        .eq('id', patientScreeningId)
        .single();

      const completedDate = new Date();
      let nextDueDate: Date | null = null;

      // Calculate next due date based on frequency
      if (screening?.screening?.recommended_frequency) {
        const freq = screening.screening.recommended_frequency;
        nextDueDate = new Date(completedDate);

        switch (freq) {
          case 'monthly':
            nextDueDate.setMonth(nextDueDate.getMonth() + 1);
            break;
          case 'every_3_months':
            nextDueDate.setMonth(nextDueDate.getMonth() + 3);
            break;
          case 'every_6_months':
            nextDueDate.setMonth(nextDueDate.getMonth() + 6);
            break;
          case 'annually':
            nextDueDate.setFullYear(nextDueDate.getFullYear() + 1);
            break;
          case 'every_2_years':
            nextDueDate.setFullYear(nextDueDate.getFullYear() + 2);
            break;
          case 'every_3_years':
            nextDueDate.setFullYear(nextDueDate.getFullYear() + 3);
            break;
          case 'every_5_years':
            nextDueDate.setFullYear(nextDueDate.getFullYear() + 5);
            break;
          case 'every_10_years':
            nextDueDate.setFullYear(nextDueDate.getFullYear() + 10);
            break;
          case 'one_time':
            nextDueDate = null; // No hay próxima fecha
            break;
        }
      }

      const { error: updateError } = await supabase
        .from('patient_screenings')
        .update({
          status: 'completed',
          completed_date: completedDate.toISOString(),
          next_due_date: nextDueDate?.toISOString() || null,
          result_summary: resultSummary || null,
          updated_at: new Date().toISOString()
        })
        .eq('id', patientScreeningId);

      if (updateError) throw updateError;

      // Refetch data
      await fetchMyScreenings();
      await fetchRecommendations();

      return { success: true };
    } catch (err) {
      logger.error('Error marking screening as completed:', err);
      return { success: false, error: err };
    }
  }, [supabase, fetchMyScreenings, fetchRecommendations]);

  // Cancel screening
  const cancelScreening = useCallback(async (patientScreeningId: string) => {
    try {

      const { error: updateError } = await supabase
        .from('patient_screenings')
        .update({
          status: 'not_started',
          scheduled_date: null,
          updated_at: new Date().toISOString()
        })
        .eq('id', patientScreeningId);

      if (updateError) throw updateError;

      // Refetch data
      await fetchMyScreenings();
      await fetchRecommendations();

      return { success: true };
    } catch (err) {
      logger.error('Error cancelling screening:', err);
      return { success: false, error: err };
    }
  }, [supabase, fetchMyScreenings, fetchRecommendations]);

  // Refetch all data
  const refetch = useCallback(async () => {
    await Promise.all([
      fetchMyScreenings(),
      fetchRecommendations()
    ]);
  }, [fetchMyScreenings, fetchRecommendations]);

  // Initial fetch
  useEffect(() => {
    fetchMyScreenings();
  }, [fetchMyScreenings]);

  useEffect(() => {
    fetchRecommendations();
  }, [fetchRecommendations]);

  return {
    myScreenings,
    recommendations,
    isLoading,
    isLoadingRecommendations,
    error,
    scheduleScreening,
    markAsCompleted,
    cancelScreening,
    refetch
  };
}

'use client';

import { useCallback, useState } from 'react';
import { logger } from '@autamedica/shared';
import type { ProfileUpdateInput, Profile } from '@/lib/zod/profiles';
import type { PatientProfileUpdateInput, Patient } from '@/lib/zod/patients';

export interface PatientProfileUpdateResult {
  profile: Profile | null;
  patient: Patient | null;
}

export interface UsePatientProfileReturn {
  isSaving: boolean;
  error: string | null;
  success: boolean;
  updateProfile: (input: {
    profile?: ProfileUpdateInput;
    patient?: PatientProfileUpdateInput;
  }) => Promise<PatientProfileUpdateResult | null>;
  resetStatus: () => void;
}

export function usePatientProfile(userId: string | null): UsePatientProfileReturn {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const updateProfile = useCallback<UsePatientProfileReturn['updateProfile']>(
    async ({ profile, patient }) => {
      if (!userId) {
        setError('Sesión inválida. Iniciá sesión nuevamente.');
        return null;
      }

      try {
        setIsSaving(true);
        setError(null);
        setSuccess(false);

        if (typeof window === 'undefined') {
          setError('Las actualizaciones solo están disponibles desde el navegador.');
          return null;
        }

        // Usar API server-side para respetar RLS y lógica de negocio
        const res = await fetch('/api/profile', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ profile, patient }),
        });

        if (!res.ok) {
          const details = await res.json().catch(() => ({}));
          throw new Error(details?.error || 'No pudimos guardar los cambios');
        }

        const json = await res.json();
        setSuccess(true);
        return { profile: json?.data?.profile ?? null, patient: json?.data?.patient ?? null };
      } catch (updateError) {
        logger.error('[usePatientProfile] update failed', updateError);
        setError('No pudimos guardar los cambios. Intentá nuevamente.');
        return null;
      } finally {
        setIsSaving(false);
      }
    },
    [userId],
  );

  const resetStatus = useCallback(() => {
    setError(null);
    setSuccess(false);
  }, []);

  return {
    isSaving,
    error,
    success,
    updateProfile,
    resetStatus,
  };
}

import { useEffect, useState } from 'react';
import {
  RemoteParticipant,
  RemoteTrack,
  RemoteTrackPublication,
  Track,
} from 'livekit-client';

/**
 * Hook para obtener el stream de video real del participante remoto (médico)
 * Usa LiveKit para WebRTC real
 *
 * @param remoteParticipant - Participante remoto de LiveKit (el médico)
 * @returns MediaStream del video del médico o null
 */
export function useRealRemoteStream(
  remoteParticipant?: RemoteParticipant
): MediaStream | null {
  const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null);

  useEffect(() => {
    if (!remoteParticipant) {
      setRemoteStream(null);
      return;
    }

    /**
     * Handler cuando un track es suscrito
     * Se ejecuta cuando el médico activa su cámara
     */
    const handleTrackSubscribed = (
      track: RemoteTrack,
      publication: RemoteTrackPublication,
      participant: RemoteParticipant
    ) => {
      // Solo nos interesan los tracks de video
      if (track.kind === Track.Kind.Video) {
        // Crear MediaStream desde el track de LiveKit
        const mediaStream = new MediaStream([track.mediaStreamTrack]);
        setRemoteStream(mediaStream);

        console.log('✅ Video remoto conectado:', {
          participantId: participant.identity,
          trackId: track.sid,
        });
      }
    };

    /**
     * Handler cuando un track es desuscrito
     * Se ejecuta cuando el médico desactiva su cámara
     */
    const handleTrackUnsubscribed = (
      track: RemoteTrack,
      publication: RemoteTrackPublication,
      participant: RemoteParticipant
    ) => {
      if (track.kind === Track.Kind.Video) {
        setRemoteStream(null);

        console.log('⚠️  Video remoto desconectado:', {
          participantId: participant.identity,
          trackId: track.sid,
        });
      }
    };

    /**
     * Handler cuando cambia el estado de mute
     */
    const handleTrackMuted = (publication: RemoteTrackPublication) => {
      if (publication.kind === Track.Kind.Video) {
        console.log('🔇 Video remoto muteado');
      }
    };

    const handleTrackUnmuted = (publication: RemoteTrackPublication) => {
      if (publication.kind === Track.Kind.Video) {
        console.log('🔊 Video remoto desmuteado');
      }
    };

    // Suscribirse a eventos de LiveKit
    remoteParticipant.on('trackSubscribed', handleTrackSubscribed);
    remoteParticipant.on('trackUnsubscribed', handleTrackUnsubscribed);
    remoteParticipant.on('trackMuted', handleTrackMuted);
    remoteParticipant.on('trackUnmuted', handleTrackUnmuted);

    // Verificar si ya hay tracks de video disponibles
    // (caso cuando el médico ya tiene cámara activa al unirse)
    remoteParticipant.videoTracks.forEach((publication) => {
      if (publication.track && publication.isSubscribed) {
        handleTrackSubscribed(
          publication.track,
          publication,
          remoteParticipant
        );
      }
    });

    // Cleanup: desuscribirse de eventos
    return () => {
      remoteParticipant.off('trackSubscribed', handleTrackSubscribed);
      remoteParticipant.off('trackUnsubscribed', handleTrackUnsubscribed);
      remoteParticipant.off('trackMuted', handleTrackMuted);
      remoteParticipant.off('trackUnmuted', handleTrackUnmuted);

      // Detener el stream si existe
      if (remoteStream) {
        remoteStream.getTracks().forEach((track) => track.stop());
      }
    };
  }, [remoteParticipant]);

  return remoteStream;
}

/**
 * Hook alternativo que acepta múltiples participantes
 * Útil para consultas grupales
 */
export function useMultipleRemoteStreams(
  remoteParticipants: RemoteParticipant[]
): Map<string, MediaStream> {
  const [streams, setStreams] = useState<Map<string, MediaStream>>(new Map());

  useEffect(() => {
    const participantStreams = new Map<string, MediaStream>();

    remoteParticipants.forEach((participant) => {
      const handleTrackSubscribed = (
        track: RemoteTrack,
        publication: RemoteTrackPublication
      ) => {
        if (track.kind === Track.Kind.Video) {
          const mediaStream = new MediaStream([track.mediaStreamTrack]);
          participantStreams.set(participant.identity, mediaStream);
          setStreams(new Map(participantStreams));
        }
      };

      participant.on('trackSubscribed', handleTrackSubscribed);

      // Check existing tracks
      participant.videoTracks.forEach((publication) => {
        if (publication.track && publication.isSubscribed) {
          handleTrackSubscribed(publication.track, publication);
        }
      });
    });

    return () => {
      participantStreams.forEach((stream) => {
        stream.getTracks().forEach((track) => track.stop());
      });
    };
  }, [remoteParticipants]);

  return streams;
}

import { useState, useEffect, useCallback } from 'react';
import type {
  ReproductiveHealthAppointmentInsert,
  ReproductiveHealthAppointmentUpdate,
  ReproductiveHealthAppointmentWithDetails,
  AppointmentStatusType
} from '@autamedica/types';
import { useSupabase } from '@autamedica/auth/react';
import { logger } from '@autamedica/shared';

interface UseAppointmentsOptions {
  patientId?: string;
  status?: AppointmentStatusType;
  upcoming?: boolean;
}

interface UseAppointmentsResult {
  appointments: ReproductiveHealthAppointmentWithDetails[];
  isLoading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
  createAppointment: (data: ReproductiveHealthAppointmentInsert) => Promise<{ success: boolean; appointmentId?: string; error?: any }>;
  updateAppointment: (id: string, data: ReproductiveHealthAppointmentUpdate) => Promise<{ success: boolean; error?: any }>;
  cancelAppointment: (id: string) => Promise<{ success: boolean; error?: any }>;
}

export function useReproductiveHealthAppointments(
  options: UseAppointmentsOptions = {}
): UseAppointmentsResult {
  const supabase = useSupabase();
  const [appointments, setAppointments] = useState<ReproductiveHealthAppointmentWithDetails[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchAppointments = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Build query
      let query = supabase
        .from('reproductive_health_appointments')
        .select(`
          *,
          specialist:reproductive_health_specialists!inner (
            id,
            specialty,
            doctor:doctors!inner (
              first_name,
              last_name
            )
          ),
          patient:patients!inner (
            first_name,
            last_name
          )
        `);

      // Apply filters
      if (options.patientId) {
        query = query.eq('patient_id', options.patientId);
      }

      if (options.status) {
        query = query.eq('status', options.status);
      }

      if (options.upcoming) {
        const now = new Date().toISOString();
        query = query
          .gte('scheduled_at', now)
          .in('status', ['scheduled', 'confirmed']);
      }

      // Order by scheduled date
      query = query.order('scheduled_at', { ascending: true });

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      // Transform data
      const transformedData: ReproductiveHealthAppointmentWithDetails[] = (data || []).map((item: any) => ({
        id: item.id,
        patient_id: item.patient_id,
        specialist_id: item.specialist_id,
        consultation_type: item.consultation_type,
        modality: item.modality,
        status: item.status,
        scheduled_at: item.scheduled_at,
        duration_minutes: item.duration_minutes,
        meeting_url: item.meeting_url,
        notes_for_doctor: item.notes_for_doctor,
        is_first_consultation: item.is_first_consultation,
        requires_interpreter: item.requires_interpreter,
        preferred_language: item.preferred_language,
        created_at: item.created_at,
        updated_at: item.updated_at,
        specialist_name: `${item.specialist?.doctor?.first_name || ''} ${item.specialist?.doctor?.last_name || ''}`.trim(),
        specialist_specialty: item.specialist?.specialty || 'gynecology',
        patient_name: `${item.patient?.first_name || ''} ${item.patient?.last_name || ''}`.trim()
      }));

      setAppointments(transformedData);
    } catch (err) {
      logger.error('Error fetching appointments:', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setIsLoading(false);
    }
  }, [supabase, options.patientId, options.status, options.upcoming]);

  const createAppointment = useCallback(async (data: ReproductiveHealthAppointmentInsert) => {
    try {

      const insertData = {
        patient_id: data.patient_id,
        specialist_id: data.specialist_id,
        consultation_type: data.consultation_type,
        modality: data.modality,
        scheduled_at: data.scheduled_at,
        duration_minutes: data.duration_minutes || 30,
        notes_for_doctor: data.notes_for_doctor || null,
        requires_interpreter: data.requires_interpreter || false,
        preferred_language: data.preferred_language || 'es',
        status: 'scheduled',
        is_first_consultation: true, // This would need logic to check
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };

      const { data: result, error: insertError } = await supabase
        .from('reproductive_health_appointments')
        .insert(insertData)
        .select()
        .single();

      if (insertError) throw insertError;

      // Refetch to update list
      await fetchAppointments();

      return {
        success: true,
        appointmentId: result?.id
      };
    } catch (err) {
      logger.error('Error creating appointment:', err);
      return {
        success: false,
        error: err
      };
    }
  }, [supabase, fetchAppointments]);

  const updateAppointment = useCallback(async (
    id: string,
    data: ReproductiveHealthAppointmentUpdate
  ) => {
    try {

      const { error: updateError } = await supabase
        .from('reproductive_health_appointments')
        .update({
          ...data,
          updated_at: new Date().toISOString()
        })
        .eq('id', id);

      if (updateError) throw updateError;

      // Refetch to update list
      await fetchAppointments();

      return { success: true };
    } catch (err) {
      logger.error('Error updating appointment:', err);
      return {
        success: false,
        error: err
      };
    }
  }, [supabase, fetchAppointments]);

  const cancelAppointment = useCallback(async (id: string) => {
    return updateAppointment(id, { status: 'cancelled_by_patient' });
  }, [updateAppointment]);

  useEffect(() => {
    fetchAppointments();
  }, [fetchAppointments]);

  return {
    appointments,
    isLoading,
    error,
    refetch: fetchAppointments,
    createAppointment,
    updateAppointment,
    cancelAppointment
  };
}

