'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import type { MediaState, ConnectionQuality, SessionParticipant, SessionEvent } from '@autamedica/types';
import { logger } from '@autamedica/shared';

interface ApiSession {
  session_id: string;
  room_id: string;
  status: string;
  scheduled_at: string | null;
  started_at: string | null;
  ended_at: string | null;
}

interface StartSessionResponse {
  session: ApiSession;
  signaling: {
    room_id: string;
    server_url: string;
    ice_servers: Array<{ urls: string | string[]; username?: string; credential?: string }>;
  };
  livekit?: LiveKitConfig;
}

interface LiveKitConfig {
  token: string;
  url: string;
  roomName?: string;
}

interface UseTelemedicineReturn {
  session: ApiSession | null;
  participants: SessionParticipant[];
  events: SessionEvent[];
  localMediaState: MediaState;
  connectionQuality: ConnectionQuality;
  loading: boolean;
  error: string | null;
  startSession: (appointmentId: string, doctorId: string) => Promise<StartSessionResponse | null>;
  endSession: () => Promise<boolean>;
  toggleVideo: () => Promise<boolean>;
  toggleAudio: () => Promise<boolean>;
  toggleScreenShare: () => Promise<boolean>;
  updateConnectionQuality: (quality: ConnectionQuality) => void;
  refreshSession: () => Promise<void>;
  joinSession: (role?: string, sessionIdOverride?: string) => Promise<boolean>;
  leaveSession: (sessionIdOverride?: string) => Promise<boolean>;
  logEvent: (eventType: string, details?: string, sessionIdOverride?: string) => Promise<void>;
  livekit: LiveKitConfig | null;
}

function mapApiSession(data: any): ApiSession {
  return {
    session_id: String(data?.session_id ?? data?.id ?? ''),
    room_id: String(data?.room_id ?? ''),
    status: String(data?.status ?? 'scheduled'),
    scheduled_at: data?.scheduled_at ?? null,
    started_at: data?.started_at ?? null,
    ended_at: data?.ended_at ?? null,
  };
}

export function useTelemedicine(sessionId?: string): UseTelemedicineReturn {
  const [session, setSession] = useState<ApiSession | null>(null);
  const [participants, setParticipants] = useState<SessionParticipant[]>([]);
  const [events, setEvents] = useState<SessionEvent[]>([]);
  const [livekit, setLivekit] = useState<LiveKitConfig | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [connectionQuality, setConnectionQuality] = useState<ConnectionQuality>('good');
  const [localMediaState, setLocalMediaState] = useState<MediaState>({
    video_enabled: false,
    audio_enabled: false,
    screen_sharing: false,
    video_muted_by_user: false,
    audio_muted_by_user: false,
  });

  const localStreamRef = useRef<MediaStream | null>(null);

  const fetchSession = useCallback(async (): Promise<void> => {
    setLoading(true);
    setError(null);
    try {
      const query = sessionId ? `/api/telemedicine/session?sessionId=${encodeURIComponent(sessionId)}` : '/api/telemedicine/session';
      const res = await fetch(query, { credentials: 'include' });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'No se pudo obtener la sesión');
      }
      const json = await res.json();
      if (json?.data) {
        const payload = json.data;
        const rawSession = payload.session ?? payload;
        setSession(mapApiSession(rawSession));
        setParticipants(payload.participants ?? []);
        setEvents(payload.events ?? []);
        setLivekit(payload.livekit ?? null);
      } else {
        setSession(null);
        setParticipants([]);
        setEvents([]);
        setLivekit(null);
      }
    } catch (err) {
      logger.error('[useTelemedicine] fetchSession error', err);
      setError(err instanceof Error ? err.message : 'Error desconocido');
    } finally {
      setLoading(false);
    }
  }, [sessionId]);

  const startSession = useCallback(async (appointmentId: string, doctorId: string): Promise<StartSessionResponse | null> => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/telemedicine/session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ appointment_id: appointmentId, doctor_id: doctorId }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'No se pudo iniciar la sesión');
      }
      const json = await res.json();
      const apiSession = mapApiSession(json?.data?.session);
      setSession(apiSession);
      setParticipants(json?.data?.participants ?? []);
      setEvents(json?.data?.events ?? []);
      setLivekit(json?.data?.livekit ?? null);
      return json?.data as StartSessionResponse;
    } catch (err) {
      logger.error('[useTelemedicine] startSession error', err);
      setError(err instanceof Error ? err.message : 'Error al iniciar sesión');
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  const endSession = useCallback(async (): Promise<boolean> => {
    if (!session) return false;
    setLoading(true);
    setError(null);
    try {
      if (localStreamRef.current) {
        localStreamRef.current.getTracks().forEach(track => track.stop());
        localStreamRef.current = null;
      }
      const res = await fetch(`/api/telemedicine/session/${session.session_id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ status: 'completed', ended: true }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'Error al finalizar sesión');
      }
      const json = await res.json().catch(() => null);
      if (json?.data) {
        setSession(prev => (prev ? { ...prev, status: json.data.status, ended_at: json.data.ended_at } : prev));
      }
      return true;
    } catch (err) {
      logger.error('[useTelemedicine] endSession error', err);
      setError(err instanceof Error ? err.message : 'Error al finalizar sesión');
      return false;
    } finally {
      setLoading(false);
    }
  }, [session]);

  const toggleVideo = useCallback(async () => {
    if (!session) return false;
    const newState = !localMediaState.video_enabled;
    if (localStreamRef.current) {
      const track = localStreamRef.current.getVideoTracks()[0];
      if (track) track.enabled = newState;
    }
    setLocalMediaState(prev => ({ ...prev, video_enabled: newState, video_muted_by_user: !newState }));
    return true;
  }, [localMediaState, session]);

  const toggleAudio = useCallback(async () => {
    if (!session) return false;
    const newState = !localMediaState.audio_enabled;
    if (localStreamRef.current) {
      const track = localStreamRef.current.getAudioTracks()[0];
      if (track) track.enabled = newState;
    }
    setLocalMediaState(prev => ({ ...prev, audio_enabled: newState, audio_muted_by_user: !newState }));
    return true;
  }, [localMediaState, session]);

  const toggleScreenShare = useCallback(async () => {
    if (!session) return false;
    setLocalMediaState(prev => ({ ...prev, screen_sharing: !prev.screen_sharing }));
    return true;
  }, [session]);

  const updateConnectionQuality = useCallback((quality: ConnectionQuality) => {
    setConnectionQuality(quality);
  }, []);

  const refreshSession = useCallback(async () => {
    await fetchSession();
  }, [fetchSession]);

  const joinSession = useCallback(async (role = 'patient', sessionIdOverride?: string): Promise<boolean> => {
    const targetSession = sessionIdOverride ?? session?.session_id;
    if (!targetSession) return false;
    try {
      const res = await fetch(`/api/telemedicine/session/${targetSession}/participants`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'join_failed');
      }
      await fetchSession();
      return true;
    } catch (err) {
      logger.error('[useTelemedicine] joinSession error', err);
      setError(err instanceof Error ? err.message : 'Error al unir a la sesión');
      return false;
    }
  }, [session, fetchSession]);

  const leaveSession = useCallback(async (sessionIdOverride?: string): Promise<boolean> => {
    const targetSession = sessionIdOverride ?? session?.session_id;
    if (!targetSession) return false;
    try {
      const res = await fetch(`/api/telemedicine/session/${targetSession}/participants`, {
        method: 'PATCH',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ left: true }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'leave_failed');
      }
      await fetchSession();
      return true;
    } catch (err) {
      logger.error('[useTelemedicine] leaveSession error', err);
      setError(err instanceof Error ? err.message : 'Error al abandonar la sesión');
      return false;
    }
  }, [session, fetchSession]);

  const logEvent = useCallback(async (eventType: string, details?: string, sessionIdOverride?: string) => {
    const targetSession = sessionIdOverride ?? session?.session_id;
    if (!targetSession) return;
    try {
      const payload = { event_type: eventType, event_data: details ? { details } : undefined };
      const res = await fetch(`/api/telemedicine/session/${targetSession}/events`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error || 'event_failed');
      }
      await fetchSession();
    } catch (err) {
      logger.error('[useTelemedicine] logEvent error', err);
      setError(err instanceof Error ? err.message : 'Error al registrar evento');
    }
  }, [session, fetchSession]);

  useEffect(() => {
    fetchSession();
  }, [fetchSession]);

  return {
    session,
    participants,
    events,
    localMediaState,
    connectionQuality,
    loading,
    error,
    startSession,
    endSession,
    toggleVideo,
    toggleAudio,
    toggleScreenShare,
    updateConnectionQuality,
    refreshSession,
    joinSession,
    leaveSession,
    logEvent,
    livekit,
  };
}

'use client'

import { useEffect, useMemo, useRef, useState } from 'react'
import {
  TelemedicineClient,
  type TelemedicineRole,
  type OfferMessage,
  type AnswerMessage,
  type IceCandidateMessage,
} from '@autamedica/telemedicine'
import { getClientEnvOrDefault } from '@autamedica/shared'

export type SignalingConnectionState =
  | 'idle'
  | 'connecting'
  | 'connected'
  | 'reconnecting'
  | 'disconnected'

export interface UseTelemedicineSignalingConfig {
  roomId: string
  userId: string
  userType: TelemedicineRole
  metadata?: Record<string, unknown>
  token?: string
  signalingUrl?: string
  autoReconnect?: boolean
}

export interface TelemedicineSignalingState {
  connectionState: SignalingConnectionState
  participants: Array<{ id: string; userType: TelemedicineRole }>
  lastOffer: OfferMessage | null
  lastAnswer: AnswerMessage | null
  lastCandidate: IceCandidateMessage | null
  error: Error | null
}

export interface TelemedicineSignalingControls {
  connect: () => Promise<void>
  disconnect: () => void
  sendOffer: (description: RTCSessionDescriptionInit, targetId?: string) => void
  sendAnswer: (description: RTCSessionDescriptionInit, targetId?: string) => void
  sendIceCandidate: (candidate: RTCIceCandidateInit, targetId?: string) => void
  sendLeave: () => void
}

export function useTelemedicineSignaling(config: UseTelemedicineSignalingConfig) {
  const [state, setState] = useState<TelemedicineSignalingState>({
    connectionState: 'idle',
    participants: [],
    lastOffer: null,
    lastAnswer: null,
    lastCandidate: null,
    error: null,
  })

  const clientRef = useRef<TelemedicineClient | null>(null)

  const normalizedConfig = useMemo(
    () => ({
      url:
        config.signalingUrl ?? getClientEnvOrDefault('NEXT_PUBLIC_SIGNALING_URL', 'ws://localhost:3005/signal'),
      roomId: config.roomId,
      userId: config.userId,
      userType: config.userType,
      metadata: config.metadata,
      token: config.token,
      autoReconnect: config.autoReconnect ?? true,
    }),
    [config.autoReconnect, config.metadata, config.roomId, config.signalingUrl, config.token, config.userId, config.userType],
  )

  useEffect(() => {
    if (typeof window === 'undefined') {
      return undefined
    }

    const client = new TelemedicineClient(normalizedConfig)
    clientRef.current = client

    const unsubscribes = [
      client.on('open', () => {
        setState((prev) => ({ ...prev, connectionState: 'connected', error: null }))
      }),
      client.on('close', () => {
        setState((prev) => ({
          ...prev,
          connectionState: normalizedConfig.autoReconnect ? 'reconnecting' : 'disconnected',
        }))
      }),
      client.on('error', (error) => {
        setState((prev) => ({ ...prev, error }))
      }),
      client.on('user-joined', (message) => {
        setState((prev) => ({
          ...prev,
          participants: addOrUpdateParticipant(prev.participants, {
            id: message.from,
            userType: message.data?.userType ?? 'unknown',
          }),
        }))
      }),
      client.on('user-left', (message) => {
        setState((prev) => ({
          ...prev,
          participants: prev.participants.filter((participant) => participant.id !== message.from),
        }))
      }),
      client.on('offer', (message) => {
        setState((prev) => ({ ...prev, lastOffer: message }))
      }),
      client.on('answer', (message) => {
        setState((prev) => ({ ...prev, lastAnswer: message }))
      }),
      client.on('ice-candidate', (message) => {
        setState((prev) => ({ ...prev, lastCandidate: message }))
      }),
    ]

    return () => {
      unsubscribes.forEach((unsubscribe) => unsubscribe())
      client.disconnect()
      clientRef.current = null
    }
  }, [normalizedConfig])

  const connect = async () => {
    if (!clientRef.current) {
      throw new Error('Telemedicine client not initialized')
    }
    setState((prev) => ({ ...prev, connectionState: 'connecting', error: null }))
    await clientRef.current.connect()
  }

  const disconnect = () => {
    clientRef.current?.disconnect()
    setState((prev) => ({
      ...prev,
      connectionState: 'disconnected',
    }))
  }

  const sendOffer = (description: RTCSessionDescriptionInit, targetId?: string) => {
    clientRef.current?.sendOffer(description, targetId)
  }

  const sendAnswer = (description: RTCSessionDescriptionInit, targetId?: string) => {
    clientRef.current?.sendAnswer(description, targetId)
  }

  const sendIceCandidate = (candidate: RTCIceCandidateInit, targetId?: string) => {
    clientRef.current?.sendIceCandidate(candidate, targetId)
  }

  const sendLeave = () => {
    clientRef.current?.sendLeave()
  }

  return {
    state,
    controls: {
      connect,
      disconnect,
      sendOffer,
      sendAnswer,
      sendIceCandidate,
      sendLeave,
    },
  }
}

function addOrUpdateParticipant(
  list: Array<{ id: string; userType: TelemedicineRole }>,
  next: { id: string; userType: TelemedicineRole },
) {
  const existing = list.find((participant) => participant.id === next.id)
  if (existing) {
    return list.map((participant) => (participant.id === next.id ? next : participant))
  }
  return [...list, next]
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { logger } from '@autamedica/shared';

/**
 * Hook principal para gestión de WebRTC Peer Connection
 *
 * Features:
 * - RTCPeerConnection con ICE servers (STUN/TURN)
 * - Manejo de ICE candidates
 * - Offer/Answer SDP exchange
 * - Remote stream bidireccional
 * - Connection state monitoring
 * - Auto-reconnection
 */

export interface WebRTCConfig {
  /** ICE servers para NAT traversal */
  iceServers?: RTCIceServer[];
  /** Auto-restart on connection failure */
  autoReconnect?: boolean;
  /** Callback cuando se recibe remote stream */
  onRemoteStream?: (stream: MediaStream) => void;
  /** Callback cuando se genera ICE candidate */
  onIceCandidate?: (candidate: RTCIceCandidate) => void;
  /** Callback cuando cambia el estado de conexión */
  onConnectionStateChange?: (state: RTCPeerConnectionState) => void;
}

export interface WebRTCState {
  /** Peer connection instance */
  peerConnection: RTCPeerConnection | null;
  /** Remote stream del médico */
  remoteStream: MediaStream | null;
  /** Estado de la conexión */
  connectionState: RTCPeerConnectionState;
  /** Estado de ICE gathering */
  iceGatheringState: RTCIceGatheringState;
  /** Estado de ICE connection */
  iceConnectionState: RTCIceConnectionState;
  /** Signaling state */
  signalingState: RTCSignalingState;
  /** Estadísticas de conexión */
  stats: WebRTCStats | null;
  /** Error de conexión */
  error: string | null;
}

export interface WebRTCStats {
  /** Bitrate en kbps */
  bitrate: number;
  /** Latencia en ms */
  latency: number;
  /** Packet loss % */
  packetLoss: number;
  /** Round trip time en ms */
  rtt: number;
  /** Frames por segundo */
  fps: number;
  /** Resolución del video */
  resolution: { width: number; height: number };
}

export interface WebRTCActions {
  /** Inicializar peer connection */
  initializePeerConnection: () => void;
  /** Agregar local stream a peer connection */
  addLocalStream: (stream: MediaStream) => void;
  /** Crear oferta SDP */
  createOffer: () => Promise<RTCSessionDescriptionInit | null>;
  /** Crear respuesta SDP */
  createAnswer: () => Promise<RTCSessionDescriptionInit | null>;
  /** Establecer remote description */
  setRemoteDescription: (description: RTCSessionDescriptionInit) => Promise<void>;
  /** Agregar ICE candidate remoto */
  addIceCandidate: (candidate: RTCIceCandidateInit) => Promise<void>;
  /** Cerrar peer connection */
  closePeerConnection: () => void;
  /** Obtener estadísticas de conexión */
  getConnectionStats: () => Promise<WebRTCStats | null>;
}

const DEFAULT_ICE_SERVERS: RTCIceServer[] = [
  // Google STUN servers (públicos y gratuitos)
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun1.l.google.com:19302' },
  { urls: 'stun:stun2.l.google.com:19302' },

  // TODO: Agregar TURN servers privados para producción
  // {
  //   urls: 'turn:turn.autamedica.com:3478',
  //   username: 'autamedica',
  //   credential: process.env.NEXT_PUBLIC_TURN_SECRET
  // }
];

export function useWebRTC(config: WebRTCConfig = {}): [WebRTCState, WebRTCActions] {
  const {
    iceServers = DEFAULT_ICE_SERVERS,
    autoReconnect = true,
    onRemoteStream,
    onIceCandidate,
    onConnectionStateChange,
  } = config;

  // State
  const [state, setState] = useState<WebRTCState>({
    peerConnection: null,
    remoteStream: null,
    connectionState: 'new',
    iceGatheringState: 'new',
    iceConnectionState: 'new',
    signalingState: 'stable',
    stats: null,
    error: null,
  });

  // Refs para evitar stale closures
  const peerConnectionRef = useRef<RTCPeerConnection | null>(null);
  const remoteStreamRef = useRef<MediaStream | null>(null);
  const statsIntervalRef = useRef<NodeJS.Timeout | null>(null);

  /**
   * Inicializar RTCPeerConnection con configuración completa
   */
  const initializePeerConnection = useCallback(() => {
    // logger.info('[useWebRTC] Initializing peer connection...');

    try {
      // Crear peer connection con ICE servers
      const pc = new RTCPeerConnection({
        iceServers,
        iceCandidatePoolSize: 10, // Pre-gather candidates
        bundlePolicy: 'max-bundle', // Multiplex all media on single connection
        rtcpMuxPolicy: 'require', // Multiplex RTP and RTCP
      });

      // Event: ICE Candidate generado (enviar al peer remoto vía signaling)
      pc.onicecandidate = (event) => {
        if (event.candidate) {
          // logger.info('[useWebRTC] New ICE candidate:', event.candidate.candidate);
          onIceCandidate?.(event.candidate);
        } else {
          // logger.info('[useWebRTC] ICE gathering completed');
        }
      };

      // Event: Remote stream recibido
      pc.ontrack = (event) => {
        // logger.info('[useWebRTC] Remote track received:', event.track.kind);

        // Agregar track al remote stream
        let stream = remoteStreamRef.current;
        if (!stream) {
          stream = new MediaStream();
          remoteStreamRef.current = stream;
        }

        stream.addTrack(event.track);

        setState(prev => ({ ...prev, remoteStream: stream }));
        onRemoteStream?.(stream);
      };

      // Event: Connection state cambió
      pc.onconnectionstatechange = () => {
        // logger.info('[useWebRTC] Connection state:', pc.connectionState);
        setState(prev => ({ ...prev, connectionState: pc.connectionState }));
        onConnectionStateChange?.(pc.connectionState);

        // Auto-reconnect si falla
        if (autoReconnect && pc.connectionState === 'failed') {
          logger.warn('[useWebRTC] Connection failed, attempting reconnect...');
          // TODO: Implementar lógica de reconexión
        }
      };

      // Event: ICE connection state cambió
      pc.oniceconnectionstatechange = () => {
        // logger.info('[useWebRTC] ICE connection state:', pc.iceConnectionState);
        setState(prev => ({ ...prev, iceConnectionState: pc.iceConnectionState }));
      };

      // Event: ICE gathering state cambió
      pc.onicegatheringstatechange = () => {
        // logger.info('[useWebRTC] ICE gathering state:', pc.iceGatheringState);
        setState(prev => ({ ...prev, iceGatheringState: pc.iceGatheringState }));
      };

      // Event: Signaling state cambió
      pc.onsignalingstatechange = () => {
        // logger.info('[useWebRTC] Signaling state:', pc.signalingState);
        setState(prev => ({ ...prev, signalingState: pc.signalingState }));
      };

      // Event: Negotiation needed (renegotiar SDP)
      pc.onnegotiationneeded = async () => {
        // logger.info('[useWebRTC] Negotiation needed');
        // TODO: Trigger renegotiación vía signaling
      };

      peerConnectionRef.current = pc;
      setState(prev => ({ ...prev, peerConnection: pc, error: null }));

      // logger.info('[useWebRTC] Peer connection initialized successfully');
    } catch (error) {
      logger.error('[useWebRTC] Failed to initialize peer connection:', error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Failed to initialize peer connection'
      }));
    }
  }, [iceServers, autoReconnect, onRemoteStream, onIceCandidate, onConnectionStateChange]);

  /**
   * Agregar local stream (cámara/micrófono) a peer connection
   */
  const addLocalStream = useCallback((stream: MediaStream) => {
    const pc = peerConnectionRef.current;
    if (!pc) {
      logger.error('[useWebRTC] Cannot add local stream: peer connection not initialized');
      return;
    }

    // logger.info('[useWebRTC] Adding local stream tracks...');

    // Agregar cada track del stream
    stream.getTracks().forEach(track => {
      // logger.info(`[useWebRTC] Adding ${track.kind} track to peer connection`);
      pc.addTrack(track, stream);
    });
  }, []);

  /**
   * Crear oferta SDP (iniciador de la llamada)
   */
  const createOffer = useCallback(async (): Promise<RTCSessionDescriptionInit | null> => {
    const pc = peerConnectionRef.current;
    if (!pc) {
      logger.error('[useWebRTC] Cannot create offer: peer connection not initialized');
      return null;
    }

    try {
      // logger.info('[useWebRTC] Creating SDP offer...');

      const offer = await pc.createOffer({
        offerToReceiveAudio: true,
        offerToReceiveVideo: true,
      });

      // logger.info('[useWebRTC] Setting local description...');
      await pc.setLocalDescription(offer);

      // logger.info('[useWebRTC] Offer created successfully');
      return offer;
    } catch (error) {
      logger.error('[useWebRTC] Failed to create offer:', error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Failed to create offer'
      }));
      return null;
    }
  }, []);

  /**
   * Crear respuesta SDP (receptor de la llamada)
   */
  const createAnswer = useCallback(async (): Promise<RTCSessionDescriptionInit | null> => {
    const pc = peerConnectionRef.current;
    if (!pc) {
      logger.error('[useWebRTC] Cannot create answer: peer connection not initialized');
      return null;
    }

    try {
      // logger.info('[useWebRTC] Creating SDP answer...');

      const answer = await pc.createAnswer();

      // logger.info('[useWebRTC] Setting local description...');
      await pc.setLocalDescription(answer);

      // logger.info('[useWebRTC] Answer created successfully');
      return answer;
    } catch (error) {
      logger.error('[useWebRTC] Failed to create answer:', error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Failed to create answer'
      }));
      return null;
    }
  }, []);

  /**
   * Establecer remote description (SDP del peer remoto)
   */
  const setRemoteDescription = useCallback(async (description: RTCSessionDescriptionInit) => {
    const pc = peerConnectionRef.current;
    if (!pc) {
      logger.error('[useWebRTC] Cannot set remote description: peer connection not initialized');
      return;
    }

    try {
      // logger.info('[useWebRTC] Setting remote description:', description.type);
      await pc.setRemoteDescription(new RTCSessionDescription(description));
      // logger.info('[useWebRTC] Remote description set successfully');
    } catch (error) {
      logger.error('[useWebRTC] Failed to set remote description:', error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : 'Failed to set remote description'
      }));
    }
  }, []);

  /**
   * Agregar ICE candidate remoto
   */
  const addIceCandidate = useCallback(async (candidate: RTCIceCandidateInit) => {
    const pc = peerConnectionRef.current;
    if (!pc) {
      logger.error('[useWebRTC] Cannot add ICE candidate: peer connection not initialized');
      return;
    }

    try {
      // logger.info('[useWebRTC] Adding remote ICE candidate');
      await pc.addIceCandidate(new RTCIceCandidate(candidate));
      // logger.info('[useWebRTC] ICE candidate added successfully');
    } catch (error) {
      logger.error('[useWebRTC] Failed to add ICE candidate:', error);
      // No marcar como error crítico - algunos candidates pueden fallar
    }
  }, []);

  /**
   * Obtener estadísticas de conexión en tiempo real
   */
  const getConnectionStats = useCallback(async (): Promise<WebRTCStats | null> => {
    const pc = peerConnectionRef.current;
    if (!pc) return null;

    try {
      const stats = await pc.getStats(null);

      let bitrate = 0;
      let latency = 0;
      let packetLoss = 0;
      let rtt = 0;
      let fps = 0;
      let resolution = { width: 0, height: 0 };

      stats.forEach(report => {
        // Inbound RTP (video recibido)
        if (report.type === 'inbound-rtp' && report.kind === 'video') {
          bitrate = Math.round((report.bytesReceived * 8) / 1000); // kbps
          packetLoss = report.packetsLost
            ? (report.packetsLost / (report.packetsReceived + report.packetsLost)) * 100
            : 0;
          fps = report.framesPerSecond || 0;
        }

        // Candidate pair (latencia RTT)
        if (report.type === 'candidate-pair' && report.state === 'succeeded') {
          rtt = report.currentRoundTripTime ? report.currentRoundTripTime * 1000 : 0; // ms
          latency = rtt / 2; // Estimación de latencia one-way
        }

        // Track (resolución)
        if (report.type === 'track' && report.kind === 'video') {
          resolution = {
            width: report.frameWidth || 0,
            height: report.frameHeight || 0,
          };
        }
      });

      const connectionStats: WebRTCStats = {
        bitrate,
        latency: Math.round(latency),
        packetLoss: Math.round(packetLoss * 10) / 10,
        rtt: Math.round(rtt),
        fps: Math.round(fps),
        resolution,
      };

      setState(prev => ({ ...prev, stats: connectionStats }));
      return connectionStats;
    } catch (error) {
      logger.error('[useWebRTC] Failed to get connection stats:', error);
      return null;
    }
  }, []);

  /**
   * Cerrar peer connection y limpiar recursos
   */
  const closePeerConnection = useCallback(() => {
    // logger.info('[useWebRTC] Closing peer connection...');

    const pc = peerConnectionRef.current;
    if (pc) {
      pc.close();
      peerConnectionRef.current = null;
    }

    // Detener stats polling
    if (statsIntervalRef.current) {
      clearInterval(statsIntervalRef.current);
      statsIntervalRef.current = null;
    }

    // Limpiar remote stream
    if (remoteStreamRef.current) {
      remoteStreamRef.current.getTracks().forEach(track => track.stop());
      remoteStreamRef.current = null;
    }

    setState({
      peerConnection: null,
      remoteStream: null,
      connectionState: 'closed',
      iceGatheringState: 'new',
      iceConnectionState: 'closed',
      signalingState: 'closed',
      stats: null,
      error: null,
    });

    // logger.info('[useWebRTC] Peer connection closed');
  }, []);

  /**
   * Effect: Auto-polling de estadísticas cuando connected
   */
  useEffect(() => {
    if (state.connectionState === 'connected' && !statsIntervalRef.current) {
      // logger.info('[useWebRTC] Starting stats polling...');
      statsIntervalRef.current = setInterval(() => {
        getConnectionStats();
      }, 1000); // Cada 1 segundo
    } else if (state.connectionState !== 'connected' && statsIntervalRef.current) {
      // logger.info('[useWebRTC] Stopping stats polling...');
      clearInterval(statsIntervalRef.current);
      statsIntervalRef.current = null;
    }

    return () => {
      if (statsIntervalRef.current) {
        clearInterval(statsIntervalRef.current);
        statsIntervalRef.current = null;
      }
    };
  }, [state.connectionState, getConnectionStats]);

  /**
   * Effect: Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      closePeerConnection();
    };
  }, [closePeerConnection]);

  return [
    state,
    {
      initializePeerConnection,
      addLocalStream,
      createOffer,
      createAnswer,
      setRemoteDescription,
      addIceCandidate,
      closePeerConnection,
      getConnectionStats,
    },
  ];
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useWebRTC } from './useWebRTC';
import { SignalingService, SignalingEvent, getSignalingService } from '@/services/SignalingService';
import { logger } from '@autamedica/shared';

/**
 * Hook orquestador completo para videollamadas WebRTC
 *
 * Combina:
 * - useWebRTC (peer connection)
 * - SignalingService (coordinación)
 * - Local media (cámara/micrófono)
 *
 * Workflow completo:
 * 1. Obtener local stream (getUserMedia)
 * 2. Conectar a signaling server
 * 3. Unirse a sala
 * 4. Inicializar peer connection
 * 5. Negociar SDP (offer/answer)
 * 6. Intercambiar ICE candidates
 * 7. Stream bidireccional establecido
 */

export interface WebRTCCallConfig {
  /** ID de la sala de videoconsulta */
  roomId: string;
  /** ID del usuario actual */
  userId: string;
  /** URL del signaling server */
  signalingServerUrl?: string;
  /** Token de autenticación */
  authToken?: string;
  /** Constraints de media */
  mediaConstraints?: MediaStreamConstraints;
}

export interface WebRTCCallState {
  /** Stream local (cámara/micrófono) */
  localStream: MediaStream | null;
  /** Stream remoto (del médico) */
  remoteStream: MediaStream | null;
  /** Estado de la llamada */
  callStatus: 'idle' | 'connecting' | 'connected' | 'failed' | 'ended';
  /** Video local habilitado */
  isVideoEnabled: boolean;
  /** Audio local habilitado */
  isAudioEnabled: boolean;
  /** Compartir pantalla activo */
  isScreenSharing: boolean;
  /** Error */
  error: string | null;
  /** Estadísticas de conexión */
  connectionStats: {
    bitrate: number;
    latency: number;
    packetLoss: number;
  } | null;
}

export interface WebRTCCallActions {
  /** Iniciar llamada */
  startCall: () => Promise<void>;
  /** Finalizar llamada */
  endCall: () => void;
  /** Toggle video */
  toggleVideo: () => void;
  /** Toggle audio */
  toggleAudio: () => void;
  /** Toggle screen share */
  toggleScreenShare: () => Promise<void>;
}

const DEFAULT_SIGNALING_URL = process.env.NEXT_PUBLIC_SIGNALING_SERVER_URL || 'ws://localhost:8888';

const DEFAULT_MEDIA_CONSTRAINTS: MediaStreamConstraints = {
  video: {
    width: { ideal: 1280 },
    height: { ideal: 720 },
    frameRate: { ideal: 30 },
    facingMode: 'user',
  },
  audio: {
    echoCancellation: true,
    noiseSuppression: true,
    autoGainControl: true,
  },
};

export function useWebRTCCall(config: WebRTCCallConfig): [WebRTCCallState, WebRTCCallActions] {
  const {
    roomId,
    userId,
    signalingServerUrl = DEFAULT_SIGNALING_URL,
    authToken,
    mediaConstraints = DEFAULT_MEDIA_CONSTRAINTS,
  } = config;

  // State
  const [localStream, setLocalStream] = useState<MediaStream | null>(null);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const [callStatus, setCallStatus] = useState<WebRTCCallState['callStatus']>('idle');
  const [isVideoEnabled, setIsVideoEnabled] = useState(true);
  const [isAudioEnabled, setIsAudioEnabled] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // WebRTC hook
  const [webrtcState, webrtcActions] = useWebRTC({
    onRemoteStream: (stream) => {
      // logger.info('[useWebRTCCall] Remote stream received');
    },
    onIceCandidate: (candidate) => {
      // Enviar ICE candidate al peer remoto vía signaling
      if (signalingRef.current) {
        signalingRef.current.sendIceCandidate(roomId, candidate);
      }
    },
    onConnectionStateChange: (state) => {
      // logger.info('[useWebRTCCall] Connection state:', state);

      if (state === 'connected') {
        setCallStatus('connected');
      } else if (state === 'failed' || state === 'disconnected') {
        setCallStatus('failed');
        setError('Conexión perdida. Intenta reconectar.');
      }
    },
  });

  // Refs
  const signalingRef = useRef<SignalingService | null>(null);
  const isInitiatorRef = useRef(false); // ¿Soy el que inicia la llamada?

  /**
   * Obtener local media stream (cámara/micrófono)
   */
  const getLocalStream = useCallback(async (): Promise<MediaStream | null> => {
    try {
      // logger.info('[useWebRTCCall] Requesting local media...');
      const stream = await navigator.mediaDevices.getUserMedia(mediaConstraints);
      // logger.info('[useWebRTCCall] Local stream obtained');
      setLocalStream(stream);
      return stream;
    } catch (err) {
      logger.error('[useWebRTCCall] Failed to get local media:', err);
      setError('No se pudo acceder a la cámara o micrófono');
      return null;
    }
  }, [mediaConstraints]);

  /**
   * Configurar event listeners del signaling service
   */
  const setupSignalingListeners = useCallback((signaling: SignalingService) => {
    // Oferta recibida (soy el receptor)
    signaling.on(SignalingEvent.OFFER_RECEIVED, async ({ offer }) => {
      // logger.info('[useWebRTCCall] Offer received, creating answer...');
      isInitiatorRef.current = false;

      // Establecer remote description (la oferta)
      await webrtcActions.setRemoteDescription(offer);

      // Crear y enviar respuesta
      const answer = await webrtcActions.createAnswer();
      if (answer && signalingRef.current) {
        signalingRef.current.sendAnswer(roomId, answer);
      }
    });

    // Respuesta recibida (soy el iniciador)
    signaling.on(SignalingEvent.ANSWER_RECEIVED, async ({ answer }) => {
      // logger.info('[useWebRTCCall] Answer received');
      await webrtcActions.setRemoteDescription(answer);
    });

    // ICE candidate recibido
    signaling.on(SignalingEvent.ICE_CANDIDATE_RECEIVED, async ({ candidate }) => {
      // logger.info('[useWebRTCCall] ICE candidate received');
      await webrtcActions.addIceCandidate(candidate);
    });

    // Usuario se unió a la sala
    signaling.on(SignalingEvent.USER_JOINED, async ({ userId: remoteUserId }) => {
      // logger.info('[useWebRTCCall] User joined:', remoteUserId);

      // Si soy el primer usuario en la sala, espero
      // Si llega otro usuario, inicio la negociación
      isInitiatorRef.current = true;

      // Crear y enviar oferta
      const offer = await webrtcActions.createOffer();
      if (offer && signalingRef.current) {
        signalingRef.current.sendOffer(roomId, offer);
      }
    });

    // Usuario salió de la sala
    signaling.on(SignalingEvent.USER_LEFT, () => {
      // logger.info('[useWebRTCCall] User left');
      setCallStatus('ended');
    });

    // Error de signaling
    signaling.on(SignalingEvent.ERROR, (err) => {
      logger.error('[useWebRTCCall] Signaling error:', err);
      setError('Error de conexión al servidor');
      setCallStatus('failed');
    });
  }, [roomId, webrtcActions]);

  /**
   * Iniciar llamada
   */
  const startCall = useCallback(async () => {
    try {
      // logger.info('[useWebRTCCall] Starting call...');
      setCallStatus('connecting');
      setError(null);

      // 1. Obtener local stream
      const stream = await getLocalStream();
      if (!stream) {
        setCallStatus('failed');
        return;
      }

      // 2. Conectar a signaling server
      // logger.info('[useWebRTCCall] Connecting to signaling server...');
      const signaling = getSignalingService({
        serverUrl: signalingServerUrl,
        userId,
        authToken,
      });

      signalingRef.current = signaling;

      // Configurar listeners
      setupSignalingListeners(signaling);

      // Conectar
      await signaling.connect();

      // 3. Unirse a sala
      // logger.info('[useWebRTCCall] Joining room:', roomId);
      signaling.joinRoom(roomId);

      // 4. Inicializar peer connection
      // logger.info('[useWebRTCCall] Initializing peer connection...');
      webrtcActions.initializePeerConnection();

      // 5. Agregar local stream a peer connection
      webrtcActions.addLocalStream(stream);

      // logger.info('[useWebRTCCall] Call started successfully');
    } catch (err) {
      logger.error('[useWebRTCCall] Failed to start call:', err);
      setError('No se pudo iniciar la llamada');
      setCallStatus('failed');
    }
  }, [
    roomId,
    userId,
    signalingServerUrl,
    authToken,
    getLocalStream,
    setupSignalingListeners,
    webrtcActions,
  ]);

  /**
   * Finalizar llamada
   */
  const endCall = useCallback(() => {
    // logger.info('[useWebRTCCall] Ending call...');

    // Detener local stream
    if (localStream) {
      localStream.getTracks().forEach(track => track.stop());
      setLocalStream(null);
    }

    // Detener screen share si está activo
    if (screenStream) {
      screenStream.getTracks().forEach(track => track.stop());
      setScreenStream(null);
      setIsScreenSharing(false);
    }

    // Salir de la sala
    if (signalingRef.current) {
      signalingRef.current.leaveRoom();
      signalingRef.current.disconnect();
      signalingRef.current = null;
    }

    // Cerrar peer connection
    webrtcActions.closePeerConnection();

    setCallStatus('ended');
  }, [localStream, screenStream, webrtcActions]);

  /**
   * Toggle video local
   */
  const toggleVideo = useCallback(() => {
    if (localStream) {
      const videoTrack = localStream.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setIsVideoEnabled(videoTrack.enabled);
      }
    }
  }, [localStream]);

  /**
   * Toggle audio local
   */
  const toggleAudio = useCallback(() => {
    if (localStream) {
      const audioTrack = localStream.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setIsAudioEnabled(audioTrack.enabled);
      }
    }
  }, [localStream]);

  /**
   * Toggle screen share
   */
  const toggleScreenShare = useCallback(async () => {
    if (isScreenSharing) {
      // Detener screen share
      if (screenStream) {
        screenStream.getTracks().forEach(track => track.stop());
        setScreenStream(null);
      }
      setIsScreenSharing(false);
    } else {
      // Iniciar screen share
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({
          video: {
            cursor: 'always',
          },
          audio: false,
        });

        setScreenStream(stream);
        setIsScreenSharing(true);

        // Detener automáticamente cuando el usuario cancela desde el navegador
        stream.getVideoTracks()[0].onended = () => {
          setScreenStream(null);
          setIsScreenSharing(false);
        };
      } catch (err) {
        logger.error('[useWebRTCCall] Failed to start screen share:', err);
        setError('No se pudo compartir la pantalla');
      }
    }
  }, [isScreenSharing, screenStream]);

  /**
   * Effect: Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      endCall();
    };
  }, [endCall]);

  /**
   * Effect: Actualizar estadísticas periódicamente
   */
  useEffect(() => {
    if (callStatus !== 'connected') return;

    const interval = setInterval(async () => {
      const stats = await webrtcActions.getConnectionStats();
      // Stats se actualizan automáticamente en webrtcState
    }, 2000);

    return () => clearInterval(interval);
  }, [callStatus, webrtcActions]);

  return [
    {
      localStream,
      remoteStream: webrtcState.remoteStream,
      callStatus,
      isVideoEnabled,
      isAudioEnabled,
      isScreenSharing,
      error: error || webrtcState.error,
      connectionStats: webrtcState.stats,
    },
    {
      startCall,
      endCall,
      toggleVideo,
      toggleAudio,
      toggleScreenShare,
    },
  ];
}

/**
 * Hook completo para videollamadas WebRTC con Signaling
 *
 * Integra:
 * - RTCPeerConnection para comunicación peer-to-peer
 * - Supabase Realtime para signaling
 * - Manejo de local/remote streams
 * - Auto-negociación de conexión
 */

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useSupabase } from '@autamedica/auth/react';
import { SupabaseSignalingService } from '@/services/SupabaseSignalingService';
import { logger } from '@autamedica/shared';

const ICE_SERVERS: RTCIceServer[] = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun1.l.google.com:19302' },
];

interface UseWebRTCVideoCallOptions {
  roomId: string;
  userId: string;
  autoStart?: boolean;
}

interface WebRTCVideoCallState {
  localStream: MediaStream | null;
  remoteStream: MediaStream | null;
  isConnected: boolean;
  isConnecting: boolean;
  isCameraOn: boolean;
  isMicOn: boolean;
  connectionState: RTCPeerConnectionState;
  error: string | null;
  remotePeerId: string | null;
}

interface WebRTCVideoCallActions {
  startCall: () => Promise<void>;
  endCall: () => void;
  toggleCamera: () => void;
  toggleMic: () => void;
  switchCamera: () => Promise<void>;
}

export function useWebRTCVideoCall(
  options: UseWebRTCVideoCallOptions
): [WebRTCVideoCallState, WebRTCVideoCallActions] {
  const { roomId, userId, autoStart = false } = options;

  const supabase = useSupabase();
  const peerConnectionRef = useRef<RTCPeerConnection | null>(null);
  const signalingServiceRef = useRef<SupabaseSignalingService | null>(null);
  const localStreamRef = useRef<MediaStream | null>(null);
  const pendingCandidatesRef = useRef<RTCIceCandidateInit[]>([]);

  const [state, setState] = useState<WebRTCVideoCallState>({
    localStream: null,
    remoteStream: null,
    isConnected: false,
    isConnecting: false,
    isCameraOn: true,
    isMicOn: true,
    connectionState: 'new',
    error: null,
    remotePeerId: null,
  });

  /**
   * Inicializar local media (cámara y micrófono)
   */
  const initializeLocalStream = useCallback(async (): Promise<MediaStream> => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 },
          facingMode: 'user',
        },
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });

      localStreamRef.current = stream;
      setState(prev => ({ ...prev, localStream: stream }));

      logger.info('[WebRTC] Local stream initialized');
      return stream;
    } catch (error) {
      logger.error('[WebRTC] Error accessing media devices:', error);
      setState(prev => ({
        ...prev,
        error: 'No se pudo acceder a la cámara o micrófono',
      }));
      throw error;
    }
  }, []);

  /**
   * Crear RTCPeerConnection
   */
  const createPeerConnection = useCallback((): RTCPeerConnection => {
    const pc = new RTCPeerConnection({ iceServers: ICE_SERVERS });

    // Manejar remote stream
    pc.ontrack = (event) => {
      logger.info('[WebRTC] Received remote track');
      const [remoteStream] = event.streams;
      setState(prev => ({ ...prev, remoteStream }));
    };

    // Manejar cambios en estado de conexión
    pc.onconnectionstatechange = () => {
      logger.info('[WebRTC] Connection state:', pc.connectionState);
      setState(prev => ({
        ...prev,
        connectionState: pc.connectionState,
        isConnected: pc.connectionState === 'connected',
        isConnecting: pc.connectionState === 'connecting',
      }));

      if (pc.connectionState === 'failed' || pc.connectionState === 'disconnected') {
        setState(prev => ({
          ...prev,
          error: 'Conexión perdida. Intentando reconectar...',
        }));
      }
    };

    // Manejar ICE candidates
    pc.onicecandidate = (event) => {
      if (event.candidate && signalingServiceRef.current) {
        logger.info('[WebRTC] Sending ICE candidate');
        signalingServiceRef.current.sendIceCandidate(
          event.candidate.toJSON(),
          state.remotePeerId || undefined
        );
      }
    };

    return pc;
  }, [state.remotePeerId]);

  /**
   * Iniciar llamada (crear oferta)
   */
  const startCall = useCallback(async () => {
    if (!supabase) {
      setState(prev => ({ ...prev, error: 'Supabase no disponible' }));
      return;
    }

    try {
      setState(prev => ({ ...prev, isConnecting: true, error: null }));

      // 1. Obtener local stream
      const localStream = await initializeLocalStream();

      // 2. Crear peer connection
      const pc = createPeerConnection();
      peerConnectionRef.current = pc;

      // 3. Agregar local tracks al peer connection
      localStream.getTracks().forEach(track => {
        pc.addTrack(track, localStream);
      });

      // 4. Inicializar servicio de signaling
      const signaling = new SupabaseSignalingService(supabase, userId, {
        onOffer: async (offer, from) => {
          logger.info('[WebRTC] Received offer from:', from);
          await pc.setRemoteDescription(offer);

          // Crear answer
          const answer = await pc.createAnswer();
          await pc.setLocalDescription(answer);
          await signaling.sendAnswer(answer, from);

          // Procesar pending candidates
          for (const candidate of pendingCandidatesRef.current) {
            await pc.addIceCandidate(candidate);
          }
          pendingCandidatesRef.current = [];

          setState(prev => ({ ...prev, remotePeerId: from }));
        },

        onAnswer: async (answer, from) => {
          logger.info('[WebRTC] Received answer from:', from);
          await pc.setRemoteDescription(answer);

          // Procesar pending candidates
          for (const candidate of pendingCandidatesRef.current) {
            await pc.addIceCandidate(candidate);
          }
          pendingCandidatesRef.current = [];
        },

        onIceCandidate: async (candidate, from) => {
          logger.info('[WebRTC] Received ICE candidate from:', from);
          try {
            if (pc.remoteDescription) {
              await pc.addIceCandidate(candidate);
            } else {
              // Guardar para procesar después
              pendingCandidatesRef.current.push(candidate);
            }
          } catch (error) {
            logger.error('[WebRTC] Error adding ICE candidate:', error);
          }
        },

        onPeerJoined: async (peerId) => {
          logger.info('[WebRTC] Peer joined:', peerId);
          setState(prev => ({ ...prev, remotePeerId: peerId }));

          // Si somos el primero, crear oferta
          const offer = await pc.createOffer();
          await pc.setLocalDescription(offer);
          await signaling.sendOffer(offer, peerId);
        },

        onPeerLeft: (peerId) => {
          logger.info('[WebRTC] Peer left:', peerId);
          setState(prev => ({
            ...prev,
            remotePeerId: null,
            remoteStream: null,
            error: 'El otro participante salió de la llamada',
          }));
        },

        onError: (error) => {
          logger.error('[WebRTC] Signaling error:', error);
          setState(prev => ({ ...prev, error: error.message }));
        },
      });

      signalingServiceRef.current = signaling;

      // 5. Unirse a la sala
      await signaling.joinRoom(roomId);

      logger.info('[WebRTC] Call started in room:', roomId);
    } catch (error) {
      logger.error('[WebRTC] Error starting call:', error);
      setState(prev => ({
        ...prev,
        error: 'Error al iniciar la llamada',
        isConnecting: false,
      }));
    }
  }, [supabase, userId, roomId, initializeLocalStream, createPeerConnection]);

  /**
   * Finalizar llamada
   */
  const endCall = useCallback(() => {
    // Cerrar peer connection
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close();
      peerConnectionRef.current = null;
    }

    // Detener local stream
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach(track => track.stop());
      localStreamRef.current = null;
    }

    // Desconectar signaling
    if (signalingServiceRef.current) {
      signalingServiceRef.current.disconnect();
      signalingServiceRef.current = null;
    }

    setState({
      localStream: null,
      remoteStream: null,
      isConnected: false,
      isConnecting: false,
      isCameraOn: true,
      isMicOn: true,
      connectionState: 'closed',
      error: null,
      remotePeerId: null,
    });

    logger.info('[WebRTC] Call ended');
  }, []);

  /**
   * Toggle cámara
   */
  const toggleCamera = useCallback(() => {
    if (localStreamRef.current) {
      const videoTrack = localStreamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setState(prev => ({ ...prev, isCameraOn: videoTrack.enabled }));
      }
    }
  }, []);

  /**
   * Toggle micrófono
   */
  const toggleMic = useCallback(() => {
    if (localStreamRef.current) {
      const audioTrack = localStreamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setState(prev => ({ ...prev, isMicOn: audioTrack.enabled }));
      }
    }
  }, []);

  /**
   * Cambiar cámara (frontal/trasera en móviles)
   */
  const switchCamera = useCallback(async () => {
    if (!localStreamRef.current) return;

    try {
      const videoTrack = localStreamRef.current.getVideoTracks()[0];
      const currentFacingMode = videoTrack.getSettings().facingMode;

      const newStream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: currentFacingMode === 'user' ? 'environment' : 'user',
        },
        audio: true,
      });

      const newVideoTrack = newStream.getVideoTracks()[0];

      // Reemplazar track en peer connection
      if (peerConnectionRef.current) {
        const sender = peerConnectionRef.current
          .getSenders()
          .find(s => s.track?.kind === 'video');

        if (sender) {
          await sender.replaceTrack(newVideoTrack);
        }
      }

      // Detener track anterior
      videoTrack.stop();

      // Actualizar local stream
      localStreamRef.current.removeTrack(videoTrack);
      localStreamRef.current.addTrack(newVideoTrack);

      setState(prev => ({ ...prev, localStream: localStreamRef.current }));
    } catch (error) {
      logger.error('[WebRTC] Error switching camera:', error);
    }
  }, []);

  // Auto-start si está habilitado
  useEffect(() => {
    if (autoStart) {
      startCall();
    }

    // Cleanup al desmontar
    return () => {
      endCall();
    };
  }, []);

  return [
    state,
    {
      startCall,
      endCall,
      toggleCamera,
      toggleMic,
      switchCamera,
    },
  ];
}

import { createClient, type SupabaseClient } from '@supabase/supabase-js'
import { ensureClientEnv, ensureServerEnv } from '@autamedica/shared'

export type PatientContextSummary = {
  name: string | null
  email: string | null
  role: string | null
  portal: string | null
  gender: string | null
  bloodType: string | null
  heightCm: number | null
  weightKg: number | null
  birthDate: string | null
}

export async function getAdminClient(): Promise<SupabaseClient> {
  const url = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL')
  const serviceKey = ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY')
  return createClient(url, serviceKey)
}

export async function buildPatientContext(userId: string, admin?: SupabaseClient) {
  const client = admin ?? (await getAdminClient())
  const [{ data: profile }, { data: patient }] = await Promise.all([
    client.from('profiles').select('*').eq('id', userId).maybeSingle(),
    client.from('patients').select('*').eq('user_id', userId).maybeSingle(),
  ])

  const summary: PatientContextSummary = {
    name: ((profile?.full_name as any) ?? [profile?.first_name, profile?.last_name].filter(Boolean).join(' ').trim()) || null,
    email: (profile?.email as any) ?? null,
    role: (profile?.role as any) ?? 'patient',
    portal: (profile?.portal as any) ?? 'patients',
    gender: (patient?.gender as any) ?? null,
    bloodType: (patient?.blood_type as any) ?? null,
    heightCm: (patient?.height_cm as any) ?? null,
    weightKg: (patient?.weight_kg as any) ?? null,
    birthDate: (patient?.birth_date as any) ?? null,
  }

  return { profile, patient, summary }
}

export async function persistPatientContextFiles(userId: string, data: { profile: any; patient: any; summary: PatientContextSummary }, admin?: SupabaseClient) {
  const client = admin ?? (await getAdminClient())
  const BUCKET = 'patient-files'

  const profileJson = Buffer.from(JSON.stringify(data.profile ?? {}, null, 2), 'utf8')
  const patientJson = Buffer.from(JSON.stringify(data.patient ?? {}, null, 2), 'utf8')
  const contextJson = Buffer.from(JSON.stringify(data.summary, null, 2), 'utf8')
  const summaryMd = Buffer.from(
    `# Resumen del Paciente\n\n` +
      `- Nombre: ${data.summary.name ?? '—'}\n` +
      `- Email: ${data.summary.email ?? '—'}\n` +
      `- Rol: ${data.summary.role ?? '—'}\n` +
      `- Género: ${data.summary.gender ?? '—'}\n` +
      `- Grupo sanguíneo: ${data.summary.bloodType ?? '—'}\n` +
      `- Altura (cm): ${data.summary.heightCm ?? '—'}\n` +
      `- Peso (kg): ${data.summary.weightKg ?? '—'}\n` +
      `- Fecha de nacimiento: ${data.summary.birthDate ?? '—'}\n`,
    'utf8',
  )

  const uploads: Array<Promise<any>> = []
  uploads.push(
    client.storage.from(BUCKET).upload(`${userId}/profile.json`, profileJson, { contentType: 'application/json', upsert: true }),
  )
  uploads.push(
    client.storage.from(BUCKET).upload(`${userId}/patient.json`, patientJson, { contentType: 'application/json', upsert: true }),
  )
  uploads.push(
    client.storage.from(BUCKET).upload(`${userId}/context.json`, contextJson, { contentType: 'application/json', upsert: true }),
  )
  uploads.push(
    client.storage.from(BUCKET).upload(`${userId}/summary.md`, summaryMd, { contentType: 'text/markdown; charset=utf-8', upsert: true }),
  )

  await Promise.allSettled(uploads)

  return {
    bucket: BUCKET,
    paths: {
      profile: `${userId}/profile.json`,
      patient: `${userId}/patient.json`,
      context: `${userId}/context.json`,
      summary: `${userId}/summary.md`,
    },
  }
}

/**
 * Servicio principal de IA con ONNX Runtime
 * Orquesta tokenización, clasificación de intenciones y generación de respuestas
 */

import * as ort from 'onnxruntime-web';
import { medicalTokenizer } from './tokenizer';
import { intentClassifier, type MedicalIntent, type IntentClassification } from './intent-classifier';
import { medicalQA, type PatientContext, type MedicalResponse } from './medical-qa';
import { logger, getClientEnvOrDefault, getOptionalClientEnv } from '@autamedica/shared';
import { loadVocab, wordPieceTokenize, type Vocab } from './wordpiece-tokenizer';

/**
 * Configuración del servicio ONNX
 */
export interface ONNXServiceConfig {
  modelPath?: string;
  useWebGL?: boolean;
  useWasm?: boolean;
  numThreads?: number;
}

/**
 * Estado de carga del modelo
 */
export type ModelLoadingState = 'idle' | 'loading' | 'ready' | 'error';

/**
 * Servicio principal de IA médica
 */
export class ONNXService {
  private session: ort.InferenceSession | null = null;
  private loadingState: ModelLoadingState = 'idle';
  private config: ONNXServiceConfig;
  private vocab: Vocab | null = null;
  private labels: string[] | null = null;
  private maxLen = 128;

  constructor(config: ONNXServiceConfig = {}) {
    this.config = {
      useWebGL: true,
      useWasm: true,
      numThreads: 4,
      ...config
    };

    this.configureONNXRuntime();
  }

  /**
   * Configura ONNX Runtime Web
   */
  private configureONNXRuntime(): void {
    // Configurar execution providers (WebGL > WASM > CPU)
    const executionProviders: ort.InferenceSession.ExecutionProviderConfig[] = [];

    if (this.config.useWebGL) {
      executionProviders.push('webgl');
    }

    if (this.config.useWasm) {
      executionProviders.push('wasm');
    }

    // Fallback a CPU si nada más está disponible
    executionProviders.push('cpu');

    // Configurar número de threads para WASM
    if (this.config.numThreads) {
      ort.env.wasm.numThreads = this.config.numThreads;
    }

    // Modo de desarrollo/producción
    if (process.env.NODE_ENV === 'development') {
      ort.env.logLevel = 'verbose';
    } else {
      ort.env.logLevel = 'warning';
    }
  }

  /**
   * Carga un modelo ONNX (preparado para futuro uso)
   */
  public async loadModel(modelPath: string): Promise<void> {
    if (this.loadingState === 'loading') {
      throw new Error('Model is already being loaded');
    }

    if (this.loadingState === 'ready') {
      // logger.info('Model already loaded');
      return;
    }

    try {
      this.loadingState = 'loading';

      // Cargar modelo desde la ruta especificada
      this.session = await ort.InferenceSession.create(modelPath, {
        executionProviders: this.config.useWebGL
          ? ['webgl', 'wasm', 'cpu']
          : ['wasm', 'cpu'],
        graphOptimizationLevel: 'all',
        enableCpuMemArena: true,
        enableMemPattern: true,
        executionMode: 'parallel'
      });

      this.loadingState = 'ready';
      // Intentar cargar labels y vocab desde el mismo directorio del modelo
      try {
        const base = modelPath.includes('/') ? modelPath.substring(0, modelPath.lastIndexOf('/')) : '.';
        // labels.json
        const labelsRes = await fetch(`${base}/labels.json`, { cache: 'force-cache' });
        if (labelsRes.ok) {
          this.labels = await labelsRes.json();
        }
        // vocab.txt (WordPiece)
        try {
          this.vocab = await loadVocab(`${base}/vocab.txt`);
        } catch {
          this.vocab = null; // si no existe, fallback a reglas
        }
      } catch (e) {
        logger.warn('No se pudieron cargar labels/vocab para ONNX', (e as any)?.message || e);
      }
      // logger.info('✅ ONNX model loaded successfully');
    } catch (error) {
      this.loadingState = 'error';
      logger.error('❌ Failed to load ONNX model:', error);
      throw error;
    }
  }

  /**
   * Ejecuta inferencia con el modelo ONNX (para uso futuro)
   */
  private async runInference(inputTensor: ort.Tensor): Promise<ort.Tensor> {
    if (!this.session) {
      throw new Error('Model not loaded. Call loadModel() first.');
    }

    try {
      const feeds: Record<string, ort.Tensor> = {
        input: inputTensor
      };

      const results = await this.session.run(feeds);
      return results[Object.keys(results)[0]];
    } catch (error) {
      logger.error('Error running inference:', error);
      throw error;
    }
  }

  /**
   * Procesa una query del paciente y genera respuesta
   * (Actualmente usa clasificación basada en reglas, preparado para ONNX)
   */
  public async processQuery(
    query: string,
    patientContext: PatientContext
  ): Promise<{
    classification: IntentClassification;
    response: MedicalResponse;
    processingTime: number;
  }> {
    const startTime = performance.now();

    // 1. Clasificar intención
    const classification = await this.classifyIntent(query);

    // 2. Generar respuesta contextual
    const response = medicalQA.generateResponse(classification, patientContext);

    const processingTime = performance.now() - startTime;

    return {
      classification,
      response,
      processingTime
    };
  }

  /**
   * Clasifica la intención del usuario
   * (Híbrido: reglas ahora, ONNX en el futuro)
   */
  private async classifyIntent(query: string): Promise<IntentClassification> {
    // Si modelo + vocab + labels están listos, usar ONNX
    if (this.loadingState === 'ready' && this.session && this.vocab && this.labels?.length) {
      try {
        const { inputIds, attentionMask, tokenTypeIds } = wordPieceTokenize(query, this.vocab, this.maxLen);
        const feeds: Record<string, ort.Tensor> = {};
        // Nombres comunes de entradas; probamos variantes
        feeds['input_ids'] = new ort.Tensor('int64', BigInt64Array.from(inputIds.map(n => BigInt(n))), [1, this.maxLen]);
        feeds['attention_mask'] = new ort.Tensor('int64', BigInt64Array.from(attentionMask.map(n => BigInt(n))), [1, this.maxLen]);
        // Algunos modelos no usan token_type_ids
        try { feeds['token_type_ids'] = new ort.Tensor('int64', BigInt64Array.from(tokenTypeIds.map(n => BigInt(n))), [1, this.maxLen]); } catch {}

        const results = await this.session.run(feeds);
        // Tomar el primer output como logits
        const firstKey = Object.keys(results)[0];
        const logits = results[firstKey].data as Float32Array | number[];
        const arr = Array.from(logits as any);
        // Softmax
        const max = Math.max(...arr);
        const exps = arr.map(v => Math.exp(v - max));
        const sum = exps.reduce((a, b) => a + b, 0);
        const probs = exps.map(v => v / sum);
        // Top label
        let topIdx = 0;
        let topProb = probs[0] ?? 0;
        for (let i = 1; i < probs.length; i++) {
          if (probs[i] > topProb) { topProb = probs[i]; topIdx = i; }
        }
        const label = (this.labels[topIdx] || 'unknown') as MedicalIntent;
        const keywords = medicalTokenizer.extractMedicalKeywords(query);
        return { intent: label, confidence: topProb, keywords };
      } catch (e) {
        logger.warn('Fallo clasificación ONNX. Usando reglas.', (e as any)?.message || e);
      }
    }
    // Fallback a reglas
    return intentClassifier.classify(query);
  }

  /**
   * Extrae embeddings de un texto (preparado para uso futuro)
   */
  public async extractEmbeddings(text: string): Promise<Float32Array | null> {
    if (this.loadingState !== 'ready' || !this.session) {
      logger.warn('Model not ready, cannot extract embeddings');
      return null;
    }

    try {
      const features = medicalTokenizer.extractFeatures(text);
      const inputTensor = new ort.Tensor(
        'int64',
        BigInt64Array.from(features.tokens.map(t => BigInt(t))),
        [1, features.tokens.length]
      );

      const output = await this.runInference(inputTensor);

      if (output.type === 'float32') {
        return output.data as Float32Array;
      }

      return null;
    } catch (error) {
      logger.error('Error extracting embeddings:', error);
      return null;
    }
  }

  /**
   * Calcula similitud entre dos textos usando embeddings
   */
  public async calculateSimilarity(text1: string, text2: string): Promise<number> {
    const emb1 = await this.extractEmbeddings(text1);
    const emb2 = await this.extractEmbeddings(text2);

    if (!emb1 || !emb2) {
      // Fallback a similitud basada en keywords
      const keywords1 = medicalTokenizer.extractMedicalKeywords(text1);
      const keywords2 = medicalTokenizer.extractMedicalKeywords(text2);

      const intersection = keywords1.filter(k => keywords2.includes(k));
      const union = [...new Set([...keywords1, ...keywords2])];

      return union.length > 0 ? intersection.length / union.length : 0;
    }

    // Cosine similarity
    return this.cosineSimilarity(emb1, emb2);
  }

  /**
   * Calcula similitud coseno entre dos vectores
   */
  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    if (a.length !== b.length) {
      throw new Error('Vectors must have same length');
    }

    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    return denominator === 0 ? 0 : dotProduct / denominator;
  }

  /**
   * Obtiene estado del servicio
   */
  public getStatus(): {
    state: ModelLoadingState;
    hasModel: boolean;
  } {
    return {
      state: this.loadingState,
      hasModel: this.session !== null
    };
  }

  /**
   * Libera recursos del modelo
   */
  public async dispose(): Promise<void> {
    if (this.session) {
      await this.session.release();
      this.session = null;
      this.loadingState = 'idle';
      // logger.info('🗑️ ONNX session disposed');
    }
  }

  /**
   * Precarga recursos de ONNX Runtime
   */
  public static async preload(): Promise<void> {
    try {
      // Precarga WASM files
      await ort.env.wasm.proxy;
      // logger.info('✅ ONNX Runtime WASM preloaded');
    } catch (error) {
      logger.warn('⚠️ Failed to preload ONNX Runtime:', error);
    }
  }
}

/**
 * Instancia singleton del servicio
 */
let onnxServiceInstance: ONNXService | null = null;

/**
 * Obtiene o crea instancia del servicio ONNX
 */
export function getONNXService(config?: ONNXServiceConfig): ONNXService {
  if (!onnxServiceInstance) {
    onnxServiceInstance = new ONNXService(config);
  }
  return onnxServiceInstance;
}

/**
 * Hook para precarga de ONNX en la app
 */
export async function initializeONNX(): Promise<void> {
  await ONNXService.preload();
  const svc = getONNXService();
  // Carga perezosa del modelo si el flag está activo
  const flag = (getOptionalClientEnv?.('NEXT_PUBLIC_AUTA_ONNX') || '').toLowerCase();
  if (flag === '1' || flag === 'true' || flag === 'on') {
    const modelPath = getClientEnvOrDefault?.('NEXT_PUBLIC_AUTA_ONNX_MODEL', '/models/intent.onnx');
    try {
      await svc.loadModel(modelPath);
      logger.info?.('Auta ONNX model loaded', { modelPath });
    } catch (e) {
      logger.warn?.('Auta ONNX model failed to load. Falling back to reglas.', (e as any)?.message || e);
    }
  }
}

/**
 * Tokenizer para procesamiento de texto médico
 * Optimizado para queries de pacientes en español
 */

export interface TokenizerConfig {
  maxLength: number;
  vocabSize: number;
}

export class MedicalTokenizer {
  private maxLength: number;
  private vocabSize: number;
  private vocabulary: Map<string, number>;
  private reverseVocab: Map<number, string>;

  constructor(config: TokenizerConfig) {
    this.maxLength = config.maxLength;
    this.vocabSize = config.vocabSize;
    this.vocabulary = new Map();
    this.reverseVocab = new Map();
    this.initializeVocabulary();
  }

  /**
   * Inicializa vocabulario médico básico en español
   */
  private initializeVocabulary(): void {
    // Tokens especiales
    const specialTokens = [
      '[PAD]', '[UNK]', '[CLS]', '[SEP]', '[MASK]'
    ];

    // Palabras médicas comunes
    const medicalWords = [
      // Síntomas
      'dolor', 'fiebre', 'tos', 'náusea', 'mareo', 'cansancio', 'presión', 'tensión',
      // Medicamentos
      'medicamento', 'pastilla', 'píldora', 'dosis', 'tratamiento', 'receta',
      // Partes del cuerpo
      'cabeza', 'pecho', 'estómago', 'corazón', 'pulmón', 'sangre',
      // Consultas
      'cita', 'consulta', 'doctor', 'médico', 'turno', 'agendar',
      // Preventivo
      'screening', 'chequeo', 'análisis', 'estudio', 'examen', 'mamografía', 'colonoscopia',
      // Reproductivo
      'embarazo', 'anticonceptivo', 'ive', 'ile', 'interrupción', 'aborto',
      // Palabras comunes
      'tengo', 'necesito', 'quiero', 'puedo', 'cuándo', 'dónde', 'cómo', 'qué',
      'mi', 'mis', 'tu', 'sus', 'el', 'la', 'los', 'las', 'un', 'una',
      'está', 'están', 'es', 'son', 'hay', 'tiene', 'tener',
      'por', 'para', 'con', 'sin', 'sobre', 'entre', 'desde', 'hasta',
      'hola', 'gracias', 'ayuda', 'información', 'ver', 'mostrar', 'saber'
    ];

    let index = 0;

    // Agregar tokens especiales
    for (const token of specialTokens) {
      this.vocabulary.set(token, index);
      this.reverseVocab.set(index, token);
      index++;
    }

    // Agregar palabras médicas
    for (const word of medicalWords) {
      this.vocabulary.set(word, index);
      this.reverseVocab.set(index, word);
      index++;
    }
  }

  /**
   * Normaliza texto para procesamiento
   */
  private normalizeText(text: string): string {
    return text
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '') // Eliminar acentos
      .replace(/[^\w\s]/g, ' ') // Reemplazar puntuación con espacios
      .replace(/\s+/g, ' ') // Normalizar espacios
      .trim();
  }

  /**
   * Tokeniza texto en IDs de vocabulario
   */
  public encode(text: string): number[] {
    const normalized = this.normalizeText(text);
    const words = normalized.split(' ');

    const tokens: number[] = [this.vocabulary.get('[CLS]')!];

    for (const word of words) {
      if (tokens.length >= this.maxLength - 1) break;

      const tokenId = this.vocabulary.get(word) ?? this.vocabulary.get('[UNK]')!;
      tokens.push(tokenId);
    }

    tokens.push(this.vocabulary.get('[SEP]')!);

    // Padding hasta maxLength
    while (tokens.length < this.maxLength) {
      tokens.push(this.vocabulary.get('[PAD]')!);
    }

    return tokens;
  }

  /**
   * Convierte IDs a texto
   */
  public decode(tokens: number[]): string {
    return tokens
      .map(id => this.reverseVocab.get(id) ?? '[UNK]')
      .filter(token => !['[PAD]', '[CLS]', '[SEP]', '[UNK]'].includes(token))
      .join(' ');
  }

  /**
   * Extrae features de texto para clasificación
   */
  public extractFeatures(text: string): {
    tokens: number[];
    attentionMask: number[];
    length: number;
  } {
    const tokens = this.encode(text);
    const attentionMask = tokens.map(t =>
      t === this.vocabulary.get('[PAD]')! ? 0 : 1
    );

    return {
      tokens,
      attentionMask,
      length: attentionMask.reduce((sum, val) => sum + val, 0)
    };
  }

  /**
   * Detecta keywords médicas en el texto
   */
  public extractMedicalKeywords(text: string): string[] {
    const normalized = this.normalizeText(text);
    const words = normalized.split(' ');

    return words.filter(word => {
      const tokenId = this.vocabulary.get(word);
      // Filtra palabras que están en vocabulario médico (no comunes ni especiales)
      return tokenId !== undefined &&
             tokenId > 5 && // Después de tokens especiales
             tokenId < 60;  // Dentro de palabras médicas
    });
  }
}

/**
 * Singleton tokenizer para uso en la app
 */
export const medicalTokenizer = new MedicalTokenizer({
  maxLength: 128,
  vocabSize: 1000
});

/**
 * Utilidades para verificar completitud de perfil de paciente
 */

interface PatientProfile {
  birth_date: string | null;
  gender: string | null;
  emergency_contact: Record<string, unknown> | null;
}

/**
 * Verifica si el perfil de paciente está completo
 *
 * Campos mínimos requeridos:
 * - birth_date
 * - gender
 * - emergency_contact (con name y phone)
 */
export function isPatientProfileComplete(patient: PatientProfile): boolean {
  if (!patient.birth_date) return false;
  if (!patient.gender) return false;

  if (!patient.emergency_contact) return false;

  const contact = patient.emergency_contact as { name?: string; phone?: string };
  if (!contact.name || !contact.phone) return false;

  return true;
}

/**
 * Retorna lista de campos faltantes en el perfil
 */
export function getMissingPatientFields(patient: PatientProfile): string[] {
  const missing: string[] = [];

  if (!patient.birth_date) missing.push('Fecha de nacimiento');
  if (!patient.gender) missing.push('Género');

  if (!patient.emergency_contact) {
    missing.push('Contacto de emergencia');
  } else {
    const contact = patient.emergency_contact as { name?: string; phone?: string };
    if (!contact.name) missing.push('Nombre de contacto de emergencia');
    if (!contact.phone) missing.push('Teléfono de contacto de emergencia');
  }

  return missing;
}

/**
 * Calcula progreso de completitud del perfil (0-100%)
 */
export function getPatientProfileCompletion(patient: PatientProfile): number {
  const totalFields = 7; // birth_date, gender, blood_type, height_cm, weight_kg, emergency_contact, insurance_info
  let completedFields = 0;

  if (patient.birth_date) completedFields++;
  if (patient.gender) completedFields++;

  // emergency_contact cuenta como 1 campo si tiene name y phone
  if (patient.emergency_contact) {
    const contact = patient.emergency_contact as { name?: string; phone?: string };
    if (contact.name && contact.phone) completedFields++;
  }

  // Campos opcionales pero recomendados
  const patientAny = patient as any;
  if (patientAny.blood_type) completedFields++;
  if (patientAny.height_cm) completedFields++;
  if (patientAny.weight_kg) completedFields++;
  if (patientAny.insurance_info) completedFields++;

  return Math.round((completedFields / totalFields) * 100);
}

import { cookies, headers } from 'next/headers';
import { createServerClient } from '@supabase/ssr';
import { createClient } from '@supabase/supabase-js';
import { ensureClientEnv, ensureServerEnv } from '@autamedica/shared';

export async function getUserIdFromRequest(): Promise<string | null> {
  const anonUrl = ensureClientEnv('NEXT_PUBLIC_SUPABASE_URL');
  const anonKey = ensureClientEnv('NEXT_PUBLIC_SUPABASE_ANON_KEY');
  const cookieStore = await cookies();
  const supabase = createServerClient(anonUrl, anonKey, {
    cookies: {
      get(name: string) { return cookieStore.get(name)?.value; },
      set() { return undefined; },
      remove() { return undefined; },
    },
  });

  const authHeader = (await headers()).get('authorization');
  if (authHeader?.toLowerCase().startsWith('bearer ')) {
    const token = authHeader.slice(7);
    try {
      const adminTmp = createClient(anonUrl, ensureServerEnv('SUPABASE_SERVICE_ROLE_KEY'));
      const { data: userRes } = await adminTmp.auth.getUser(token);
      if (userRes?.user) return userRes.user.id;
    } catch (_) { return null; }
  }

  const { data: userData } = await supabase.auth.getUser();
  return userData.user?.id ?? null;
}

/**
 * Servicio de señalización para WebRTC
 *
 * Maneja la coordinación entre peers para establecer conexión WebRTC:
 * - Intercambio de SDP (Session Description Protocol)
 * - Intercambio de ICE candidates
 * - Gestión de salas y presencia
 *
 * NOTA: Este servicio se conectará al Signaling Server (FASE 4)
 * Por ahora incluye la interfaz y mock para desarrollo local
 */

import { EventEmitter } from 'events';
import { logger } from '@autamedica/shared';

/**
 * Eventos que emite el servicio de señalización
 */
export enum SignalingEvent {
  /** Conexión establecida con servidor */
  CONNECTED = 'connected',
  /** Desconexión del servidor */
  DISCONNECTED = 'disconnected',
  /** Error de conexión */
  ERROR = 'error',

  /** Usuario se unió a la sala */
  USER_JOINED = 'user-joined',
  /** Usuario salió de la sala */
  USER_LEFT = 'user-left',

  /** Oferta SDP recibida */
  OFFER_RECEIVED = 'offer-received',
  /** Respuesta SDP recibida */
  ANSWER_RECEIVED = 'answer-received',
  /** ICE candidate recibido */
  ICE_CANDIDATE_RECEIVED = 'ice-candidate-received',

  /** Llamada iniciada por peer remoto */
  CALL_INITIATED = 'call-initiated',
  /** Llamada terminada */
  CALL_ENDED = 'call-ended',
}

/**
 * Mensajes del protocolo de señalización
 */
export interface SignalingMessage {
  type: 'offer' | 'answer' | 'ice-candidate' | 'join-room' | 'leave-room' | 'call-init' | 'call-end';
  roomId: string;
  userId: string;
  data?: any;
}

export interface SignalingConfig {
  /** URL del servidor de señalización (WebSocket) */
  serverUrl: string;
  /** ID del usuario actual */
  userId: string;
  /** Token de autenticación */
  authToken?: string;
  /** Auto-reconexión */
  autoReconnect?: boolean;
  /** Intervalo de heartbeat (ms) */
  heartbeatInterval?: number;
}

/**
 * Cliente de señalización para WebRTC
 */
export class SignalingService extends EventEmitter {
  private ws: WebSocket | null = null;
  private config: Required<SignalingConfig>;
  private currentRoomId: string | null = null;
  private reconnectTimer: NodeJS.Timeout | null = null;
  private heartbeatTimer: NodeJS.Timeout | null = null;
  private isConnected = false;

  constructor(config: SignalingConfig) {
    super();

    this.config = {
      serverUrl: config.serverUrl,
      userId: config.userId,
      authToken: config.authToken || '',
      autoReconnect: config.autoReconnect ?? true,
      heartbeatInterval: config.heartbeatInterval ?? 30000, // 30s
    };
  }

  /**
   * Conectar al servidor de señalización
   */
  async connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      // logger.info('[SignalingService] Connecting to:', this.config.serverUrl);

      try {
        // Crear WebSocket connection
        const wsUrl = `${this.config.serverUrl}?userId=${this.config.userId}${
          this.config.authToken ? `&token=${this.config.authToken}` : ''
        }`;

        this.ws = new WebSocket(wsUrl);

        // Handler: Connection opened
        this.ws.onopen = () => {
          // logger.info('[SignalingService] Connected successfully');
          this.isConnected = true;
          this.emit(SignalingEvent.CONNECTED);
          this.startHeartbeat();
          resolve();
        };

        // Handler: Message received
        this.ws.onmessage = (event) => {
          this.handleMessage(event.data);
        };

        // Handler: Connection error
        this.ws.onerror = (error) => {
          logger.error('[SignalingService] WebSocket error:', error);
          this.emit(SignalingEvent.ERROR, error);
          reject(error);
        };

        // Handler: Connection closed
        this.ws.onclose = (event) => {
          // logger.info('[SignalingService] Connection closed:', event.code, event.reason);
          this.isConnected = false;
          this.stopHeartbeat();
          this.emit(SignalingEvent.DISCONNECTED);

          // Auto-reconnect si está habilitado
          if (this.config.autoReconnect && event.code !== 1000) {
            // logger.info('[SignalingService] Attempting reconnection in 5s...');
            this.reconnectTimer = setTimeout(() => {
              this.connect();
            }, 5000);
          }
        };
      } catch (error) {
        logger.error('[SignalingService] Failed to create WebSocket:', error);
        reject(error);
      }
    });
  }

  /**
   * Desconectar del servidor
   */
  disconnect(): void {
    // logger.info('[SignalingService] Disconnecting...');

    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }

    this.stopHeartbeat();

    if (this.ws) {
      this.ws.close(1000, 'Client disconnect');
      this.ws = null;
    }

    this.isConnected = false;
    this.currentRoomId = null;
  }

  /**
   * Unirse a una sala de videoconsulta
   */
  joinRoom(roomId: string): void {
    // logger.info('[SignalingService] Joining room:', roomId);

    this.currentRoomId = roomId;

    const message: SignalingMessage = {
      type: 'join-room',
      roomId,
      userId: this.config.userId,
    };

    this.send(message);
  }

  /**
   * Salir de la sala actual
   */
  leaveRoom(): void {
    if (!this.currentRoomId) {
      logger.warn('[SignalingService] Not in any room');
      return;
    }

    // logger.info('[SignalingService] Leaving room:', this.currentRoomId);

    const message: SignalingMessage = {
      type: 'leave-room',
      roomId: this.currentRoomId,
      userId: this.config.userId,
    };

    this.send(message);
    this.currentRoomId = null;
  }

  /**
   * Enviar oferta SDP al peer remoto
   */
  sendOffer(roomId: string, offer: RTCSessionDescriptionInit): void {
    // logger.info('[SignalingService] Sending SDP offer to room:', roomId);

    const message: SignalingMessage = {
      type: 'offer',
      roomId,
      userId: this.config.userId,
      data: offer,
    };

    this.send(message);
  }

  /**
   * Enviar respuesta SDP al peer remoto
   */
  sendAnswer(roomId: string, answer: RTCSessionDescriptionInit): void {
    // logger.info('[SignalingService] Sending SDP answer to room:', roomId);

    const message: SignalingMessage = {
      type: 'answer',
      roomId,
      userId: this.config.userId,
      data: answer,
    };

    this.send(message);
  }

  /**
   * Enviar ICE candidate al peer remoto
   */
  sendIceCandidate(roomId: string, candidate: RTCIceCandidate): void {
    // logger.info('[SignalingService] Sending ICE candidate to room:', roomId);

    const message: SignalingMessage = {
      type: 'ice-candidate',
      roomId,
      userId: this.config.userId,
      data: {
        candidate: candidate.candidate,
        sdpMLineIndex: candidate.sdpMLineIndex,
        sdpMid: candidate.sdpMid,
      },
    };

    this.send(message);
  }

  /**
   * Enviar mensaje al servidor
   */
  private send(message: SignalingMessage): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      logger.error('[SignalingService] Cannot send message: WebSocket not connected');
      return;
    }

    try {
      this.ws.send(JSON.stringify(message));
    } catch (error) {
      logger.error('[SignalingService] Failed to send message:', error);
    }
  }

  /**
   * Manejar mensajes recibidos del servidor
   */
  private handleMessage(data: string): void {
    try {
      const message: SignalingMessage = JSON.parse(data);

      // logger.info('[SignalingService] Message received:', message.type);

      switch (message.type) {
        case 'offer':
          this.emit(SignalingEvent.OFFER_RECEIVED, {
            roomId: message.roomId,
            userId: message.userId,
            offer: message.data,
          });
          break;

        case 'answer':
          this.emit(SignalingEvent.ANSWER_RECEIVED, {
            roomId: message.roomId,
            userId: message.userId,
            answer: message.data,
          });
          break;

        case 'ice-candidate':
          this.emit(SignalingEvent.ICE_CANDIDATE_RECEIVED, {
            roomId: message.roomId,
            userId: message.userId,
            candidate: message.data,
          });
          break;

        case 'call-init':
          this.emit(SignalingEvent.CALL_INITIATED, {
            roomId: message.roomId,
            userId: message.userId,
          });
          break;

        case 'call-end':
          this.emit(SignalingEvent.CALL_ENDED, {
            roomId: message.roomId,
            userId: message.userId,
          });
          break;

        default:
          logger.warn('[SignalingService] Unknown message type:', message.type);
      }
    } catch (error) {
      logger.error('[SignalingService] Failed to parse message:', error);
    }
  }

  /**
   * Iniciar heartbeat para mantener conexión viva
   */
  private startHeartbeat(): void {
    this.heartbeatTimer = setInterval(() => {
      if (this.ws && this.ws.readyState === WebSocket.OPEN) {
        this.ws.send(JSON.stringify({ type: 'ping' }));
      }
    }, this.config.heartbeatInterval);
  }

  /**
   * Detener heartbeat
   */
  private stopHeartbeat(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  /**
   * Verificar si está conectado
   */
  get connected(): boolean {
    return this.isConnected && this.ws?.readyState === WebSocket.OPEN;
  }

  /**
   * Obtener sala actual
   */
  get roomId(): string | null {
    return this.currentRoomId;
  }
}

/**
 * Instancia singleton del servicio de señalización
 * (se inicializa cuando el usuario inicia una llamada)
 */
let signalingInstance: SignalingService | null = null;

/**
 * Obtener instancia del servicio de señalización
 */
export function getSignalingService(config?: SignalingConfig): SignalingService {
  if (!signalingInstance && config) {
    signalingInstance = new SignalingService(config);
  }

  if (!signalingInstance) {
    throw new Error('SignalingService not initialized. Provide config on first call.');
  }

  return signalingInstance;
}

/**
 * Limpiar instancia singleton (útil para testing)
 */
export function resetSignalingService(): void {
  if (signalingInstance) {
    signalingInstance.disconnect();
    signalingInstance = null;
  }
}

/**
 * Servicio de Señalización WebRTC usando Supabase Realtime
 *
 * En lugar de un servidor WebSocket dedicado, usamos Supabase Realtime
 * como canal de comunicación para intercambiar SDP offers/answers e ICE candidates.
 *
 * Ventajas:
 * - No requiere servidor adicional
 * - Escalable automáticamente
 * - Autenticación integrada con Supabase Auth
 * - Real-time bidireccional
 */

import type { RealtimeChannel, SupabaseClient } from '@supabase/supabase-js';
import { logger } from '@autamedica/shared';

export type SignalingMessageType =
  | 'offer'
  | 'answer'
  | 'ice-candidate'
  | 'join-room'
  | 'leave-room'
  | 'peer-joined'
  | 'peer-left';

export interface SignalingMessage {
  type: SignalingMessageType;
  roomId: string;
  from: string;
  to?: string;
  data?: any;
  timestamp: number;
}

export interface SignalingCallbacks {
  onOffer?: (offer: RTCSessionDescriptionInit, from: string) => void;
  onAnswer?: (answer: RTCSessionDescriptionInit, from: string) => void;
  onIceCandidate?: (candidate: RTCIceCandidateInit, from: string) => void;
  onPeerJoined?: (peerId: string) => void;
  onPeerLeft?: (peerId: string) => void;
  onError?: (error: Error) => void;
}

export class SupabaseSignalingService {
  private supabase: SupabaseClient;
  private channel: RealtimeChannel | null = null;
  private currentRoomId: string | null = null;
  private userId: string;
  private callbacks: SignalingCallbacks;

  constructor(
    supabase: SupabaseClient,
    userId: string,
    callbacks: SignalingCallbacks = {}
  ) {
    this.supabase = supabase;
    this.userId = userId;
    this.callbacks = callbacks;
  }

  /**
   * Unirse a una sala de videollamada
   */
  async joinRoom(roomId: string): Promise<void> {
    try {
      // Salir de sala anterior si existe
      if (this.currentRoomId) {
        await this.leaveRoom();
      }

      this.currentRoomId = roomId;

      // Crear canal de Realtime para esta sala
      this.channel = this.supabase.channel(`webrtc:${roomId}`, {
        config: {
          broadcast: { self: true }, // Recibir propios mensajes para debugging
          presence: { key: this.userId },
        },
      });

      // Suscribirse a mensajes broadcast
      this.channel.on('broadcast', { event: 'signaling' }, (payload) => {
        this.handleSignalingMessage(payload.payload as SignalingMessage);
      });

      // Suscribirse a eventos de presencia
      this.channel.on('presence', { event: 'join' }, ({ key, newPresences }) => {
        logger.info('[Signaling] Peer joined:', key);
        if (key !== this.userId && this.callbacks.onPeerJoined) {
          this.callbacks.onPeerJoined(key);
        }
      });

      this.channel.on('presence', { event: 'leave' }, ({ key, leftPresences }) => {
        logger.info('[Signaling] Peer left:', key);
        if (key !== this.userId && this.callbacks.onPeerLeft) {
          this.callbacks.onPeerLeft(key);
        }
      });

      // Suscribirse al canal
      await this.channel.subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          logger.info('[Signaling] Subscribed to room:', roomId);

          // Trackear presencia
          await this.channel?.track({
            user_id: this.userId,
            online_at: new Date().toISOString(),
          });

          // Notificar que nos unimos
          await this.sendMessage({
            type: 'join-room',
            roomId,
            from: this.userId,
            timestamp: Date.now(),
          });
        }
      });
    } catch (error) {
      logger.error('[Signaling] Error joining room:', error);
      if (this.callbacks.onError) {
        this.callbacks.onError(error as Error);
      }
      throw error;
    }
  }

  /**
   * Salir de la sala actual
   */
  async leaveRoom(): Promise<void> {
    if (!this.channel || !this.currentRoomId) {
      return;
    }

    try {
      // Notificar que salimos
      await this.sendMessage({
        type: 'leave-room',
        roomId: this.currentRoomId,
        from: this.userId,
        timestamp: Date.now(),
      });

      // Untrack presencia
      await this.channel.untrack();

      // Desuscribirse del canal
      await this.supabase.removeChannel(this.channel);

      this.channel = null;
      this.currentRoomId = null;

      logger.info('[Signaling] Left room');
    } catch (error) {
      logger.error('[Signaling] Error leaving room:', error);
    }
  }

  /**
   * Enviar oferta SDP a peer remoto
   */
  async sendOffer(offer: RTCSessionDescriptionInit, to?: string): Promise<void> {
    if (!this.currentRoomId) {
      throw new Error('Not in a room');
    }

    await this.sendMessage({
      type: 'offer',
      roomId: this.currentRoomId,
      from: this.userId,
      to,
      data: offer,
      timestamp: Date.now(),
    });

    logger.info('[Signaling] Sent offer to:', to || 'room');
  }

  /**
   * Enviar respuesta SDP a peer remoto
   */
  async sendAnswer(answer: RTCSessionDescriptionInit, to: string): Promise<void> {
    if (!this.currentRoomId) {
      throw new Error('Not in a room');
    }

    await this.sendMessage({
      type: 'answer',
      roomId: this.currentRoomId,
      from: this.userId,
      to,
      data: answer,
      timestamp: Date.now(),
    });

    logger.info('[Signaling] Sent answer to:', to);
  }

  /**
   * Enviar ICE candidate a peer remoto
   */
  async sendIceCandidate(candidate: RTCIceCandidateInit, to?: string): Promise<void> {
    if (!this.currentRoomId) {
      throw new Error('Not in a room');
    }

    await this.sendMessage({
      type: 'ice-candidate',
      roomId: this.currentRoomId,
      from: this.userId,
      to,
      data: candidate,
      timestamp: Date.now(),
    });
  }

  /**
   * Enviar mensaje genérico de señalización
   */
  private async sendMessage(message: SignalingMessage): Promise<void> {
    if (!this.channel) {
      throw new Error('Channel not initialized');
    }

    await this.channel.send({
      type: 'broadcast',
      event: 'signaling',
      payload: message,
    });
  }

  /**
   * Manejar mensaje de señalización recibido
   */
  private handleSignalingMessage(message: SignalingMessage): void {
    // Ignorar mensajes propios
    if (message.from === this.userId) {
      return;
    }

    // Si el mensaje tiene destinatario específico, verificar que seamos nosotros
    if (message.to && message.to !== this.userId) {
      return;
    }

    logger.info('[Signaling] Received message:', message.type, 'from:', message.from);

    switch (message.type) {
      case 'offer':
        if (this.callbacks.onOffer) {
          this.callbacks.onOffer(message.data, message.from);
        }
        break;

      case 'answer':
        if (this.callbacks.onAnswer) {
          this.callbacks.onAnswer(message.data, message.from);
        }
        break;

      case 'ice-candidate':
        if (this.callbacks.onIceCandidate) {
          this.callbacks.onIceCandidate(message.data, message.from);
        }
        break;

      case 'peer-joined':
        if (this.callbacks.onPeerJoined) {
          this.callbacks.onPeerJoined(message.from);
        }
        break;

      case 'peer-left':
        if (this.callbacks.onPeerLeft) {
          this.callbacks.onPeerLeft(message.from);
        }
        break;

      default:
        logger.warn('[Signaling] Unknown message type:', message.type);
    }
  }

  /**
   * Obtener peers actuales en la sala
   */
  async getPeersInRoom(): Promise<string[]> {
    if (!this.channel) {
      return [];
    }

    const presenceState = this.channel.presenceState();
    return Object.keys(presenceState).filter(key => key !== this.userId);
  }

  /**
   * Cleanup
   */
  async disconnect(): Promise<void> {
    await this.leaveRoom();
  }
}

// Store simplificado para pacientes
export const useMedicalHistoryStore = () => ({
  addEntry: async (entry: any) => logger.info('Entry added:', entry),
  suggestPrescriptions: async () => [],
  analyzeVitals: async () => null
})

/**
 * Store médico específico para pacientes - Vista desde perspectiva del paciente
 */

// Usando una implementación simple sin zustand por ahora
interface PatientMedicalEntry {
  id: string
  type: 'symptom' | 'medication_taken' | 'vital_sign' | 'note' | 'appointment'
  content: string
  metadata?: {
    medication?: string
    dosage?: string
    takenAt?: string
    symptomSeverity?: 'leve' | 'moderado' | 'severo'
    vitals?: {
      weight?: number
      bloodPressure?: string
      heartRate?: number
      temperature?: number
    }
    appointmentType?: 'consulta' | 'control' | 'emergencia'
  }
  timestamp: string
  patientId: string
  isPrivate?: boolean // Notas privadas del paciente
}

interface PatientMedicalState {
  entries: PatientMedicalEntry[]
  isLoading: boolean
  lastSync: string | null
  personalNotes: string[]
  symptoms: PatientMedicalEntry[]
  medications: PatientMedicalEntry[]
  vitals: PatientMedicalEntry[]
}

class PatientMedicalStore {
  private state: PatientMedicalState = {
    entries: [],
    isLoading: false,
    lastSync: null,
    personalNotes: [],
    symptoms: [],
    medications: [],
    vitals: []
  }

  private listeners: Array<(state: PatientMedicalState) => void> = []

  // Subscribe to state changes
  subscribe(listener: (state: PatientMedicalState) => void) {
    this.listeners.push(listener)
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener)
    }
  }

  private notify() {
    this.listeners.forEach(listener => listener(this.state))
  }

  getState() {
    return this.state
  }

  // Actions específicas para pacientes
  async addPersonalNote(content: string, patientId: string) {
    const newEntry: PatientMedicalEntry = {
      id: crypto.randomUUID(),
      type: 'note',
      content,
      timestamp: new Date().toISOString(),
      patientId,
      isPrivate: true
    }

    this.state.entries.push(newEntry)
    this.state.personalNotes.push(content)
    this.state.lastSync = new Date().toISOString()
    this.notify()

    // Simular sincronización
    await this.syncWithBackend()
  }

  async recordSymptom(symptom: string, severity: 'leve' | 'moderado' | 'severo', patientId: string) {
    const newEntry: PatientMedicalEntry = {
      id: crypto.randomUUID(),
      type: 'symptom',
      content: symptom,
      metadata: {
        symptomSeverity: severity
      },
      timestamp: new Date().toISOString(),
      patientId
    }

    this.state.entries.push(newEntry)
    this.state.symptoms.push(newEntry)
    this.state.lastSync = new Date().toISOString()
    this.notify()

    await this.syncWithBackend()
  }

  async recordMedicationTaken(medication: string, dosage: string, patientId: string) {
    const newEntry: PatientMedicalEntry = {
      id: crypto.randomUUID(),
      type: 'medication_taken',
      content: `Tomé ${medication}`,
      metadata: {
        medication,
        dosage,
        takenAt: new Date().toISOString()
      },
      timestamp: new Date().toISOString(),
      patientId
    }

    this.state.entries.push(newEntry)
    this.state.medications.push(newEntry)
    this.state.lastSync = new Date().toISOString()
    this.notify()

    await this.syncWithBackend()
  }

  async recordVitalSigns(vitals: PatientMedicalEntry['metadata']['vitals'], patientId: string) {
    const newEntry: PatientMedicalEntry = {
      id: crypto.randomUUID(),
      type: 'vital_sign',
      content: 'Signos vitales registrados',
      metadata: { vitals },
      timestamp: new Date().toISOString(),
      patientId
    }

    this.state.entries.push(newEntry)
    this.state.vitals.push(newEntry)
    this.state.lastSync = new Date().toISOString()
    this.notify()

    await this.syncWithBackend()
  }

  // Análisis desde perspectiva del paciente
  getSymptomTrends() {
    const symptoms = this.state.symptoms.slice(-7) // Últimos 7 registros
    const trends = symptoms.reduce((acc, symptom) => {
      const severity = symptom.metadata?.symptomSeverity || 'leve'
      acc[severity] = (acc[severity] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    return trends
  }

  getMedicationAdherence() {
    const medications = this.state.medications.slice(-30) // Último mes
    const today = new Date()
    const thirtyDaysAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000)

    const recentMeds = medications.filter(med =>
      new Date(med.timestamp) >= thirtyDaysAgo
    )

    return {
      totalTaken: recentMeds.length,
      adherenceScore: recentMeds.length > 0 ? Math.min(100, (recentMeds.length / 30) * 100) : 0,
      lastTaken: recentMeds[recentMeds.length - 1]?.timestamp || null
    }
  }

  getHealthSummary() {
    const symptoms = this.getSymptomTrends()
    const medication = this.getMedicationAdherence()
    const vitals = this.state.vitals.slice(-1)[0] // Últimos signos vitales

    return {
      symptomsCount: this.state.symptoms.length,
      lastSymptom: this.state.symptoms[this.state.symptoms.length - 1]?.content || 'Ninguno',
      medicationAdherence: medication.adherenceScore,
      lastVitals: vitals?.metadata?.vitals || null,
      overallStatus: this.calculateOverallStatus()
    }
  }

  private calculateOverallStatus(): 'excelente' | 'bueno' | 'regular' | 'necesita_atencion' {
    const symptoms = this.getSymptomTrends()
    const severeSymptoms = symptoms['severo'] || 0
    const medication = this.getMedicationAdherence()

    if (severeSymptoms > 0) return 'necesita_atencion'
    if (medication.adherenceScore < 50) return 'regular'
    if (medication.adherenceScore > 80) return 'excelente'
    return 'bueno'
  }

  private async syncWithBackend() {
    this.state.isLoading = true
    this.notify()

    try {
      // Simular sincronización con backend
      await new Promise(resolve => setTimeout(resolve, 300))

      // logger.info('[Patient Medical Store] Synced with backend')
      this.state.lastSync = new Date().toISOString()
    } catch (error) {
      logger.error('[Patient Medical Store] Sync failed:', error)
    } finally {
      this.state.isLoading = false
      this.notify()
    }
  }

  // Métodos para compartir con médicos
  async generateMedicalSummaryForDoctor() {
    const summary = this.getHealthSummary()
    const recentEntries = this.state.entries.slice(-10)

    return {
      summary,
      recentEntries: recentEntries.filter(entry => !entry.isPrivate), // Excluir notas privadas
      trends: this.getSymptomTrends(),
      medicationAdherence: this.getMedicationAdherence(),
      generatedAt: new Date().toISOString()
    }
  }

  // Limpiar datos sensibles
  async clearPrivateData() {
    this.state.personalNotes = []
    this.state.entries = this.state.entries.filter(entry => !entry.isPrivate)
    this.notify()
  }
}

// Singleton instance para toda la app
export const patientMedicalStore = new PatientMedicalStore()

// React hook para usar el store
export function usePatientMedicalStore() {
  const [state, setState] = useState(patientMedicalStore.getState())

  useEffect(() => {
    const unsubscribe = patientMedicalStore.subscribe(setState)
    return unsubscribe
  }, [])

  return {
    ...state,
    addPersonalNote: patientMedicalStore.addPersonalNote.bind(patientMedicalStore),
    recordSymptom: patientMedicalStore.recordSymptom.bind(patientMedicalStore),
    recordMedicationTaken: patientMedicalStore.recordMedicationTaken.bind(patientMedicalStore),
    recordVitalSigns: patientMedicalStore.recordVitalSigns.bind(patientMedicalStore),
    getHealthSummary: patientMedicalStore.getHealthSummary.bind(patientMedicalStore),
    generateMedicalSummaryForDoctor: patientMedicalStore.generateMedicalSummaryForDoctor.bind(patientMedicalStore)
  }
}

// Necesario para useState
import { useState, useEffect } from 'react'

/**
 * Tipos para Anamnesis Interactiva
 * Basado en la estructura de Alvarez con storytelling médico
 */

export interface AnamnesisStep {
  id: string;
  title: string;
  subtitle: string;
  story?: {
    intro: string;
    why: string;
    example?: string;
    didYouKnow?: string;
  };
  fields: AnamnesisField[];
  mediaUrl?: string; // URL de imagen o video educativo
  completed: boolean;
  category: AnamnesisCategory;
}

export type AnamnesisCategory =
  | 'filiacion'
  | 'motivo_consulta'
  | 'enfermedad_actual'
  | 'antecedentes_personales'
  | 'antecedentes_familiares'
  | 'revision_sistemas';

export interface AnamnesisField {
  id: string;
  type: 'text' | 'number' | 'select' | 'multiselect' | 'date' | 'textarea' | 'boolean' | 'scale';
  label: string;
  placeholder?: string;
  required: boolean;
  options?: { value: string; label: string; explanation?: string }[];
  tooltip?: string;
  educationalNote?: string; // Nota que aparece al completar
  validation?: {
    min?: number;
    max?: number;
    pattern?: string;
  };
  dependsOn?: {
    fieldId: string;
    value: any;
  };
}

export interface AnamnesisData {
  patient_id: string;
  started_at: string;
  last_updated: string;
  completed_at?: string;
  progress_percentage: number;

  // Datos de Filiación
  filiacion: {
    edad: number;
    sexo: 'masculino' | 'femenino' | 'otro';
