  };

  manager.processAlert(exampleAlert).then(incident => {
    console.log('\n📋 Incident processed:');
    console.log(JSON.stringify(incident, null, 2));

    console.log('\n📊 Incident statistics:');
    console.log(JSON.stringify(manager.getIncidentStats(), null, 2));
  });
}

/**
 * Connection Quality Indicator Component
 * Visual display of WebRTC connection quality metrics
 *
 * @module ConnectionQualityIndicator
 */

'use client';

import { useState, useEffect } from 'react';
import type {
  ConnectionQuality,
  ConnectionStats,
  DetailedStats,
} from '@/hooks/useConnectionQuality';

export interface ConnectionQualityIndicatorProps {
  stats: ConnectionStats | null;
  detailedStats?: DetailedStats | null;
  className?: string;
  compact?: boolean;
  showAlert?: boolean;
}

/**
 * Quality config for visual display
 */
const QUALITY_CONFIG: Record<
  ConnectionQuality,
  {
    label: string;
    color: string;
    bgColor: string;
    icon: string;
  }
> = {
  excellent: {
    label: 'Excelente',
    color: 'text-green-600',
    bgColor: 'bg-green-100',
    icon: '●●●●',
  },
  good: {
    label: 'Buena',
    color: 'text-blue-600',
    bgColor: 'bg-blue-100',
    icon: '●●●○',
  },
  fair: {
    label: 'Regular',
    color: 'text-yellow-600',
    bgColor: 'bg-yellow-100',
    icon: '●●○○',
  },
  poor: {
    label: 'Mala',
    color: 'text-orange-600',
    bgColor: 'bg-orange-100',
    icon: '●○○○',
  },
  disconnected: {
    label: 'Desconectado',
    color: 'text-red-600',
    bgColor: 'bg-red-100',
    icon: '○○○○',
  },
};

/**
 * Format bitrate for display
 */
function formatBitrate(kbps: number): string {
  if (kbps >= 1000) {
    return `${(kbps / 1000).toFixed(1)} Mbps`;
  }
  return `${Math.round(kbps)} kbps`;
}

/**
 * Format latency for display
 */
function formatLatency(ms: number): string {
  return `${Math.round(ms)} ms`;
}

/**
 * Format packet loss for display
 */
function formatPacketLoss(percentage: number): string {
  return `${percentage.toFixed(2)}%`;
}

/**
 * Connection Quality Indicator Component
 */
export function ConnectionQualityIndicator({
  stats,
  detailedStats,
  className = '',
  compact = false,
  showAlert = true,
}: ConnectionQualityIndicatorProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showPoorAlert, setShowPoorAlert] = useState(false);

  // Show alert when quality drops
  useEffect(() => {
    if (!stats || !showAlert) return;

    if (stats.quality === 'poor' || stats.quality === 'disconnected') {
      setShowPoorAlert(true);
      const timer = setTimeout(() => setShowPoorAlert(false), 5000);
      return () => clearTimeout(timer);
    }
  }, [stats?.quality, showAlert]);

  if (!stats) {
    return (
      <div className={`rounded-lg bg-gray-100 p-3 ${className}`}>
        <div className="flex items-center gap-2">
          <div className="h-2 w-2 animate-pulse rounded-full bg-gray-400"></div>
          <span className="text-sm text-gray-600">Conectando...</span>
        </div>
      </div>
    );
  }

  const config = QUALITY_CONFIG[stats.quality];

  // Compact mode - just show quality badge
  if (compact && !isExpanded) {
    return (
      <div className={className}>
        <button
          onClick={() => setIsExpanded(true)}
          className={`flex items-center gap-2 rounded-full px-3 py-1 ${config.bgColor} transition-all hover:scale-105`}
        >
          <span className={`text-sm font-medium ${config.color}`}>{config.icon}</span>
          <span className={`text-xs font-semibold ${config.color}`}>{config.label}</span>
        </button>
      </div>
    );
  }

  return (
    <div className={`space-y-3 ${className}`}>
      {/* Poor Connection Alert */}
      {showPoorAlert && (stats.quality === 'poor' || stats.quality === 'disconnected') && (
        <div className="animate-pulse rounded-lg border-2 border-red-500 bg-red-50 p-3">
          <div className="flex items-center gap-2">
            <span className="text-xl">⚠️</span>
            <div>
              <p className="text-sm font-semibold text-red-800">Conexión inestable</p>
              <p className="text-xs text-red-600">
                La calidad de video puede verse afectada. Verifica tu conexión a internet.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Main Stats Card */}
      <div className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm">
        {/* Header with Quality Badge */}
        <div className="mb-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`rounded-lg px-3 py-1 ${config.bgColor}`}>
              <span className={`text-sm font-medium ${config.color}`}>{config.icon}</span>
            </div>
            <div>
              <p className="text-sm font-semibold text-gray-800">Calidad de Conexión</p>
              <p className={`text-xs font-bold ${config.color}`}>{config.label}</p>
            </div>
          </div>

          {compact && (
            <button
              onClick={() => setIsExpanded(false)}
              className="text-xs text-gray-500 hover:text-gray-700"
            >
              Minimizar
            </button>
          )}
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 gap-3">
          {/* Bitrate */}
          <div className="rounded-lg bg-gray-50 p-2">
            <p className="text-xs text-gray-600">Bitrate</p>
            <p className="text-lg font-bold text-gray-900">{formatBitrate(stats.bitrate)}</p>
          </div>

          {/* Latency */}
          <div className="rounded-lg bg-gray-50 p-2">
            <p className="text-xs text-gray-600">Latencia</p>
            <p className="text-lg font-bold text-gray-900">{formatLatency(stats.latency)}</p>
          </div>

          {/* Packet Loss */}
          <div className="rounded-lg bg-gray-50 p-2">
            <p className="text-xs text-gray-600">Pérdida de Paquetes</p>
            <p className="text-lg font-bold text-gray-900">{formatPacketLoss(stats.packetLoss)}</p>
          </div>

          {/* Jitter */}
          <div className="rounded-lg bg-gray-50 p-2">
            <p className="text-xs text-gray-600">Jitter</p>
            <p className="text-lg font-bold text-gray-900">{formatLatency(stats.jitter)}</p>
          </div>
        </div>

        {/* Detailed Stats (optional) */}
        {detailedStats && (
          <details className="mt-3">
            <summary className="cursor-pointer text-xs text-gray-500 hover:text-gray-700">
              Ver estadísticas detalladas
            </summary>

            <div className="mt-3 space-y-3 text-xs">
              {/* Video Stats */}
              <div className="rounded-lg border border-gray-200 bg-gray-50 p-2">
                <p className="mb-2 font-semibold text-gray-700">📹 Video</p>
                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span className="text-gray-600">Enviado:</span>
                    <span className="font-medium text-gray-900">
                      {formatBitrate(detailedStats.video.sent.bitrate)} @ {detailedStats.video.sent.fps} fps
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Recibido:</span>
                    <span className="font-medium text-gray-900">
                      {formatBitrate(detailedStats.video.received.bitrate)} @ {detailedStats.video.received.fps} fps
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Resolución:</span>
                    <span className="font-medium text-gray-900">
                      {detailedStats.video.received.resolution || 'N/A'}
                    </span>
                  </div>
                </div>
              </div>

              {/* Audio Stats */}
              <div className="rounded-lg border border-gray-200 bg-gray-50 p-2">
                <p className="mb-2 font-semibold text-gray-700">🎤 Audio</p>
                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span className="text-gray-600">Enviado:</span>
                    <span className="font-medium text-gray-900">
                      {formatBitrate(detailedStats.audio.sent.bitrate)}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Recibido:</span>
                    <span className="font-medium text-gray-900">
                      {formatBitrate(detailedStats.audio.received.bitrate)}
                    </span>
                  </div>
                </div>
              </div>

              {/* Connection Stats */}
              <div className="rounded-lg border border-gray-200 bg-gray-50 p-2">
                <p className="mb-2 font-semibold text-gray-700">🔌 Conexión</p>
                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span className="text-gray-600">RTT:</span>
                    <span className="font-medium text-gray-900">
                      {formatLatency(detailedStats.connection.currentRoundTripTime)}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Ancho de banda:</span>
                    <span className="font-medium text-gray-900">
                      {formatBitrate(detailedStats.connection.availableOutgoingBitrate)}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Estado:</span>
                    <span className="font-medium text-gray-900">
                      {detailedStats.connection.state}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </details>
        )}

        {/* Timestamp */}
        <p className="mt-3 text-xs text-gray-400">
          Actualizado: {new Date(stats.timestamp).toLocaleTimeString()}
        </p>
      </div>
    </div>
  );
}

/**
 * FileSharing Component
 * Componente drag-and-drop para compartir archivos durante videoconsultas
 */

'use client';

import React, { useState, useRef, useCallback } from 'react';
import { useSessionFiles } from '../../hooks/useSessionFiles';
import {
  formatFileSize,
  getFileIcon,
  isImage,
  ALLOWED_FILE_TYPES,
  MAX_FILE_SIZE,
} from '../../lib/sessionFiles';
import { logger } from '@autamedica/shared';

export interface FileSharingProps {
  userId: string;
  sessionId: string;
  onFileShared?: (fileUrl: string) => void;
  className?: string;
}

export function FileSharing({
  userId,
  sessionId,
  onFileShared,
  className = '',
}: FileSharingProps) {
  const {
    files,
    uploading,
    uploadProgress,
    error,
    uploadFile,
    uploadFiles,
    deleteFile,
    refreshFiles,
    downloadFile,
  } = useSessionFiles({ userId, sessionId });

  const [isDragging, setIsDragging] = useState(false);
  const [showFiles, setShowFiles] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  /**
   * Handle file selection from input
   */
  const handleFileSelect = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const selectedFiles = Array.from(e.target.files || []);
      if (selectedFiles.length === 0) return;

      try {
        if (selectedFiles.length === 1) {
          const result = await uploadFile(selectedFiles[0]);
          onFileShared?.(result.url);
        } else {
          const results = await uploadFiles(selectedFiles);
          results.forEach((result) => onFileShared?.(result.url));
        }
      } catch (err) {
        logger.error('Upload failed:', err);
      }

      // Reset input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    },
    [uploadFile, uploadFiles, onFileShared]
  );

  /**
   * Handle drag events
   */
  const handleDragEnter = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback(
    async (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setIsDragging(false);

      const droppedFiles = Array.from(e.dataTransfer.files);
      if (droppedFiles.length === 0) return;

      try {
        if (droppedFiles.length === 1) {
          const result = await uploadFile(droppedFiles[0]);
          onFileShared?.(result.url);
        } else {
          const results = await uploadFiles(droppedFiles);
          results.forEach((result) => onFileShared?.(result.url));
        }
      } catch (err) {
        logger.error('Upload failed:', err);
      }
    },
    [uploadFile, uploadFiles, onFileShared]
  );

  /**
   * Handle delete file
   */
  const handleDelete = useCallback(
    async (filePath: string) => {
      if (!confirm('¿Estás seguro de eliminar este archivo?')) return;

      try {
        await deleteFile(filePath);
      } catch (err) {
        logger.error('Delete failed:', err);
      }
    },
    [deleteFile]
  );

  /**
   * Handle download file
   */
  const handleDownload = useCallback(
    async (filePath: string, fileName: string) => {
      try {
        await downloadFile(filePath, fileName);
      } catch (err) {
        logger.error('Download failed:', err);
      }
    },
    [downloadFile]
  );

  return (
    <div className={`flex flex-col ${className}`}>
      {/* Header with toggle */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 dark:border-gray-700">
        <button
          onClick={() => setShowFiles(!showFiles)}
          className="flex items-center space-x-2 text-sm font-semibold text-gray-900 dark:text-gray-100 hover:text-blue-600 dark:hover:text-blue-400"
        >
          <svg
            className="w-5 h-5 text-blue-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
            />
          </svg>
          <span>Archivos Compartidos</span>
          {files.length > 0 && (
            <span className="px-2 py-0.5 text-xs bg-blue-100 dark:bg-blue-900 text-blue-600 dark:text-blue-300 rounded-full">
              {files.length}
            </span>
          )}
        </button>
        <button
          onClick={() => setShowFiles(!showFiles)}
          className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
        >
          <svg
            className={`w-5 h-5 transition-transform ${showFiles ? 'rotate-180' : ''}`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 9l-7 7-7-7"
            />
          </svg>
        </button>
      </div>

      {/* Content */}
      {showFiles && (
        <div className="flex-1 overflow-y-auto">
          {/* Upload area */}
          <div
            className={`m-4 p-6 border-2 border-dashed rounded-lg transition-colors ${
              isDragging
                ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                : 'border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-800/50'
            }`}
            onDragEnter={handleDragEnter}
            onDragLeave={handleDragLeave}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
          >
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept={[...ALLOWED_FILE_TYPES.images, ...ALLOWED_FILE_TYPES.documents].join(',')}
              onChange={handleFileSelect}
              className="hidden"
            />

            <div className="text-center">
              <svg
                className="mx-auto h-12 w-12 text-gray-400"
                stroke="currentColor"
                fill="none"
                viewBox="0 0 48 48"
              >
                <path
                  d="M28 8H12a4 4 0 00-4 4v20m32-12v8m0 0v8a4 4 0 01-4 4H12a4 4 0 01-4-4v-4m32-4l-3.172-3.172a4 4 0 00-5.656 0L28 28M8 32l9.172-9.172a4 4 0 015.656 0L28 28m0 0l4 4m4-24h8m-4-4v8m-12 4h.02"
                  strokeWidth={2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
              <p className="mt-2 text-sm text-gray-600 dark:text-gray-400">
                {isDragging ? (
                  <span className="font-semibold">Suelta los archivos aquí</span>
                ) : (
                  <>
                    <button
                      onClick={() => fileInputRef.current?.click()}
                      className="text-blue-600 hover:text-blue-500 dark:text-blue-400 font-semibold"
                      disabled={uploading}
                    >
                      Selecciona archivos
                    </button>
                    <span> o arrástralos aquí</span>
                  </>
                )}
              </p>
              <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                Imágenes y documentos hasta {MAX_FILE_SIZE / 1024 / 1024}MB
              </p>
            </div>

            {/* Upload progress */}
            {uploading && (
              <div className="mt-4">
                <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                  <div
                    className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${uploadProgress}%` }}
                  />
                </div>
                <p className="mt-1 text-xs text-center text-gray-600 dark:text-gray-400">
                  Subiendo... {Math.round(uploadProgress)}%
                </p>
              </div>
            )}
          </div>

          {/* Error message */}
          {error && (
            <div className="mx-4 mb-4 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
              <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
            </div>
          )}

          {/* Files list */}
          {files.length > 0 && (
            <div className="px-4 pb-4">
              <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase mb-2">
                Archivos ({files.length})
              </h4>
              <div className="space-y-2">
                {files.map((file, index) => (
                  <div
                    key={index}
                    className="flex items-center justify-between p-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-sm transition-shadow"
                  >
                    <div className="flex items-center space-x-3 flex-1 min-w-0">
                      {/* File icon or thumbnail */}
                      <div className="flex-shrink-0">
                        {isImage(file.type) ? (
                          <img
                            src={file.url}
                            alt={file.name}
                            className="w-10 h-10 object-cover rounded"
                          />
                        ) : (
                          <div className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-gray-700 rounded text-2xl">
                            {getFileIcon(file.type)}
                          </div>
                        )}
                      </div>

                      {/* File info */}
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                          {file.name}
                        </p>
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          {formatFileSize(file.size)} • {new Date(file.uploadedAt).toLocaleTimeString('es-AR', {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </p>
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center space-x-2 ml-2">
                      <button
                        onClick={() => handleDownload(file.path, file.name)}
                        className="p-1.5 text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 rounded hover:bg-gray-100 dark:hover:bg-gray-700"
                        title="Descargar"
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                          />
                        </svg>
                      </button>
                      {file.uploadedBy === userId && (
                        <button
                          onClick={() => handleDelete(file.path)}
                          className="p-1.5 text-gray-400 hover:text-red-600 dark:hover:text-red-400 rounded hover:bg-gray-100 dark:hover:bg-gray-700"
                          title="Eliminar"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                            />
                          </svg>
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {files.length === 0 && !uploading && (
            <div className="px-4 pb-4 text-center">
              <p className="text-sm text-gray-500 dark:text-gray-400">
                No hay archivos compartidos aún
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * SessionChat Component
 * Componente de chat en tiempo real para sesiones de videoconsulta
 */

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useSessionChat } from '../../hooks/useSessionChat';
import type { SenderRole } from '../../lib/sessionChat';
import { logger } from '@autamedica/shared';

export interface SessionChatProps {
  sessionId: string;
  userId: string;
  userRole: SenderRole;
  className?: string;
}

export function SessionChat({ sessionId, userId, userRole, className = '' }: SessionChatProps) {
  const {
    messages,
    unreadCount,
    isTyping,
    loading,
    error,
    sendMessage,
    deleteMessage,
    markAsRead,
    setTyping,
  } = useSessionChat({
    sessionId,
    userId,
    userRole,
    autoMarkAsRead: true,
    enableTypingIndicators: true,
  });

  const [inputMessage, setInputMessage] = useState('');
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Handle send message
  const handleSend = async () => {
    if (!inputMessage.trim() || isSending) return;

    try {
      setIsSending(true);
      await sendMessage(inputMessage.trim());
      setInputMessage('');
      inputRef.current?.focus();
    } catch (err) {
      logger.error('Failed to send message:', err);
    } finally {
      setIsSending(false);
    }
  };

  // Handle typing indicator
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputMessage(e.target.value);

    // Send typing indicator
    if (e.target.value.length > 0) {
      setTyping(true);
    } else {
      setTyping(false);
    }
  };

  // Handle Enter key
  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Format timestamp
  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('es-AR', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  // Check if someone is typing (excluding self)
  const someoneIsTyping = Object.entries(isTyping).some(
    ([typingUserId, typing]) => typing && typingUserId !== userId
  );

  return (
    <div className={`flex flex-col h-full bg-white dark:bg-gray-800 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center space-x-2">
          <svg
            className="w-5 h-5 text-blue-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
            />
          </svg>
          <h3 className="text-sm font-semibold text-gray-900 dark:text-gray-100">
            Chat de Consulta
          </h3>
        </div>
        {unreadCount > 0 && (
          <span className="px-2 py-1 text-xs font-medium text-white bg-red-500 rounded-full">
            {unreadCount}
          </span>
        )}
      </div>

      {/* Messages container */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {loading && (
          <div className="flex items-center justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
          </div>
        )}

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-3">
            <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
          </div>
        )}

        {!loading && messages.length === 0 && (
          <div className="text-center py-8">
            <p className="text-sm text-gray-500 dark:text-gray-400">
              No hay mensajes aún. Envía el primero!
            </p>
          </div>
        )}

        {messages.map((message) => {
          const isOwn = message.sender_id === userId;
          const isSystem = message.message_type === 'system';

          if (isSystem) {
            return (
              <div key={message.id} className="flex justify-center">
                <span className="text-xs text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-700 px-3 py-1 rounded-full">
                  {message.message}
                </span>
              </div>
            );
          }

          return (
            <div
              key={message.id}
              className={`flex ${isOwn ? 'justify-end' : 'justify-start'}`}
            >
              <div className={`max-w-[75%] ${isOwn ? 'items-end' : 'items-start'}`}>
                {/* Sender role badge */}
                {!isOwn && (
                  <span className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">
                    {message.sender_role === 'doctor' ? 'Dr.' : 'Paciente'}
                  </span>
                )}

                {/* Message bubble */}
                <div
                  className={`rounded-lg px-4 py-2 ${
                    isOwn
                      ? 'bg-blue-500 text-white'
                      : 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-gray-100'
                  }`}
                >
                  {/* File attachment */}
                  {message.file_url && (
                    <div className="mb-2">
                      {message.message_type === 'image' ? (
                        <img
                          src={message.file_url}
                          alt={message.file_name || 'Imagen'}
                          className="max-w-full rounded"
                        />
                      ) : (
                        <a
                          href={message.file_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center space-x-2 text-sm underline"
                        >
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                            <path
                              fillRule="evenodd"
                              d="M8 4a3 3 0 00-3 3v4a5 5 0 0010 0V7a1 1 0 112 0v4a7 7 0 11-14 0V7a5 5 0 0110 0v4a3 3 0 11-6 0V7a1 1 0 012 0v4a1 1 0 102 0V7a3 3 0 00-3-3z"
                              clipRule="evenodd"
                            />
                          </svg>
                          <span>{message.file_name}</span>
                        </a>
                      )}
                    </div>
                  )}

                  {/* Message text */}
                  <p className="text-sm whitespace-pre-wrap break-words">{message.message}</p>

                  {/* Timestamp and read status */}
                  <div className="flex items-center justify-end space-x-1 mt-1">
                    <span
                      className={`text-xs ${
                        isOwn ? 'text-blue-100' : 'text-gray-500 dark:text-gray-400'
                      }`}
                    >
                      {formatTime(message.created_at)}
                    </span>
                    {isOwn && (
                      <span className="text-xs text-blue-100">
                        {message.read ? '✓✓' : '✓'}
                      </span>
                    )}
                  </div>
                </div>

                {/* Delete button for own messages */}
                {isOwn && (
                  <button
                    onClick={() => deleteMessage(message.id)}
                    className="text-xs text-gray-500 hover:text-red-500 mt-1"
                  >
                    Eliminar
                  </button>
                )}
              </div>
            </div>
          );
        })}

        {/* Typing indicator */}
        {someoneIsTyping && (
          <div className="flex justify-start">
            <div className="bg-gray-100 dark:bg-gray-700 rounded-lg px-4 py-2">
              <div className="flex space-x-1">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-100"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-200"></div>
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input area */}
      <div className="border-t border-gray-200 dark:border-gray-700 p-4">
        <div className="flex items-end space-x-2">
          <input
            ref={inputRef}
            type="text"
            value={inputMessage}
            onChange={handleInputChange}
            onKeyPress={handleKeyPress}
            placeholder="Escribe un mensaje..."
            disabled={isSending}
            className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
          />
          <button
            onClick={handleSend}
            disabled={!inputMessage.trim() || isSending}
            className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {isSending ? (
              <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Waiting Room Component
 * Virtual waiting room with media device testing
 *
 * @module WaitingRoom
 */

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { logger } from '@autamedica/shared';

export interface WaitingRoomProps {
  sessionId: string;
  userId: string;
  userRole: 'patient' | 'doctor';
  onReady: () => void;
  estimatedWaitTime?: number; // minutes
  className?: string;
}

type DeviceTestStatus = 'untested' | 'testing' | 'success' | 'failed';

export function WaitingRoom({
  sessionId,
  userId,
  userRole,
  onReady,
  estimatedWaitTime = 5,
  className = '',
}: WaitingRoomProps) {
  const [cameraStatus, setCameraStatus] = useState<DeviceTestStatus>('untested');
  const [micStatus, setMicStatus] = useState<DeviceTestStatus>('untested');
  const [speakerStatus, setSpeakerStatus] = useState<DeviceTestStatus>('untested');
  const [isReady, setIsReady] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [audioLevel, setAudioLevel] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);

  // Test camera
  const testCamera = useCallback(async () => {
    try {
      setCameraStatus('testing');

      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 },
        },
        audio: false,
      });

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }

      setStream(mediaStream);
      setCameraStatus('success');
    } catch (error) {
      logger.error('Camera test failed:', error);
      setCameraStatus('failed');
    }
  }, []);

  // Test microphone
  const testMicrophone = useCallback(async () => {
    try {
      setMicStatus('testing');

      const audioStream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
        video: false,
      });

      // Setup audio analysis
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      const microphone = audioContext.createMediaStreamSource(audioStream);

      analyser.fftSize = 256;
      microphone.connect(analyser);

      audioContextRef.current = audioContext;
      analyserRef.current = analyser;

      // Start analyzing audio level
      const dataArray = new Uint8Array(analyser.frequencyBinCount);
      const checkAudioLevel = () => {
        analyser.getByteFrequencyData(dataArray);
        const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
        setAudioLevel(average);
        requestAnimationFrame(checkAudioLevel);
      };
      checkAudioLevel();

      // Combine with existing stream
      if (stream) {
        audioStream.getAudioTracks().forEach((track) => {
          stream.addTrack(track);
        });
      } else {
        setStream(audioStream);
      }

      setMicStatus('success');
    } catch (error) {
      logger.error('Microphone test failed:', error);
      setMicStatus('failed');
    }
  }, [stream]);

  // Test speaker (play test sound)
  const testSpeaker = useCallback(async () => {
    try {
      setSpeakerStatus('testing');

      const audio = new Audio('/sounds/test-tone.mp3'); // You'll need to add this file
      await audio.play();

      // Wait for audio to finish
      await new Promise((resolve) => {
        audio.onended = resolve;
        setTimeout(resolve, 2000); // Fallback timeout
      });

      setSpeakerStatus('success');
    } catch (error) {
      logger.error('Speaker test failed:', error);
      // Assume success if autoplay blocked (common in browsers)
      setSpeakerStatus('success');
    }
  }, []);

  // Run all tests
  const runAllTests = useCallback(async () => {
    await testCamera();
    await testMicrophone();
    await testSpeaker();
  }, [testCamera, testMicrophone, testSpeaker]);

  // Check if ready
  useEffect(() => {
    const ready =
      cameraStatus === 'success' &&
      micStatus === 'success' &&
      speakerStatus === 'success';

    setIsReady(ready);
  }, [cameraStatus, micStatus, speakerStatus]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach((track) => track.stop());
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, [stream]);

  const allTestsPassed = cameraStatus === 'success' && micStatus === 'success' && speakerStatus === 'success';
  const anyTestFailed = cameraStatus === 'failed' || micStatus === 'failed' || speakerStatus === 'failed';

  return (
    <div className={`mx-auto max-w-4xl space-y-6 p-6 ${className}`}>
      {/* Header */}
      <div className="text-center">
        <h1 className="mb-2 text-2xl font-bold text-gray-900">Sala de Espera Virtual</h1>
        <p className="text-gray-600">
          Prepárate para tu consulta médica verificando tu cámara y micrófono
        </p>
        {estimatedWaitTime > 0 && (
          <p className="mt-2 text-sm text-gray-500">
            ⏱️ Tiempo estimado de espera: {estimatedWaitTime} {estimatedWaitTime === 1 ? 'minuto' : 'minutos'}
          </p>
        )}
      </div>

      {/* Video Preview */}
      <div className="relative overflow-hidden rounded-lg bg-gray-900 shadow-xl">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          className="aspect-video w-full object-cover"
        />

        {cameraStatus === 'untested' && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-800 bg-opacity-90">
            <div className="text-center">
              <span className="mb-3 block text-6xl">📹</span>
              <p className="text-white">Tu cámara aparecerá aquí</p>
            </div>
          </div>
        )}

        {cameraStatus === 'testing' && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-800 bg-opacity-90">
            <div className="text-center">
              <div className="mb-3 inline-block h-12 w-12 animate-spin rounded-full border-4 border-white border-t-transparent"></div>
              <p className="text-white">Activando cámara...</p>
            </div>
          </div>
        )}

        {cameraStatus === 'failed' && (
          <div className="absolute inset-0 flex items-center justify-center bg-red-900 bg-opacity-90">
            <div className="text-center">
              <span className="mb-3 block text-6xl">❌</span>
              <p className="text-white font-semibold">Error al acceder a la cámara</p>
              <p className="text-sm text-white/80">Verifica los permisos del navegador</p>
            </div>
          </div>
        )}

        {/* Audio Level Indicator */}
        {micStatus === 'success' && (
          <div className="absolute bottom-4 left-4 right-4">
            <div className="rounded-lg bg-black bg-opacity-50 p-3">
              <p className="mb-2 text-xs font-medium text-white">Nivel de Micrófono</p>
              <div className="h-2 overflow-hidden rounded-full bg-gray-700">
                <div
                  className="h-full bg-green-500 transition-all duration-100"
                  style={{ width: `${Math.min((audioLevel / 128) * 100, 100)}%` }}
                />
              </div>
              <p className="mt-1 text-xs text-white/70">
                {audioLevel > 20 ? '🎤 Detectando audio' : '🔇 Silencio'}
              </p>
            </div>
          </div>
        )}
      </div>

      {/* Device Tests */}
      <div className="space-y-3">
        <h2 className="text-lg font-semibold text-gray-900">Verificación de Dispositivos</h2>

        {/* Camera Test */}
        <div className="flex items-center justify-between rounded-lg border border-gray-300 bg-white p-4">
          <div className="flex items-center gap-3">
            <div className={`flex h-10 w-10 items-center justify-center rounded-full ${
              cameraStatus === 'success' ? 'bg-green-100' :
              cameraStatus === 'failed' ? 'bg-red-100' : 'bg-gray-100'
            }`}>
              {cameraStatus === 'success' && <span className="text-xl">✓</span>}
              {cameraStatus === 'failed' && <span className="text-xl">✗</span>}
              {cameraStatus === 'testing' && <div className="h-5 w-5 animate-spin rounded-full border-2 border-gray-400 border-t-transparent"></div>}
              {cameraStatus === 'untested' && <span className="text-xl">📹</span>}
            </div>
            <div>
              <p className="font-medium text-gray-900">Cámara</p>
              <p className="text-sm text-gray-600">
                {cameraStatus === 'success' && 'Funcionando correctamente'}
                {cameraStatus === 'failed' && 'Error al acceder'}
                {cameraStatus === 'testing' && 'Probando...'}
                {cameraStatus === 'untested' && 'No verificada'}
              </p>
            </div>
          </div>

          {cameraStatus === 'untested' && (
            <button
              onClick={testCamera}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
            >
              Probar
            </button>
          )}
        </div>

        {/* Microphone Test */}
        <div className="flex items-center justify-between rounded-lg border border-gray-300 bg-white p-4">
          <div className="flex items-center gap-3">
            <div className={`flex h-10 w-10 items-center justify-center rounded-full ${
              micStatus === 'success' ? 'bg-green-100' :
              micStatus === 'failed' ? 'bg-red-100' : 'bg-gray-100'
            }`}>
              {micStatus === 'success' && <span className="text-xl">✓</span>}
              {micStatus === 'failed' && <span className="text-xl">✗</span>}
              {micStatus === 'testing' && <div className="h-5 w-5 animate-spin rounded-full border-2 border-gray-400 border-t-transparent"></div>}
              {micStatus === 'untested' && <span className="text-xl">🎤</span>}
            </div>
            <div>
              <p className="font-medium text-gray-900">Micrófono</p>
              <p className="text-sm text-gray-600">
                {micStatus === 'success' && 'Funcionando correctamente'}
                {micStatus === 'failed' && 'Error al acceder'}
                {micStatus === 'testing' && 'Probando...'}
                {micStatus === 'untested' && 'No verificado'}
              </p>
            </div>
          </div>

          {micStatus === 'untested' && (
            <button
              onClick={testMicrophone}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
            >
              Probar
            </button>
          )}
        </div>

        {/* Speaker Test */}
        <div className="flex items-center justify-between rounded-lg border border-gray-300 bg-white p-4">
          <div className="flex items-center gap-3">
            <div className={`flex h-10 w-10 items-center justify-center rounded-full ${
              speakerStatus === 'success' ? 'bg-green-100' :
              speakerStatus === 'failed' ? 'bg-red-100' : 'bg-gray-100'
            }`}>
              {speakerStatus === 'success' && <span className="text-xl">✓</span>}
              {speakerStatus === 'failed' && <span className="text-xl">✗</span>}
              {speakerStatus === 'testing' && <div className="h-5 w-5 animate-spin rounded-full border-2 border-gray-400 border-t-transparent"></div>}
              {speakerStatus === 'untested' && <span className="text-xl">🔊</span>}
            </div>
            <div>
              <p className="font-medium text-gray-900">Altavoces</p>
              <p className="text-sm text-gray-600">
                {speakerStatus === 'success' && 'Funcionando correctamente'}
                {speakerStatus === 'failed' && 'Error de reproducción'}
                {speakerStatus === 'testing' && 'Reproduciendo tono de prueba...'}
                {speakerStatus === 'untested' && 'No verificados'}
              </p>
            </div>
          </div>

          {speakerStatus === 'untested' && (
            <button
              onClick={testSpeaker}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
            >
              Probar
            </button>
          )}
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-3">
        <button
          onClick={runAllTests}
          disabled={cameraStatus === 'testing' || micStatus === 'testing' || speakerStatus === 'testing'}
          className="flex-1 rounded-lg border border-gray-300 px-6 py-3 font-medium text-gray-700 transition-colors hover:bg-gray-50 disabled:opacity-50"
        >
          {allTestsPassed ? 'Volver a Probar' : 'Probar Todo'}
        </button>

        <button
          onClick={onReady}
          disabled={!isReady}
          className="flex-1 rounded-lg bg-green-600 px-6 py-3 font-medium text-white transition-colors hover:bg-green-700 disabled:bg-gray-300 disabled:cursor-not-allowed"
        >
          {isReady ? '✓ Entrar a la Consulta' : 'Completa las Pruebas'}
        </button>
      </div>

      {/* Help Text */}
      {anyTestFailed && (
        <div className="rounded-lg border border-yellow-300 bg-yellow-50 p-4">
          <p className="mb-2 font-semibold text-yellow-800">Problemas con los dispositivos?</p>
          <ul className="ml-4 list-disc space-y-1 text-sm text-yellow-700">
            <li>Verifica que el navegador tenga permisos para cámara y micrófono</li>
            <li>Asegúrate de que ningún otro programa esté usando los dispositivos</li>
            <li>Prueba recargar la página</li>
            <li>Si persiste el problema, contacta con soporte técnico</li>
          </ul>
        </div>
      )}
    </div>
  );
}

/**
 * Connection Monitor Hook (Integrated)
 * Combines quality monitoring with automatic reporting to Supabase
 *
 * @module useConnectionMonitor
 */

import { useEffect, useCallback, useRef } from 'react';
import {
  useConnectionQuality,
  type UseConnectionQualityOptions,
  type ConnectionQuality,
  type ConnectionStats,
} from './useConnectionQuality';
import { reportConnectionQuality } from '@/lib/telemedicine';
import { logger } from '@autamedica/shared';

export interface UseConnectionMonitorOptions extends UseConnectionQualityOptions {
  participantId: string | null;
  reportInterval?: number; // ms, default 5000 (5 seconds)
  enableAutoReport?: boolean; // default true
}

export interface UseConnectionMonitorReturn {
  stats: ConnectionStats | null;
  isMonitoring: boolean;
  startMonitoring: () => void;
  stopMonitoring: () => void;
}

/**
 * Hook: Monitor connection quality and auto-report to Supabase
 */
export function useConnectionMonitor(options: UseConnectionMonitorOptions): UseConnectionMonitorReturn {
  const {
    participantId,
    reportInterval = 5000,
    enableAutoReport = true,
    ...qualityOptions
  } = options;

  const reportTimerRef = useRef<NodeJS.Timeout | null>(null);
  const lastReportedStatsRef = useRef<ConnectionStats | null>(null);

  // Report stats to Supabase
  const reportStats = useCallback(
    async (stats: ConnectionStats) => {
      if (!participantId || !enableAutoReport) return;
      if (stats.quality === 'disconnected') return; // Don't report disconnected state

      try {
        await reportConnectionQuality(participantId, {
          bitrate: stats.bitrate,
          latency: stats.latency,
          packetLoss: stats.packetLoss,
          quality: stats.quality,
        });

        lastReportedStatsRef.current = stats;
      } catch (error) {
        logger.error('Failed to report connection quality:', error);
      }
    },
    [participantId, enableAutoReport]
  );

  // On quality change callback
  const handleQualityChange = useCallback(
    (quality: ConnectionQuality) => {
      logger.info(`[ConnectionMonitor] Quality changed to: ${quality}`);

      // Immediately report significant quality changes
      if (quality === 'poor' || quality === 'disconnected') {
        const currentStats = lastReportedStatsRef.current;
        if (currentStats && participantId) {
          reportStats(currentStats);
        }
      }
    },
    [participantId, reportStats]
  );

  // On stats update callback
  const handleStatsUpdate = useCallback(
    (stats: ConnectionStats) => {
      // Stats updated - will be reported on interval
    },
    []
  );

  // Use the base connection quality hook
  const {
    stats,
    isMonitoring,
    startMonitoring: startQualityMonitoring,
    stopMonitoring: stopQualityMonitoring,
  } = useConnectionQuality({
    ...qualityOptions,
    onQualityChange: handleQualityChange,
    onStatsUpdate: handleStatsUpdate,
  });

  // Setup periodic reporting
  useEffect(() => {
    if (!isMonitoring || !enableAutoReport || !participantId) {
      return;
    }

    // Initial report
    if (stats) {
      reportStats(stats);
    }

    // Setup interval
    reportTimerRef.current = setInterval(() => {
      if (stats) {
        reportStats(stats);
      }
    }, reportInterval);

    return () => {
      if (reportTimerRef.current) {
        clearInterval(reportTimerRef.current);
        reportTimerRef.current = null;
      }
    };
  }, [isMonitoring, stats, reportInterval, enableAutoReport, participantId, reportStats]);

  const startMonitoring = useCallback(() => {
    startQualityMonitoring();
  }, [startQualityMonitoring]);

  const stopMonitoring = useCallback(() => {
    stopQualityMonitoring();

    // Clear report timer
    if (reportTimerRef.current) {
      clearInterval(reportTimerRef.current);
      reportTimerRef.current = null;
    }

    // Final report before stopping
    if (stats && participantId && enableAutoReport) {
      reportStats(stats);
    }
  }, [stopQualityMonitoring, stats, participantId, enableAutoReport, reportStats]);

  return {
    stats,
    isMonitoring,
    startMonitoring,
    stopMonitoring,
  };
}

/**
 * Connection Quality Monitoring Hook
 * Monitors WebRTC connection stats: bitrate, latency, packet loss, jitter
 *
 * @module useConnectionQuality
 */

import { useEffect, useState, useCallback, useRef } from 'react';
import { logger } from '@autamedica/shared';

/**
 * Connection Quality Levels
 */
export type ConnectionQuality = 'excellent' | 'good' | 'fair' | 'poor' | 'disconnected';

/**
 * Connection Statistics
 */
export interface ConnectionStats {
  bitrate: number; // kbps
  latency: number; // ms
  packetLoss: number; // percentage
  jitter: number; // ms
  quality: ConnectionQuality;
  timestamp: number;
}

/**
 * Detailed Statistics for Advanced Monitoring
 */
export interface DetailedStats {
  video: {
    sent: {
      bitrate: number;
      fps: number;
      resolution: string;
      packetsLost: number;
      totalPackets: number;
    };
    received: {
      bitrate: number;
      fps: number;
      resolution: string;
      packetsLost: number;
      totalPackets: number;
    };
  };
  audio: {
    sent: {
      bitrate: number;
      packetsLost: number;
      totalPackets: number;
    };
    received: {
      bitrate: number;
      packetsLost: number;
      totalPackets: number;
    };
  };
  connection: {
    currentRoundTripTime: number;
    availableOutgoingBitrate: number;
    state: RTCPeerConnectionState;
  };
}

/**
 * Hook Options
 */
export interface UseConnectionQualityOptions {
  peerConnection: RTCPeerConnection | null;
  interval?: number; // ms, default 1000
  onQualityChange?: (quality: ConnectionQuality) => void;
  onStatsUpdate?: (stats: ConnectionStats) => void;
}

/**
 * Hook Return Type
 */
export interface UseConnectionQualityReturn {
  stats: ConnectionStats | null;
  detailedStats: DetailedStats | null;
  isMonitoring: boolean;
  startMonitoring: () => void;
  stopMonitoring: () => void;
}

/**
 * Calculate connection quality based on stats
 */
function calculateQuality(stats: {
  bitrate: number;
  latency: number;
  packetLoss: number;
  jitter: number;
}): ConnectionQuality {
  const { bitrate, latency, packetLoss, jitter } = stats;

  // Disconnected if no bitrate
  if (bitrate === 0) {
    return 'disconnected';
  }

  // Poor quality conditions
  if (
    latency > 300 ||
    packetLoss > 5 ||
    jitter > 50 ||
    bitrate < 100
  ) {
    return 'poor';
  }

  // Fair quality conditions
  if (
    latency > 150 ||
    packetLoss > 2 ||
    jitter > 30 ||
    bitrate < 300
  ) {
    return 'fair';
  }

  // Good quality conditions
  if (
    latency > 80 ||
    packetLoss > 0.5 ||
    jitter > 15 ||
    bitrate < 500
  ) {
    return 'good';
  }

  // Excellent quality
  return 'excellent';
}

/**
 * Parse RTCStats to extract connection metrics
 */
async function parseStats(pc: RTCPeerConnection): Promise<{
  basic: ConnectionStats;
  detailed: DetailedStats;
}> {
  const stats = await pc.getStats();

  let bitrate = 0;
  let latency = 0;
  let packetLoss = 0;
  let jitter = 0;

  const videoSent = { bitrate: 0, fps: 0, resolution: '', packetsLost: 0, totalPackets: 0 };
  const videoReceived = { bitrate: 0, fps: 0, resolution: '', packetsLost: 0, totalPackets: 0 };
  const audioSent = { bitrate: 0, packetsLost: 0, totalPackets: 0 };
  const audioReceived = { bitrate: 0, packetsLost: 0, totalPackets: 0 };
  const connection = {
    currentRoundTripTime: 0,
    availableOutgoingBitrate: 0,
    state: pc.connectionState,
  };

  let bitrateCount = 0;
  let latencyCount = 0;

  stats.forEach((report) => {
    // Outbound RTP (sent)
    if (report.type === 'outbound-rtp') {
      if (report.kind === 'video' && report.bytesSent) {
        const kbps = (report.bytesSent * 8) / 1000;
        videoSent.bitrate = kbps;
        videoSent.fps = report.framesPerSecond || 0;
        videoSent.resolution = `${report.frameWidth || 0}x${report.frameHeight || 0}`;
        videoSent.packetsLost = report.packetsLost || 0;
        videoSent.totalPackets = report.packetsSent || 0;
        bitrate += kbps;
        bitrateCount++;
      }
      if (report.kind === 'audio' && report.bytesSent) {
        const kbps = (report.bytesSent * 8) / 1000;
        audioSent.bitrate = kbps;
        audioSent.packetsLost = report.packetsLost || 0;
        audioSent.totalPackets = report.packetsSent || 0;
        bitrate += kbps;
        bitrateCount++;
      }
    }

    // Inbound RTP (received)
    if (report.type === 'inbound-rtp') {
      if (report.kind === 'video' && report.bytesReceived) {
        const kbps = (report.bytesReceived * 8) / 1000;
        videoReceived.bitrate = kbps;
        videoReceived.fps = report.framesPerSecond || 0;
        videoReceived.resolution = `${report.frameWidth || 0}x${report.frameHeight || 0}`;
        videoReceived.packetsLost = report.packetsLost || 0;
        videoReceived.totalPackets = report.packetsReceived || 0;
        bitrate += kbps;
        bitrateCount++;

        // Jitter (video)
        if (report.jitter) {
          jitter = Math.max(jitter, report.jitter * 1000);
        }

        // Packet loss (video)
        if (report.packetsLost && report.packetsReceived) {
          const lossPercentage = (report.packetsLost / (report.packetsLost + report.packetsReceived)) * 100;
          packetLoss = Math.max(packetLoss, lossPercentage);
        }
      }

      if (report.kind === 'audio' && report.bytesReceived) {
        const kbps = (report.bytesReceived * 8) / 1000;
        audioReceived.bitrate = kbps;
        audioReceived.packetsLost = report.packetsLost || 0;
        audioReceived.totalPackets = report.packetsReceived || 0;
        bitrate += kbps;
        bitrateCount++;

        // Jitter (audio)
        if (report.jitter) {
          jitter = Math.max(jitter, report.jitter * 1000);
        }

        // Packet loss (audio)
        if (report.packetsLost && report.packetsReceived) {
          const lossPercentage = (report.packetsLost / (report.packetsLost + report.packetsReceived)) * 100;
          packetLoss = Math.max(packetLoss, lossPercentage);
        }
      }
    }

    // Candidate pair (for RTT)
    if (report.type === 'candidate-pair' && report.state === 'succeeded') {
      if (report.currentRoundTripTime) {
        latency = report.currentRoundTripTime * 1000; // Convert to ms
        connection.currentRoundTripTime = latency;
        latencyCount++;
      }
      if (report.availableOutgoingBitrate) {
        connection.availableOutgoingBitrate = report.availableOutgoingBitrate / 1000; // kbps
      }
    }
  });

  // Average bitrate
  if (bitrateCount > 0) {
    bitrate = bitrate / bitrateCount;
  }

  const quality = calculateQuality({ bitrate, latency, packetLoss, jitter });

  return {
    basic: {
      bitrate,
      latency,
      packetLoss,
      jitter,
      quality,
      timestamp: Date.now(),
    },
    detailed: {
      video: {
        sent: videoSent,
        received: videoReceived,
      },
      audio: {
        sent: audioSent,
        received: audioReceived,
      },
      connection,
    },
  };
}

/**
 * Hook: Monitor WebRTC connection quality
 */
export function useConnectionQuality(options: UseConnectionQualityOptions): UseConnectionQualityReturn {
  const {
    peerConnection,
    interval = 1000,
    onQualityChange,
    onStatsUpdate,
  } = options;

  const [stats, setStats] = useState<ConnectionStats | null>(null);
  const [detailedStats, setDetailedStats] = useState<DetailedStats | null>(null);
  const [isMonitoring, setIsMonitoring] = useState(false);

  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const previousQualityRef = useRef<ConnectionQuality | null>(null);

  const collectStats = useCallback(async () => {
    if (!peerConnection) return;

    try {
      const { basic, detailed } = await parseStats(peerConnection);

      setStats(basic);
      setDetailedStats(detailed);

      // Trigger callbacks
      onStatsUpdate?.(basic);

      if (previousQualityRef.current !== basic.quality) {
        onQualityChange?.(basic.quality);
        previousQualityRef.current = basic.quality;
      }
    } catch (error) {
      logger.error('Failed to collect WebRTC stats:', error);
    }
  }, [peerConnection, onStatsUpdate, onQualityChange]);

  const startMonitoring = useCallback(() => {
    if (isMonitoring || !peerConnection) return;

    setIsMonitoring(true);
    collectStats(); // Initial collection

    intervalRef.current = setInterval(() => {
      collectStats();
    }, interval);
  }, [peerConnection, interval, collectStats, isMonitoring]);

  const stopMonitoring = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setIsMonitoring(false);
  }, []);

  // Auto-start monitoring when peerConnection becomes available
  useEffect(() => {
    if (peerConnection && peerConnection.connectionState === 'connected') {
      startMonitoring();
    }

    return () => {
      stopMonitoring();
    };
  }, [peerConnection, startMonitoring, stopMonitoring]);

  return {
    stats,
    detailedStats,
    isMonitoring,
    startMonitoring,
    stopMonitoring,
  };
}

/**
 * Reconnection Hook
 * Automatic reconnection for WebRTC connections
 *
 * @module useReconnection
 */

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { logger } from '@autamedica/shared';

export type ConnectionState =
  | 'connected'
  | 'disconnected'
  | 'reconnecting'
  | 'failed';

export interface ReconnectionConfig {
  /** Maximum number of reconnection attempts */
  maxAttempts?: number;
  /** Initial delay in ms (doubles each attempt) */
  initialDelay?: number;
  /** Maximum delay between attempts in ms */
  maxDelay?: number;
  /** Enable ICE restart on reconnection */
  enableIceRestart?: boolean;
  /** Callback when reconnection starts */
  onReconnectStart?: () => void;
  /** Callback when reconnection succeeds */
  onReconnectSuccess?: () => void;
  /** Callback when reconnection fails */
  onReconnectFailed?: (attempts: number) => void;
  /** Custom reconnection logic */
  reconnectFn?: () => Promise<void>;
}

export interface UseReconnectionOptions {
  /** WebRTC peer connection to monitor */
  peerConnection: RTCPeerConnection | null;
  /** Socket.io or WebSocket connection to monitor */
  signaling: any;
  /** Configuration options */
  config?: ReconnectionConfig;
  /** Enable automatic reconnection */
  enabled?: boolean;
}

export interface UseReconnectionReturn {
  /** Current connection state */
  state: ConnectionState;
  /** Number of reconnection attempts */
  attempts: number;
  /** Whether reconnection is in progress */
  isReconnecting: boolean;
  /** Manually trigger reconnection */
  reconnect: () => Promise<void>;
  /** Reset reconnection state */
  reset: () => void;
  /** Next retry delay in seconds */
  nextRetryIn: number;
}

/**
 * Calculate exponential backoff delay
 */
function calculateBackoff(
  attempt: number,
  initialDelay: number,
  maxDelay: number
): number {
  const delay = initialDelay * Math.pow(2, attempt);
  return Math.min(delay, maxDelay);
}

/**
 * Hook for automatic WebRTC reconnection
 */
export function useReconnection(
  options: UseReconnectionOptions
): UseReconnectionReturn {
  const {
    peerConnection,
    signaling,
    config = {},
    enabled = true,
  } = options;

  const {
    maxAttempts = 10,
    initialDelay = 1000,
    maxDelay = 30000,
    enableIceRestart = true,
    onReconnectStart,
    onReconnectSuccess,
    onReconnectFailed,
    reconnectFn,
  } = config;

  const [state, setState] = useState<ConnectionState>('connected');
  const [attempts, setAttempts] = useState(0);
  const [nextRetryIn, setNextRetryIn] = useState(0);

  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const countdownIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const isReconnectingRef = useRef(false);

  /**
   * Clear all timers
   */
  const clearTimers = useCallback(() => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }
    if (countdownIntervalRef.current) {
      clearInterval(countdownIntervalRef.current);
      countdownIntervalRef.current = null;
    }
    setNextRetryIn(0);
  }, []);

  /**
   * Reset reconnection state
   */
  const reset = useCallback(() => {
    clearTimers();
    setAttempts(0);
    setState('connected');
    isReconnectingRef.current = false;
  }, [clearTimers]);

  /**
   * Perform reconnection
   */
  const performReconnection = useCallback(async () => {
    if (!peerConnection || !signaling) {
      logger.warn('[Reconnection] Missing peer connection or signaling');
      return;
    }

    try {
      // Use custom reconnect function if provided
      if (reconnectFn) {
        await reconnectFn();
      } else {
        // Default: ICE restart
        if (enableIceRestart && peerConnection.restartIce) {
          logger.info('[Reconnection] Performing ICE restart');
          peerConnection.restartIce();
        }

        // Renegotiate connection
        if (peerConnection.createOffer) {
          const offer = await peerConnection.createOffer({ iceRestart: enableIceRestart });
          await peerConnection.setLocalDescription(offer);

          // Send offer through signaling
          if (signaling.emit) {
            signaling.emit('offer', { sdp: offer });
          }
        }
      }

      logger.info('[Reconnection] Reconnection successful');
      setState('connected');
      reset();
      onReconnectSuccess?.();
    } catch (error) {
      logger.error('[Reconnection] Reconnection failed:', error);
      throw error;
    }
  }, [peerConnection, signaling, enableIceRestart, reconnectFn, reset, onReconnectSuccess]);

  /**
   * Attempt reconnection with backoff
   */
  const attemptReconnection = useCallback(
    async (attemptNumber: number) => {
      if (attemptNumber >= maxAttempts) {
        logger.error('[Reconnection] Max attempts reached');
        setState('failed');
        isReconnectingRef.current = false;
        onReconnectFailed?.(attemptNumber);
        return;
      }

      const delay = calculateBackoff(attemptNumber, initialDelay, maxDelay);
      const delaySeconds = Math.ceil(delay / 1000);

      logger.info(
        `[Reconnection] Attempt ${attemptNumber + 1}/${maxAttempts} in ${delaySeconds}s`
      );

      setState('reconnecting');
      setAttempts(attemptNumber + 1);
      setNextRetryIn(delaySeconds);

      // Start countdown
      let remaining = delaySeconds;
      countdownIntervalRef.current = setInterval(() => {
        remaining--;
        setNextRetryIn(remaining);
        if (remaining <= 0 && countdownIntervalRef.current) {
          clearInterval(countdownIntervalRef.current);
        }
      }, 1000);

      // Schedule reconnection attempt
      reconnectTimeoutRef.current = setTimeout(async () => {
        try {
          await performReconnection();
        } catch (error) {
          // Retry on next attempt
          attemptReconnection(attemptNumber + 1);
        }
      }, delay);
    },
    [maxAttempts, initialDelay, maxDelay, performReconnection, onReconnectFailed]
  );

  /**
   * Manually trigger reconnection
   */
  const reconnect = useCallback(async () => {
    if (isReconnectingRef.current) {
      logger.warn('[Reconnection] Already reconnecting');
      return;
    }

    isReconnectingRef.current = true;
    clearTimers();
    onReconnectStart?.();

    try {
      await performReconnection();
    } catch (error) {
      // Start retry loop
      attemptReconnection(0);
    }
  }, [clearTimers, performReconnection, attemptReconnection, onReconnectStart]);

  /**
   * Monitor peer connection state
   */
  useEffect(() => {
    if (!enabled || !peerConnection) return;

    const handleConnectionStateChange = () => {
      const connectionState = peerConnection.connectionState;
      logger.info('[Reconnection] Connection state:', connectionState);

      switch (connectionState) {
        case 'connected':
          if (state !== 'connected') {
            reset();
          }
          break;

        case 'disconnected':
        case 'failed':
          if (state === 'connected' && !isReconnectingRef.current) {
            logger.warn('[Reconnection] Connection lost, starting reconnection');
            setState('disconnected');
            reconnect();
          }
          break;

        case 'closed':
          setState('failed');
          clearTimers();
          break;
      }
    };

    const handleIceConnectionStateChange = () => {
      const iceState = peerConnection.iceConnectionState;
      logger.info('[Reconnection] ICE state:', iceState);

      if (iceState === 'failed' && state === 'connected' && !isReconnectingRef.current) {
        logger.warn('[Reconnection] ICE failed, starting reconnection');
        setState('disconnected');
        reconnect();
      }
    };

    peerConnection.addEventListener('connectionstatechange', handleConnectionStateChange);
    peerConnection.addEventListener('iceconnectionstatechange', handleIceConnectionStateChange);

    return () => {
      peerConnection.removeEventListener('connectionstatechange', handleConnectionStateChange);
      peerConnection.removeEventListener('iceconnectionstatechange', handleIceConnectionStateChange);
    };
  }, [enabled, peerConnection, state, reconnect, reset, clearTimers]);

  /**
   * Monitor signaling connection
   */
  useEffect(() => {
    if (!enabled || !signaling) return;

    const handleDisconnect = () => {
      logger.warn('[Reconnection] Signaling disconnected');
      if (state === 'connected' && !isReconnectingRef.current) {
        setState('disconnected');
        reconnect();
      }
    };

    const handleReconnect = () => {
      logger.info('[Reconnection] Signaling reconnected');
      if (state !== 'connected') {
        reconnect();
      }
    };

    // Socket.io events
    if (signaling.on) {
      signaling.on('disconnect', handleDisconnect);
      signaling.on('reconnect', handleReconnect);
    }

    return () => {
      if (signaling.off) {
        signaling.off('disconnect', handleDisconnect);
        signaling.off('reconnect', handleReconnect);
      }
    };
  }, [enabled, signaling, state, reconnect]);

  /**
   * Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      clearTimers();
    };
  }, [clearTimers]);

  return {
    state,
    attempts,
    isReconnecting: isReconnectingRef.current || state === 'reconnecting',
    reconnect,
    reset,
    nextRetryIn,
  };
}

/**
 * Notification Service
 * Push notifications for telemedicine events
 *
 * @module notifications
 */

import { getSupabaseClient } from './supabaseClient';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { logger } from '@autamedica/shared';

/**
 * Notification types
 */
export type NotificationType =
  | 'incoming_call'
  | 'call_missed'
  | 'call_ended'
  | 'session_starting'
  | 'message_received'
  | 'recording_started';

/**
 * Notification status
 */
export type NotificationStatus = 'pending' | 'sent' | 'delivered' | 'read' | 'failed';

/**
 * Notification priority
 */
export type NotificationPriority = 'low' | 'normal' | 'high' | 'urgent';

/**
 * Call notification
 */
export interface CallNotification {
  id: string;
  user_id: string;
  type: NotificationType;
  session_id?: string;
  title: string;
  body: string;
  action_url?: string;
  metadata: Record<string, any>;
  status: NotificationStatus;
  push_subscription?: PushSubscriptionJSON;
  priority: NotificationPriority;
  expires_at?: string;
  created_at: string;
}

/**
 * Send notification
 */
export async function sendNotification(params: {
  userId: string;
  type: NotificationType;
  title: string;
  body: string;
  sessionId?: string;
  actionUrl?: string;
  metadata?: Record<string, any>;
  priority?: NotificationPriority;
  expiresIn?: number; // minutes
}): Promise<CallNotification> {
  const supabase = getSupabaseClient();

  const expiresAt = params.expiresIn
    ? new Date(Date.now() + params.expiresIn * 60 * 1000).toISOString()
    : undefined;

  const { data, error } = await supabase
    .from('call_notifications')
    .insert({
      user_id: params.userId,
      type: params.type,
      session_id: params.sessionId,
      title: params.title,
      body: params.body,
      action_url: params.actionUrl,
      metadata: params.metadata || {},
      priority: params.priority || 'normal',
      expires_at: expiresAt,
      status: 'pending',
    })
    .select()
    .single();

  if (error) {
    throw new Error(`Failed to send notification: ${error.message}`);
  }

  return data as CallNotification;
}

