    .select('*')
    .eq('session_id', sessionId)
    .ilike('message', `%${searchTerm}%`)
    .is('deleted_at', null)
    .order('created_at', { ascending: false });

  if (error) {
    throw new Error(`Failed to search messages: ${error.message}`);
  }

  return data as ChatMessage[];
}

/**
 * Subscribe to new messages in real-time
 */
export function subscribeToSessionChat(
  sessionId: string,
  callbacks: {
    onNewMessage?: (message: ChatMessage) => void;
    onMessageUpdate?: (message: ChatMessage) => void;
    onMessageDelete?: (messageId: string) => void;
  }
): RealtimeChannel {
  const supabase = getSupabaseClient();
  const channel = supabase.channel(`session-chat-${sessionId}`);

  // Subscribe to new messages
  if (callbacks.onNewMessage) {
    channel.on(
      'postgres_changes',
      {
        event: 'INSERT',
        schema: 'public',
        table: 'session_chat_messages',
        filter: `session_id=eq.${sessionId}`,
      },
      (payload) => {
        callbacks.onNewMessage?.(payload.new as ChatMessage);
      }
    );
  }

  // Subscribe to message updates (read status, metadata)
  if (callbacks.onMessageUpdate) {
    channel.on(
      'postgres_changes',
      {
        event: 'UPDATE',
        schema: 'public',
        table: 'session_chat_messages',
        filter: `session_id=eq.${sessionId}`,
      },
      (payload) => {
        callbacks.onMessageUpdate?.(payload.new as ChatMessage);
      }
    );
  }

  // Subscribe to message deletes
  if (callbacks.onMessageDelete) {
    channel.on(
      'postgres_changes',
      {
        event: 'UPDATE',
        schema: 'public',
        table: 'session_chat_messages',
        filter: `session_id=eq.${sessionId}`,
      },
      (payload) => {
        const message = payload.new as ChatMessage;
        if (message.deleted_at) {
          callbacks.onMessageDelete?.(message.id);
        }
      }
    );
  }

  channel.subscribe();

  return channel;
}

/**
 * Unsubscribe from chat updates
 */
export async function unsubscribeFromChat(channel: RealtimeChannel): Promise<void> {
  await channel.unsubscribe();
}

/**
 * Send typing indicator (ephemeral, not stored)
 */
export async function sendTypingIndicator(
  sessionId: string,
  userId: string,
  isTyping: boolean
): Promise<void> {
  const supabase = getSupabaseClient();
  const channel = supabase.channel(`session-chat-${sessionId}`);

  await channel.send({
    type: 'broadcast',
    event: 'typing',
    payload: {
      userId,
      isTyping,
      timestamp: new Date().toISOString(),
    },
  });
}

/**
 * Listen for typing indicators
 */
export function subscribeToTypingIndicators(
  sessionId: string,
  onTyping: (data: { userId: string; isTyping: boolean }) => void
): RealtimeChannel {
  const supabase = getSupabaseClient();
  const channel = supabase.channel(`session-chat-${sessionId}`);

  channel.on('broadcast', { event: 'typing' }, (payload) => {
    onTyping({
      userId: payload.payload.userId,
      isTyping: payload.payload.isTyping,
    });
  });

  channel.subscribe();

  return channel;
}

/**
 * Get message statistics for a session
 */
export async function getMessageStats(sessionId: string): Promise<{
  total: number;
  byType: Record<MessageType, number>;
  bySender: Record<string, number>;
}> {
  const supabase = getSupabaseClient();

  const { data, error } = await supabase
    .from('session_chat_messages')
    .select('message_type, sender_id')
    .eq('session_id', sessionId)
    .is('deleted_at', null);

  if (error) {
    throw new Error(`Failed to get message stats: ${error.message}`);
  }

  const stats = {
    total: data.length,
    byType: {} as Record<MessageType, number>,
    bySender: {} as Record<string, number>,
  };

  data.forEach((msg) => {
    // Count by type
    stats.byType[msg.message_type as MessageType] =
      (stats.byType[msg.message_type as MessageType] || 0) + 1;

    // Count by sender
    stats.bySender[msg.sender_id] = (stats.bySender[msg.sender_id] || 0) + 1;
  });

  return stats;
}

/**
 * Export chat history
 */
export async function exportChatHistory(sessionId: string): Promise<string> {
  const messages = await getSessionMessages(sessionId);

  const chatHistory = messages.map((msg) => ({
    timestamp: msg.created_at,
    sender: msg.sender_role,
    message: msg.message,
    type: msg.message_type,
  }));

  return JSON.stringify(chatHistory, null, 2);
}

/**
 * Session File Management
 * Sistema de compartir archivos durante sesiones de videoconsulta
 *
 * @module sessionFiles
 */

import { getSupabaseClient } from './supabaseClient';

/**
 * File upload result
 */
export interface FileUploadResult {
  path: string;
  url: string;
  fullPath: string;
}

/**
 * File metadata
 */
export interface SessionFile {
  name: string;
  path: string;
  size: number;
  type: string;
  url: string;
  uploadedAt: string;
  uploadedBy: string;
}

/**
 * Allowed file types for medical documents
 */
export const ALLOWED_FILE_TYPES = {
  images: ['image/jpeg', 'image/png', 'image/gif', 'image/webp'],
  documents: [
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain',
    'text/csv',
  ],
};

export const ALL_ALLOWED_TYPES = [
  ...ALLOWED_FILE_TYPES.images,
  ...ALLOWED_FILE_TYPES.documents,
];

/**
 * Maximum file size (50MB)
 */
export const MAX_FILE_SIZE = 50 * 1024 * 1024;

/**
 * Validate file before upload
 */
export function validateFile(file: File): { valid: boolean; error?: string } {
  // Check file size
  if (file.size > MAX_FILE_SIZE) {
    return {
      valid: false,
      error: `El archivo excede el tamaño máximo de ${MAX_FILE_SIZE / 1024 / 1024}MB`,
    };
  }

  // Check file type
  if (!ALL_ALLOWED_TYPES.includes(file.type)) {
    return {
      valid: false,
      error: 'Tipo de archivo no permitido. Solo se aceptan imágenes y documentos médicos.',
    };
  }

  return { valid: true };
}

/**
 * Generate file path for storage
 */
export function generateFilePath(
  userId: string,
  sessionId: string,
  fileName: string
): string {
  const timestamp = Date.now();
  const sanitizedFileName = fileName.replace(/[^a-zA-Z0-9.-]/g, '_');
  return `${userId}/${sessionId}/${timestamp}-${sanitizedFileName}`;
}

/**
 * Upload file to storage
 */
export async function uploadSessionFile(
  file: File,
  userId: string,
  sessionId: string,
  onProgress?: (progress: number) => void
): Promise<FileUploadResult> {
  const supabase = getSupabaseClient();

  // Validate file
  const validation = validateFile(file);
  if (!validation.valid) {
    throw new Error(validation.error);
  }

  // Generate unique file path
  const filePath = generateFilePath(userId, sessionId, file.name);

  // Upload file
  const { data, error } = await supabase.storage
    .from('telemedicine-files')
    .upload(filePath, file, {
      cacheControl: '3600',
      upsert: false,
    });

  if (error) {
    throw new Error(`Error al subir archivo: ${error.message}`);
  }

  // Get public URL
  const { data: urlData } = supabase.storage
    .from('telemedicine-files')
    .getPublicUrl(data.path);

  return {
    path: data.path,
    url: urlData.publicUrl,
    fullPath: data.fullPath || data.path,
  };
}

/**
 * Upload multiple files
 */
export async function uploadMultipleFiles(
  files: File[],
  userId: string,
  sessionId: string,
  onProgress?: (fileIndex: number, progress: number) => void
): Promise<FileUploadResult[]> {
  const results: FileUploadResult[] = [];

  for (let i = 0; i < files.length; i++) {
    const result = await uploadSessionFile(
      files[i],
      userId,
      sessionId,
      (progress) => onProgress?.(i, progress)
    );
    results.push(result);
  }

  return results;
}

/**
 * Delete a file from storage
 */
export async function deleteSessionFile(filePath: string): Promise<void> {
  const supabase = getSupabaseClient();

  const { error } = await supabase.storage
    .from('telemedicine-files')
    .remove([filePath]);

  if (error) {
    throw new Error(`Error al eliminar archivo: ${error.message}`);
  }
}

/**
 * List all files in a session
 */
export async function listSessionFiles(
  userId: string,
  sessionId: string
): Promise<SessionFile[]> {
  const supabase = getSupabaseClient();

  const folderPath = `${userId}/${sessionId}`;

  const { data, error } = await supabase.storage
    .from('telemedicine-files')
    .list(folderPath, {
      limit: 100,
      offset: 0,
      sortBy: { column: 'created_at', order: 'desc' },
    });

  if (error) {
    throw new Error(`Error al listar archivos: ${error.message}`);
  }

  // Convert to SessionFile format
  const files: SessionFile[] = data.map((file) => {
    const filePath = `${folderPath}/${file.name}`;
    const { data: urlData } = supabase.storage
      .from('telemedicine-files')
      .getPublicUrl(filePath);

    return {
      name: file.name,
      path: filePath,
      size: file.metadata?.size || 0,
      type: file.metadata?.mimetype || 'application/octet-stream',
      url: urlData.publicUrl,
      uploadedAt: file.created_at || new Date().toISOString(),
      uploadedBy: userId,
    };
  });

  return files;
}

/**
 * Download a file
 */
export async function downloadSessionFile(filePath: string): Promise<Blob> {
  const supabase = getSupabaseClient();

  const { data, error } = await supabase.storage
    .from('telemedicine-files')
    .download(filePath);

  if (error) {
    throw new Error(`Error al descargar archivo: ${error.message}`);
  }

  return data;
}

/**
 * Get file URL (signed URL for private files)
 */
export async function getFileUrl(
  filePath: string,
  expiresIn: number = 3600
): Promise<string> {
  const supabase = getSupabaseClient();

  const { data, error } = await supabase.storage
    .from('telemedicine-files')
