/**
 * Subscribe to session real-time updates
 */
export function subscribeToSession(
  sessionId: string,
  callbacks: {
    onSessionUpdate?: (session: TelemedicineSession) => void;
    onParticipantUpdate?: (participant: SessionParticipant) => void;
    onEventLogged?: (event: SessionEvent) => void;
  }
): RealtimeChannel {
  const supabase = getSupabaseClient();
  const channel = supabase.channel(`session-${sessionId}`);

  // Subscribe to session updates
  if (callbacks.onSessionUpdate) {
    channel.on(
      'postgres_changes',
      {
        event: 'UPDATE',
        schema: 'public',
        table: 'telemedicine_sessions',
        filter: `id=eq.${sessionId}`,
      },
      (payload) => {
        callbacks.onSessionUpdate?.(payload.new as TelemedicineSession);
      }
    );
  }

  // Subscribe to participant updates
  if (callbacks.onParticipantUpdate) {
    channel.on(
      'postgres_changes',
      {
        event: '*',
        schema: 'public',
        table: 'session_participants',
        filter: `session_id=eq.${sessionId}`,
      },
      (payload) => {
        callbacks.onParticipantUpdate?.(payload.new as SessionParticipant);
      }
    );
  }

  // Subscribe to new events
  if (callbacks.onEventLogged) {
    channel.on(
      'postgres_changes',
      {
        event: 'INSERT',
        schema: 'public',
        table: 'session_events',
        filter: `session_id=eq.${sessionId}`,
      },
      (payload) => {
        callbacks.onEventLogged?.(payload.new as SessionEvent);
      }
    );
  }

  channel.subscribe();

  return channel;
}

/**
 * Unsubscribe from session updates
 */
export async function unsubscribeFromSession(channel: RealtimeChannel): Promise<void> {
  await channel.unsubscribe();
}

/**
 * Helper: Generate unique room ID
 */
export function generateRoomId(): string {
  return `room-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Helper: Calculate session duration
 */
export function calculateSessionDuration(actualStart: string, actualEnd: string): number {
  const start = new Date(actualStart).getTime();
  const end = new Date(actualEnd).getTime();
  return Math.floor((end - start) / 1000); // seconds
}

/**
 * Report connection quality stats
 * Updates participant connection stats in real-time
 */
export async function reportConnectionQuality(
  participantId: string,
  stats: {
    bitrate: number;
    latency: number;
    packetLoss: number;
    quality: 'excellent' | 'good' | 'fair' | 'poor';
  }
): Promise<void> {
  const supabase = getSupabaseClient();

  const { error } = await supabase
    .from('session_participants')
    .update({
      connection_stats: {
        bitrate: Math.round(stats.bitrate),
        latency: Math.round(stats.latency),
        packet_loss: parseFloat(stats.packetLoss.toFixed(2)),
        quality: stats.quality,
      },
    })
    .eq('id', participantId);

  if (error) {
    logger.error('Failed to report connection quality:', error.message);
  }
}

/**
 * Get average connection quality for session
 * Analyzes all participants' stats to get session-level quality
 */
export async function getSessionConnectionQuality(
  sessionId: string
): Promise<{
  averageBitrate: number;
  averageLatency: number;
  averagePacketLoss: number;
  overallQuality: 'excellent' | 'good' | 'fair' | 'poor';
} | null> {
  const supabase = getSupabaseClient();

  const { data: participants, error } = await supabase
    .from('session_participants')
    .select('connection_stats')
    .eq('session_id', sessionId)
    .not('connection_stats', 'is', null);

  if (error || !participants || participants.length === 0) {
    return null;
  }

  let totalBitrate = 0;
  let totalLatency = 0;
  let totalPacketLoss = 0;
  let count = 0;

  const qualityScores: Record<string, number> = {
    excellent: 4,
    good: 3,
    fair: 2,
    poor: 1,
  };

  let totalQualityScore = 0;

  participants.forEach((p) => {
    if (p.connection_stats) {
      totalBitrate += p.connection_stats.bitrate || 0;
      totalLatency += p.connection_stats.latency || 0;
      totalPacketLoss += p.connection_stats.packet_loss || 0;
      totalQualityScore += qualityScores[p.connection_stats.quality] || 0;
      count++;
    }
  });

  if (count === 0) return null;

  const avgQualityScore = totalQualityScore / count;
  let overallQuality: 'excellent' | 'good' | 'fair' | 'poor' = 'poor';

  if (avgQualityScore >= 3.5) overallQuality = 'excellent';
  else if (avgQualityScore >= 2.5) overallQuality = 'good';
  else if (avgQualityScore >= 1.5) overallQuality = 'fair';

  return {
    averageBitrate: totalBitrate / count,
    averageLatency: totalLatency / count,
    averagePacketLoss: totalPacketLoss / count,
    overallQuality,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { validateSession, isSessionExpired, getSessionTimeRemaining } from '../session';

describe('Session Management', () => {
  describe('validateSession', () => {
    it('should validate active session', () => {
      const validSession = {
        user: { id: 'user-123', email: 'test@example.com' },
        expires_at: Date.now() + 3600000, // 1 hour from now
      };

      expect(validateSession(validSession)).toBe(true);
    });

    it('should reject expired session', () => {
      const expiredSession = {
        user: { id: 'user-123', email: 'test@example.com' },
        expires_at: Date.now() - 3600000, // 1 hour ago
      };

      expect(validateSession(expiredSession)).toBe(false);
    });

    it('should reject session without user', () => {
      const invalidSession = {
        user: null,
        expires_at: Date.now() + 3600000,
      };

      expect(validateSession(invalidSession as any)).toBe(false);
    });

    it('should reject session without expiration', () => {
      const invalidSession = {
        user: { id: 'user-123', email: 'test@example.com' },
        expires_at: null,
      };

      expect(validateSession(invalidSession as any)).toBe(false);
    });
  });

  describe('isSessionExpired', () => {
    it('should detect expired session', () => {
      const expiredTime = Date.now() - 1000;
      expect(isSessionExpired(expiredTime)).toBe(true);
    });

    it('should detect active session', () => {
      const activeTime = Date.now() + 3600000;
      expect(isSessionExpired(activeTime)).toBe(false);
    });

    it('should handle edge case of exactly now', () => {
      const now = Date.now();
      // Should be expired if equal to current time
      expect(isSessionExpired(now)).toBe(true);
    });
  });

  describe('getSessionTimeRemaining', () => {
    it('should calculate time remaining correctly', () => {
      const futureTime = Date.now() + 3600000; // 1 hour
      const remaining = getSessionTimeRemaining(futureTime);

      expect(remaining).toBeGreaterThan(3599000); // ~1 hour
      expect(remaining).toBeLessThanOrEqual(3600000);
    });

    it('should return 0 for expired session', () => {
      const pastTime = Date.now() - 1000;
      expect(getSessionTimeRemaining(pastTime)).toBe(0);
    });

    it('should return 0 for current time', () => {
      const now = Date.now();
      expect(getSessionTimeRemaining(now)).toBeLessThanOrEqual(1);
    });
  });
});

/**
 * @fileoverview Centralized Supabase client for browser environments
 */

import { createBrowserClient as createSupabaseBrowserClient } from '@supabase/ssr'
import { getSupabaseConfig, getSessionConfig, getDomainConfig } from '../utils/config'
import type { SupabaseClient } from '@supabase/supabase-js'

let supabaseClient: SupabaseClient | null = null

/**
 * Create or get the Supabase browser client
 * Singleton pattern to ensure only one client instance
 */
export function createBrowserClient(): SupabaseClient {
  // Return existing client if already created
  if (supabaseClient) {
    return supabaseClient
  }

  // Server-side protection
  if (typeof window === 'undefined') {
    throw new Error('createBrowserClient must only be called in browser environment')
  }

  const { url, anonKey } = getSupabaseConfig()
  const sessionConfig = getSessionConfig()
  const domainConfig = getDomainConfig()

  // Create the client with SSO cookie configuration
  supabaseClient = createSupabaseBrowserClient(url, anonKey, {
    cookies: {
      get(name: string) {
        // Use js-cookie for better cross-domain support
        if (typeof window !== 'undefined') {
          const cookies = document.cookie.split('; ')
          const cookie = cookies.find(c => c.startsWith(`${name}=`))
          return cookie ? decodeURIComponent(cookie.split('=')[1] || '') : undefined
        }
        return undefined
      },
      set(name: string, value: string, options: any) {
        if (typeof window !== 'undefined') {
          // Set cookie with domain for SSO
          const cookieOptions = [
            `${name}=${encodeURIComponent(value)}`,
            `path=/`,
            `domain=${domainConfig.cookie}`,
            `max-age=${options.maxAge || sessionConfig.maxAge}`,
            `SameSite=Lax`,
            // Add Secure flag for production (HTTPS)
            process.env.NODE_ENV === 'production' ? `Secure` : '',
          ].filter(Boolean) // Remove empty strings

          document.cookie = cookieOptions.join('; ')
        }
      },
      remove(name: string) {
        if (typeof window !== 'undefined') {
          // Remove cookie from all possible domains
          const domains = [
            domainConfig.cookie,
            `.${domainConfig.base}`,
            domainConfig.base,
            'localhost'
          ]

          domains.forEach(domain => {
            document.cookie = `${name}=; path=/; domain=${domain}; expires=Thu, 01 Jan 1970 00:00:00 GMT`
          })
        }
      }
    },
    auth: {
      autoRefreshToken: true,
      persistSession: true,
      detectSessionInUrl: true,
      flowType: 'pkce', // Use PKCE flow for better security
      storage: {
        // Use localStorage with fallback to sessionStorage
        getItem: (key: string) => {
          if (typeof window !== 'undefined') {
            try {
              return window.localStorage.getItem(key)
            } catch {
              return window.sessionStorage.getItem(key)
            }
          }
          return null
        },
        setItem: (key: string, value: string) => {
          if (typeof window !== 'undefined') {
            try {
              window.localStorage.setItem(key, value)
            } catch {
              window.sessionStorage.setItem(key, value)
            }
          }
        },
        removeItem: (key: string) => {
          if (typeof window !== 'undefined') {
            try {
              window.localStorage.removeItem(key)
            } catch {
              window.sessionStorage.removeItem(key)
            }
          }
        }
      }
    }
  }) as unknown as SupabaseClient

  return supabaseClient!
}

/**
 * Get the existing Supabase client or create a new one
 */
export function getSupabaseClient(): SupabaseClient {
  if (!supabaseClient) {
    return createBrowserClient()
  }
  return supabaseClient
}

/**
 * Sign out and clear all sessions across apps
 */
export async function signOutGlobally(): Promise<void> {
  const client = getSupabaseClient()
  const domainConfig = getDomainConfig()

  // Sign out from Supabase
  await client.auth.signOut()

  // Clear all auth-related cookies
  const authCookies = [
    'autamedica_session',
    'sb-access-token',
    'sb-refresh-token',
    'sb-auth-token'
  ]

  authCookies.forEach(cookieName => {
    // Clear from all possible domains
    const domains = [
      domainConfig.cookie,
      `.${domainConfig.base}`,
      domainConfig.base,
      'localhost'
    ]

    domains.forEach(domain => {
      document.cookie = `${cookieName}=; path=/; domain=${domain}; expires=Thu, 01 Jan 1970 00:00:00 GMT`
    })
  })

  // Clear localStorage
  if (typeof window !== 'undefined') {
    const keysToRemove = Object.keys(localStorage).filter(key =>
      key.includes('supabase') || key.includes('autamedica')
    )
    keysToRemove.forEach(key => localStorage.removeItem(key))
  }
}

/**
 * @fileoverview React hooks and context for authentication
 */

'use client'

import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useMemo
} from 'react'
import { User } from '@supabase/supabase-js'
import {
  AuthState,
  UserProfile,
  UserRole,
  AuthError
} from '../types'
import { isUserRole, ROLES } from '../roles'
import {
  getSupabaseClient,
  signOutGlobally
} from '../client/supabase'
import {
  getRedirectUrl,
  storeLastPath,
  getLastPath,
  clearLastPath
} from '../utils/redirect'
import logger from '../utils/logger'

/**
 * Authentication context
 */
interface AuthContextValue extends AuthState {
  signIn: (email: string, password: string) => Promise<void>
  signInWithMagicLink: (email: string) => Promise<void>
  signInWithOAuth: (provider: 'google') => Promise<void>
  signOut: () => Promise<void>
  refreshSession: () => Promise<void>
  redirectToRole: (returnUrl?: string) => void
  updateLastPath: (path: string) => void
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined)

/**
 * Extract user profile from Supabase user
 */
function normalizeRole(role: unknown): UserRole | null {
  if (typeof role === 'string') {
    if (role === ROLES.COMPANY_ADMIN) {
      return ROLES.ORGANIZATION_ADMIN
    }

    if (isUserRole(role)) {
      return role
    }
  }

  logger.error('User does not have a role assigned')
  return null
}

function extractUserProfile(user: User): UserProfile | null {
  const role = normalizeRole(user.user_metadata?.role)

  if (!role) {
    return null
  }

  return {
    id: user.id,
    email: user.email!,
    role,
    first_name: user.user_metadata?.first_name,
    last_name: user.user_metadata?.last_name,
    company_name: user.user_metadata?.company_name,
    created_at: user.created_at,
    updated_at: user.updated_at || user.created_at,
    last_path: getLastPath(user.id) ?? '/dashboard'
  }
}

/**
 * Authentication provider props
 */
interface AuthProviderProps {
  children: React.ReactNode
  onAuthStateChange?: (state: AuthState) => void
}

/**
 * Check if dev bypass is enabled
 */
const isDevBypass = typeof window !== 'undefined' &&
  process.env.NEXT_PUBLIC_AUTH_DEV_BYPASS === 'true'

/**
 * Authentication provider component
 */
export function AuthProvider({
  children,
  onAuthStateChange
}: AuthProviderProps) {
  const [state, setState] = useState<AuthState>({
    user: null,
    profile: null,
    session: null,
    loading: true,
    error: null
  })
  const [isClient, setIsClient] = useState(false)

  // Initialize client safely after hydration
  useEffect(() => {
    setIsClient(true)
  }, [])

  // Initialize Supabase client only on client side and not in dev bypass
  const supabase = useMemo(() => {
    if (!isClient || isDevBypass) return null

    try {
      return getSupabaseClient()
    } catch (error) {
      logger.error('Failed to initialize Supabase client:', error)
      setState(prev => ({
        ...prev,
        error: error as Error,
        loading: false
      }))
      return null
    }
  }, [isClient])

  // Load initial session
  useEffect(() => {
    // Handle dev bypass mode
    if (isDevBypass && isClient) {
      const params = new URLSearchParams(window.location.search)
      const role = params.get('as') === 'patient' ? ROLES.PATIENT : ROLES.DOCTOR

      // Create mock user for dev mode
      const mockUser = {
        id: `dev-${role}-1`,
        email: `${role}@dev.local`,
        user_metadata: { role },
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      } as any

      const mockProfile: UserProfile = {
        id: mockUser.id,
        email: mockUser.email,
        role,
        first_name: 'Dev',
        last_name: role === ROLES.DOCTOR ? 'Doctor' : 'Patient',
        created_at: mockUser.created_at,
        updated_at: mockUser.updated_at,
        last_path: '/dashboard'
      }

      setState({
        user: mockUser,
        profile: mockProfile,
        session: { access_token: 'dev-token', user: mockUser } as any,
        loading: false,
        error: null
      })
      return
    }

    if (!supabase) return

    const loadSession = async () => {
      try {
        const { data: { session }, error } = await supabase.auth.getSession()

        if (error) throw error

        if (session) {
          const profile = extractUserProfile(session.user)
          setState({
            user: session.user,
            profile,
            session,
            loading: false,
            error: null
          })
        } else {
          setState({
            user: null,
            profile: null,
            session: null,
            loading: false,
            error: null
          })
        }
      } catch (error) {
        logger.error('Failed to load session:', error)
        setState({
          user: null,
          profile: null,
          session: null,
          loading: false,
          error: error as Error
        })
      }
    }

    loadSession()
  }, [supabase, isClient])

  // Listen for auth state changes
  useEffect(() => {
    if (!supabase || isDevBypass) return

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        logger.info('Auth state changed:', event)

        if (session) {
          const profile = extractUserProfile(session.user)
          const newState = {
            user: session.user,
            profile,
            session,
            loading: false,
            error: null
          }
          setState(newState)
          onAuthStateChange?.(newState)

          // Auto-redirect after successful sign in
          if (event === 'SIGNED_IN' && profile && typeof window !== 'undefined') {
            logger.info('Sign in successful, redirecting to role-specific app...')

            // Get redirect URL based on role
            const redirectUrl = getRedirectUrl(
              profile.role,
              undefined,
              profile.last_path
            )

            logger.info('Redirecting to:', redirectUrl)

            // Use setTimeout to ensure state is updated before redirect
            setTimeout(() => {
              window.location.href = redirectUrl
            }, 100)
          }
        } else {
          const newState = {
            user: null,
            profile: null,
            session: null,
            loading: false,
            error: null
          }
          setState(newState)
          onAuthStateChange?.(newState)
        }

        // Handle specific events
        if (event === 'SIGNED_OUT') {
          // Clear stored paths on sign out
          if (state.user) {
            clearLastPath(state.user.id)
          }
        }
      }
    )

    return () => subscription.unsubscribe()
  }, [supabase, onAuthStateChange, state.user])

  // Sign in with email and password
  const signIn = useCallback(async (email: string, password: string) => {
    if (isDevBypass) {
      logger.info('Dev bypass mode - skipping sign in')
      return
    }

    if (!supabase) {
      throw new AuthError('CONFIGURATION_ERROR', 'Supabase client not initialized')
    }

    setState(prev => ({ ...prev, loading: true, error: null }))

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password
      })

      if (error) throw error
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error as Error
      }))
      throw error
    }
  }, [supabase])

  // Sign in with magic link
  const signInWithMagicLink = useCallback(async (email: string) => {
    if (isDevBypass) {
      logger.info('Dev bypass mode - skipping magic link')
      return
    }

    if (!supabase) {
      throw new AuthError('CONFIGURATION_ERROR', 'Supabase client not initialized')
    }

    setState(prev => ({ ...prev, loading: true, error: null }))

    try {
      const { error } = await supabase.auth.signInWithOtp({
        email,
        options: {
          shouldCreateUser: false // Don't create new users
        }
      })

      if (error) throw error
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error as Error
      }))
      throw error
    }
  }, [supabase])

  // Sign out
  const signOut = useCallback(async () => {
    if (isDevBypass) {
      logger.info('Dev bypass mode - skipping sign out')
      setState({
        user: null,
        profile: null,
        session: null,
        loading: false,
        error: null
      })
      return
    }

    setState(prev => ({ ...prev, loading: true, error: null }))

    try {
      // Clear last path before signing out
      if (state.user) {
        clearLastPath(state.user.id)
      }

      await signOutGlobally()

      setState({
        user: null,
        profile: null,
        session: null,
        loading: false,
        error: null
      })
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error as Error
      }))
      throw error
    }
  }, [state.user])

  // Sign in with OAuth
  const signInWithOAuth = useCallback(async (provider: 'google') => {
    if (isDevBypass) {
      logger.info('Dev bypass mode - skipping OAuth sign in')
      return
    }

    if (!supabase) {
      throw new AuthError('CONFIGURATION_ERROR', 'Supabase client not initialized')
    }

    setState(prev => ({ ...prev, loading: true, error: null }))

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider,
        options: {
          redirectTo: window.location.origin + '/auth/callback'
        }
      })

      if (error) throw error
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error as Error
      }))
      throw error
    }
  }, [supabase])

  // Refresh session
  const refreshSession = useCallback(async () => {
    if (isDevBypass) {
      logger.info('Dev bypass mode - skipping refresh')
      return
    }

    if (!supabase) return

    try {
      const { data: { session }, error } = await supabase.auth.refreshSession()

      if (error) throw error

      if (session) {
        const profile = extractUserProfile(session.user)
        setState({
          user: session.user,
          profile,
          session,
          loading: false,
          error: null
        })
      }
    } catch (error) {
      logger.error('Failed to refresh session:', error)
      setState(prev => ({
        ...prev,
        error: error as Error
      }))
    }
  }, [supabase])

  // Redirect to user's role-appropriate app
  const redirectToRole = useCallback((returnUrl?: string) => {
    if (!state.profile) {
      logger.warn('Cannot redirect: no user profile')
      return
    }

    const redirectUrl = getRedirectUrl(
      state.profile.role,
      returnUrl,
      state.profile.last_path
    )

    if (typeof window !== 'undefined') {
      window.location.href = redirectUrl
    }
  }, [state.profile])

  // Update last visited path for the user
  const updateLastPath = useCallback((path: string) => {
    if (!state.user) return

    storeLastPath(state.user.id, path)

    // Update local state
    setState(prev => ({
      ...prev,
      profile: prev.profile ? {
        ...prev.profile,
        last_path: path
      } : null
    }))
  }, [state.user])

  const value: AuthContextValue = {
    ...state,
    signIn,
    signInWithMagicLink,
    signInWithOAuth,
    signOut,
    refreshSession,
    redirectToRole,
    updateLastPath
  }

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  )
}

/**
 * Hook to use authentication context
 */
export function useAuth() {
  const context = useContext(AuthContext)

  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider')
  }

  return context
}

/**
 * Hook to require authentication
 */
export function useRequireAuth(
  redirectUrl?: string
): AuthContextValue {
  const auth = useAuth()

  useEffect(() => {
    if (!auth.loading && !auth.user) {
      // Redirect to login if not authenticated
      const loginUrl = `/auth/login${redirectUrl ? `?returnUrl=${encodeURIComponent(redirectUrl)}` : ''}`
      window.location.href = loginUrl
    }
  }, [auth.loading, auth.user, redirectUrl])

  return auth
}

/**
 * Hook to require a specific role
 */
export function useRequireRole(
  allowedRoles: UserRole[],
  redirectUrl?: string
): AuthContextValue {
  const auth = useRequireAuth(redirectUrl)

  useEffect(() => {
    if (!auth.loading && auth.profile) {
      if (!allowedRoles.includes(auth.profile.role)) {
        // Redirect to correct app for user's role
        auth.redirectToRole()
      }
    }
  }, [auth, allowedRoles])

  return auth
}

/**
 * @fileoverview Authentication middleware for Next.js apps
 * Validates user sessions and enforces role-based access control
 */

import { NextRequest, NextResponse } from 'next/server'
import { createServerClient } from '@supabase/ssr'
import {
  UserRole,
  AppName,
  APP_ALLOWED_ROLES,
  AuthError,
  UserProfile
} from '../types'
import { isUserRole, ROLES } from '../roles'
import {
  getSupabaseConfig,
  getDomainConfig,
  getSessionConfig
} from '../utils/config'
import {
  getLoginUrl,
  isCorrectAppForRole,
  getCorrectAppUrl
} from '../utils/redirect'
import logger from '../utils/logger'

/**
 * Create Supabase server client for middleware
 */
function createMiddlewareClient(request: NextRequest) {
  const { url, anonKey } = getSupabaseConfig()
  const sessionConfig = getSessionConfig()
  const domainConfig = getDomainConfig()

  const supabaseResponse = NextResponse.next({
    request
  })

  const supabase = createServerClient(url, anonKey, {
    cookies: {
      get(name) {
        return request.cookies.get(name)?.value
      },
      set(name, value, options) {
        const cookieOptions = {
          ...options,
          domain: domainConfig.cookie,
          path: '/',
          sameSite: 'lax' as const,
          secure: true,
          maxAge: options.maxAge || sessionConfig.maxAge
        }
        request.cookies.set({ name, value, ...cookieOptions })
        supabaseResponse.cookies.set({ name, value, ...cookieOptions })
      },
      remove(name, options) {
        const removeOptions = {
          ...options,
          domain: domainConfig.cookie,
          path: '/',
          maxAge: 0
        }
        request.cookies.set({ name, value: '', ...removeOptions })
        supabaseResponse.cookies.set({ name, value: '', ...removeOptions })
      }
    }
  })

  return { supabase, response: supabaseResponse }
}

/**
 * Extract user profile from Supabase user
 */
function normalizeRole(role: unknown): UserRole {
  if (typeof role === 'string') {
    if (role === ROLES.COMPANY_ADMIN) {
      return ROLES.ORGANIZATION_ADMIN
    }

    if (isUserRole(role)) {
      return role
    }
  }

  return ROLES.PATIENT
}

function extractUserProfile(user: any): UserProfile {
  const role = normalizeRole(user.user_metadata?.role)

  if (!role) {
    throw new AuthError(
      'INVALID_ROLE',
      'User does not have a valid role assigned',
      403
    )
  }

  return {
    id: user.id,
    email: user.email!,
    role,
    first_name: user.user_metadata?.first_name,
    last_name: user.user_metadata?.last_name,
    company_name: user.user_metadata?.company_name,
    created_at: user.created_at,
    updated_at: user.updated_at || user.created_at
  }
}

/**
 * Determine the current app from the request
 */
function getCurrentApp(request: NextRequest): AppName {
  const host = request.headers.get('host') || ''

  if (host.includes('patients')) return 'patients'
  if (host.includes('doctors')) return 'doctors'
  if (host.includes('companies')) return 'companies'
  if (host.includes('admin')) return 'admin'

  // Check port for development
  if (host.includes('3003')) return 'patients'
  if (host.includes('3002')) return 'doctors'
  if (host.includes('3004')) return 'companies'
  if (host.includes('3005')) return 'admin'

  return 'web-app'
}

/**
 * Main authentication middleware
 */
export async function authMiddleware(
  request: NextRequest,
  options?: {
    requireAuth?: boolean
    allowedRoles?: UserRole[]
    publicPaths?: string[]
  }
) {
  const pathname = request.nextUrl.pathname
  const currentApp = getCurrentApp(request)

  // Check if path is public
  if (options?.publicPaths?.some(path => pathname.startsWith(path))) {
    return NextResponse.next()
  }

  // Create Supabase client
  const { supabase, response } = createMiddlewareClient(request)

  // Get session
  const { data: { session }, error } = await supabase.auth.getSession()

  // If auth is not required and no session, allow access
  if (!options?.requireAuth && !session) {
    return response
  }

  // If auth is required but no session, redirect to login
  if (options?.requireAuth && !session) {
    const loginUrl = getLoginUrl(request.url)
    return NextResponse.redirect(new URL(loginUrl))
  }

  // If we have a session, validate it
  if (session) {
    try {
      // Get user details
      const { data: { user }, error: userError } = await supabase.auth.getUser()

      if (userError || !user) {
        // Session is invalid, redirect to login
        const loginUrl = getLoginUrl(request.url)
        return NextResponse.redirect(new URL(loginUrl))
      }

      // Extract user profile
      const profile = extractUserProfile(user)

      // Check if user has access to current app
      const allowedRoles = options?.allowedRoles || APP_ALLOWED_ROLES[currentApp]

      if (!allowedRoles.includes(profile.role)) {
        // User doesn't have access to this app, redirect to their correct app
        const correctUrl = getCorrectAppUrl(profile.role, pathname)
        return NextResponse.redirect(new URL(correctUrl))
      }

      // Check if user is in the correct app for their role
      if (!isCorrectAppForRole(currentApp, profile.role)) {
        // Redirect to the correct app while preserving the path
        const correctUrl = getCorrectAppUrl(profile.role, pathname)
        return NextResponse.redirect(new URL(correctUrl))
      }

      // Add user info to headers for downstream use
      response.headers.set('x-user-id', profile.id)
      response.headers.set('x-user-role', profile.role)
      response.headers.set('x-user-email', profile.email)

      return response
    } catch (error) {
      logger.error('Auth middleware error:', error)

      // On error, redirect to login
      const loginUrl = getLoginUrl(request.url)
      return NextResponse.redirect(new URL(loginUrl))
    }
  }

  return response
}

/**
 * Create app-specific middleware with predefined options
 */
export function createAppMiddleware(appName: AppName) {
  const allowedRoles = APP_ALLOWED_ROLES[appName]

  return async (request: NextRequest) => {
    // Define public paths for each app
    const publicPaths: Record<AppName, string[]> = {
      'web-app': ['/auth', '/api/health', '/', '/terms', '/privacy'],
      'auth': ['/api/health', '/'],
      'patients': ['/api/health'],
      'doctors': ['/api/health'],
      'companies': ['/api/health'],
      'admin': ['/api/health']
    }

    return authMiddleware(request, {
      requireAuth: appName !== 'web-app', // Only web-app allows unauthenticated access
      allowedRoles,
      publicPaths: publicPaths[appName]
    })
  }
}

/**
 * Funciones de manejo de sesión
 *
 * Este módulo provee funciones para obtener, validar y manejar sesiones de usuario
 * con integración completa con los tipos de @autamedica/types.
 */

import { createServerClient } from "./server";
import { redirect } from "next/navigation";
import type { User, UserSession } from "@autamedica/types";
import { toISODateString } from "@autamedica/types";
import type { UserRole, Portal } from "./roles";
import { canAccessPortal, isUserRole, ROLES } from "./roles";
import { logger } from '@autamedica/shared';

const DEFAULT_PORTAL_REDIRECT: Record<UserRole, string> = {
  patient: "/patients",
  doctor: "/doctors",
  company: "/companies",
  company_admin: "/companies",
  organization_admin: "/admin",
  admin: "/admin",
  platform_admin: "/admin",
};

function normalizeRole(role: unknown): UserRole {
  if (typeof role === "string") {
    if (role === ROLES.COMPANY_ADMIN) {
      return ROLES.ORGANIZATION_ADMIN;
    }

    if (isUserRole(role)) {
      return role;
    }
  }

  return ROLES.PATIENT;
}

function getCentralAuthOrigin(): string {
  if (process.env.NEXT_PUBLIC_APP_URL) {
    return process.env.NEXT_PUBLIC_APP_URL;
  }

  return process.env.NODE_ENV === 'production'
    ? 'https://www.autamedica.com'
    : 'http://localhost:3000';
}

function buildCentralLoginUrl(returnTo?: string): string {
  const loginUrl = new URL('/auth/login', getCentralAuthOrigin());

  if (returnTo && !returnTo.startsWith('/auth/')) {
    loginUrl.searchParams.set('returnTo', returnTo);
  }

  return loginUrl.toString();
}

/**
 * Obtiene la sesión actual del usuario
 * @returns La sesión del usuario o null si no está autenticado
 */
export async function getSession(): Promise<UserSession | null> {
  try {
    const supabase = await createServerClient();
    const {
      data: { session },
      error,
    } = await supabase.auth.getSession();

    if (error || !session) {
      return null;
    }

    // Mapear la sesión de Supabase a nuestro tipo UserSession
    const userSession: UserSession = {
      user: {
        id: session.user.id,
        email: session.user.email!,
        emailVerified: !!session.user.email_confirmed_at,
        role: normalizeRole(session.user.user_metadata?.role),
        createdAt: toISODateString(new Date(session.user.created_at)),
        updatedAt: toISODateString(new Date(session.user.updated_at!)),
      },
      accessToken: session.access_token,
      refreshToken: session.refresh_token || "",
      expiresAt: toISODateString(new Date(session.expires_at! * 1000)),
    };

    return userSession;
  } catch (error) {
    logger.error("Error getting session:", error);
    return null;
  }
}

/**
 * Requiere una sesión válida, redirige al login si no está autenticado
 * @param redirectTo URL de redirección después del login (opcional)
 * @returns La sesión del usuario
 * @throws Redirect si no está autenticado
 */
export async function requireSession(
  redirectTo?: string
): Promise<UserSession> {
  const session = await getSession();

  if (!session) {
    redirect(buildCentralLoginUrl(redirectTo));
  }

  return session!;
}

/**
 * Requiere acceso a un portal específico
 * @param portal Portal requerido
 * @param redirectTo URL de redirección después del login (opcional)
 * @returns La sesión del usuario si tiene acceso
 * @throws Redirect si no tiene acceso o no está autenticado
 */
export async function requirePortalAccess(
  portal: Portal,
  redirectTo?: string
): Promise<UserSession> {
  const session = await requireSession(redirectTo);

  if (!canAccessPortal(session.user.role, portal)) {
    // Redirigir al portal apropiado según el rol del usuario
    redirect(DEFAULT_PORTAL_REDIRECT[session.user.role] || "/");
  }

  return session;
}

/**
 * Cierra la sesión del usuario
 */
export async function signOut() {
  try {
    const supabase = await createServerClient();
    const { error } = await supabase.auth.signOut();

    if (error) {
      logger.error("Error signing out:", error);
      throw new Error("Error cerrando sesión");
    }

    redirect("/");
  } catch (error) {
    logger.error("Error in signOut:", error);
    throw error;
  }
}

/**
 * Obtiene solo el usuario actual sin la información completa de sesión
 * @returns El usuario actual o null si no está autenticado
 */
export async function getCurrentUser(): Promise<User | null> {
  const session = await getSession();
  return session?.user || null;
}

/**
 * Verifica si el usuario actual tiene un rol específico
 * @param role Rol a verificar
 * @returns true si el usuario tiene el rol especificado
 */
export async function hasRole(role: UserRole): Promise<boolean> {
  const user = await getCurrentUser();
  return user?.role === role;
}

/**
 * Verifica si el usuario actual puede acceder a un portal
 * @param portal Portal a verificar
 * @returns true si el usuario puede acceder al portal
 */
export async function hasPortalAccess(portal: Portal): Promise<boolean> {
  const user = await getCurrentUser();
  return user ? canAccessPortal(user.role, portal) : false;
}

/**
 * @fileoverview Cloudflare Workers KV-based SSO implementation
 * Uses Cloudflare KV for shared session storage across subdomains
 */

import type { UserProfile, UserRole } from '../types'
import logger from './logger'

/**
 * Basic KV interface for Cloudflare Workers
 */
interface KVNamespace {
  get(key: string, options?: { type?: 'text' | 'json' | 'arrayBuffer' | 'stream' }): Promise<any>
  put(key: string, value: string | ArrayBuffer | ReadableStream, options?: { expirationTtl?: number }): Promise<void>
  delete(key: string): Promise<void>
  list(options?: { prefix?: string; limit?: number; cursor?: string }): Promise<{ keys: Array<{ name: string }> }>
}

/**
 * Cloudflare KV namespace bindings (injected by Cloudflare)
 */
declare global {
  const AUTH_SESSIONS: KVNamespace
  const USER_PROFILES: KVNamespace
}

/**
 * Session data stored in KV
 */
interface KVSession {
  userId: string
  email: string
  role: UserRole
  profile: UserProfile
  expiresAt: number
  createdAt: number
  lastActivity: number
}

/**
 * Generate a session key for KV storage
 */
function getSessionKey(sessionId: string): string {
  return `session:${sessionId}`
}

/**
 * Generate a user key for KV storage
 */
function getUserKey(userId: string): string {
  return `user:${userId}`
}

/**
 * Create a new session in Cloudflare KV
 * This enables SSO across all .pages.dev subdomains
 */
export async function createKVSession(
  sessionId: string,
  userId: string,
  profile: UserProfile,
  ttl: number = 86400 // 24 hours default
): Promise<void> {
  if (typeof AUTH_SESSIONS === 'undefined') {
    logger.warn('AUTH_SESSIONS KV namespace not available')
    return
  }

  const now = Date.now()
  const session: KVSession = {
    userId,
    email: profile.email,
    role: profile.role,
    profile,
    expiresAt: now + (ttl * 1000),
    createdAt: now,
    lastActivity: now
  }

  // Store session with TTL
  await AUTH_SESSIONS.put(
    getSessionKey(sessionId),
    JSON.stringify(session),
    { expirationTtl: ttl }
  )

  // Also store user profile for quick lookup
  await USER_PROFILES.put(
    getUserKey(userId),
    JSON.stringify(profile),
    { expirationTtl: ttl }
  )
}

/**
 * Get session from Cloudflare KV
 */
export async function getKVSession(sessionId: string): Promise<KVSession | null> {
  if (typeof AUTH_SESSIONS === 'undefined') {
    logger.warn('AUTH_SESSIONS KV namespace not available')
    return null
  }

  try {
    const sessionData = await AUTH_SESSIONS.get(getSessionKey(sessionId))
    if (!sessionData) return null

    const session = JSON.parse(sessionData) as KVSession

    // Check if session is expired
    if (session.expiresAt < Date.now()) {
      await deleteKVSession(sessionId)
      return null
    }

    // Update last activity
    session.lastActivity = Date.now()
    await AUTH_SESSIONS.put(
      getSessionKey(sessionId),
      JSON.stringify(session),
      { expirationTtl: Math.floor((session.expiresAt - Date.now()) / 1000) }
    )

    return session
  } catch (error) {
    logger.error('Error getting KV session:', error)
    return null
  }
}

/**
 * Delete session from Cloudflare KV
 */
export async function deleteKVSession(sessionId: string): Promise<void> {
  if (typeof AUTH_SESSIONS === 'undefined') {
    logger.warn('AUTH_SESSIONS KV namespace not available')
    return
  }

  const session = await getKVSession(sessionId)
  if (session) {
    // Delete session
    await AUTH_SESSIONS.delete(getSessionKey(sessionId))

    // Delete user profile
    await USER_PROFILES.delete(getUserKey(session.userId))
  }
}

/**
 * Validate session and get user profile
 */
export async function validateKVSession(sessionId: string): Promise<UserProfile | null> {
  const session = await getKVSession(sessionId)
  return session?.profile || null
}

/**
 * Refresh session TTL
 */
export async function refreshKVSession(
  sessionId: string,
  additionalTtl: number = 3600 // Add 1 hour by default
): Promise<boolean> {
  const session = await getKVSession(sessionId)
  if (!session) return false

  session.expiresAt = Date.now() + (additionalTtl * 1000)

  await AUTH_SESSIONS.put(
    getSessionKey(sessionId),
    JSON.stringify(session),
    { expirationTtl: additionalTtl }
  )

  return true
}

/**
 * Get all active sessions for a user (for security/audit)
 */
export async function getUserSessions(userId: string): Promise<string[]> {
  if (typeof AUTH_SESSIONS === 'undefined') {
    logger.warn('AUTH_SESSIONS KV namespace not available')
    return []
  }

  // This would require listing keys which is expensive in KV
  // In production, you'd want to maintain a separate index
  logger.warn('getUserSessions not fully implemented - requires KV list operation')
  return []
}

/**
 * Create a session cookie that works across .pages.dev subdomains
 */
export function createSSOCookie(sessionId: string, ttl: number = 86400): string {
  const expires = new Date(Date.now() + ttl * 1000).toUTCString()

  // Cookie that works across all .pages.dev subdomains
  return [
    `autamedica_session=${sessionId}`,
    `Domain=.pages.dev`,
    `Path=/`,
    `Expires=${expires}`,
    `HttpOnly`,
    `Secure`,
    `SameSite=Lax`
  ].join('; ')
}

/**
 * Parse session ID from cookie header
 */
export function parseSessionFromCookie(cookieHeader: string | null): string | null {
  if (!cookieHeader) return null

  const cookies = cookieHeader.split(';').reduce((acc, cookie) => {
    const [key, value] = cookie.trim().split('=')
    if (key && value) {
      acc[key] = value
    }
    return acc
  }, {} as Record<string, string>)

  return cookies['autamedica_session'] || null
}

