"use client";

import { useState, useEffect, useCallback } from "react";
import type { Patient, Appointment } from "@autamedica/types";
import { logger } from '@autamedica/shared';

/**
 * Hook para obtener pacientes del doctor actual
 * Requiere cliente de Supabase con sesión activa
 */
export function usePatients(supabaseClient?: any) {
  const [patients, setPatients] = useState<Patient[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchPatients = useCallback(async () => {
    if (!supabaseClient) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);

      // Obtener pacientes activos (sin soft delete)
      const { data, error: fetchError } = await supabaseClient
        .from('patients')
        .select('*')
        .is('deleted_at', null)
        .eq('active', true)
        .order('created_at', { ascending: false });

      if (fetchError) throw fetchError;

      setPatients(data || []);
    } catch (err) {
      logger.error('Error fetching patients:', err);
      setError(err instanceof Error ? err.message : 'Error al cargar pacientes');
    } finally {
      setLoading(false);
    }
  }, [supabaseClient]);

  useEffect(() => {
    fetchPatients();
  }, [fetchPatients]);

  return {
    patients,
    loading,
    error,
    refetch: fetchPatients
  };
}

