/**
 * Boundary Transformation Utilities
 *
 * Sistema híbrido de naming convention para AutaMedica:
 * - BD/Contratos/DAL: snake_case (fiel al esquema Supabase)
 * - UI/Componentes/Forms: camelCase (ergonómico en React/TS)
 * - Transformación solo en boundaries (entrada/salida de UI)
 *
 * REGLA ORO: Todo lo que toque BD/RLS/SQL = snake_case
 *            Todo lo que pinte en pantalla = camelCase
 *
 * @example
 * ```ts
 * // Desde BD → UI
 * const dbData = { patient_id: '123', start_time: '2025-01-01' };
 * const uiData = toCamel(dbData); // { patientId: '123', startTime: '2025-01-01' }
 *
 * // Desde UI → BD
 * const formData = { patientId: '123', startTime: '2025-01-01' };
 * const dbPayload = toSnake(formData); // { patient_id: '123', start_time: '2025-01-01' }
 * ```
 */

type Primitive = string | number | boolean | null | undefined | Date;
type AnyRecord = Record<string, unknown>;

/**
 * Convierte camelCase → snake_case
 * Ejemplo: "patientId" → "patient_id"
 */
const snake = (str: string): string =>
  str.replace(/[A-Z]/g, (match) => `_${match.toLowerCase()}`);

/**
 * Convierte snake_case → camelCase
 * Ejemplo: "patient_id" → "patientId"
 */
const camel = (str: string): string =>
  str.replace(/_([a-z])/g, (_, char) => char.toUpperCase());

/**
 * Transforma recursivamente un objeto/array de snake_case a camelCase
 *
 * USAR: Cuando datos vienen de BD/Supabase hacia UI
 *
 * @template T - Tipo esperado después de transformación (UI type)
 * @param input - Datos en snake_case (DB type)
 * @returns Datos transformados a camelCase
 *
 * @example
 * ```ts
 * interface UiAppointment {
 *   patientId: string;
 *   startTime: string;
 *   endTime: string | null;
 * }
 *
 * const dbData = { patient_id: '123', start_time: '2025-01-01', end_time: null };
 * const uiData = toCamel<UiAppointment>(dbData);
 * // uiData: { patientId: '123', startTime: '2025-01-01', endTime: null }
 * ```
 */
export function toCamel<T = unknown>(input: unknown): T {
  // Arrays: transformar cada elemento
  if (Array.isArray(input)) {
    return input.map((value) => toCamel(value)) as unknown as T;
  }

  // Objetos planos: transformar llaves recursivamente
  // Excluir Date, null, primitivos
  if (input && typeof input === 'object' && !(input instanceof Date)) {
    const output: AnyRecord = {};

    for (const [key, value] of Object.entries(input as AnyRecord)) {
      output[camel(key)] = toCamel(value);
    }

    return output as T;
  }

  // Primitivos: retornar tal cual
  return input as T;
}

/**
 * Transforma recursivamente un objeto/array de camelCase a snake_case
 *
 * USAR: Cuando datos van desde UI hacia BD/Supabase
 *
 * @template T - Tipo esperado después de transformación (DB type)
 * @param input - Datos en camelCase (UI type)
 * @returns Datos transformados a snake_case
 *
 * @example
 * ```ts
 * interface DbAppointment {
 *   patient_id: string;
 *   start_time: string;
 *   end_time: string | null;
 * }
 *
 * const formData = { patientId: '123', startTime: '2025-01-01', endTime: null };
 * const dbPayload = toSnake<DbAppointment>(formData);
 * // dbPayload: { patient_id: '123', start_time: '2025-01-01', end_time: null }
 * ```
 */
export function toSnake<T = unknown>(input: unknown): T {
  // Arrays: transformar cada elemento
  if (Array.isArray(input)) {
    return input.map((value) => toSnake(value)) as unknown as T;
  }

  // Objetos planos: transformar llaves recursivamente
  // Excluir Date, null, primitivos
  if (input && typeof input === 'object' && !(input instanceof Date)) {
    const output: AnyRecord = {};

    for (const [key, value] of Object.entries(input as AnyRecord)) {
      output[snake(key)] = toSnake(value);
    }

    return output as T;
  }

  // Primitivos: retornar tal cual
  return input as T;
}

/**
 * Type helpers para inferir tipos transformados
 *
 * @example
 * ```ts
 * type DbUser = { user_id: string; first_name: string };
 * type UiUser = CamelCased<DbUser>; // { userId: string; firstName: string }
 * ```
 */
export type CamelCased<T> = T extends Array<infer U>
  ? Array<CamelCased<U>>
  : T extends Record<string, unknown>
  ? {
      [K in keyof T as K extends string
        ? CamelCase<K>
        : K]: CamelCased<T[K]>;
    }
  : T;

export type SnakeCased<T> = T extends Array<infer U>
  ? Array<SnakeCased<U>>
  : T extends Record<string, unknown>
  ? {
      [K in keyof T as K extends string
        ? SnakeCase<K>
        : K]: SnakeCased<T[K]>;
    }
  : T;

// String transformation types (compile-time only)
type CamelCase<S extends string> = S extends `${infer Head}_${infer Tail}`
  ? `${Head}${Capitalize<CamelCase<Tail>>}`
  : S;

type SnakeCase<S extends string> = S extends `${infer Head}${infer Tail}`
  ? Tail extends Uncapitalize<Tail>
    ? `${Uncapitalize<Head>}${SnakeCase<Tail>}`
    : `${Uncapitalize<Head>}_${SnakeCase<Tail>}`
  : S;

/**
 * Application configuration helpers
 * Migrated from @autamedica/config for consolidation
 *
 * IMPORTANT: Uses environment utilities from shared/env
 * No direct process.env access per monorepo rules
 */

import { getClientEnvOrDefault, isDevelopment } from '../env';

export type AppName = 'patients' | 'doctors';

export interface AppEnvironmentConfig {
  nodeEnv: string;
  authHubOrigin: string;
  appOrigin: string;
  supabase: {
    url: string;
    anonKey: string;
  };
  signalingUrl: string;
  authDevBypassEnabled: boolean;
}

export interface LoginUrlBuilder {
  build(returnTo?: string): string;
}

/**
 * Gets the auth hub origin based on environment
 */
function getAuthHubOrigin(): string {
  return isDevelopment()
    ? getClientEnvOrDefault('NEXT_PUBLIC_APP_URL', 'http://localhost:3000')
    : getClientEnvOrDefault('NEXT_PUBLIC_APP_URL', 'https://www.autamedica.com');
}

/**
 * Gets app origins configuration
 */
function getAppOrigins(): Record<AppName, string> {
  const devMode = isDevelopment();

  return {
    patients: devMode
      ? getClientEnvOrDefault('NEXT_PUBLIC_PATIENTS_DEV_URL', 'http://localhost:3002')
      : getClientEnvOrDefault('NEXT_PUBLIC_PATIENTS_URL', 'https://patients.autamedica.com'),
    doctors: devMode
      ? getClientEnvOrDefault('NEXT_PUBLIC_DOCTORS_DEV_URL', 'http://localhost:3001')
      : getClientEnvOrDefault('NEXT_PUBLIC_DOCTORS_URL', 'https://doctors.autamedica.com'),
  };
}

/**
 * Gets environment configuration for a specific app
 *
 * @param appName - The application name ('patients' | 'doctors')
 * @returns Complete environment configuration for the app
 */
export function getAppEnv(appName: AppName): AppEnvironmentConfig {
  const appOrigins = getAppOrigins();
  const authHubOrigin = getAuthHubOrigin();

  return {
    nodeEnv: isDevelopment() ? 'development' : 'production',
    authHubOrigin,
    appOrigin: appOrigins[appName],
    supabase: {
      url: getClientEnvOrDefault(
        'NEXT_PUBLIC_SUPABASE_URL',
        'https://knywotiidsydsaveqkjs.supabase.co',
      ),
      anonKey: getClientEnvOrDefault(
        'NEXT_PUBLIC_SUPABASE_ANON_KEY',
        'REPLACE_WITH_ROTATED_KEY.7UFMVZsWTWOAynnhzkG76I_lhVCYtd_RmTt9EH3wJD4',
      ),
    },
    signalingUrl: getClientEnvOrDefault(
      'NEXT_PUBLIC_SIGNALING_URL',
      'ws://localhost:3005/signal',
    ),
    authDevBypassEnabled: getClientEnvOrDefault('NEXT_PUBLIC_AUTH_DEV_BYPASS', 'false') === 'true',
  };
}

/**
 * Creates a login URL builder for a specific app
 *
 * @param appName - The application name
 * @returns Login URL builder with build() method
 */
export function getLoginUrlBuilder(appName: AppName): LoginUrlBuilder {
  const authHubOrigin = getAuthHubOrigin();

  return {
    build(returnTo?: string): string {
      const params = new URLSearchParams();
      if (returnTo) {
        params.set('returnTo', returnTo);
      }
      const query = params.toString();
      return query ? `${authHubOrigin}/auth/login/?${query}` : `${authHubOrigin}/auth/login/`;
    },
  };
}

import { createClient } from '@supabase/supabase-js'
import type { Database } from '@autamedica/types'
import { getClientEnvOrDefault, logger } from '@autamedica/shared'
import type { Call, CallStatus, CallEvent } from './types'

// Service for call management
export class CallService {
  private supabase: any
  private functionsBaseUrl: string
  private anonKey: string

  constructor(supabaseUrl: string, supabaseKey: string) {
    this.supabase = createClient<Database>(supabaseUrl, supabaseKey)
    this.anonKey = supabaseKey
    this.functionsBaseUrl = `${new URL(supabaseUrl).origin}/functions/v1`
  }

  async createCall(doctorId: string, patientId: string): Promise<Call> {
    try {
      // Get auth session for authorization header
      const { data: { session } } = await this.supabase.auth.getSession()

      if (!session?.access_token) {
        throw new Error('No active session found. Please login first.')
      }

      // Primary path: Edge Function
      const response = await fetch(`${this.functionsBaseUrl}/create-call`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${session.access_token}`,
          'Content-Type': 'application/json',
          'apikey': this.anonKey
        },
        body: JSON.stringify({
          doctorId,
          patientId
        })
      })

      // Fallback path for environments where Edge Functions are not deployed yet
      if (response.status === 404) {
        logger.warn('create-call edge function not found, falling back to RPC')
        return await this.createCallViaRpc(doctorId, patientId)
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`)
      }

      const result = await response.json()

      if (result.success === false) {
        throw new Error(result.error || 'Failed to create call')
      }

      if (result.call) {
        return result.call as Call
      }

      // Backward compatibility with direct payload responses
      return result as Call
    } catch (err) {
      logger.error('Error in createCall:', err)
      throw err
    }
  }

  async updateCallStatus(callId: string, status: CallStatus, reason?: string): Promise<boolean> {
    try {
      // Get auth session for authorization header
      const { data: { session } } = await this.supabase.auth.getSession()

      if (!session?.access_token) {
        throw new Error('No active session found. Please login first.')
      }

      // Primary path: Edge Function
      const response = await fetch(`${this.functionsBaseUrl}/update-call-status`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${session.access_token}`,
          'Content-Type': 'application/json',
          'apikey': this.anonKey
        },
        body: JSON.stringify({
          callId,
          status,
          reason
        })
      })

      // Fallback path for environments where Edge Functions are not deployed yet
      if (response.status === 404) {
        logger.warn('update-call-status edge function not found, falling back to RPC')
        return await this.updateCallStatusViaRpc(callId, status, reason)
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        throw new Error(errorData.error || `HTTP ${response.status}: ${response.statusText}`)
      }

      const result = await response.json()

      if (result.success === false) {
        throw new Error(result.error || 'Failed to update call status')
      }

      if (typeof result.updated === 'boolean') {
        return result.updated
      }

      return Boolean(result)
    } catch (err) {
      logger.error('Error in updateCallStatus:', err)
      throw err
    }
  }

  private async createCallViaRpc(doctorId: string, patientId: string): Promise<Call> {
    const { data, error } = await this.supabase.rpc('create_call', {
      p_doctor_id: doctorId,
      p_patient_id: patientId
    })

    if (error) throw error

    if (Array.isArray(data)) {
      const first = data[0]
      if (!first) throw new Error('RPC create_call returned no rows')
      return first as Call
    }

    if (!data) throw new Error('RPC create_call returned empty payload')
    return data as Call
  }

  private async updateCallStatusViaRpc(callId: string, status: CallStatus, reason?: string): Promise<boolean> {
    const { data, error } = await this.supabase.rpc('update_call_status', {
      p_call_id: callId,
      p_status: status,
      p_reason: reason ?? null
    })

    if (error) throw error
    return Boolean(data)
  }

  async getCall(callId: string): Promise<Call | null> {
    const { data, error } = await this.supabase
      .from('calls')
      .select('*')
      .eq('id', callId)
      .maybeSingle()

    if (error) throw error
    return data as Call | null
  }

  async getCallByRoomId(roomId: string): Promise<Call | null> {
    const { data, error } = await this.supabase
      .from('calls')
      .select('*')
      .eq('room_id', roomId)
      .maybeSingle()

    if (error) throw error
    return data as Call | null
  }

  async getActiveCallsForDoctor(doctorId: string): Promise<Call[]> {
    const { data, error } = await this.supabase
      .from('calls')
      .select('*')
      .eq('doctor_id', doctorId)
      .in('status', ['requested', 'ringing', 'accepted', 'connecting', 'connected'])
      .order('created_at', { ascending: false })

    if (error) throw error
    return data as Call[]
  }

  async getActiveCallsForPatient(patientId: string): Promise<Call[]> {
    const { data, error } = await this.supabase
      .from('calls')
      .select('*')
      .eq('patient_id', patientId)
      .in('status', ['requested', 'ringing', 'accepted', 'connecting', 'connected'])
      .order('created_at', { ascending: false })

    if (error) throw error
    return data as Call[]
  }

  async logEvent(callId: string, type: string, payload?: Record<string, any>): Promise<void> {
    const { error } = await this.supabase
      .from('call_events')
      .insert({
        call_id: callId,
        type,
        payload
      })

    if (error) throw error
  }

  async getCallEvents(callId: string): Promise<CallEvent[]> {
    const { data, error } = await this.supabase
      .from('call_events')
      .select('*')
      .eq('call_id', callId)
      .order('at', { ascending: true })

    if (error) throw error
    return data as CallEvent[]
  }

  // Subscribe to call changes
  subscribeToCall(callId: string, callback: (call: Call) => void) {
    return this.supabase
      .channel(`call:${callId}`)
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'calls',
        filter: `id=eq.${callId}`
      }, (payload: any) => {
        callback(payload.new as Call)
      })
      .subscribe()
  }

  // Subscribe to calls for a user (doctor or patient)
  subscribeToUserCalls(userId: string, userType: 'doctor' | 'patient', callback: (call: Call) => void) {
    const column = userType === 'doctor' ? 'doctor_id' : 'patient_id'

    return this.supabase
      .channel(`user_calls:${userId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'calls',
        filter: `${column}=eq.${userId}`
      }, (payload: any) => {
        callback(payload.new as Call)
      })
      .subscribe()
  }
}

// Utility function to generate room ID
export function generateRoomId(): string {
  return `room_${Math.random().toString(36).substring(2, 10)}_${Date.now().toString(36)}`
}

// Create service instance with environment variables
export function createCallService(): CallService {
  const supabaseUrl = getClientEnvOrDefault('NEXT_PUBLIC_SUPABASE_URL', '')
  const supabaseKey = getClientEnvOrDefault('NEXT_PUBLIC_SUPABASE_ANON_KEY', '')

  if (!supabaseUrl || !supabaseKey) {
    throw new Error('Missing Supabase environment variables')
  }

  return new CallService(supabaseUrl, supabaseKey)
}

// Call status types matching database enum
export type CallStatus =
  | 'requested'   // created by doctor
  | 'ringing'     // notified to patient
  | 'accepted'    // patient accepted
  | 'declined'    // patient declined
  | 'canceled'    // doctor canceled/expired
  | 'connecting'  // SDP/ICE exchange
  | 'connected'   // WebRTC OK
  | 'ended'       // hung up or timeout

export interface Call {
  id: string
  room_id: string
  doctor_id: string
  patient_id: string
  status: CallStatus
  created_at: string
  accepted_at?: string
  ended_at?: string
  reason?: string
}

export interface CallEvent {
  id: number
  call_id: string
  at: string
  type: string
  payload?: Record<string, any>
}

// WebSocket message types for signaling
export interface WSMessage {
  type: string
  [key: string]: any
}

// Control messages (user channel)
export interface InviteMessage extends WSMessage {
  type: 'invite'
  callId: string
  roomId: string
  from: { doctorId: string; name?: string }
  to: { patientId: string }
}

export interface AcceptMessage extends WSMessage {
  type: 'accept'
  callId: string
  roomId: string
  by: 'patient'
}

export interface DeclineMessage extends WSMessage {
  type: 'decline'
  callId: string
  reason?: string
}

export interface CancelMessage extends WSMessage {
  type: 'cancel'
  callId: string
}

export interface EndMessage extends WSMessage {
  type: 'end'
  callId: string
}

// WebRTC signaling messages (room channel)
export interface JoinMessage extends WSMessage {
  type: 'join'
  userId: string
}

export interface OfferMessage extends WSMessage {
  type: 'offer'
  sdp: string
  from?: string
}

export interface AnswerMessage extends WSMessage {
  type: 'answer'
  sdp: string
  from?: string
}

export interface CandidateMessage extends WSMessage {
  type: 'candidate'
  candidate: RTCIceCandidate
  from?: string
}

export type ControlMessage = InviteMessage | AcceptMessage | DeclineMessage | CancelMessage | EndMessage
export type SignalingMessage = JoinMessage | OfferMessage | AnswerMessage | CandidateMessage

import { useState, useCallback, useEffect } from 'react'
import { logger } from '@autamedica/shared'
import type { WebRTCClient } from '../webrtc-client'

export interface MediaControlsState {
  isMicOn: boolean
  isCamOn: boolean
  isSharing: boolean
  hasLocalStream: boolean
  mediaError: Error | null
}

export interface MediaControlsActions {
  toggleMic: (enabled?: boolean) => boolean
  toggleCam: (enabled?: boolean) => boolean
  startShare: () => Promise<void>
  stopShare: () => void
  refreshMediaState: () => void
}

export type MediaControlsHook = MediaControlsState & MediaControlsActions

export function useMediaControls(client: WebRTCClient | null): MediaControlsHook {
  const [state, setState] = useState<MediaControlsState>({
    isMicOn: false,
    isCamOn: false,
    isSharing: false,
    hasLocalStream: false,
    mediaError: null
  })

  // Refresh media state from client
  const refreshMediaState = useCallback(() => {
    if (!client) {
      setState({
        isMicOn: false,
        isCamOn: false,
        isSharing: false,
        hasLocalStream: false,
        mediaError: null
      })
      return
    }

    const localStream = client.getLocalStream()
    const hasStream = !!localStream

    setState(prev => ({
      ...prev,
      isMicOn: hasStream ? client.isAudioEnabled() : false,
      isCamOn: hasStream ? client.isVideoEnabled() : false,
      hasLocalStream: hasStream,
      mediaError: null
    }))
  }, [client])

  // Update state when client changes
  useEffect(() => {
    refreshMediaState()
  }, [client, refreshMediaState])

  // Monitor local stream changes
  useEffect(() => {
    if (!client) return

    const handleLocalStream = () => {
      refreshMediaState()
    }

    const handleError = (error: Error) => {
      setState(prev => ({ ...prev, mediaError: error }))
    }

    client.on('local-stream', handleLocalStream)
    client.on('error', handleError)

    return () => {
      client.off('local-stream', handleLocalStream)
      client.off('error', handleError)
    }
  }, [client, refreshMediaState])

  // Toggle microphone
  const toggleMic = useCallback((enabled?: boolean): boolean => {
    if (!client) {
      logger.warn('[useMediaControls] No client available for mic toggle')
      return false
    }

    try {
      const newState = client.toggleAudio(enabled)
      setState(prev => ({ ...prev, isMicOn: newState, mediaError: null }))
      logger.info(`[useMediaControls] Microphone ${newState ? 'enabled' : 'disabled'}`)
      return newState
    } catch (error) {
      const mediaError = error instanceof Error ? error : new Error('Failed to toggle microphone')
      setState(prev => ({ ...prev, mediaError }))
      logger.error('[useMediaControls] Failed to toggle microphone:', error)
      return false
    }
  }, [client])

  // Toggle camera
  const toggleCam = useCallback((enabled?: boolean): boolean => {
    if (!client) {
      logger.warn('[useMediaControls] No client available for camera toggle')
      return false
    }

    try {
      const newState = client.toggleVideo(enabled)
      setState(prev => ({ ...prev, isCamOn: newState, mediaError: null }))
      logger.info(`[useMediaControls] Camera ${newState ? 'enabled' : 'disabled'}`)
      return newState
    } catch (error) {
      const mediaError = error instanceof Error ? error : new Error('Failed to toggle camera')
      setState(prev => ({ ...prev, mediaError }))
      logger.error('[useMediaControls] Failed to toggle camera:', error)
      return false
    }
  }, [client])

  // Start screen sharing
  const startShare = useCallback(async (): Promise<void> => {
    if (!client) {
      throw new Error('No client available for screen sharing')
    }

    try {
      setState(prev => ({ ...prev, mediaError: null }))

      // Check if getDisplayMedia is available
      if (!navigator.mediaDevices?.getDisplayMedia) {
        throw new Error('Screen sharing not supported in this browser')
      }

      const screenStream = await navigator.mediaDevices.getDisplayMedia({
        video: {
          // @ts-ignore - mediaSource is supported in getDisplayMedia
        mediaSource: 'screen',
          width: { ideal: 1920 },
          height: { ideal: 1080 },
          frameRate: { ideal: 30 }
        },
        audio: false
      })

      setState(prev => ({ ...prev, isSharing: true }))
      logger.info('[useMediaControls] Screen sharing started')

      // Handle when user stops screen sharing via browser UI
      const videoTrack = screenStream.getVideoTracks()[0]
      if (videoTrack) {
        videoTrack.onended = () => {
          setState(prev => ({ ...prev, isSharing: false }))
          logger.info('[useMediaControls] Screen sharing ended by user')
        }
      }

      // TODO: Integrate screen stream with WebRTC client
      // This might require extending the WebRTCClient to handle screen sharing
      // For now, we just track the state

    } catch (error) {
      const mediaError = error instanceof Error ? error : new Error('Failed to start screen sharing')
      setState(prev => ({ ...prev, mediaError, isSharing: false }))
      logger.error('[useMediaControls] Failed to start screen sharing:', error)
      throw error
    }
  }, [client])

  // Stop screen sharing
  const stopShare = useCallback((): void => {
    setState(prev => ({ ...prev, isSharing: false, mediaError: null }))
    logger.info('[useMediaControls] Screen sharing stopped')

    // TODO: Stop screen stream in WebRTC client
    // This would require client.stopScreenShare() or similar
  }, [])

  return {
    ...state,
    toggleMic,
    toggleCam,
    startShare,
    stopShare,
    refreshMediaState
  }
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { logger } from '@autamedica/shared'
import type { WebRTCClient } from '../webrtc-client'

export interface RtcStatsData {
  rtt: number | null // Round trip time in ms
  packetLoss: number | null // Packet loss percentage (0-100)
  bitrateKbps: number | null // Bitrate in Kbps
  framesPerSecond: number | null // Video FPS
  audioLevel: number | null // Audio level (0-1)
  connectionQuality: 'excellent' | 'good' | 'fair' | 'poor' | 'unknown'
  timestamp: number
}

export interface RtcStatsState {
  stats: RtcStatsData
  isCollecting: boolean
  error: Error | null
  history: RtcStatsData[] // Last 30 samples
}

export interface RtcStatsActions {
  startCollection: () => void
  stopCollection: () => void
  getAverageStats: (samples?: number) => Partial<RtcStatsData>
  clearHistory: () => void
}

export type RtcStatsHook = RtcStatsState & RtcStatsActions

interface UseRtcStatsOptions {
  interval?: number // Collection interval in ms
  autoStart?: boolean
  maxHistorySize?: number
}

const DEFAULT_OPTIONS: Required<UseRtcStatsOptions> = {
  interval: 2000, // 2 seconds
  autoStart: true,
  maxHistorySize: 30 // Keep last 30 samples (1 minute at 2s interval)
}

function createEmptyStats(): RtcStatsData {
  return {
    rtt: null,
    packetLoss: null,
    bitrateKbps: null,
    framesPerSecond: null,
    audioLevel: null,
    connectionQuality: 'unknown',
    timestamp: Date.now()
  }
}

function calculateConnectionQuality(stats: Partial<RtcStatsData>): RtcStatsData['connectionQuality'] {
  const { rtt, packetLoss } = stats

  if (rtt === null || rtt === undefined || packetLoss === null || packetLoss === undefined) return 'unknown'

  if (rtt < 100 && packetLoss < 1) return 'excellent'
  if (rtt < 200 && packetLoss < 3) return 'good'
  if (rtt < 400 && packetLoss < 5) return 'fair'
  return 'poor'
}

export function useRtcStats(
  client: WebRTCClient | null,
  options: UseRtcStatsOptions = {}
): RtcStatsHook {
  const opts = { ...DEFAULT_OPTIONS, ...options }

  const [state, setState] = useState<RtcStatsState>({
    stats: createEmptyStats(),
    isCollecting: false,
    error: null,
    history: []
  })

  const intervalRef = useRef<NodeJS.Timeout | undefined>(undefined)
  const previousStatsRef = useRef<Map<string, any>>(new Map())

  // Collect stats from peer connections
  const collectStats = useCallback(async (): Promise<RtcStatsData> => {
    if (!client) {
      return createEmptyStats()
    }

    try {
      const peerConnections = client.getPeerConnections()
      const statsData = createEmptyStats()
      let validConnections = 0

      // Aggregate stats from all peer connections
      for (const [userId, pc] of peerConnections) {
        if (pc.connectionState !== 'connected') continue

        const stats = await pc.getStats()
        const currentStats = new Map()

        stats.forEach((report) => {
          currentStats.set(report.id, report)
        })

        // Calculate RTT from ICE candidate pairs
        for (const [, report] of currentStats.entries()) {
          if (report.type === 'candidate-pair' && report.state === 'succeeded') {
            if (typeof report.currentRoundTripTime === 'number') {
              const rtt = report.currentRoundTripTime * 1000 // Convert to ms
              statsData.rtt = statsData.rtt === null ? rtt : Math.max(statsData.rtt, rtt)
            }
          }
        }

        // Calculate packet loss and bitrate from inbound RTP streams
        for (const [id, report] of currentStats.entries()) {
          if (report.type === 'inbound-rtp') {
            // Packet loss calculation
            if (typeof report.packetsLost === 'number' && typeof report.packetsReceived === 'number') {
              const totalPackets = report.packetsLost + report.packetsReceived
              if (totalPackets > 0) {
                const packetLossPercent = (report.packetsLost / totalPackets) * 100
                statsData.packetLoss = statsData.packetLoss === null
                  ? packetLossPercent
                  : Math.max(statsData.packetLoss, packetLossPercent)
              }
            }

            // Bitrate calculation
            const previousReport = previousStatsRef.current.get(id)
            if (previousReport && typeof report.bytesReceived === 'number') {
              const bytesDiff = report.bytesReceived - (previousReport.bytesReceived || 0)
              const timeDiff = report.timestamp - (previousReport.timestamp || 0)

              if (timeDiff > 0) {
                const bitrateKbps = (bytesDiff * 8) / (timeDiff) // Convert to Kbps
                statsData.bitrateKbps = statsData.bitrateKbps === null
                  ? bitrateKbps
                  : statsData.bitrateKbps + bitrateKbps
              }
            }

            // Video FPS (for video streams)
            if (report.kind === 'video' && typeof report.framesPerSecond === 'number') {
              statsData.framesPerSecond = statsData.framesPerSecond === null
                ? report.framesPerSecond
                : Math.max(statsData.framesPerSecond, report.framesPerSecond)
            }

            // Audio level (for audio streams)
            if (report.kind === 'audio' && typeof report.audioLevel === 'number') {
              statsData.audioLevel = statsData.audioLevel === null
                ? report.audioLevel
                : Math.max(statsData.audioLevel, report.audioLevel)
            }
          }
        }

        // Store current stats for next calculation
        previousStatsRef.current = currentStats
        validConnections++
      }

      // Calculate connection quality
      statsData.connectionQuality = calculateConnectionQuality(statsData)
      statsData.timestamp = Date.now()

      return statsData

    } catch (error) {
      logger.error('[useRtcStats] Failed to collect stats:', error)
      throw error
    }
  }, [client])

  // Start stats collection
  const startCollection = useCallback(() => {
    if (intervalRef.current || !client) return

    setState(prev => ({ ...prev, isCollecting: true, error: null }))

    const collect = async () => {
      try {
        const stats = await collectStats()
        setState(prev => {
          const newHistory = [...prev.history, stats].slice(-opts.maxHistorySize)
          return {
            ...prev,
            stats,
            history: newHistory,
            error: null
          }
        })
      } catch (error) {
        setState(prev => ({
          ...prev,
          error: error instanceof Error ? error : new Error('Stats collection failed'),
          isCollecting: false
        }))
        if (intervalRef.current) {
          clearInterval(intervalRef.current)
          intervalRef.current = undefined
        }
      }
    }

    // Collect immediately
    collect()

    // Set up interval
    intervalRef.current = setInterval(collect, opts.interval)
    logger.info(`[useRtcStats] Started stats collection (interval: ${opts.interval}ms)`)
  }, [client, collectStats, opts.interval, opts.maxHistorySize])

  // Stop stats collection
  const stopCollection = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current)
      intervalRef.current = undefined
    }

    setState(prev => ({ ...prev, isCollecting: false }))
    logger.info('[useRtcStats] Stopped stats collection')
  }, [])

  // Calculate average stats over last N samples
  const getAverageStats = useCallback((samples: number = 10): Partial<RtcStatsData> => {
    const recentHistory = state.history.slice(-samples)
    if (recentHistory.length === 0) return {}

    const totals = {
      rtt: 0,
      packetLoss: 0,
      bitrateKbps: 0,
      framesPerSecond: 0,
      audioLevel: 0
    }

    const counts = {
      rtt: 0,
      packetLoss: 0,
      bitrateKbps: 0,
      framesPerSecond: 0,
      audioLevel: 0
    }

    recentHistory.forEach(stats => {
      Object.keys(totals).forEach(key => {
        const value = stats[key as keyof typeof totals]
        if (value !== null && typeof value === 'number') {
          totals[key as keyof typeof totals] += value
          counts[key as keyof typeof counts]++
        }
      })
    })

    const averages: Partial<RtcStatsData> = {}
    Object.keys(totals).forEach(key => {
      const count = counts[key as keyof typeof counts]
      if (count > 0) {
        averages[key as keyof typeof totals] = totals[key as keyof typeof totals] / count
      }
    })

    return averages
  }, [state.history])

  // Clear history
  const clearHistory = useCallback(() => {
    setState(prev => ({ ...prev, history: [] }))
  }, [])

  // Auto-start collection when client becomes available
  useEffect(() => {
    if (opts.autoStart && client && client.getConnectionState() === 'connected') {
      startCollection()
    }

    return () => {
      stopCollection()
    }
  }, [client, opts.autoStart, startCollection, stopCollection])

  // Listen for connection state changes
  useEffect(() => {
    if (!client) return

    const handleConnectionState = (connectionState: string) => {
      if (connectionState === 'connected' && opts.autoStart) {
        startCollection()
      } else if (connectionState !== 'connected') {
        stopCollection()
      }
    }

    client.on('connection-state', handleConnectionState as any)

    return () => {
      client.off('connection-state', handleConnectionState as any)
    }
  }, [client, opts.autoStart, startCollection, stopCollection])

  return {
    ...state,
    startCollection,
    stopCollection,
    getAverageStats,
    clearHistory
  }
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { logger } from '@autamedica/shared'
import { WebRTCClient, type ConnectionState, type MediaConstraints } from '../webrtc-client'

export interface TelemedicineClientState {
  client: WebRTCClient | null
  connectionState: ConnectionState
  localStream: MediaStream | null
  remoteStreams: Map<string, MediaStream>
  error: Error | null
  isConnecting: boolean
  reconnectAttempts: number
}

export interface TelemedicineClientActions {
  connect: () => Promise<void>
  disconnect: () => Promise<void>
  startLocalStream: (constraints?: MediaConstraints) => Promise<MediaStream | void>
  stopLocalStream: () => void
}

export type TelemedicineClientHook = TelemedicineClientState & TelemedicineClientActions

interface UseTelemedicineClientOptions {
  autoConnect?: boolean
  maxReconnectAttempts?: number
  reconnectBackoffBase?: number
  reconnectBackoffMax?: number
  mediaConstraints?: MediaConstraints
}

const DEFAULT_OPTIONS: Required<UseTelemedicineClientOptions> = {
  autoConnect: false,
  maxReconnectAttempts: 5,
  reconnectBackoffBase: 1000,
  reconnectBackoffMax: 10000,
  mediaConstraints: { video: true, audio: true }
}

export function useTelemedicineClient(
  roomId: string,
  userId: string,
  userType: 'doctor' | 'patient' | 'nurse',
  options: UseTelemedicineClientOptions = {}
): TelemedicineClientHook {
  const opts = { ...DEFAULT_OPTIONS, ...options }

  const [state, setState] = useState<TelemedicineClientState>({
    client: null,
    connectionState: 'disconnected',
    localStream: null,
    remoteStreams: new Map(),
    error: null,
    isConnecting: false,
    reconnectAttempts: 0
  })

  const reconnectTimeoutRef = useRef<NodeJS.Timeout | undefined>(undefined)
  const clientRef = useRef<WebRTCClient | undefined>(undefined)

  // Calculate exponential backoff delay
  const calculateBackoffDelay = useCallback((attempt: number): number => {
    const delay = Math.min(
      opts.reconnectBackoffBase * Math.pow(2, attempt),
      opts.reconnectBackoffMax
    )
    // Add jitter to prevent thundering herd
    return delay + Math.random() * 1000
  }, [opts.reconnectBackoffBase, opts.reconnectBackoffMax])

  // Initialize WebRTC client
  useEffect(() => {
    logger.info(`[useTelemedicineClient] Initializing for ${userType}: ${userId} in room ${roomId}`)

    const client = new WebRTCClient({
      userId,
      userType,
      roomId
    })

    clientRef.current = client

    // Set up event listeners
    client.on('connection-state', (connectionState: any) => {
      logger.info(`[useTelemedicineClient] Connection state:`, connectionState)
      setState(prev => ({
        ...prev,
        connectionState,
        isConnecting: connectionState === 'connecting',
        error: connectionState === 'failed' ? new Error('Connection failed') : null
      }))

      // Handle reconnection on failure
      if (connectionState === 'failed' && state.reconnectAttempts < opts.maxReconnectAttempts) {
        const delay = calculateBackoffDelay(state.reconnectAttempts)
        logger.info(`[useTelemedicineClient] Scheduling reconnection in ${delay}ms (attempt ${state.reconnectAttempts + 1})`)

        reconnectTimeoutRef.current = setTimeout(() => {
          setState(prev => ({ ...prev, reconnectAttempts: prev.reconnectAttempts + 1 }))
          client.connect(roomId).catch(error => {
            logger.error('[useTelemedicineClient] Reconnection failed:', error)
          })
        }, delay)
      }

      // Reset reconnect attempts on successful connection
      if (connectionState === 'connected') {
        setState(prev => ({ ...prev, reconnectAttempts: 0, error: null }))
        if (reconnectTimeoutRef.current) {
          clearTimeout(reconnectTimeoutRef.current)
          reconnectTimeoutRef.current = undefined
        }
      }
    })

    client.on('local-stream', (stream: any) => {
      logger.info(`[useTelemedicineClient] Got local stream`)
      setState(prev => ({ ...prev, localStream: stream }))
    })

    client.on('remote-stream', (stream: any, userId: any) => {
      logger.info(`[useTelemedicineClient] Got remote stream from:`, userId)
      setState(prev => ({
        ...prev,
        remoteStreams: new Map(prev.remoteStreams).set(userId, stream)
      }))
    })

    client.on('user-left', (userId: any) => {
      logger.info(`[useTelemedicineClient] User left:`, userId)
      setState(prev => {
        const newRemoteStreams = new Map(prev.remoteStreams)
        newRemoteStreams.delete(userId)
        return { ...prev, remoteStreams: newRemoteStreams }
      })
    })

    client.on('error', (error) => {
      logger.error(`[useTelemedicineClient] WebRTC error:`, error)
      setState(prev => ({ ...prev, error }))
    })

    setState(prev => ({ ...prev, client }))

    // Auto-connect if enabled
    if (opts.autoConnect) {
      client.connect(roomId).catch(error => {
        logger.error('[useTelemedicineClient] Auto-connect failed:', error)
        setState(prev => ({ ...prev, error }))
      })
    }

    return () => {
      logger.info(`[useTelemedicineClient] Cleaning up`)
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current)
      }
      client.disconnect()
    }
  }, [roomId, userId, userType, opts.autoConnect, opts.maxReconnectAttempts])

  // Connect function
  const connect = useCallback(async (): Promise<void> => {
    if (!clientRef.current) {
      throw new Error('Client not initialized')
    }

    setState(prev => ({ ...prev, isConnecting: true, error: null }))

    try {
      await clientRef.current.connect(roomId)
    } catch (error) {
      logger.error('[useTelemedicineClient] Connect failed:', error)
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error : new Error('Connection failed'),
        isConnecting: false
      }))
      throw error
    }
  }, [roomId])

  // Disconnect function
  const disconnect = useCallback(async (): Promise<void> => {
    if (!clientRef.current) return

    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current)
      reconnectTimeoutRef.current = undefined
    }

    setState(prev => ({
      ...prev,
      reconnectAttempts: 0,
      isConnecting: false
    }))

    await clientRef.current.disconnect()
  }, [])

  // Start local stream
  const startLocalStream = useCallback(async (constraints?: MediaConstraints): Promise<MediaStream | void> => {
    if (!clientRef.current) {
      throw new Error('Client not initialized')
    }

    try {
      const stream = await clientRef.current.startLocalStream(constraints || opts.mediaConstraints)
      return stream
    } catch (error) {
      logger.error('[useTelemedicineClient] Failed to start local stream:', error)
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error : new Error('Failed to access media devices')
      }))
      throw error
    }
  }, [opts.mediaConstraints])

  // Stop local stream
  const stopLocalStream = useCallback((): void => {
    if (!clientRef.current) return
    clientRef.current.stopLocalStream()
    setState(prev => ({ ...prev, localStream: null }))
  }, [])

  return {
    ...state,
    connect,
    disconnect,
    startLocalStream,
    stopLocalStream
  }
}

/**
 * HTTP-based WebRTC Client for AltaMedica Telemedicine
 * Uses fetch and polling instead of WebSockets for better reliability
 */

import { logger } from '@autamedica/shared'

export interface HttpWebRTCConfig {
  signalingUrl: string
  iceServers: RTCIceServer[]
  roomId?: string
  userId: string
  userType: 'doctor' | 'patient' | 'nurse'
  pollInterval?: number // milliseconds
}

export interface MediaConstraints {
  video: boolean | MediaTrackConstraints
  audio: boolean | MediaTrackConstraints
}

export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'failed' | 'closed'

export interface HttpWebRTCEvents {
  'connection-state': (state: ConnectionState) => void
  'remote-stream': (stream: MediaStream, userId: string) => void
  'local-stream': (stream: MediaStream) => void
  'user-joined': (userId: string, userType: string) => void
  'user-left': (userId: string) => void
  'error': (error: Error) => void
}

export class HttpWebRTCClient {
  private peerConnections = new Map<string, RTCPeerConnection>()
  private localStream: MediaStream | null = null
  private config: HttpWebRTCConfig
  private eventListeners = new Map<keyof HttpWebRTCEvents, Function[]>()
  private connectionState: ConnectionState = 'disconnected'
  private pollTimer: number | null = null
  private lastPollTimestamp = 0
  private isPolling = false

  // Default ICE servers (using public STUN servers)
  private static readonly DEFAULT_ICE_SERVERS: RTCIceServer[] = [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun2.l.google.com:19302' }
  ]

  constructor(config: Partial<HttpWebRTCConfig> & { userId: string; userType: 'doctor' | 'patient' | 'nurse' }) {
    this.config = {
      signalingUrl: 'https://autamedica-http-signaling-server.ecucondor.workers.dev',
      iceServers: HttpWebRTCClient.DEFAULT_ICE_SERVERS,
      roomId: 'default-room',
      pollInterval: 1000, // Poll every second
      ...config
    }
  }

  // Event listener methods
  on<T extends keyof HttpWebRTCEvents>(event: T, listener: HttpWebRTCEvents[T]): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, [])
    }
    this.eventListeners.get(event)!.push(listener)
  }

  off<T extends keyof HttpWebRTCEvents>(event: T, listener: HttpWebRTCEvents[T]): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      const index = listeners.indexOf(listener)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }

  private emit<T extends keyof HttpWebRTCEvents>(event: T, ...args: Parameters<HttpWebRTCEvents[T]>): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.forEach(listener => {
        try {
          // @ts-ignore
          listener(...args)
        } catch (error) {
          logger.error(`Error in ${event} listener:`, error)
        }
      })
    }
  }

  private setConnectionState(state: ConnectionState): void {
    if (this.connectionState !== state) {
      this.connectionState = state
      this.emit('connection-state', state)
    }
  }

  async connect(roomId?: string): Promise<void> {
    if (this.connectionState === 'connecting' || this.connectionState === 'connected') {
      return
    }

    this.setConnectionState('connecting')

    try {
      const finalRoomId = roomId || this.config.roomId!

      // Join the room via HTTP API
      const joinResponse = await fetch(`${this.config.signalingUrl}/api/join`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          roomId: finalRoomId,
          userId: this.config.userId,
          userType: this.config.userType
        })
      })

      if (!joinResponse.ok) {
        throw new Error(`Join failed: ${joinResponse.status}`)
      }

      const joinData = await joinResponse.json()

      if (!joinData.success) {
        throw new Error(`Join failed: ${joinData.error}`)
      }

      logger.info('Successfully joined room:', finalRoomId)

      // Process existing users in the room
      if (joinData.roomState?.users) {
        for (const user of joinData.roomState.users) {
          this.emit('user-joined', user.userId, user.userType)
        }
      }

      this.setConnectionState('connected')

      // Start polling for messages
      this.startPolling()

    } catch (error) {
      logger.error('Connection failed:', error)
      this.setConnectionState('failed')
      this.emit('error', error as Error)
      throw error
    }
  }

  async startLocalStream(constraints: MediaConstraints = { video: true, audio: true }): Promise<MediaStream> {
    try {
      this.localStream = await navigator.mediaDevices.getUserMedia(constraints)
      this.emit('local-stream', this.localStream)

      // Add tracks to all existing peer connections
      for (const [userId, pc] of this.peerConnections) {
        this.localStream.getTracks().forEach(track => {
          pc.addTrack(track, this.localStream!)
        })
      }

      return this.localStream
    } catch (error) {
      logger.error('Failed to get local stream:', error)
      this.emit('error', new Error('Failed to access camera/microphone'))
      throw error
    }
  }

  stopLocalStream(): void {
    if (this.localStream) {
      this.localStream.getTracks().forEach(track => track.stop())
      this.localStream = null
    }
  }

  async disconnect(): Promise<void> {
    this.setConnectionState('disconnected')

    // Stop polling
    this.stopPolling()

    // Leave room via HTTP API
    if (this.config.roomId) {
      try {
        await fetch(`${this.config.signalingUrl}/api/leave`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            roomId: this.config.roomId,
            userId: this.config.userId
          })
        })
      } catch (error) {
        logger.error('Error leaving room:', error)
      }
    }

    this.cleanup()
  }

  private cleanup(): void {
    // Close all peer connections
    for (const [userId, pc] of this.peerConnections) {
      pc.close()
    }
    this.peerConnections.clear()

    // Stop local stream
    this.stopLocalStream()
  }

  private startPolling(): void {
    if (this.isPolling) return

    this.isPolling = true
    this.lastPollTimestamp = Date.now()

    const poll = async () => {
      if (!this.isPolling || this.connectionState !== 'connected') {
        return
      }

      try {
        const response = await fetch(
          `${this.config.signalingUrl}/api/poll?roomId=${encodeURIComponent(this.config.roomId!)}&userId=${encodeURIComponent(this.config.userId)}&since=${this.lastPollTimestamp}`,
          {
            method: 'GET',
            headers: {
              'Content-Type': 'application/json'
            }
          }
        )

        if (response.ok) {
          const data = await response.json()
          this.lastPollTimestamp = data.timestamp

          // Process messages
          for (const message of data.messages) {
            await this.handleSignalingMessage(message)
          }
        }
      } catch (error) {
        logger.error('Polling error:', error)
        // Don't emit error for polling failures - just retry
      }

      // Schedule next poll
      this.pollTimer = window.setTimeout(poll, this.config.pollInterval!)
    }

    // Start polling immediately
    poll()
  }

  private stopPolling(): void {
    this.isPolling = false
    if (this.pollTimer !== null) {
      clearTimeout(this.pollTimer)
      this.pollTimer = null
    }
  }

  private async sendSignalingMessage(message: any): Promise<void> {
    try {
      const response = await fetch(`${this.config.signalingUrl}/api/message`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          roomId: this.config.roomId,
          from: this.config.userId,
          ...message
        })
      })

      if (!response.ok) {
        throw new Error(`Failed to send message: ${response.status}`)
      }
    } catch (error) {
      logger.error('Failed to send signaling message:', error)
      this.emit('error', error as Error)
    }
  }

  private async handleSignalingMessage(message: any): Promise<void> {
    logger.info('Received signaling message:', message)

    switch (message.type) {
      case 'user-joined':
        this.emit('user-joined', message.from, message.data?.userType || 'unknown')
        // Create offer for the new user if we have local stream
        if (this.localStream) {
          await this.createPeerConnection(message.from, true)
        }
        break

      case 'user-left': {
        this.emit('user-left', message.from)
        const pc = this.peerConnections.get(message.from)
        if (pc) {
          pc.close()
          this.peerConnections.delete(message.from)
        }
        break
      }

      case 'offer':
        await this.handleOffer(message.from, message.data)
        break

      case 'answer':
        await this.handleAnswer(message.from, message.data)
        break

      case 'ice-candidate':
        await this.handleIceCandidate(message.from, message.data)
        break

      default:
        logger.warn('Unknown message type:', message.type)
    }
  }

  private async createPeerConnection(userId: string, createOffer: boolean): Promise<RTCPeerConnection> {
    const pc = new RTCPeerConnection({ iceServers: this.config.iceServers })

    // Add local stream tracks if available
    if (this.localStream) {
      this.localStream.getTracks().forEach(track => {
        pc.addTrack(track, this.localStream!)
      })
    }

    // Handle remote stream
    pc.ontrack = (event) => {
      logger.info('Received remote stream from', userId)
      const stream = event.streams?.[0]
      if (stream) {
        this.emit('remote-stream', stream, userId)
      }
    }

    // Handle ICE candidates
    pc.onicecandidate = (event) => {
      if (event.candidate) {
        this.sendSignalingMessage({
          type: 'ice-candidate',
          to: userId,
          data: event.candidate
        })
      }
    }

    // Handle connection state changes
    pc.onconnectionstatechange = () => {
      logger.info(`Peer connection with ${userId} state:`, pc.connectionState)
      if (pc.connectionState === 'failed' || pc.connectionState === 'closed') {
        this.peerConnections.delete(userId)
      }
    }

    this.peerConnections.set(userId, pc)

    // Create offer if requested
    if (createOffer) {
      const offer = await pc.createOffer()
      await pc.setLocalDescription(offer)

      this.sendSignalingMessage({
        type: 'offer',
        to: userId,
        data: offer
      })
    }

    return pc
  }

  private async handleOffer(userId: string, offer: RTCSessionDescriptionInit): Promise<void> {
    const pc = await this.createPeerConnection(userId, false)

    await pc.setRemoteDescription(offer)
    const answer = await pc.createAnswer()
    await pc.setLocalDescription(answer)

    this.sendSignalingMessage({
      type: 'answer',
      to: userId,
      data: answer
    })
  }

  private async handleAnswer(userId: string, answer: RTCSessionDescriptionInit): Promise<void> {
    const pc = this.peerConnections.get(userId)
    if (pc) {
      await pc.setRemoteDescription(answer)
    }
  }

  private async handleIceCandidate(userId: string, candidate: RTCIceCandidateInit): Promise<void> {
    const pc = this.peerConnections.get(userId)
    if (pc) {
      await pc.addIceCandidate(candidate)
    }
  }

  // Utility methods
  getConnectionState(): ConnectionState {
    return this.connectionState
  }

  getLocalStream(): MediaStream | null {
    return this.localStream
  }

  getPeerConnections(): Map<string, RTCPeerConnection> {
    return new Map(this.peerConnections)
  }

  // Media control methods
  toggleVideo(enabled?: boolean): boolean {
    if (!this.localStream) return false

    const videoTrack = this.localStream.getVideoTracks()[0]
    if (videoTrack) {
      videoTrack.enabled = enabled !== undefined ? enabled : !videoTrack.enabled
      return videoTrack.enabled
    }
    return false
  }

  toggleAudio(enabled?: boolean): boolean {
    if (!this.localStream) return false

    const audioTrack = this.localStream.getAudioTracks()[0]
    if (audioTrack) {
      audioTrack.enabled = enabled !== undefined ? enabled : !audioTrack.enabled
      return audioTrack.enabled
    }
    return false
  }

  isVideoEnabled(): boolean {
    if (!this.localStream) return false
    const videoTrack = this.localStream.getVideoTracks()[0]
    return videoTrack ? videoTrack.enabled : false
  }

  isAudioEnabled(): boolean {
    if (!this.localStream) return false
    const audioTrack = this.localStream.getAudioTracks()[0]
    return audioTrack ? audioTrack.enabled : false
  }

  // Keep-alive ping
  async ping(): Promise<void> {
    if (this.connectionState === 'connected') {
      try {
        await fetch(`${this.config.signalingUrl}/api/ping`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            userId: this.config.userId
          })
        })
      } catch (error) {
        logger.error('Ping failed:', error)
      }
    }
  }
}

import { ensureClientEnv, logger } from '@autamedica/shared'
import type { WSMessage, ControlMessage, SignalingMessage } from '../calls/types'

// WebSocket signaling client
export class SignalingClient {
  private ws: WebSocket | null = null
  private userId: string
  private roomId?: string
  private userType: 'doctor' | 'patient'
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private messageQueue: WSMessage[] = []
  private listeners: Map<string, Set<(message: any) => void>> = new Map()

  constructor(userId: string, userType: 'doctor' | 'patient', roomId?: string) {
    this.userId = userId
    this.userType = userType
    this.roomId = roomId
  }

  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        const signalingUrl = ensureClientEnv('NEXT_PUBLIC_SIGNALING_URL')
        let wsUrl = `${signalingUrl}?userId=${this.userId}&userType=${this.userType}`

        if (this.roomId) {
          wsUrl += `&roomId=${this.roomId}`
        }

        this.ws = new WebSocket(wsUrl)

        this.ws.onopen = () => {
          logger.info('[SignalingClient] Connected')
          this.reconnectAttempts = 0

          // Send queued messages
          while (this.messageQueue.length > 0) {
            const message = this.messageQueue.shift()!
            this.send(message)
          }

          resolve()
        }

        this.ws.onclose = (event) => {
          logger.info('[SignalingClient] Disconnected:', event.code, event.reason)

          if (event.code !== 1000 && this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++
            setTimeout(() => {
              logger.info(`[SignalingClient] Reconnecting... (${this.reconnectAttempts}/${this.maxReconnectAttempts})`)
              this.connect()
            }, 1000 * this.reconnectAttempts)
          }
        }

        this.ws.onerror = (error) => {
          logger.error('[SignalingClient] Error:', error)
          reject(error)
        }

        this.ws.onmessage = (event) => {
          try {
            const message = JSON.parse(event.data)
            this.handleMessage(message)
          } catch (error) {
            logger.error('[SignalingClient] Failed to parse message:', error)
          }
        }

      } catch (error) {
        reject(error)
      }
    })
  }

  disconnect() {
    if (this.ws) {
      this.ws.close(1000, 'Client disconnect')
      this.ws = null
    }
  }

  send(message: WSMessage) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message))
    } else {
      // Queue message for when connection is ready
      this.messageQueue.push(message)
    }
  }

  // Control messages (user channel)
  sendToUser(toUserId: string, message: ControlMessage) {
    this.send({
      ...message,
      toUserId
    })
  }

  // Room messages (WebRTC signaling)
  sendToRoom(message: SignalingMessage) {
    this.send({
      ...message,
      from: this.userId
    })
  }

  // Join a room for WebRTC signaling
  joinRoom(roomId: string) {
    this.roomId = roomId
    this.send({
      type: 'join',
      roomId,
      userId: this.userId
    })
  }

  // Leave current room
  leaveRoom() {
    if (this.roomId) {
      this.send({
        type: 'leave',
        roomId: this.roomId,
        userId: this.userId
      })
      this.roomId = undefined
    }
  }

  // Event listeners
  on(event: string, callback: (message: any) => void) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event)!.add(callback)

    // Return unsubscribe function
    return () => {
      this.listeners.get(event)?.delete(callback)
    }
  }

  off(event: string, callback: (message: any) => void) {
    this.listeners.get(event)?.delete(callback)
  }

  private handleMessage(message: WSMessage) {
    logger.info('[SignalingClient] Received:', message)

    // Emit to specific event listeners
    const listeners = this.listeners.get(message.type)
    if (listeners) {
      listeners.forEach(callback => callback(message))
    }

    // Emit to general message listeners
    const generalListeners = this.listeners.get('message')
    if (generalListeners) {
      generalListeners.forEach(callback => callback(message))
    }
  }

  // Convenience methods for common events
  onUserMessage(callback: (message: ControlMessage) => void) {
    return this.on('message', (message) => {
      // Filter for control messages sent to this user
      if (['invite', 'accept', 'decline', 'cancel', 'end'].includes(message.type)) {
        callback(message as ControlMessage)
      }
    })
  }

  onRoomMessage(callback: (message: SignalingMessage) => void) {
    return this.on('message', (message) => {
      // Filter for room signaling messages
      if (['join', 'leave', 'offer', 'answer', 'candidate'].includes(message.type)) {
        callback(message as SignalingMessage)
      }
    })
  }

  // Check connection status
  get isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN
  }

  get connectionState(): number {
    return this.ws?.readyState ?? WebSocket.CLOSED
  }
}

// React hook for using signaling client
export function createSignalingClient(userId: string, userType: 'doctor' | 'patient', roomId?: string): SignalingClient {
  return new SignalingClient(userId, userType, roomId)
}

import { getClientEnvOrDefault, getOptionalClientEnv } from '@autamedica/shared'
import { SignalingClient } from './client'

export function createSignaling(
  userId: string,
  userType: 'doctor' | 'patient',
  roomId?: string
) {
  const base = getClientEnvOrDefault(
    'NEXT_PUBLIC_SIGNALING_URL',
    'wss://autamedica-signaling-server.ecucondor.workers.dev/connect'
  )
  const qs = new URLSearchParams({
    userId,
    userType,
    ...(roomId ? { roomId } : {}),
  })
  const wsUrl = `${base}?${qs.toString()}`
  const debug = getOptionalClientEnv('NEXT_PUBLIC_WEBRTC_DEBUG') === '1'
  return new SignalingClient(userId, userType, roomId)
}

/**
 * WebRTC Client for AltaMedica Telemedicine
 * Handles peer-to-peer video/audio connections with signaling server
 */

import { logger } from '@autamedica/shared'
import { loadIceServers } from './config/ice-servers'

export interface WebRTCConfig {
  signalingUrl: string
  iceServers: RTCIceServer[]
  roomId?: string
  userId: string
  userType: 'doctor' | 'patient' | 'nurse'
}

export interface MediaConstraints {
  video: boolean | MediaTrackConstraints
  audio: boolean | MediaTrackConstraints
}

export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'failed' | 'closed'

export interface WebRTCEvents {
  'connection-state': (state: ConnectionState) => void
  'remote-stream': (stream: MediaStream, userId: string) => void
  'local-stream': (stream: MediaStream) => void
  'user-joined': (userId: string, userType: string) => void
  'user-left': (userId: string) => void
  'error': (error: Error) => void
}

interface PeerState {
  pc: RTCPeerConnection
  pendingIceCandidates: RTCIceCandidateInit[]
  isMakingOffer: boolean
  isSettingRemoteAnswerPending: boolean
  ignoreOffer: boolean
  isPolite: boolean
}

export class WebRTCClient {
  private ws: WebSocket | null = null
  private peerConnections = new Map<string, PeerState>()
  private localStream: MediaStream | null = null
  private config: WebRTCConfig
  private eventListeners = new Map<keyof WebRTCEvents, Function[]>()
  private connectionState: ConnectionState = 'disconnected'

  // Default ICE servers (using public STUN servers)
  private static readonly DEFAULT_ICE_SERVERS: RTCIceServer[] = [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun2.l.google.com:19302' }
  ]

  constructor(config: Partial<WebRTCConfig> & { userId: string; userType: 'doctor' | 'patient' | 'nurse' }) {
    // Use environment-configured ICE servers or fallback to defaults
    const iceServers = config.iceServers || loadIceServers() || WebRTCClient.DEFAULT_ICE_SERVERS

    this.config = {
      signalingUrl: 'wss://autamedica-signaling-server.ecucondor.workers.dev/signaling',
      iceServers,
      roomId: 'default-room',
      ...config
    }
  }

  // Event listener methods
  on<T extends keyof WebRTCEvents>(event: T, listener: WebRTCEvents[T]): () => void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, [])
    }
    this.eventListeners.get(event)!.push(listener)

    // Return unsubscribe function
    return () => {
      this.off(event, listener)
    }
  }

  off<T extends keyof WebRTCEvents>(event: T, listener: WebRTCEvents[T]): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      const index = listeners.indexOf(listener)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }

  private emit<T extends keyof WebRTCEvents>(event: T, ...args: Parameters<WebRTCEvents[T]>): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.forEach(listener => {
        try {
          // @ts-ignore
          listener(...args)
        } catch (error) {
          logger.error(`Error in ${event} listener:`, error)
        }
      })
    }
  }

  private setConnectionState(state: ConnectionState): void {
    if (this.connectionState !== state) {
      this.connectionState = state
      this.emit('connection-state', state)
    }
  }

  async connect(roomId?: string): Promise<void> {
    if (this.connectionState === 'connecting' || this.connectionState === 'connected') {
      return
    }

    this.setConnectionState('connecting')

    try {
      const finalRoomId = roomId || this.config.roomId!
      const wsUrl = `${this.config.signalingUrl}?roomId=${encodeURIComponent(finalRoomId)}`

      this.ws = new WebSocket(wsUrl)

      this.ws.onopen = () => {
        logger.info('WebSocket connected')
        // Join the room
        this.sendSignalingMessage({
          type: 'join',
          from: this.config.userId,
          data: { userType: this.config.userType }
        })
      }

      this.ws.onmessage = (event) => {
        this.handleSignalingMessage(JSON.parse(event.data))
      }

      this.ws.onerror = (error) => {
        logger.error('WebSocket error:', error)
        this.setConnectionState('failed')
        this.emit('error', new Error('WebSocket connection failed'))
      }

      this.ws.onclose = () => {
        logger.info('WebSocket disconnected')
        this.setConnectionState('disconnected')
        this.cleanup()
      }

      // Wait for connection
      await new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(() => {
          reject(new Error('Connection timeout'))
        }, 10000)

        const originalOnOpen = this.ws!.onopen
        this.ws!.onopen = (event) => {
          clearTimeout(timeout)
          originalOnOpen?.call(this.ws!, event)
          resolve()
        }

        const originalOnError = this.ws!.onerror
        this.ws!.onerror = (error) => {
          clearTimeout(timeout)
          originalOnError?.call(this.ws!, error)
          reject(new Error('WebSocket connection failed'))
        }
      })

    } catch (error) {
      this.setConnectionState('failed')
      throw error
    }
  }

  async startLocalStream(constraints: MediaConstraints = { video: true, audio: true }): Promise<MediaStream> {
    try {
      this.localStream = await navigator.mediaDevices.getUserMedia(constraints)
      this.emit('local-stream', this.localStream)

      // Add tracks to all existing peer connections
      for (const [, peerState] of this.peerConnections) {
        this.attachLocalTracks(peerState.pc)
      }

      return this.localStream
    } catch (error) {
      logger.error('Failed to get local stream:', error)
      this.emit('error', new Error('Failed to access camera/microphone'))
      throw error
    }
  }

  stopLocalStream(): void {
    if (this.localStream) {
      this.localStream.getTracks().forEach(track => track.stop())
      this.localStream = null
    }
  }

  async disconnect(): Promise<void> {
    this.setConnectionState('disconnected')

    if (this.ws) {
      this.sendSignalingMessage({ type: 'leave' })
      this.ws.close()
      this.ws = null
    }

    this.cleanup()
  }

  private cleanup(): void {
    // Close all peer connections
    for (const [, peerState] of this.peerConnections) {
      peerState.pc.close()
    }
    this.peerConnections.clear()

    // Stop local stream
    this.stopLocalStream()
  }

  private sendSignalingMessage(message: any): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message))
    }
  }

  private async handleSignalingMessage(message: any): Promise<void> {
    logger.info('Received signaling message:', message)

    switch (message.type) {
      case 'room-state':
        // Handle initial room state
        for (const user of message.data.users) {
          this.emit('user-joined', user.id, user.userType)
        }
        this.setConnectionState('connected')
        break

      case 'user-joined':
        this.emit('user-joined', message.from, message.data.userType)
        this.ensurePeerConnection(message.from)
        break

      case 'user-left': {
        this.emit('user-left', message.from)
        const peerState = this.peerConnections.get(message.from)
        if (peerState) {
          peerState.pc.close()
          this.peerConnections.delete(message.from)
        }
        break
      }

      case 'offer':
        await this.handleOffer(message.from, message.data)
        break

      case 'answer':
        await this.handleAnswer(message.from, message.data)
        break

      case 'ice-candidate':
        await this.handleIceCandidate(message.from, message.data)
        break

      case 'error':
        logger.error('Signaling error:', message.data)
        this.emit('error', new Error(message.data))
        break
    }
  }

  private ensurePeerConnection(userId: string): PeerState {
    let peerState = this.peerConnections.get(userId)
    if (peerState) {
      return peerState
    }

    const pc = new RTCPeerConnection({ iceServers: this.config.iceServers })
    const isPolite = this.config.userType !== 'doctor'

    peerState = {
      pc,
      pendingIceCandidates: [],
      isMakingOffer: false,
      isSettingRemoteAnswerPending: false,
      ignoreOffer: false,
      isPolite
    }

    pc.ontrack = (event) => {
      logger.info('Received remote stream from', userId)
      const stream = event.streams?.[0]
      if (stream) {
        this.emit('remote-stream', stream, userId)
      }
    }

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        this.sendSignalingMessage({
          type: 'ice-candidate',
          to: userId,
          data: event.candidate
        })
      }
    }

    pc.onconnectionstatechange = () => {
      logger.info(`Peer connection with ${userId} state:`, pc.connectionState)
      if (pc.connectionState === 'failed' || pc.connectionState === 'closed') {
        this.peerConnections.delete(userId)
      }
    }

    pc.onnegotiationneeded = async () => {
      if (!peerState || peerState.isPolite) {
        return
      }

      try {
        peerState!.isMakingOffer = true
        await pc.setLocalDescription()

        if (pc.localDescription) {
          this.sendSignalingMessage({
            type: 'offer',
            to: userId,
            data: pc.localDescription
          })
        }
      } catch (error) {
        logger.error('Failed to handle negotiationneeded:', error)
      } finally {
        if (peerState) {
          peerState.isMakingOffer = false
        }
      }
    }

    this.attachLocalTracks(pc)

    this.peerConnections.set(userId, peerState)
    return peerState
  }

  private attachLocalTracks(pc: RTCPeerConnection): void {
    const stream = this.localStream
    if (!stream) return

    const existingTrackIds = new Set(
      pc.getSenders()
        .map(sender => sender.track?.id)
        .filter((id): id is string => Boolean(id))
    )

    stream.getTracks().forEach(track => {
      if (!existingTrackIds.has(track.id)) {
        pc.addTrack(track, stream)
      }
    })
  }

  private async handleOffer(userId: string, offer: RTCSessionDescriptionInit): Promise<void> {
    const peerState = this.ensurePeerConnection(userId)
    const { pc } = peerState

    const offerCollision = peerState.isMakingOffer || pc.signalingState !== 'stable'

    peerState.ignoreOffer = !peerState.isPolite && offerCollision
    if (peerState.ignoreOffer) {
      logger.warn('Ignoring offer due to collision (impolite peer)')
      return
    }

    try {
      if (offerCollision) {
        logger.info('Offer collision detected, rolling back local description')
        await pc.setLocalDescription({ type: 'rollback' })
      }

      await pc.setRemoteDescription(new RTCSessionDescription(offer))
      this.attachLocalTracks(pc)

      const answer = await pc.createAnswer()
      await pc.setLocalDescription(answer)

      this.sendSignalingMessage({
        type: 'answer',
        to: userId,
        data: answer
      })

      await this.flushPendingIceCandidates(peerState)
      peerState.ignoreOffer = false
    } catch (error) {
      logger.error('Failed to handle offer:', error)
    }
  }

  private async handleAnswer(userId: string, answer: RTCSessionDescriptionInit): Promise<void> {
    const peerState = this.peerConnections.get(userId)
    if (!peerState) return

    try {
      peerState.isSettingRemoteAnswerPending = true
      await peerState.pc.setRemoteDescription(new RTCSessionDescription(answer))
      await this.flushPendingIceCandidates(peerState)
    } catch (error) {
      logger.error('Failed to handle answer:', error)
    } finally {
      peerState.isSettingRemoteAnswerPending = false
      peerState.ignoreOffer = false
    }
  }

  private async handleIceCandidate(userId: string, candidate: RTCIceCandidateInit): Promise<void> {
    const peerState = this.ensurePeerConnection(userId)
    const { pc } = peerState

    if (pc.remoteDescription) {
      try {
        await pc.addIceCandidate(new RTCIceCandidate(candidate))
      } catch (error) {
        logger.error('Failed to add ICE candidate:', error)
      }
    } else {
      logger.info('Remote description not set yet, queuing ICE candidate')
      peerState.pendingIceCandidates.push(candidate)
    }
  }

  private async flushPendingIceCandidates(peerState: PeerState): Promise<void> {
    if (!peerState.pc.remoteDescription) {
      return
    }

    while (peerState.pendingIceCandidates.length > 0) {
      const candidateInit = peerState.pendingIceCandidates.shift()!
      try {
        await peerState.pc.addIceCandidate(new RTCIceCandidate(candidateInit))
      } catch (error) {
        logger.error('Failed to add queued ICE candidate:', error)
      }
    }
  }

  // Utility methods
  getConnectionState(): ConnectionState {
    return this.connectionState
  }

  getLocalStream(): MediaStream | null {
    return this.localStream
  }

  getPeerConnections(): Map<string, RTCPeerConnection> {
    const map = new Map<string, RTCPeerConnection>()
    for (const [userId, peerState] of this.peerConnections) {
      map.set(userId, peerState.pc)
    }
    return map
  }

  // Media control methods
  toggleVideo(enabled?: boolean): boolean {
    if (!this.localStream) return false

    const videoTrack = this.localStream.getVideoTracks()[0]
    if (videoTrack) {
      videoTrack.enabled = enabled !== undefined ? enabled : !videoTrack.enabled
      return videoTrack.enabled
    }
    return false
  }

  toggleAudio(enabled?: boolean): boolean {
    if (!this.localStream) return false

    const audioTrack = this.localStream.getAudioTracks()[0]
    if (audioTrack) {
      audioTrack.enabled = enabled !== undefined ? enabled : !audioTrack.enabled
      return audioTrack.enabled
    }
    return false
  }

  isVideoEnabled(): boolean {
    if (!this.localStream) return false
    const videoTrack = this.localStream.getVideoTracks()[0]
    return videoTrack ? videoTrack.enabled : false
  }

  isAudioEnabled(): boolean {
    if (!this.localStream) return false
    const audioTrack = this.localStream.getAudioTracks()[0]
    return audioTrack ? audioTrack.enabled : false
  }
}

import { getClientEnvOrDefault, logger } from '@autamedica/shared'
import type { SignalingClient } from '../signaling/client'

// WebRTC peer connection manager
export class WebRTCPeer {
  private pc: RTCPeerConnection
  private signaling: SignalingClient
  private localStream: MediaStream | null = null
  private remoteStream: MediaStream | null = null
  private isInitiator: boolean
  private listeners: Map<string, Set<(event: any) => void>> = new Map()

  constructor(signaling: SignalingClient, isInitiator = false) {
    this.signaling = signaling
    this.isInitiator = isInitiator

    // Parse ICE servers from environment
    const iceServers = this.parseIceServers()

    this.pc = new RTCPeerConnection({
      iceServers,
      iceCandidatePoolSize: 10
    })

    this.setupPeerConnection()
    this.setupSignalingHandlers()
  }

  private parseIceServers(): RTCIceServer[] {
    try {
      const iceServersStr = getClientEnvOrDefault('NEXT_PUBLIC_ICE_SERVERS', '[]')
      const parsed = JSON.parse(iceServersStr)
      if (Array.isArray(parsed)) return parsed
      logger.warn('[WebRTCPeer] NEXT_PUBLIC_ICE_SERVERS must be a JSON array; falling back to default')
    } catch (error) {
      logger.error('[WebRTCPeer] Failed to parse NEXT_PUBLIC_ICE_SERVERS:', error)
    }

    // Default ICE servers
    return [
      { urls: ['stun:stun.l.google.com:19302'] }
    ]
  }

  private setupPeerConnection() {
    this.pc.onicecandidate = (event) => {
      if (event.candidate) {
        this.signaling.sendToRoom({
          type: 'candidate',
          candidate: event.candidate
        })
      }
    }

    this.pc.onconnectionstatechange = () => {
      logger.info('[WebRTCPeer] Connection state:', this.pc.connectionState)
      this.emit('connectionstatechange', { state: this.pc.connectionState })

      if (this.pc.connectionState === 'connected') {
        this.emit('connected')
      } else if (this.pc.connectionState === 'failed') {
        this.emit('failed')
      }
    }

    this.pc.oniceconnectionstatechange = () => {
      logger.info('[WebRTCPeer] ICE connection state:', this.pc.iceConnectionState)
      this.emit('iceconnectionstatechange', { state: this.pc.iceConnectionState })
    }

    this.pc.ontrack = (event) => {
      logger.info('[WebRTCPeer] Received remote track')

      if (!this.remoteStream) {
        this.remoteStream = new MediaStream()
      }

      // Add tracks to remote stream
      event.streams[0]?.getTracks().forEach(track => {
        if (this.remoteStream && !this.remoteStream.getTracks().some(t => t.id === track.id)) {
          this.remoteStream.addTrack(track)
        }
      })

      this.emit('remotestream', { stream: this.remoteStream })
    }
  }

  private setupSignalingHandlers() {
    this.signaling.onRoomMessage(async (message) => {
      try {
        switch (message.type) {
          case 'offer':
            await this.handleOffer(message.sdp)
            break
          case 'answer':
            await this.handleAnswer(message.sdp)
            break
          case 'candidate':
            await this.handleCandidate(message.candidate)
            break
        }
      } catch (error) {
        logger.error('[WebRTCPeer] Error handling signaling message:', error)
        this.emit('error', { error })
      }
    })
  }

  async startCall(): Promise<void> {
    try {
      // Get user media
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        },
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 },
          frameRate: { ideal: 30 }
        }
      })

      this.localStream = stream
      this.emit('localstream', { stream })

      // Add tracks to peer connection
      stream.getTracks().forEach(track => {
        this.pc.addTrack(track, stream)
      })

      // If initiator, create offer
      if (this.isInitiator) {
        await this.createOffer()
      }

    } catch (error) {
      logger.error('[WebRTCPeer] Failed to start call:', error)
      this.emit('error', { error })
      throw error
    }
  }

  private async createOffer(): Promise<void> {
    const offer = await this.pc.createOffer()
    await this.pc.setLocalDescription(offer)

    this.signaling.sendToRoom({
      type: 'offer',
      sdp: offer.sdp!
    })
  }

  private async handleOffer(sdp: string): Promise<void> {
    await this.pc.setRemoteDescription({ type: 'offer', sdp })

    const answer = await this.pc.createAnswer()
    await this.pc.setLocalDescription(answer)

    this.signaling.sendToRoom({
      type: 'answer',
      sdp: answer.sdp!
    })
  }

  private async handleAnswer(sdp: string): Promise<void> {
    await this.pc.setRemoteDescription({ type: 'answer', sdp })
  }

  private async handleCandidate(candidate: RTCIceCandidate): Promise<void> {
    await this.pc.addIceCandidate(candidate)
  }

  hangup(): void {
    // Stop local tracks
    this.localStream?.getTracks().forEach(track => track.stop())

    // Close peer connection
    this.pc.close()

    // Clear streams
    this.localStream = null
    this.remoteStream = null

    this.emit('hangup')
  }

  // Event handling
  on(event: string, callback: (data: any) => void) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event)!.add(callback)

    return () => {
      this.listeners.get(event)?.delete(callback)
    }
  }

  off(event: string, callback: (data: any) => void) {
    this.listeners.get(event)?.delete(callback)
  }

  private emit(event: string, data?: any) {
    const listeners = this.listeners.get(event)
    if (listeners) {
      listeners.forEach(callback => callback(data))
    }
  }

  // Getters
  get connectionState(): RTCPeerConnectionState {
    return this.pc.connectionState
  }

  get iceConnectionState(): RTCIceConnectionState {
    return this.pc.iceConnectionState
  }

  get localMediaStream(): MediaStream | null {
    return this.localStream
  }

  get remoteMediaStream(): MediaStream | null {
    return this.remoteStream
  }

  // Statistics
  async getStats(): Promise<RTCStatsReport> {
    return await this.pc.getStats()
  }

  async getSelectedCandidatePair(): Promise<RTCIceCandidatePairStats | null> {
    const stats = await this.getStats()
    let selected: RTCIceCandidatePairStats | null = null

    stats.forEach((report) => {
      if (report.type === 'candidate-pair' && (report as RTCIceCandidatePairStats).state === 'succeeded') {
        selected = report as RTCIceCandidatePairStats
      }
    })

    return selected
  }
}

