const { createClient } = require('@supabase/supabase-js')

const supabaseUrl = 'https://knywotiidsydsaveqkjs.supabase.co'
const supabaseKey = 'REPLACE_WITH_ROTATED_KEY.DeEm08k7QOrKObWaz8AUaOB5N6Z2QZhZHFaUf2siALA'

// IDs de prueba
const DOCTOR_ID = 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11'
const PATIENT_ID = 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12'
const SIGNALING_URL = 'http://localhost:8080'

class HTTPSignalingAuditor {
  constructor() {
    this.supabase = createClient(supabaseUrl, supabaseKey)
    this.callData = null
    this.auditLog = []
  }

  log(phase, message, data = null) {
    const timestamp = new Date().toISOString()
    const logEntry = { timestamp, phase, message, data }
    this.auditLog.push(logEntry)

    console.log(`[${timestamp}] 📋 ${phase}: ${message}`)
    if (data) {
      console.log(`   📄 Data:`, JSON.stringify(data, null, 2))
    }
  }

  async checkSignalingServer() {
    this.log('SIGNALING_CHECK', 'Verificando signaling server HTTP...')

    try {
      const response = await fetch(`${SIGNALING_URL}/health`)

      if (response.ok) {
        const healthData = await response.json()
        this.log('SIGNALING_SUCCESS', '✅ Signaling server HTTP disponible', healthData)
        return true
      } else {
        this.log('SIGNALING_WARNING', '⚠️ Signaling server responde pero sin /health', {
          status: response.status,
          statusText: response.statusText
        })
        return true // Puede funcionar sin endpoint /health
      }
    } catch (error) {
      this.log('SIGNALING_ERROR', '❌ Signaling server no disponible', error.message)
      throw error
    }
  }

  async testSignalingEndpoints() {
    this.log('ENDPOINTS_TEST', 'Probando endpoints del signaling server...')

    const endpoints = [
      { path: '/', method: 'GET', description: 'Root endpoint' },
      { path: '/api/signaling/health', method: 'GET', description: 'Health check' },
      { path: '/api/signaling/invite', method: 'POST', description: 'Send invitation' },
      { path: '/api/signaling/rooms', method: 'GET', description: 'List rooms' }
    ]

    const results = []

    for (const endpoint of endpoints) {
      try {
        const options = {
          method: endpoint.method,
          headers: {
            'Content-Type': 'application/json'
          }
        }

        // Para POST, agregar un body de prueba
        if (endpoint.method === 'POST') {
          options.body = JSON.stringify({
            type: 'test',
            from: DOCTOR_ID,
            to: PATIENT_ID
          })
        }

        const response = await fetch(`${SIGNALING_URL}${endpoint.path}`, options)

        results.push({
          path: endpoint.path,
          method: endpoint.method,
          status: response.status,
          available: response.status < 500
        })

        this.log('ENDPOINT_TEST', `${endpoint.method} ${endpoint.path}: ${response.status}`)

      } catch (error) {
        results.push({
          path: endpoint.path,
          method: endpoint.method,
          error: error.message,
          available: false
        })

        this.log('ENDPOINT_ERROR', `${endpoint.method} ${endpoint.path}: Error - ${error.message}`)
      }
    }

    return results
  }

  async createCall() {
    this.log('DB_CALL_CREATE', 'Creando llamada en base de datos...')

    try {
      const { data, error } = await this.supabase
        .rpc('create_call', {
          p_doctor_id: DOCTOR_ID,
          p_patient_id: PATIENT_ID
        })

      if (error) {
        this.log('DB_ERROR', '❌ Error creando llamada en DB (usando fallback)', error)

        // Fallback: simular datos de llamada
        this.callData = {
          id: 'test-call-' + Date.now(),
          room_id: 'room_' + Math.random().toString(36).substr(2, 8),
          doctor_id: DOCTOR_ID,
          patient_id: PATIENT_ID,
          status: 'requested',
          created_at: new Date().toISOString()
        }

        this.log('FALLBACK_CALL', '🔄 Usando datos de llamada simulados', this.callData)
        return this.callData
      }

      this.callData = data[0]
      this.log('DB_CALL_SUCCESS', '✅ Llamada creada en DB', this.callData)
      return this.callData

    } catch (error) {
      this.log('DB_CALL_FAILED', '❌ No se pudo crear llamada en DB', error.message)
      throw error
    }
  }

  async sendSignalingInvitation() {
    this.log('SIGNALING_INVITE', 'Enviando invitación via HTTP signaling...')

    const invitePayload = {
      type: 'call_invite',
      callId: this.callData.id,
      roomId: this.callData.room_id,
      from: DOCTOR_ID,
      to: PATIENT_ID,
      fromType: 'doctor',
      toType: 'patient',
      timestamp: Date.now()
    }

    try {
      const response = await fetch(`${SIGNALING_URL}/api/signaling/invite`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(invitePayload)
      })

      if (response.ok) {
        const result = await response.json()
        this.log('SIGNALING_SUCCESS', '✅ Invitación enviada exitosamente', result)
        return result
      } else {
        const error = await response.text()
        this.log('SIGNALING_FAILED', '❌ Error enviando invitación', {
          status: response.status,
          error
        })
        return null
      }
    } catch (error) {
      this.log('SIGNALING_ERROR', '❌ Error de red enviando invitación', error.message)
      return null
    }
  }

  async checkPatientNotifications() {
    this.log('PATIENT_CHECK', 'Verificando notificaciones para paciente...')

    try {
      const response = await fetch(`${SIGNALING_URL}/api/signaling/messages/${PATIENT_ID}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json'
        }
      })

      if (response.ok) {
        const messages = await response.json()
        this.log('PATIENT_MESSAGES', '✅ Mensajes para paciente obtenidos', messages)

        // Verificar si hay invitaciones pendientes
        const invitations = messages.filter(msg => msg.type === 'call_invite')
        if (invitations.length > 0) {
          this.log('INVITATION_FOUND', '🎉 ¡Invitación encontrada para paciente!', invitations[0])
          return invitations[0]
        } else {
          this.log('NO_INVITATIONS', '⚠️ No se encontraron invitaciones para paciente')
          return null
        }
      } else {
        this.log('PATIENT_ERROR', '❌ Error obteniendo mensajes de paciente', response.status)
        return null
      }
    } catch (error) {
      this.log('PATIENT_FETCH_ERROR', '❌ Error de red obteniendo mensajes', error.message)
      return null
    }
  }

  async simulatePatientAcceptance(invitation) {
    this.log('PATIENT_ACCEPT', 'Simulando aceptación de llamada por paciente...')

    // 1. Actualizar estado en DB
    try {
      const { data, error } = await this.supabase
        .rpc('update_call_status', {
          p_call_id: invitation.callId,
          p_status: 'accepted'
        })

      if (!error) {
        this.log('DB_ACCEPT_SUCCESS', '✅ Estado actualizado a "accepted" en DB')
      } else {
        this.log('DB_ACCEPT_FAILED', '⚠️ No se pudo actualizar DB, continuando...', error)
      }
    } catch (error) {
      this.log('DB_ACCEPT_ERROR', '⚠️ Error actualizando DB, continuando...', error.message)
    }

    // 2. Enviar respuesta via signaling
    const acceptPayload = {
      type: 'call_accepted',
      callId: invitation.callId,
      roomId: invitation.roomId,
      from: PATIENT_ID,
      to: DOCTOR_ID,
      timestamp: Date.now()
    }

    try {
      const response = await fetch(`${SIGNALING_URL}/api/signaling/accept`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(acceptPayload)
      })

      if (response.ok) {
        const result = await response.json()
        this.log('ACCEPT_SUCCESS', '✅ Aceptación enviada exitosamente', result)
        return result
      } else {
        this.log('ACCEPT_FAILED', '❌ Error enviando aceptación', response.status)
        return null
      }
    } catch (error) {
      this.log('ACCEPT_ERROR', '❌ Error de red enviando aceptación', error.message)
      return null
    }
  }

  async runFullAudit() {
    console.log('\n🔍 INICIANDO AUDITORÍA HTTP SIGNALING COMPLETA\n')

    try {
      // 1. Verificar signaling server
      await this.checkSignalingServer()

      // 2. Probar endpoints
      const endpointResults = await this.testSignalingEndpoints()

      // 3. Crear llamada en DB
      await this.createCall()

      // 4. Enviar invitación via signaling
      const inviteResult = await this.sendSignalingInvitation()

      // 5. Verificar que el paciente reciba la notificación
      await new Promise(resolve => setTimeout(resolve, 1000)) // Esperar 1s
      const invitation = await this.checkPatientNotifications()

      // 6. Simular aceptación si se encontró invitación
      if (invitation) {
        await this.simulatePatientAcceptance(invitation)
      }

      // 7. Generar reporte final
      this.generateAuditReport(endpointResults)

    } catch (error) {
      this.log('AUDIT_ERROR', '❌ Error en auditoría', error.message)
      this.generateAuditReport([], error)
    }
  }

  generateAuditReport(endpointResults = [], error = null) {
    console.log('\n📊 REPORTE DE AUDITORÍA HTTP SIGNALING FINAL\n')
    console.log('='.repeat(60))

    if (error) {
      console.log('❌ AUDITORÍA FALLIDA:', error.message)
    } else {
      console.log('✅ AUDITORÍA COMPLETADA')
    }

    console.log('\n🔗 INFRAESTRUCTURA:')
    console.log('  - Supabase DB:', supabaseUrl)
    console.log('  - Signaling HTTP:', SIGNALING_URL)
    console.log('  - Doctor App: http://localhost:4001')
    console.log('  - Patient App: http://localhost:4002')

    console.log('\n📋 ENDPOINTS PROBADOS:')
    endpointResults.forEach(endpoint => {
      const status = endpoint.available ? '✅' : '❌'
      console.log(`  ${status} ${endpoint.method} ${endpoint.path} (${endpoint.status || endpoint.error})`)
    })

    console.log('\n🎯 FASES EJECUTADAS:')
    const phases = [...new Set(this.auditLog.map(log => log.phase))]
    phases.forEach(phase => {
      const phaseLogs = this.auditLog.filter(log => log.phase === phase)
      const success = phaseLogs.some(log => log.message.includes('✅'))
      console.log(`  ${success ? '✅' : '❌'} ${phase} (${phaseLogs.length} eventos)`)
    })

    console.log('\n📝 SIGUIENTE PASO:')
    if (error) {
      console.log('  ❌ Revisar signaling server y endpoints')
    } else {
      console.log('  ✅ Probar manualmente en Doctors App (http://localhost:4001)')
      console.log('  ✅ Verificar Patients App (http://localhost:4002)')
    }

    console.log('\n📄 Log detallado guardado en audit-http-log.json')
    require('fs').writeFileSync('audit-http-log.json', JSON.stringify(this.auditLog, null, 2))
  }
}

async function main() {
  const auditor = new HTTPSignalingAuditor()
  await auditor.runFullAudit()
}

if (require.main === module) {
  main().catch(console.error)
}

module.exports = HTTPSignalingAuditor

#!/usr/bin/env node

const WebSocket = require('ws')
const { createClient } = require('@supabase/supabase-js')

const supabaseUrl = 'https://knywotiidsydsaveqkjs.supabase.co'
const supabaseKey = 'REPLACE_WITH_ROTATED_KEY.DeEm08k7QOrKObWaz8AUaOB5N6Z2QZhZHFaUf2siALA'

// IDs de prueba
const DOCTOR_ID = 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11'
const PATIENT_ID = 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12'

class SignalingAuditor {
  constructor() {
    this.supabase = createClient(supabaseUrl, supabaseKey)
    this.doctorWs = null
    this.patientWs = null
    this.callData = null
    this.auditLog = []
  }

  log(phase, message, data = null) {
    const timestamp = new Date().toISOString()
    const logEntry = { timestamp, phase, message, data }
    this.auditLog.push(logEntry)

    console.log(`[${timestamp}] 📋 ${phase}: ${message}`)
    if (data) {
      console.log(`   📄 Data:`, data)
    }
  }

  async checkSignalingServer() {
    this.log('INFRASTRUCTURE', 'Verificando signaling server...')

    // URLs posibles del signaling server
    const signalingUrls = [
      'ws://localhost:3001',
      'ws://localhost:8080',
      'wss://altamedica-signaling.pages.dev',
      'ws://localhost:3000/api/ws'
    ]

    for (const url of signalingUrls) {
      try {
        this.log('CONNECTION_TEST', `Probando conexión a: ${url}`)

        const testWs = new WebSocket(url)

        await new Promise((resolve, reject) => {
          const timeout = setTimeout(() => {
            testWs.close()
            reject(new Error('Timeout'))
          }, 3000)

          testWs.on('open', () => {
            clearTimeout(timeout)
            this.log('CONNECTION_SUCCESS', `✅ Signaling server activo en: ${url}`)
            testWs.close()
            resolve(url)
          })

          testWs.on('error', (error) => {
            clearTimeout(timeout)
            reject(error)
          })
        })

        return url // Retorna el primer servidor que funcione

      } catch (error) {
        this.log('CONNECTION_FAILED', `❌ No disponible: ${url} - ${error.message}`)
      }
    }

    throw new Error('❌ No se encontró ningún signaling server activo')
  }

  async setupWebSocketConnections(signalingUrl) {
    this.log('WS_SETUP', 'Configurando conexiones WebSocket...')

    // Conexión del doctor
    this.doctorWs = new WebSocket(signalingUrl)
    this.doctorWs.on('open', () => {
      this.log('WS_DOCTOR', '✅ Doctor conectado al signaling server')
      this.doctorWs.send(JSON.stringify({
        type: 'join',
        userId: DOCTOR_ID,
        userType: 'doctor'
      }))
    })

    this.doctorWs.on('message', (data) => {
      const message = JSON.parse(data.toString())
      this.log('WS_DOCTOR_MSG', 'Doctor recibió mensaje', message)
    })

    // Conexión del paciente
    this.patientWs = new WebSocket(signalingUrl)
    this.patientWs.on('open', () => {
      this.log('WS_PATIENT', '✅ Paciente conectado al signaling server')
      this.patientWs.send(JSON.stringify({
        type: 'join',
        userId: PATIENT_ID,
        userType: 'patient'
      }))
    })

    this.patientWs.on('message', (data) => {
      const message = JSON.parse(data.toString())
      this.log('WS_PATIENT_MSG', 'Paciente recibió mensaje', message)

      // Verificar si es una invitación de llamada
      if (message.type === 'call_invite') {
        this.log('CALL_INVITE_RECEIVED', '🎉 Paciente recibió invitación de llamada!', message)

        // Simular aceptación automática después de 2 segundos
        setTimeout(() => {
          this.simulateCallAcceptance(message)
        }, 2000)
      }
    })

    // Esperar a que ambas conexiones estén listas
    await this.waitForConnections()
  }

  async waitForConnections() {
    return new Promise((resolve) => {
      let doctorReady = false
      let patientReady = false

      const checkReady = () => {
        if (doctorReady && patientReady) {
          this.log('WS_READY', '✅ Ambas conexiones WebSocket listas')
          resolve()
        }
      }

      this.doctorWs.on('open', () => {
        doctorReady = true
        checkReady()
      })

      this.patientWs.on('open', () => {
        patientReady = true
        checkReady()
      })
    })
  }

  async createCall() {
    this.log('DB_CALL_CREATE', 'Creando llamada en base de datos...')

    try {
      const { data, error } = await this.supabase
        .rpc('create_call', {
          p_doctor_id: DOCTOR_ID,
          p_patient_id: PATIENT_ID
        })

      if (error) {
        this.log('DB_ERROR', '❌ Error creando llamada', error)
        throw error
      }

      this.callData = data[0]
      this.log('DB_CALL_SUCCESS', '✅ Llamada creada en DB', this.callData)
      return this.callData

    } catch (error) {
      this.log('DB_CALL_FAILED', '❌ No se pudo crear llamada en DB', error.message)

      // Fallback: simular datos de llamada
      this.callData = {
        id: 'test-call-' + Date.now(),
        room_id: 'room_' + Math.random().toString(36).substr(2, 8),
        doctor_id: DOCTOR_ID,
        patient_id: PATIENT_ID,
        status: 'requested',
        created_at: new Date().toISOString()
      }

      this.log('FALLBACK_CALL', '🔄 Usando datos de llamada simulados', this.callData)
      return this.callData
    }
  }

  async sendCallInvitation() {
    this.log('SIGNALING_INVITE', 'Enviando invitación de llamada via signaling...')

    const inviteMessage = {
      type: 'call_invite',
      callId: this.callData.id,
      roomId: this.callData.room_id,
      from: DOCTOR_ID,
      to: PATIENT_ID,
      fromType: 'doctor',
      toType: 'patient',
      timestamp: Date.now()
    }

    this.doctorWs.send(JSON.stringify(inviteMessage))
    this.log('SIGNALING_SENT', '📤 Invitación enviada por doctor', inviteMessage)
  }

  async simulateCallAcceptance(inviteMessage) {
    this.log('CALL_ACCEPTANCE', 'Simulando aceptación de llamada por paciente...')

    // Actualizar estado en DB
    try {
      const { data, error } = await this.supabase
        .rpc('update_call_status', {
          p_call_id: inviteMessage.callId,
          p_status: 'accepted'
        })

      if (!error) {
        this.log('DB_ACCEPT_SUCCESS', '✅ Estado actualizado a "accepted" en DB')
      }
    } catch (error) {
      this.log('DB_ACCEPT_FAILED', '⚠️ No se pudo actualizar DB, pero continuando...')
    }

    // Enviar respuesta via signaling
    const acceptMessage = {
      type: 'call_accepted',
      callId: inviteMessage.callId,
      roomId: inviteMessage.roomId,
      from: PATIENT_ID,
      to: DOCTOR_ID,
      timestamp: Date.now()
    }

    this.patientWs.send(JSON.stringify(acceptMessage))
    this.log('CALL_ACCEPTED', '✅ Paciente aceptó llamada', acceptMessage)
  }

  async runFullAudit() {
    console.log('\n🔍 INICIANDO AUDITORÍA COMPLETA DEL SISTEMA DE LLAMADAS\n')

    try {
      // 1. Verificar signaling server
      const signalingUrl = await this.checkSignalingServer()

      // 2. Configurar conexiones WebSocket
      await this.setupWebSocketConnections(signalingUrl)

      // 3. Crear llamada en DB
      await this.createCall()

      // 4. Enviar invitación via signaling
      await this.sendCallInvitation()

      // 5. Esperar respuesta del paciente (timeout 10 segundos)
      await this.waitForCallResponse()

      // 6. Generar reporte final
      this.generateAuditReport()

    } catch (error) {
      this.log('AUDIT_ERROR', '❌ Error en auditoría', error.message)
      this.generateAuditReport(error)
    } finally {
      this.cleanup()
    }
  }

  async waitForCallResponse() {
    this.log('WAITING_RESPONSE', 'Esperando respuesta del paciente (10s timeout)...')

    return new Promise((resolve) => {
      const timeout = setTimeout(() => {
        this.log('TIMEOUT', '⏱️ Timeout esperando respuesta del paciente')
        resolve()
      }, 10000)

      const originalPatientHandler = this.patientWs.onmessage
      this.patientWs.onmessage = (event) => {
        const message = JSON.parse(event.data)
        if (message.type === 'call_accepted') {
          clearTimeout(timeout)
          this.log('RESPONSE_RECEIVED', '✅ Respuesta del paciente recibida')
          resolve()
        }
        if (originalPatientHandler) originalPatientHandler(event)
      }
    })
  }

  generateAuditReport(error = null) {
    console.log('\n📊 REPORTE DE AUDITORÍA FINAL\n')
    console.log('='.repeat(60))

    if (error) {
      console.log('❌ AUDITORÍA FALLIDA:', error.message)
    } else {
      console.log('✅ AUDITORÍA COMPLETADA')
    }

    console.log('\n📋 Fases ejecutadas:')
    const phases = [...new Set(this.auditLog.map(log => log.phase))]
    phases.forEach(phase => {
      const phaseLogs = this.auditLog.filter(log => log.phase === phase)
      const success = phaseLogs.some(log => log.message.includes('✅'))
      console.log(`  ${success ? '✅' : '❌'} ${phase} (${phaseLogs.length} eventos)`)
    })

    console.log('\n🔗 URLs verificadas:')
    console.log('  - Supabase:', supabaseUrl)
    console.log('  - Doctor App: http://localhost:4001')
    console.log('  - Patient App: http://localhost:4002')

    console.log('\n📝 Log completo guardado en audit-log.json')
    require('fs').writeFileSync('audit-log.json', JSON.stringify(this.auditLog, null, 2))
  }

  cleanup() {
    if (this.doctorWs) this.doctorWs.close()
    if (this.patientWs) this.patientWs.close()
    this.log('CLEANUP', '🧹 Conexiones cerradas')
  }
}

async function main() {
  const auditor = new SignalingAuditor()
  await auditor.runFullAudit()
}

if (require.main === module) {
  main().catch(console.error)
}

module.exports = SignalingAuditor

#!/usr/bin/env node
/* eslint-disable @typescript-eslint/no-require-imports */

/**
 * AutaMedica Auth SSO Monitoring Script
 * Verifica la salud del sistema de autenticación enterprise
 */

const https = require('https');
const fs = require('fs');
const path = require('path');
const domainsConfig = require('./config/domains.js');

const { URLS, PAGES_TARGETS, DOMAINS } = domainsConfig;

const MONITORING_CONFIG = {
  // URLs a monitorear (con soporte para BASE_URL de environment)
  endpoints: {
    webApp: process.env.BASE_URL || URLS.web,
    authHub: process.env.AUTH_HUB_URL || URLS.authHub,
    doctors: process.env.DOCTORS_URL || URLS.doctors,
    patients: process.env.PATIENTS_URL || URLS.patients,
    companies: process.env.COMPANIES_URL || URLS.companies,
    admin: process.env.ADMIN_URL || URLS.admin,
    doctorsPages: `https://${PAGES_TARGETS.doctors}`,
    patientsPages: `https://${PAGES_TARGETS.patients}`,
    companiesPages: `https://${PAGES_TARGETS.companies}`,
    adminPages: `https://${PAGES_TARGETS.admin}`,
  },

  // Rutas críticas para verificar redirects
  criticalPaths: [
    '/auth/login',
    '/auth/register',
    '/auth/forgot-password'
  ],

  // Headers de seguridad requeridos
  requiredSecurityHeaders: [
    'content-security-policy',
    'x-frame-options',
    'x-content-type-options',
    'referrer-policy'
  ],

  // Timeouts
  timeout: 10000,
  retries: 3
};

class AuthMonitor {
  constructor() {
    this.results = {
      timestamp: new Date().toISOString(),
      checks: [],
      summary: {
        total: 0,
        passed: 0,
        failed: 0,
        warnings: 0
      }
    };
  }

  async run() {
    console.log('🔒 AutaMedica Auth SSO Monitor v1.0');
    console.log('=====================================');
    console.log(`⏰ ${this.results.timestamp}`);
    console.log('');

    await this.checkAuthRedirects();
    await this.checkSecurityHeaders();
    await this.checkPortalConnectivity();
    await this.checkCookieCompliance();

    this.generateReport();
    this.saveResults();

    return this.results;
  }

  async checkAuthRedirects() {
    console.log('📍 Verificando disponibilidad de rutas de auth...');

    for (const path of MONITORING_CONFIG.criticalPaths) {
      const check = {
        type: 'auth_redirect',
        path,
        timestamp: new Date().toISOString(),
        status: 'running'
      };

      try {
        const result = await this.makeRequest(MONITORING_CONFIG.endpoints.authHub + path, {
          followRedirects: false
        });

        const expectedTarget = `${DOMAINS.authHub}/auth`;
        const actualLocation = result.headers.location || '';

        if (
          [200, 301, 302, 307, 308].includes(result.statusCode) &&
          (!actualLocation || actualLocation.includes(expectedTarget))
        ) {
          check.status = 'passed';
          check.message = `✅ ${path} → ${result.statusCode} ${actualLocation ? `→ ${actualLocation}` : ''}`;
          this.results.summary.passed++;
        } else {
          check.status = 'failed';
          check.message = `❌ ${path} → ${result.statusCode} → ${actualLocation}`;
          this.results.summary.failed++;
        }

      } catch (error) {
        check.status = 'failed';
        check.message = `❌ Error: ${error.message}`;
        this.results.summary.failed++;
      }

      this.results.checks.push(check);
      console.log(`  ${check.message}`);
    }

    this.results.summary.total += MONITORING_CONFIG.criticalPaths.length;
  }

  async checkSecurityHeaders() {
    console.log('\n🛡️  Verificando headers de seguridad...');

    const check = {
      type: 'security_headers',
      timestamp: new Date().toISOString(),
      status: 'running',
      details: {}
    };

    try {
      const result = await this.makeRequest(MONITORING_CONFIG.endpoints.webApp);

      for (const headerName of MONITORING_CONFIG.requiredSecurityHeaders) {
        const headerValue = result.headers[headerName];

        if (headerValue) {
          check.details[headerName] = {
            status: '✅',
            value: headerValue.substring(0, 100) + (headerValue.length > 100 ? '...' : '')
          };
        } else {
          check.details[headerName] = {
            status: '❌',
            value: 'Missing'
          };
          this.results.summary.failed++;
        }
      }

      // Verificar CSP específico para AutaMedica
      const csp = result.headers['content-security-policy'] || '';
      if (csp.includes('*.autamedica.com') && csp.includes('*.supabase.co')) {
        check.cspCompliance = '✅ CSP configurado para AutaMedica domains';
      } else {
        check.cspCompliance = '⚠️ CSP podría necesitar ajustes para AutaMedica';
        this.results.summary.warnings++;
      }

      check.status = 'completed';
      check.message = 'Security headers verification completed';

    } catch (error) {
      check.status = 'failed';
      check.message = `❌ Error verificando headers: ${error.message}`;
      this.results.summary.failed++;
    }

    this.results.checks.push(check);
    this.results.summary.total++;

    // Log results
    for (const [header, details] of Object.entries(check.details)) {
      console.log(`  ${details.status} ${header}: ${details.value}`);
    }
    if (check.cspCompliance) {
      console.log(`  ${check.cspCompliance}`);
    }
  }

  async checkPortalConnectivity() {
    console.log('\n🌐 Verificando conectividad de portales...');

    const portals = ['doctors', 'patients', 'companies', 'admin'];

    for (const portal of portals) {
      const check = {
        type: 'portal_connectivity',
        portal,
        timestamp: new Date().toISOString(),
        status: 'running'
      };

      try {
        const url = MONITORING_CONFIG.endpoints[portal];
        const result = await this.makeRequest(url);

        if (result.statusCode >= 200 && result.statusCode < 400) {
          check.status = 'passed';
          check.message = `✅ ${portal} portal: ${result.statusCode}`;
          this.results.summary.passed++;
        } else {
          check.status = 'warning';
          check.message = `⚠️ ${portal} portal: ${result.statusCode} (podría requerir auth)`;
          this.results.summary.warnings++;
        }

      } catch (error) {
        check.status = 'failed';
        check.message = `❌ ${portal} portal: ${error.message}`;
        this.results.summary.failed++;
      }

      this.results.checks.push(check);
      console.log(`  ${check.message}`);
    }

    this.results.summary.total += portals.length;
  }

  async checkCookieCompliance() {
    console.log('\n🍪 Verificando compliance de cookies...');

    const check = {
      type: 'cookie_compliance',
      timestamp: new Date().toISOString(),
      status: 'info',
      message: 'ℹ️ Cookie compliance requiere verificación manual en Auth Hub'
    };

    check.requirements = {
      domain: '.autamedica.com',
      path: '/',
      secure: true,
      httpOnly: true,
      sameSite: 'None'
    };

    check.instructions = [
      '1. Verificar que Auth Hub setea am_session con Domain=.autamedica.com',
      '2. Confirmar flags: Secure; HttpOnly; SameSite=None',
      '3. Validar TTL y refresh automático',
      '4. Probar cross-domain SSO entre portales'
    ];

    this.results.checks.push(check);
    this.results.summary.total++;

    console.log(`  ${check.message}`);
    console.log('  📋 Requisitos de cookie am_session:');
    for (const [key, value] of Object.entries(check.requirements)) {
      console.log(`    ${key}: ${value}`);
    }
  }

  async makeRequest(url, options = {}) {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error('Request timeout'));
      }, MONITORING_CONFIG.timeout);

      const req = https.get(url, {
        timeout: MONITORING_CONFIG.timeout,
        ...options
      }, (res) => {
        clearTimeout(timeout);

        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: data
          });
        });
      });

      req.on('error', (error) => {
        clearTimeout(timeout);
        reject(error);
      });

      req.on('timeout', () => {
        req.destroy();
        reject(new Error('Request timeout'));
      });
    });
  }

  generateReport() {
    console.log('\n📊 RESUMEN DEL MONITOREO');
    console.log('========================');
    console.log(`✅ Passed: ${this.results.summary.passed}`);
    console.log(`❌ Failed: ${this.results.summary.failed}`);
    console.log(`⚠️ Warnings: ${this.results.summary.warnings}`);
    console.log(`📊 Total: ${this.results.summary.total}`);

    const successRate = (this.results.summary.passed / this.results.summary.total * 100).toFixed(1);
    console.log(`🎯 Success Rate: ${successRate}%`);

    if (this.results.summary.failed > 0) {
      console.log('\n🚨 ISSUES TO ADDRESS:');
      this.results.checks
        .filter(check => check.status === 'failed')
        .forEach(check => {
          console.log(`  • ${check.message}`);
        });
    }

    if (this.results.summary.warnings > 0) {
      console.log('\n⚠️ WARNINGS:');
      this.results.checks
        .filter(check => check.status === 'warning' || check.monitoring?.includes('⚠️'))
        .forEach(check => {
          const message = check.monitoring || check.message;
          console.log(`  • ${message}`);
        });
    }
  }

  saveResults() {
    const outputDir = path.join(process.cwd(), 'monitoring-results');
    const outputFile = path.join(outputDir, `auth-monitor-${Date.now()}.json`);

    try {
      if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir, { recursive: true });
      }

      fs.writeFileSync(outputFile, JSON.stringify(this.results, null, 2));
      console.log(`\n💾 Resultados guardados en: ${outputFile}`);
    } catch (error) {
      console.error(`❌ Error guardando resultados: ${error.message}`);
    }
  }
}

// CLI Interface
if (require.main === module) {
  const monitor = new AuthMonitor();

  monitor.run()
    .then(() => {
      const exitCode = monitor.results.summary.failed > 0 ? 1 : 0;
      process.exit(exitCode);
    })
    .catch(error => {
      console.error('❌ Error ejecutando monitor:', error);
      process.exit(1);
    });
}

module.exports = AuthMonitor;

#!/usr/bin/env node
/**
 * Auto-Generate Documentation for Missing Exports
 *
 * Este script:
 * 1. Detecta exports sin documentar
 * 2. Analiza el código fuente para inferir tipos y propósitos
 * 3. Genera automáticamente entradas para GLOSARIO_MAESTRO.md
 * 4. Actualiza el glosario con las nuevas entradas
 */

import { readFileSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = join(__dirname, '..');

// Colores para output
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

/**
 * Obtiene todos los exports de un package
 */
function getPackageExports(packagePath) {
  try {
    const packageFile = join(rootDir, packagePath, 'src', 'index.ts');
    const content = readFileSync(packageFile, 'utf-8');

    const exports = new Set();

    // Detectar exports directos: export { ... }
    const exportRegex = /export\s*{\s*([^}]+)\s*}/g;
    let match;
    while ((match = exportRegex.exec(content)) !== null) {
      const exportList = match[1];
      exportList.split(',').forEach(item => {
        const cleanItem = item.trim().split(/\s+as\s+/)[0].trim();
        if (cleanItem) exports.add(cleanItem);
      });
    }

    // Detectar exports nombrados: export const/function/interface/type/enum
    const namedExportRegex = /export\s+(const|function|interface|type|enum|class)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/g;
    while ((match = namedExportRegex.exec(content)) !== null) {
      exports.add(match[2]);
    }

    // Detectar re-exports: export * from
    const reExportRegex = /export\s*\*\s*from\s*['"]([^'"]+)['"]/g;
    while ((match = reExportRegex.exec(content)) !== null) {
      const reExportPath = match[1];
      try {
        const reExportFile = join(rootDir, packagePath, 'src', `${reExportPath}.ts`);
        const reExportContent = readFileSync(reExportFile, 'utf-8');

        // Recursivamente obtener exports del archivo re-exportado
        const subExports = extractExportsFromContent(reExportContent);
        subExports.forEach(exp => exports.add(exp));
      } catch (err) {
        // Si no puede leer el archivo, continúa
      }
    }

    return Array.from(exports).sort();
  } catch (error) {
    log(`⚠️  Error al leer exports de ${packagePath}: ${error.message}`, 'yellow');
    return [];
  }
}

/**
 * Extrae exports de contenido de archivo
 */
function extractExportsFromContent(content) {
  const exports = new Set();

  // Detectar exports directos
  const exportRegex = /export\s*{\s*([^}]+)\s*}/g;
  let match;
  while ((match = exportRegex.exec(content)) !== null) {
    const exportList = match[1];
    exportList.split(',').forEach(item => {
      const cleanItem = item.trim().split(/\s+as\s+/)[0].trim();
      if (cleanItem) exports.add(cleanItem);
    });
  }

  // Detectar exports nombrados
  const namedExportRegex = /export\s+(const|function|interface|type|enum|class)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/g;
  while ((match = namedExportRegex.exec(content)) !== null) {
    exports.add(match[2]);
  }

  return Array.from(exports);
}

/**
 * Analiza el código fuente para inferir el tipo y propósito de un export
 */
function analyzeExport(exportName, packagePath) {
  try {
    const srcDir = join(rootDir, packagePath, 'src');
    const files = [
      join(srcDir, 'index.ts'),
      join(srcDir, 'types.ts'),
      join(srcDir, 'constants.ts'),
      join(srcDir, 'utils.ts'),
      join(srcDir, 'validators.ts'),
      join(srcDir, 'auth.ts'),
      join(srcDir, 'client.ts'),
      join(srcDir, 'server.ts')
    ];

    for (const file of files) {
      try {
        const content = readFileSync(file, 'utf-8');

        // Buscar la definición del export
        const patterns = [
          // interface/type
          new RegExp(`export\\s+(interface|type)\\s+${exportName}\\s*[={]`, 'g'),
          // const/let
          new RegExp(`export\\s+const\\s+${exportName}\\s*[:=]`, 'g'),
          // function
          new RegExp(`export\\s+function\\s+${exportName}\\s*\\(`, 'g'),
          // enum
          new RegExp(`export\\s+enum\\s+${exportName}\\s*{`, 'g'),
          // class
          new RegExp(`export\\s+class\\s+${exportName}\\s*{`, 'g')
        ];

        for (const pattern of patterns) {
          const match = pattern.exec(content);
          if (match) {
            const type = match[1] || 'const';
            const description = inferDescription(exportName, type, content);
            return { type, description };
          }
        }
      } catch (err) {
        // Continúa con el siguiente archivo
      }
    }

    // Si no encuentra definición, inferir por nombre
    return inferFromName(exportName);
  } catch (error) {
    return inferFromName(exportName);
  }
}

/**
 * Infiere descripción basada en el contexto del código
 */
function inferDescription(exportName, type, content) {
  const name = exportName.toLowerCase();

  // Patrones médicos específicos
  if (name.includes('patient')) return `${type === 'interface' ? 'Interfaz' : 'Utilidad'} para manejo de datos de pacientes en el sistema médico.`;
  if (name.includes('doctor')) return `${type === 'interface' ? 'Interfaz' : 'Utilidad'} para gestión de información de médicos.`;
  if (name.includes('appointment')) return `${type === 'interface' ? 'Interfaz' : 'Utilidad'} para gestión de citas médicas.`;
  if (name.includes('medical')) return `${type === 'interface' ? 'Interfaz' : 'Utilidad'} para datos médicos y registros clínicos.`;
  if (name.includes('auth')) return `${type === 'interface' ? 'Interfaz' : 'Utilidad'} para autenticación y autorización.`;
  if (name.includes('telemedicine')) return `${type === 'interface' ? 'Interfaz' : 'Utilidad'} para funcionalidades de telemedicina.`;

  // Patrones por tipo
  if (type === 'interface' || type === 'type') {
    if (name.endsWith('id')) return `Tipo de identificador único para ${name.replace('id', '')} en el sistema.`;
    if (name.endsWith('config')) return `Configuración para ${name.replace('config', '')} del sistema.`;
    if (name.endsWith('props')) return `Propiedades del componente ${name.replace('props', '')}.`;
    if (name.endsWith('response')) return `Respuesta de API para operaciones de ${name.replace('response', '')}.`;
    return `Interfaz de datos para ${exportName.toLowerCase()} en el ecosistema AutaMedica.`;
  }

  if (type === 'enum') {
    if (name.includes('status')) return `Estados posibles para ${name.replace('status', '')} en el sistema.`;
    if (name.includes('role')) return `Roles de usuario disponibles en la plataforma médica.`;
    return `Enumeración de valores posibles para ${exportName.toLowerCase()}.`;
  }

  if (type === 'const') {
    if (name.includes('config')) return `Configuración constante para ${name.replace('config', '')} del sistema.`;
    if (name.includes('validation')) return `Reglas de validación para ${name.replace('validation', '')}.`;
    return `Constante del sistema para ${exportName.toLowerCase()}.`;
  }

  if (type === 'function') {
    if (name.startsWith('validate')) return `Valida ${name.replace('validate', '')} según reglas médicas y de negocio.`;
    if (name.startsWith('create')) return `Crea una nueva instancia de ${name.replace('create', '')}.`;
    if (name.startsWith('get')) return `Obtiene información de ${name.replace('get', '')} del sistema.`;
    if (name.startsWith('use')) return `Hook de React para gestión de ${name.replace('use', '')}.`;
    return `Función utilitaria para ${exportName.toLowerCase()} en el sistema médico.`;
  }

  return `Utilidad del sistema AutaMedica para ${exportName.toLowerCase()}.`;
}

/**
 * Infiere tipo y descripción solo por el nombre
 */
function inferFromName(exportName) {
  const name = exportName.toLowerCase();

  // Inferir tipo por convenciones de naming
  if (exportName.endsWith('Id') || exportName.endsWith('ID')) {
    return {
      type: 'type',
      description: `Identificador único tipado para ${exportName.replace(/Id$|ID$/, '').toLowerCase()} en el sistema.`
    };
  }

  if (exportName.endsWith('Config') || exportName.endsWith('Configuration')) {
    return {
      type: 'interface',
      description: `Configuración para ${exportName.replace(/Config$|Configuration$/, '').toLowerCase()} del sistema médico.`
    };
  }

  if (exportName.endsWith('Props')) {
    return {
      type: 'interface',
      description: `Propiedades del componente ${exportName.replace('Props', '')} en la interfaz médica.`
    };
  }

  if (exportName.endsWith('Response') || exportName.endsWith('Result')) {
    return {
      type: 'interface',
      description: `Respuesta de API para operaciones de ${exportName.replace(/Response$|Result$/, '').toLowerCase()}.`
    };
  }

  if (exportName.endsWith('Status') || exportName.endsWith('State')) {
    return {
      type: 'enum',
      description: `Estados posibles para ${exportName.replace(/Status$|State$/, '').toLowerCase()} en el sistema.`
    };
  }

  if (exportName.startsWith('use') && exportName.length > 3) {
    return {
      type: 'function',
      description: `Hook de React para gestión de ${exportName.substring(3).toLowerCase()} en la aplicación médica.`
    };
  }

  if (exportName.startsWith('create') || exportName.startsWith('validate') || exportName.startsWith('get')) {
    return {
      type: 'function',
      description: `Función utilitaria para ${exportName.toLowerCase()} en el ecosistema AutaMedica.`
    };
  }

  // Default based on naming patterns
  if (/^[A-Z][a-z]+$/.test(exportName)) {
    return {
      type: 'interface',
      description: `Interfaz de datos para ${exportName.toLowerCase()} en el sistema médico.`
    };
  }

  if (/^[A-Z_]+$/.test(exportName)) {
    return {
      type: 'const',
      description: `Constante del sistema para ${exportName.toLowerCase().replace(/_/g, ' ')}.`
    };
  }

  return {
    type: 'unknown',
    description: `Utilidad del sistema AutaMedica para ${exportName.toLowerCase()}.`
  };
}

/**
 * Lee el glosario actual
 */
function readGlosario() {
  try {
    const glosarioPath = join(rootDir, 'docs', 'GLOSARIO_MAESTRO.md');
    const content = readFileSync(glosarioPath, 'utf-8');
    return content;
  } catch (error) {
    log(`❌ Error al leer GLOSARIO_MAESTRO.md: ${error.message}`, 'red');
    return '';
  }
}

/**
 * Extrae exports ya documentados del glosario
 */
function getDocumentedExports(glosarioContent) {
  const documented = new Set();

  // Buscar headers ### que representan exports documentados
  const headerRegex = /^### (.+)$/gm;
  let match;
  while ((match = headerRegex.exec(glosarioContent)) !== null) {
    const exportName = match[1].trim();
    documented.add(exportName);
  }

  return documented;
}

/**
 * Genera entrada de documentación para un export
 */
function generateDocEntry(exportName, analysis, packageName) {
  const { type, description } = analysis;

  return `### ${exportName}
- **Tipo:** ${type}
- **Package:** ${packageName}
- **Descripción:** ${description}
- **Contrato:** Pendiente de documentación detallada
`;
}

/**
 * Actualiza el glosario con nuevas entradas
 */
function updateGlosario(newEntries) {
  if (newEntries.length === 0) {
    log('✅ No hay nuevos exports para documentar', 'green');
    return false;
  }

  const glosarioPath = join(rootDir, 'docs', 'GLOSARIO_MAESTRO.md');
  let content = readGlosario();

  // Buscar la sección donde agregar nuevos exports
  const insertPoint = content.lastIndexOf('\n## ') || content.length;

  // Crear sección de nuevos exports
  const newSection = `\n## 📋 Exports Auto-generados\n\n${newEntries.join('\n')}`;

  // Insertar antes de la última sección o al final
  const updatedContent = content.slice(0, insertPoint) + newSection + content.slice(insertPoint);

  try {
    writeFileSync(glosarioPath, updatedContent, 'utf-8');
    log(`✅ Glosario actualizado con ${newEntries.length} nuevas entradas`, 'green');
    return true;
  } catch (error) {
    log(`❌ Error al escribir GLOSARIO_MAESTRO.md: ${error.message}`, 'red');
    return false;
  }
}

/**
 * Función principal
 */
async function main() {
  log('🔍 Generando documentación automática para exports faltantes...', 'cyan');

  const packages = [
    { path: 'packages/types', name: '@autamedica/types' },
    { path: 'packages/shared', name: '@autamedica/shared' },
    { path: 'packages/auth', name: '@autamedica/auth' },
    { path: 'packages/hooks', name: '@autamedica/hooks' }
  ];

  const glosarioContent = readGlosario();
  const documentedExports = getDocumentedExports(glosarioContent);

  const newEntries = [];
  let totalMissing = 0;

  for (const pkg of packages) {
    log(`📦 Analizando ${pkg.name}...`, 'blue');

    const exports = getPackageExports(pkg.path);
    const missingExports = exports.filter(exp => !documentedExports.has(exp));

    if (missingExports.length > 0) {
      log(`   📋 Encontrados ${missingExports.length} exports sin documentar`, 'yellow');

      for (const exportName of missingExports) {
        const analysis = analyzeExport(exportName, pkg.path);
        const entry = generateDocEntry(exportName, analysis, pkg.name);
        newEntries.push(entry);
        totalMissing++;

        log(`   ✨ ${exportName} (${analysis.type})`, 'magenta');
      }
    } else {
      log(`   ✅ Todos los exports están documentados`, 'green');
    }
  }

  if (totalMissing > 0) {
    log(`\n📝 Generando documentación para ${totalMissing} exports...`, 'cyan');
    const updated = updateGlosario(newEntries);

    if (updated) {
      log(`\n🎉 ¡Documentación generada exitosamente!`, 'green');
      log(`📖 Revisa docs/GLOSARIO_MAESTRO.md para ajustar descripciones si es necesario`, 'yellow');
    }
  } else {
    log('\n✅ ¡Todos los exports ya están documentados!', 'green');
  }
}

// Ejecutar si es llamado directamente
if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(error => {
    log(`💥 Error: ${error.message}`, 'red');
    process.exit(1);
  });
}

export { main as autoGenerateDocs };

#!/usr/bin/env node

/**
 * check-glossary.js - Validador de terminología médica para Autamedica
 *
 * Valida que el código fuente siga las convenciones de nomenclatura médica
 * y terminología específica del proyecto Autamedica.
 */

const fs = require('fs');
const path = require('path');
const glob = require('glob');

// Colores para output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  bold: '\x1b[1m'
};

class GlossaryChecker {
  constructor() {
    this.glossary = this.loadGlossary();
    this.errors = [];
    this.warnings = [];
    this.suggestions = [];
  }

  loadGlossary() {
    try {
      const glossaryPath = path.join(process.cwd(), 'glossary.json');
      return JSON.parse(fs.readFileSync(glossaryPath, 'utf8'));
    } catch (error) {
      console.error(`${colors.red}❌ Error cargando glossary.json: ${error.message}${colors.reset}`);
      process.exit(1);
    }
  }

  log(level, message, file = '', line = 0) {
    const entry = { level, message, file, line, timestamp: new Date().toISOString() };

    switch (level) {
      case 'error':
        this.errors.push(entry);
        break;
      case 'warning':
        this.warnings.push(entry);
        break;
      case 'suggestion':
        this.suggestions.push(entry);
        break;
    }
  }

  checkForbiddenTerms(content, filePath) {
    const allForbidden = [
      ...this.glossary.forbidden.general,
      ...this.glossary.forbidden.medical,
      ...this.glossary.forbidden.security
    ];

    allForbidden.forEach(term => {
      const regex = new RegExp(`\\b${term}\\b`, 'gi');
      const matches = content.match(regex);

      if (matches) {
        matches.forEach(() => {
          this.log('error',
            `Término prohibido encontrado: "${term}"`,
            filePath
          );
        });
      }
    });
  }

  checkPreferredTerminology(content, filePath) {
    Object.entries(this.glossary.preferred.terminology).forEach(([incorrect, correct]) => {
      const regex = new RegExp(`\\b${incorrect}\\b`, 'gi');
      const matches = content.match(regex);

      if (matches) {
        matches.forEach(() => {
          this.log('warning',
            `Usar "${correct}" en lugar de "${incorrect}"`,
            filePath
          );
        });
      }
    });
  }

  checkVariableNaming(content, filePath) {
    // Buscar declaraciones de variables
    const variableRegex = /(const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/g;
    let match;

    while ((match = variableRegex.exec(content)) !== null) {
      const variableName = match[2];

      // Verificar abreviaciones prohibidas
      this.glossary.patterns.variables.no_abbreviations.forEach(abbrev => {
        if (variableName.toLowerCase().includes(abbrev)) {
          this.log('warning',
            `Evitar abreviación "${abbrev}" en variable "${variableName}". Usar nombre descriptivo.`,
            filePath
          );
        }
      });

      // Verificar camelCase
      if (this.glossary.patterns.variables.camelCase) {
        if (!/^[a-z][a-zA-Z0-9]*$/.test(variableName) && !variableName.startsWith('_')) {
          this.log('suggestion',
            `Variable "${variableName}" debería usar camelCase`,
            filePath
          );
        }
      }
    }
  }

  checkComponentNaming(filePath) {
    const fileName = path.basename(filePath, path.extname(filePath));

    // Verificar sufijos prohibidos
    this.glossary.patterns.components.forbidden_suffixes.forEach(suffix => {
      if (fileName.endsWith(suffix)) {
        this.log('error',
          `Archivo "${fileName}" no debe terminar en "${suffix}"`,
          filePath
        );
      }
    });

    // Verificar nombres prohibidos
    this.glossary.patterns.files.forbidden_names.forEach(forbiddenName => {
      if (path.basename(filePath).toLowerCase() === forbiddenName.toLowerCase()) {
        this.log('error',
          `Nombre de archivo prohibido: "${forbiddenName}"`,
          filePath
        );
      }
    });
  }

  checkHIPAACompliance(content, filePath) {
    // Buscar console.log con posibles datos médicos
    const consoleLogRegex = /console\.(log|info|debug|warn|error)\s*\([^)]*\)/g;
    let match;

    while ((match = consoleLogRegex.exec(content)) !== null) {
      const logContent = match[0].toLowerCase();

      // Palabras que podrían indicar datos médicos
      const medicalDataIndicators = [
        'patient', 'paciente', 'medical', 'médico', 'diagnosis', 'diagnóstico',
        'prescription', 'prescripción', 'treatment', 'tratamiento', 'phi', 'pii'
      ];

      medicalDataIndicators.forEach(indicator => {
        if (logContent.includes(indicator)) {
          this.log('error',
            `Posible violación HIPAA: console.log con datos médicos detectado ("${indicator}")`,
            filePath
          );
        }
      });
    }

    // Verificar comentarios requeridos para PHI
    const phiRegex = /\b(phi|pii|patient.*data|medical.*record|health.*information)\b/gi;
    if (phiRegex.test(content)) {
      const hasRequiredComment = this.glossary.compliance.hipaa.required_comments.some(
        comment => content.toLowerCase().includes(comment.toLowerCase())
      );

      if (!hasRequiredComment) {
        this.log('warning',
          'Archivo maneja datos PHI pero no tiene comentarios de compliance HIPAA requeridos',
          filePath
        );
      }
    }
  }

  async checkFile(filePath) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');

      // Ejecutar todas las validaciones
      this.checkForbiddenTerms(content, filePath);
      this.checkPreferredTerminology(content, filePath);
      this.checkVariableNaming(content, filePath);
      this.checkComponentNaming(filePath);
      this.checkHIPAACompliance(content, filePath);

    } catch (error) {
      this.log('error', `Error leyendo archivo: ${error.message}`, filePath);
    }
  }

  async checkProject() {
    console.log(`${colors.blue}🔍 Autamedica Glossary Checker${colors.reset}`);
