    if (type.includes('array')) {
      return 'Lista de valores';
    }
    if (type.includes('bytea')) {
      return 'Datos binarios';
    }
    return dataType;
  });

  // Array and object helpers
  Handlebars.registerHelper('join', function(array, separator = ', ') {
    if (!Array.isArray(array)) return '';
    return array.join(separator);
  });

  Handlebars.registerHelper('length', function(array) {
    if (!Array.isArray(array)) return 0;
    return array.length;
  });

  Handlebars.registerHelper('first', function(array) {
    if (!Array.isArray(array) || array.length === 0) return null;
    return array[0];
  });

  Handlebars.registerHelper('last', function(array) {
    if (!Array.isArray(array) || array.length === 0) return null;
    return array[array.length - 1];
  });

  Handlebars.registerHelper('slice', function(array, start = 0, end) {
    if (!Array.isArray(array)) return [];
    return array.slice(start, end);
  });

  // Grouping helpers
  Handlebars.registerHelper('groupBy', function(array, key, options) {
    if (!Array.isArray(array)) return '';

    const groups = {};
    array.forEach(item => {
      const groupKey = item[key] || 'Otros';
      if (!groups[groupKey]) {
        groups[groupKey] = [];
      }
      groups[groupKey].push(item);
    });

    let result = '';
    for (const [groupName, items] of Object.entries(groups)) {
      result += options.fn({
        group_name: groupName,
        items: items,
        item_count: items.length
      });
    }
    return result;
  });

  // Math helpers
  Handlebars.registerHelper('add', function(a, b) {
    return (a || 0) + (b || 0);
  });

  Handlebars.registerHelper('subtract', function(a, b) {
    return (a || 0) - (b || 0);
  });

  Handlebars.registerHelper('multiply', function(a, b) {
    return (a || 0) * (b || 0);
  });

  Handlebars.registerHelper('divide', function(a, b) {
    return b !== 0 ? (a || 0) / b : 0;
  });

  Handlebars.registerHelper('percentage', function(part, total) {
    if (!total || total === 0) return '0%';
    return `${Math.round((part / total) * 100)}%`;
