 */
export interface ValidationResult {
  validation_type: 'SCHEMA_CONSISTENCY' | 'HIPAA_COMPLIANCE' | 'NAMING_CONVENTIONS' | 'DOCUMENTATION_COMPLETENESS';
  status: 'PASSED' | 'FAILED' | 'WARNING';
  message: string;
  affected_objects?: string[];
