/**
 * AutaMedica - k6 Smoke Test
 *
 * Smoke test básico para validar que las aplicaciones pueden
 * manejar carga ligera sin degradarse
 *
 * Perfil de carga:
 * - 10 VUs (virtual users)
 * - 30 segundos de duración
 * - ~50 requests/segundo
 *
 * SLOs validados:
 * - HTTP 200 OK rate > 99.5%
 * - TTFB p95 < 600ms
 * - Request duration p99 < 1000ms
 * - Error rate < 0.5%
 */

import http from "k6/http";
import { check, sleep } from "k6";
import { Rate, Trend } from "k6/metrics";

// Custom metrics
const errorRate = new Rate("errors");
const ttfb = new Trend("ttfb");

// Test configuration
export const options = {
  vus: 10, // 10 concurrent users
  duration: "30s", // run for 30 seconds

  thresholds: {
    // HTTP errors should be less than 0.5%
    errors: ["rate<0.005"],

    // 99% of requests should complete in <1000ms
    http_req_duration: ["p(99)<1000"],

    // 95% of TTFB should be <600ms
    ttfb: ["p(95)<600"],

    // Success rate should be >99.5%
    checks: ["rate>0.995"],
  },

  // Tag requests for better reporting
  tags: {
    project: "autamedica",
    environment: "production",
  },
};

// Test endpoints
const ENDPOINTS = [
  {
    name: "Patients App",
    url: "https://patients.autamedica.com",
    weight: 0.4, // 40% of traffic
  },
  {
    name: "Doctors App",
    url: "https://doctors.autamedica.com",
    weight: 0.4, // 40% of traffic
  },
  {
    name: "Companies App",
    url: "https://companies.autamedica.com",
    weight: 0.2, // 20% of traffic
  },
];

// Helper to select endpoint based on weight
function selectEndpoint() {
  const rand = Math.random();
  let cumulative = 0;

  for (const endpoint of ENDPOINTS) {
    cumulative += endpoint.weight;
    if (rand < cumulative) {
      return endpoint;
    }
  }

  return ENDPOINTS[0];
}

export default function () {
  const endpoint = selectEndpoint();

  // Make request
  const response = http.get(endpoint.url, {
    headers: {
      "User-Agent": "k6-AutaMedica-Smoke/1.0",
    },
    tags: {
      endpoint: endpoint.name,
    },
  });

  // Record TTFB
  ttfb.add(response.timings.waiting);

  // Check response
  const checkResults = check(
    response,
    {
      "status is 200 or 3xx": (r) =>
        r.status === 200 || (r.status >= 300 && r.status < 400),
      "response time < 1000ms": (r) => r.timings.duration < 1000,
      "waiting time (TTFB) < 600ms": (r) => r.timings.waiting < 600,
      "has content": (r) => r.body.length > 0,
    },
    { endpoint: endpoint.name }
  );

  // Record error rate
  errorRate.add(!checkResults);

  // Log failures for debugging
  if (!checkResults) {
    console.error(
      `[${endpoint.name}] Failed: status=${response.status}, duration=${response.timings.duration}ms`
    );
  }

  // Think time: simulate user reading/interacting
  sleep(1);
}

// Setup function (runs once at start)
export function setup() {
  console.log("🚀 Starting AutaMedica Smoke Test");
  console.log(`   VUs: ${options.vus}`);
  console.log(`   Duration: ${options.duration}`);
  console.log(`   Endpoints: ${ENDPOINTS.length}`);
  console.log("");

  return {
    timestamp: new Date().toISOString(),
  };
}

// Teardown function (runs once at end)
export function teardown(data) {
  console.log("");
  console.log("✅ AutaMedica Smoke Test completed");
  console.log(`   Started: ${data.timestamp}`);
  console.log(`   Finished: ${new Date().toISOString()}`);
}

// Summary handler
export function handleSummary(data) {
  const summary = {
    timestamp: new Date().toISOString(),
    duration: data.state.testRunDurationMs,
    metrics: {
      http_reqs: data.metrics.http_reqs,
      http_req_duration: data.metrics.http_req_duration,
      http_req_failed: data.metrics.http_req_failed,
      checks: data.metrics.checks,
      errors: data.metrics.errors,
      ttfb: data.metrics.ttfb,
    },
    thresholds: data.metrics,
  };

  // Log summary to console
  console.log("\n📊 Test Summary:");
  console.log(`   Total requests: ${data.metrics.http_reqs.values.count}`);
  console.log(
    `   Success rate: ${(data.metrics.checks.values.rate * 100).toFixed(2)}%`
  );
  console.log(
    `   Error rate: ${(data.metrics.errors ? data.metrics.errors.values.rate * 100 : 0).toFixed(2)}%`
  );
  console.log(
    `   Avg response time: ${data.metrics.http_req_duration.values.avg.toFixed(2)}ms`
  );
  console.log(
    `   p95 response time: ${data.metrics.http_req_duration.values["p(95)"].toFixed(2)}ms`
  );
  console.log(
    `   p99 response time: ${data.metrics.http_req_duration.values["p(99)"].toFixed(2)}ms`
  );

  if (data.metrics.ttfb) {
    console.log(
      `   p95 TTFB: ${data.metrics.ttfb.values["p(95)"].toFixed(2)}ms`
    );
  }

  // Return summary for file output
  return {
    "generated-docs/k6-smoke-report.json": JSON.stringify(summary, null, 2),
    stdout: textSummary(data, { indent: "  ", enableColors: true }),
  };
}

// Helper for text summary (fallback if not using default textSummary)
function textSummary(data, options = {}) {
  return JSON.stringify(data, null, 2);
}

#!/usr/bin/env node

/**
 * Script de migración automática: console.* → logger
 *
 * Migra console.log/warn/error/debug/info a logger de Pino
 *
 * Uso:
 *   node scripts/migrate-to-logger.mjs                    # Preview (dry-run)
 *   node scripts/migrate-to-logger.mjs --apply            # Aplicar cambios
 *   node scripts/migrate-to-logger.mjs --file path.ts     # Solo un archivo
 */

import fs from 'fs/promises';
import path from 'path';
import { glob } from 'glob';

const DRY_RUN = !process.argv.includes('--apply');
const SINGLE_FILE = process.argv.find(arg => arg.startsWith('--file='))?.split('=')[1];

// Estadísticas
const stats = {
  filesProcessed: 0,
  filesChanged: 0,
  replacements: 0,
  patterns: {
    'console.log': 0,
    'console.error': 0,
    'console.warn': 0,
    'console.info': 0,
    'console.debug': 0,
  }
};

/**
 * Migrar archivo individual
 */
async function migrateFile(filePath) {
  const content = await fs.readFile(filePath, 'utf-8');
  let newContent = content;
  let fileChanged = false;

  // 1. Agregar import de logger si no existe y hay console.*
  const hasConsoleUsage = /console\.(log|error|warn|info|debug)/.test(content);
  const hasLoggerImport = /import.*logger.*from.*@autamedica\/shared/.test(content);

  if (hasConsoleUsage && !hasLoggerImport) {
    // Encontrar la última línea de import
    const importMatch = content.match(/^import[^;]+;$/gm);
    if (importMatch) {
      const lastImport = importMatch[importMatch.length - 1];
      const importIndex = content.lastIndexOf(lastImport);
      const afterLastImport = importIndex + lastImport.length;

      newContent = content.slice(0, afterLastImport) +
        "\nimport { logger } from '@autamedica/shared';" +
        content.slice(afterLastImport);

      fileChanged = true;
    }
  }

  // 2. Reemplazar console.* por logger.*
  const replacements = [
    {
      pattern: /console\.log\(/g,
      replacement: 'logger.info(',
      name: 'console.log'
    },
    {
      pattern: /console\.error\(/g,
      replacement: 'logger.error(',
      name: 'console.error'
    },
    {
      pattern: /console\.warn\(/g,
      replacement: 'logger.warn(',
      name: 'console.warn'
    },
    {
      pattern: /console\.info\(/g,
      replacement: 'logger.info(',
      name: 'console.info'
    },
    {
      pattern: /console\.debug\(/g,
      replacement: 'logger.debug(',
      name: 'console.debug'
    },
  ];

  for (const { pattern, replacement, name } of replacements) {
    const matches = newContent.match(pattern) || [];
    if (matches.length > 0) {
      newContent = newContent.replace(pattern, replacement);
      stats.patterns[name] += matches.length;
      stats.replacements += matches.length;
      fileChanged = true;
    }
  }

  if (fileChanged) {
    stats.filesChanged++;

    if (!DRY_RUN) {
      await fs.writeFile(filePath, newContent, 'utf-8');
    }

    return {
      path: filePath,
      changes: Object.entries(stats.patterns)
        .filter(([, count]) => count > 0)
        .map(([name, count]) => `${name}: ${count}`)
        .join(', ')
    };
  }

  return null;
}

/**
 * Main
 */
async function main() {
  console.log('🔄 Migración console.* → logger\n');
  console.log(`Mode: ${DRY_RUN ? '🔍 DRY RUN (preview)' : '✅ APPLY CHANGES'}\n`);

  // Obtener archivos a procesar
  let files = [];

  if (SINGLE_FILE) {
    files = [SINGLE_FILE];
  } else {
    files = await glob('**/*.{ts,tsx}', {
      cwd: process.cwd(),
      ignore: [
        '**/node_modules/**',
        '**/.next/**',
        '**/dist/**',
        '**/dist-esm/**',
        '**/.turbo/**',
        '**/build/**',
        '**/*.test.{ts,tsx}',
        '**/*.spec.{ts,tsx}',
      ]
    });
  }

  console.log(`📁 Procesando ${files.length} archivos...\n`);

  const changes = [];

  for (const file of files) {
    stats.filesProcessed++;
    const result = await migrateFile(file);
    if (result) {
      changes.push(result);
    }
  }

  // Reporte
  console.log('\n📊 REPORTE DE MIGRACIÓN\n');
  console.log(`Archivos procesados: ${stats.filesProcessed}`);
  console.log(`Archivos modificados: ${stats.filesChanged}`);
  console.log(`Total reemplazos: ${stats.replacements}\n`);

  console.log('Detalles por patrón:');
  for (const [pattern, count] of Object.entries(stats.patterns)) {
    if (count > 0) {
      console.log(`  ${pattern.padEnd(20)} → ${count}`);
    }
  }

  if (changes.length > 0) {
    console.log('\n📝 Archivos modificados:');
    changes.slice(0, 20).forEach(({ path, changes }) => {
      console.log(`  ✓ ${path}`);
      console.log(`    ${changes}`);
    });

    if (changes.length > 20) {
      console.log(`  ... y ${changes.length - 20} más`);
    }
  }

  if (DRY_RUN && stats.filesChanged > 0) {
    console.log('\n💡 Para aplicar cambios: node scripts/migrate-to-logger.mjs --apply');
  }

  if (!DRY_RUN && stats.filesChanged > 0) {
    console.log('\n✅ Migración completada!');
    console.log('⚠️  Ejecuta: pnpm build && pnpm lint para verificar');
  }
}

main().catch(console.error);

#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const args = process.argv.slice(2);
const options = {};
for (let i = 0; i < args.length; i += 1) {
  const arg = args[i];
  if (arg === '--dir' || arg === '-d') {
    options.outputDir = args[i + 1];
    i += 1;
  }
}

const cwd = process.cwd();
const workerDir = path.resolve(cwd, options.outputDir ?? '.open-next');
const workerPath = path.join(workerDir, '_worker.js');
const originalWorkerPath = path.join(workerDir, 'worker.js');
const routesPath = path.join(workerDir, '_routes.json');

if (!fs.existsSync(workerDir)) {
  console.error('⚠️  Directorio .open-next no encontrado, salteando patch.');
  process.exit(0);
}

if (!fs.existsSync(workerPath)) {
  if (fs.existsSync(originalWorkerPath)) {
    fs.renameSync(originalWorkerPath, workerPath);
    console.log('ℹ️  worker.js renombrado a _worker.js.');
  } else {
    console.error('⚠️  Worker file no encontrado, salteando patch.');
    process.exit(0);
  }
}

let source = fs.readFileSync(workerPath, 'utf8');

const snippetSignature = 'return Response.redirect(new URL(target, request.url), 307);';
const securityHeadersSignature = 'function addSecurityHeaders(response)';

if (!source.includes(snippetSignature)) {
  const rewriteSnippet = `            const url = new URL(request.url);\n            if (url.pathname.startsWith(\"/_next/static/\")) {\n                const target = \"/assets\" + url.pathname + url.search;\n                return Response.redirect(new URL(target, request.url), 307);\n            }\n`;

  const pattern = /(async fetch\(request, env, ctx\) {\n)(\s*return runWithCloudflareRequestContext\(request, env, ctx, async \(\) => {\n\s*const response = maybeGetSkewProtectionResponse\(request\);\n\s*if \(response\) {\n\s*return response;\n\s*}\n\s*)(const url = new URL\(request.url\);\n)/;

  if (!pattern.test(source)) {
    console.error('❌ No se encontró el bloque de fetch esperado para aplicar el patch.');
    process.exit(1);
  }

  source = source.replace(pattern, (_, p1, p2, p3) => `${p1}${p2}${rewriteSnippet}`);
  fs.writeFileSync(workerPath, source);
  console.log('✅ _worker.js parcheado (rewrite /_next/static → fetch /assets).');
} else {
  console.log('ℹ️  Patch ya aplicado en _worker.js.');
}

// Add security headers function
if (!source.includes(securityHeadersSignature)) {
  const securityHeadersFunc = `
function addSecurityHeaders(response) {
  const headers = new Headers(response.headers);
  headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  headers.set('X-Frame-Options', 'DENY');
  headers.set('X-Content-Type-Options', 'nosniff');
  headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  headers.set('Permissions-Policy', 'geolocation=(), microphone=(), camera=(), payment=(), usb=(), magnetometer=(), gyroscope=(), accelerometer=()');
  headers.set('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval' https://cdn.supabase.co; connect-src 'self' https://knywotiidsydsaveqkjs.supabase.co https://*.supabase.co wss://*.supabase.co; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self' data:; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}
`;

  // Insert before export default
  source = source.replace(/export default {/, `${securityHeadersFunc}\nexport default {`);

  // Wrap the final return in the fetch handler
  source = source.replace(
    /(\s+)(\/\/ @ts-expect-error: resolved by wrangler build\n\s+const { handler } = await import\("\.\/server-functions\/default\/handler\.mjs"\);\n\s+return handler\(reqOrResp, env, ctx, request\.signal\);)/,
    '$1// @ts-expect-error: resolved by wrangler build\n$1const { handler } = await import("./server-functions/default/handler.mjs");\n$1const handlerResponse = await handler(reqOrResp, env, ctx, request.signal);\n$1return addSecurityHeaders(handlerResponse);'
  );

  fs.writeFileSync(workerPath, source);
  console.log('✅ Security headers agregados al Worker.');
} else {
  console.log('ℹ️  Security headers ya están presentes.');
}

if (!fs.existsSync(routesPath)) {
  fs.writeFileSync(
    routesPath,
    JSON.stringify(
      {
        version: 1,
        include: ['/*'],
        exclude: ['/assets/*'],
      },
      null,
      2,
    ) + '\n',
  );
  console.log('✅ _routes.json creado.');
}

