async function validateExports() {
  console.log("🔍 Validating exports against glossaries...");

  try {
    // Leer glosarios modulares
    const glossaryDir = "docs/glossary";
    let glosario = "";

    // Si existe el directorio de glosarios, leer todos los archivos .md
    if (fs.existsSync(glossaryDir)) {
      const glossaryFiles = fs.readdirSync(glossaryDir).filter(f => f.endsWith('.md'));
      for (const file of glossaryFiles) {
        const content = fs.readFileSync(path.join(glossaryDir, file), "utf8");
        glosario += content + "\n\n";
      }
      console.log(`📚 Loaded ${glossaryFiles.length} modular glossaries`);
    }

    // Fallback: leer glosario maestro si existe
    const glosarioPath = "docs/GLOSARIO_MAESTRO.md";
    if (fs.existsSync(glosarioPath)) {
      const masterGlosario = fs.readFileSync(glosarioPath, "utf8");
      glosario += masterGlosario;
      console.log("📚 Loaded GLOSARIO_MAESTRO.md");
    }

    if (!glosario) {
      console.warn("⚠️  No glossaries found, skipping validation");
      return;
    }

    // Extraer exports esperados del glosario
    const expectedExports = extractExpectedExports(glosario);

    // Lista de tipos críticos que requieren ADR si cambian
    const CRITICAL_TYPES = [
      'PatientId', 'DoctorId', 'CompanyId', 'UUID',
      'Patient', 'Doctor', 'Appointment', 'MedicalRecord',
      'APIResponse', 'AuthUser', 'UserRole',
      'ISODateString', 'EmailAddress', 'PhoneNumber'
    ];

    // Validar cada package
    const packages = ["types", "shared", "auth", "hooks"];
    let hasErrors = false;
    let hasCriticalChanges = false;

    for (const pkg of packages) {
      const packagePath = `packages/${pkg}/src/index.ts`;

      if (!fs.existsSync(packagePath)) {
        console.error(`❌ Package index not found: ${packagePath}`);
        hasErrors = true;
        continue;
      }

      const indexContent = fs.readFileSync(packagePath, "utf8");
      const actualExports = extractActualExports(indexContent);
      const expected = expectedExports[`@autamedica/${pkg}`] || [];

      // Verificar exports faltantes
      const missing = expected.filter(exp => !actualExports.includes(exp));
      if (missing.length > 0) {
        console.error(`❌ @autamedica/${pkg} missing exports:`, missing.join(", "));
        hasErrors = true;
      }

      // Verificar exports no documentados (excluyendo internos permitidos)
      const undocumented = actualExports
        .filter(exp => !expected.includes(exp))
        .filter(exp => !ALLOWED_INTERNAL_EXPORTS.includes(exp));

      if (undocumented.length > 0) {
        console.warn(`⚠️  @autamedica/${pkg} undocumented exports (${undocumented.length}):`, undocumented.join(", "));

        // Verificar si hay tipos críticos no documentados
        const criticalUndocumented = undocumented.filter(exp => CRITICAL_TYPES.includes(exp));
        if (criticalUndocumented.length > 0) {
          console.error(`🚨 CRITICAL: Undocumented critical types: ${criticalUndocumented.join(", ")}`);
          console.error(`   These require documentation in GLOSARIO_MAESTRO.md and ADR if breaking change`);
          hasErrors = true;
          hasCriticalChanges = true;
        } else {
          // Para exports no críticos, marcar para auto-generación
          hasErrors = true; // Esto activará la auto-generación
        }
      }

      // Verificar cambios en tipos críticos (para packages types)
      if (pkg === 'types') {
        const criticalExports = actualExports.filter(exp => CRITICAL_TYPES.includes(exp));
        if (criticalExports.length > 0) {
          console.log(`🔒 Critical types found: ${criticalExports.join(", ")}`);

          // Si es CI, verificar si hay ADR para cambios críticos
          if (process.env.CI && hasCriticalChanges) {
            const adrPath = 'docs/adr';
            if (!fs.existsSync(adrPath)) {
              console.error(`🚨 CRITICAL: No ADR directory found at ${adrPath}`);
              console.error(`   Critical type changes require Architecture Decision Records`);
              hasErrors = true;
            } else {
              console.log(`📋 ADR directory exists - ensure critical changes are documented`);
            }
          }
        }
      }

      if (!hasErrors) {
        console.log(`✅ @autamedica/${pkg} exports are valid`);
      }
    }

    if (hasErrors) {
      console.log("\n🔧 Intentando generar documentación automática...");

      try {
        await autoGenerateDocs();
        console.log("\n✨ Documentación generada. Ejecutando validación nuevamente...");

        // Re-ejecutar validación después de generar docs
        await validateExportsSecondPass();
      } catch (autoGenError) {
        console.error(`❌ Error en auto-generación: ${autoGenError.message}`);
        console.error("\n❌ Export validation failed!");
        process.exit(1);
      }
    } else {
      console.log("\n🎉 All exports are properly documented and implemented!");
    }

  } catch (error) {
    console.error("❌ Validation script failed:", error.message);
    process.exit(1);
  }
}

function normalizeExportName(name) {
  return name
    .trim()
    .replace(/\s+as\s+.+$/iu, "")
    .replace(/\/\*.*?\*\//gu, "")
    .replace(/[\s;]+/g, "")
    .replace(/,$/, "")
    .trim();
}

function collectExportsFromCode(code, exportsSet) {
  // Regex mejorado para capturar export { } multi-línea
  const namedExportRegex = /export(?:\s+type)?\s*\{([\s\S]*?)\}/g;
  let namedMatch;
  while ((namedMatch = namedExportRegex.exec(code)) !== null) {
    const names = namedMatch[1]
      .split(/[,\n]/)  // Split por comas Y newlines
      .map(normalizeExportName)
      .filter(Boolean);

    for (const name of names) {
      exportsSet.add(name);
    }
  }

  const singleExportRegexes = [
    /export\s+const\s+([A-Za-z0-9_]+)/g,
    /export\s+function\s+([A-Za-z0-9_]+)/g,
    /export\s+class\s+([A-Za-z0-9_]+)/g,
    /export\s+enum\s+([A-Za-z0-9_]+)/g,
    /export\s+interface\s+([A-Za-z0-9_]+)/g,
    /export\s+type\s+([A-Za-z0-9_]+)/g,
  ];

  for (const regex of singleExportRegexes) {
    let singleMatch;
    while ((singleMatch = regex.exec(code)) !== null) {
      const name = normalizeExportName(singleMatch[1]);
      if (name) {
        exportsSet.add(name);
      }
    }
  }
}

function extractExpectedExports(glosarioContent) {
  const expected = {};

  // Priorizar la sección autogenerada si existe
  const autoSectionMatch = glosarioContent.match(/<!-- AUTOGEN_PACKAGES:START -->([\s\S]*?)<!-- AUTOGEN_PACKAGES:END -->/);
  if (autoSectionMatch) {
    const autoContent = autoSectionMatch[1];
    const lineRegex = /-\s+([a-zA-Z0-9_-]+):\s*([^\n]*)/g;
    let lineMatch;
    while ((lineMatch = lineRegex.exec(autoContent)) !== null) {
      const pkgSlug = lineMatch[1].trim();
      const symbolsLine = lineMatch[2] ?? "";
      const symbols = Array.from(symbolsLine.matchAll(/`([^`]+)`/g))
        .map((match) => match[1].trim())
        .filter(Boolean);
      if (symbols.length > 0) {
        expected[`@autamedica/${pkgSlug}`] = symbols;
      }
    }
  }

  const addCodeBlocksToPackage = (content, packageName) => {
    if (!content) {
      return;
    }

    const exportsSet = new Set(expected[packageName] ?? []);
    const codeBlockRegex = /```typescript([\s\S]*?)```/g;
    let codeMatch;
    while ((codeMatch = codeBlockRegex.exec(content)) !== null) {
      collectExportsFromCode(codeMatch[1], exportsSet);
    }

    if (exportsSet.size > 0) {
      expected[packageName] = [...exportsSet];
    }
  };

  // Bloques generales (antes de la sección por package) pertenecen a @autamedica/types
  const [generalContent, packagesContent = ""] = glosarioContent.split("## 📖 Exports por Package");
  if (!expected['@autamedica/types']) {
    addCodeBlocksToPackage(generalContent, "@autamedica/types");
  }

  // Capturar el contenido de cada sección de package del glosario
  // Soporta tanto ### (3 hashes) como ## (2 hashes) para compatibilidad con glosarios modulares
  const sectionRegex = /##+ @autamedica\/([^\n]+)\n([\s\S]*?)(?=##+ @autamedica\/|##+ [A-Z]|$)/g;

  let sectionMatch;
  while ((sectionMatch = sectionRegex.exec(packagesContent)) !== null) {
    const packageName = sectionMatch[1].trim();
    const sectionContent = sectionMatch[2] ?? "";

    if (!expected[`@autamedica/${packageName}`]) {
      addCodeBlocksToPackage(sectionContent, `@autamedica/${packageName}`);
    }
  }

  // También procesar secciones de glosario completo (que incluye modulares)
  // Buscar secciones ## @autamedica/ en todo el contenido
  const fullSectionRegex = /## @autamedica\/([^\n]+)\n([\s\S]*?)(?=## @autamedica\/|## [🎯📚]|---\n\n##|$)/g;
  let fullMatch;
  while ((fullMatch = fullSectionRegex.exec(glosarioContent)) !== null) {
    const packageName = fullMatch[1].trim();
    const sectionContent = fullMatch[2] ?? "";

    if (!expected[`@autamedica/${packageName}`]) {
      addCodeBlocksToPackage(sectionContent, `@autamedica/${packageName}`);
    }
  }

  return expected;
}

function extractActualExports(indexContent) {
  const exportsSet = new Set();
  collectExportsFromCode(indexContent, exportsSet);
  return [...exportsSet];
}

/**
 * Segunda pasada de validación después de auto-generar documentación
 */
async function validateExportsSecondPass() {
  console.log("🔄 Segunda validación después de auto-generación...");

  try {
    // Leer glosarios modulares
    const glossaryDir = "docs/glossary";
    let glosario = "";

    if (fs.existsSync(glossaryDir)) {
      const glossaryFiles = fs.readdirSync(glossaryDir).filter(f => f.endsWith('.md'));
      for (const file of glossaryFiles) {
        const content = fs.readFileSync(path.join(glossaryDir, file), "utf8");
        glosario += content + "\n\n";
      }
    }

    // Fallback: leer glosario maestro
    const glosarioPath = "docs/GLOSARIO_MAESTRO.md";
    if (fs.existsSync(glosarioPath)) {
      const masterGlosario = fs.readFileSync(glosarioPath, "utf8");
      glosario += masterGlosario;
    }

    const expectedExports = extractExpectedExports(glosario);

    // Reutilizar la misma lista ALLOWED_INTERNAL_EXPORTS del módulo
    const packages = ["types", "shared", "auth", "hooks"];
    let stillHasErrors = false;

    for (const pkg of packages) {
      const packagePath = `packages/${pkg}/src/index.ts`;

      if (!fs.existsSync(packagePath)) {
        continue;
      }

      const indexContent = fs.readFileSync(packagePath, "utf8");
      const actualExports = extractActualExports(indexContent);
      const expected = expectedExports[`@autamedica/${pkg}`] || [];

      // Aplicar MISMO filtro que primera pasada
      const undocumented = actualExports
        .filter(exp => !expected.includes(exp))
        .filter(exp => !ALLOWED_INTERNAL_EXPORTS.includes(exp));

      if (undocumented.length > 0) {
        console.error(`❌ @autamedica/${pkg} aún tiene exports sin documentar (${undocumented.length}):`, undocumented.join(", "));
        stillHasErrors = true;
      } else {
        console.log(`✅ @autamedica/${pkg} exports válidos después de auto-generación`);
      }
    }

    if (stillHasErrors) {
      console.error("\n❌ Algunos exports siguen sin documentar después de auto-generación!");
      console.error("🔧 Revisa el archivo docs/GLOSARIO_MAESTRO.md manualmente");
      process.exit(1);
    } else {
      console.log("\n🎉 ¡Todos los exports están documentados después de auto-generación!");
    }

  } catch (error) {
    console.error("❌ Segunda validación falló:", error.message);
    process.exit(1);
  }
}

validateExports();

#!/usr/bin/env node

/**
 * Script de validación anti-hardcode para AutaMedica
 *
 * Detecta patrones prohibidos de código hardcodeado:
 * - Nombres de usuarios ficticios (Dr. Invitado, Carlos Ruiz, etc.)
 * - Datos de demo (Consultas activas X/Y hardcodeado)
 * - Horarios hardcodeados con nombres (Próxima: HH:MM - Nombre)
 * - FALLBACK constants sin uso de datos reales primero
 *
 * Uso:
 *   node scripts/validate-no-hardcode.mjs
 *   node scripts/validate-no-hardcode.mjs --fix
 *
 * Exit codes:
 *   0 - Sin violaciones
 *   1 - Violaciones encontradas
 */

import { readFileSync, readdirSync, statSync } from 'fs'
import { join, relative } from 'path'
import { fileURLToPath } from 'url'
import { dirname } from 'path'

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)
const ROOT_DIR = join(__dirname, '..')

// Patrones prohibidos
const FORBIDDEN_PATTERNS = [
  {
    pattern: /Dr\.\s+Invitado/g,
    message: 'Nombre de usuario hardcodeado "Dr. Invitado"',
    severity: 'error'
  },
  {
    pattern: /Carlos\s+Ruiz/g,
    message: 'Nombre de paciente hardcodeado "Carlos Ruiz"',
    severity: 'error'
  },
  {
    pattern: /Consultas\s+activas\s+\d+\/\d+/g,
    message: 'Estadísticas de consultas hardcodeadas',
    severity: 'error'
  },
  {
    pattern: /Próxima:\s*\d{1,2}:\d{2}\s*-\s*[A-Z][a-z]+\s+[A-Z]/g,
    message: 'Cita hardcodeada con nombre específico',
    severity: 'error'
  },
  {
    pattern: /const\s+FALLBACK_USER\s*=\s*['"]/g,
    message: 'FALLBACK_USER definido sin strategy de datos reales primero',
    severity: 'warning'
  },
  {
    pattern: /useState\(['"](Dr\.|Dra\.)\s+[A-Z]/g,
    message: 'useState inicializado con nombre hardcodeado',
    severity: 'error'
  }
]

// Directorios a escanear
const SCAN_DIRS = [
  'apps/doctors/src',
  'apps/patients/src',
  'apps/companies/src',
  'apps/admin/src',
  'apps/web-app/src'
]

// Archivos excluidos
const EXCLUDED_FILES = [
  'node_modules',
  '.next',
  'dist',
  '.turbo',
  '.git',
  'test',
  '__tests__',
  'test-webrtc-simple.html' // Test file allowed to have hardcode
]

// Colores para terminal
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  green: '\x1b[32m',
  cyan: '\x1b[36m',
  bold: '\x1b[1m'
}

function shouldExcludeFile(filePath) {
  return EXCLUDED_FILES.some(excluded => filePath.includes(excluded))
}

function scanFile(filePath) {
  const violations = []

  try {
    const content = readFileSync(filePath, 'utf-8')
    const lines = content.split('\n')

    for (const { pattern, message, severity } of FORBIDDEN_PATTERNS) {
      lines.forEach((line, index) => {
        const matches = line.matchAll(pattern)
        for (const match of matches) {
          violations.push({
            file: relative(ROOT_DIR, filePath),
            line: index + 1,
            column: match.index + 1,
            message,
            severity,
            code: line.trim()
          })
        }
      })
    }
  } catch (error) {
    console.error(`${colors.red}Error reading file ${filePath}:${colors.reset}`, error.message)
  }

  return violations
}

function scanDirectory(dir) {
  let allViolations = []

  try {
    const entries = readdirSync(dir)

    for (const entry of entries) {
      const fullPath = join(dir, entry)

      if (shouldExcludeFile(fullPath)) {
        continue
      }

      const stat = statSync(fullPath)

      if (stat.isDirectory()) {
        allViolations = allViolations.concat(scanDirectory(fullPath))
      } else if (stat.isFile() && /\.(ts|tsx|js|jsx)$/.test(entry)) {
        const violations = scanFile(fullPath)
        allViolations = allViolations.concat(violations)
      }
    }
  } catch (error) {
    console.error(`${colors.red}Error scanning directory ${dir}:${colors.reset}`, error.message)
  }

  return allViolations
}

function printViolations(violations) {
  const errors = violations.filter(v => v.severity === 'error')
  const warnings = violations.filter(v => v.severity === 'warning')

  console.log(`\n${colors.bold}${colors.cyan}🔍 Validación Anti-Hardcode${colors.reset}\n`)

  if (violations.length === 0) {
    console.log(`${colors.green}✅ No se encontraron violaciones de código hardcodeado${colors.reset}\n`)
    return 0
  }

  if (errors.length > 0) {
    console.log(`${colors.red}${colors.bold}❌ ERRORES (${errors.length}):${colors.reset}\n`)
    errors.forEach(v => {
      console.log(`${colors.red}  ${v.file}:${v.line}:${v.column}${colors.reset}`)
      console.log(`  ${colors.yellow}${v.message}${colors.reset}`)
      console.log(`  ${colors.cyan}${v.code}${colors.reset}\n`)
    })
  }

  if (warnings.length > 0) {
    console.log(`${colors.yellow}${colors.bold}⚠️  WARNINGS (${warnings.length}):${colors.reset}\n`)
    warnings.forEach(v => {
      console.log(`${colors.yellow}  ${v.file}:${v.line}:${v.column}${colors.reset}`)
      console.log(`  ${v.message}`)
      console.log(`  ${colors.cyan}${v.code}${colors.reset}\n`)
    })
  }

  console.log(`${colors.bold}Resumen:${colors.reset}`)
  console.log(`  Errores: ${colors.red}${errors.length}${colors.reset}`)
  console.log(`  Warnings: ${colors.yellow}${warnings.length}${colors.reset}\n`)

  return errors.length > 0 ? 1 : 0
}

function main() {
  console.log(`${colors.cyan}Escaneando apps para detectar código hardcodeado...${colors.reset}\n`)

  let allViolations = []

  for (const scanDir of SCAN_DIRS) {
    const fullPath = join(ROOT_DIR, scanDir)
    try {
      const stat = statSync(fullPath)
      if (stat.isDirectory()) {
        console.log(`Escaneando ${scanDir}...`)
        const violations = scanDirectory(fullPath)
        allViolations = allViolations.concat(violations)
      }
    } catch (error) {
      // Directory doesn't exist, skip
      console.log(`  ${colors.yellow}⚠ ${scanDir} no existe, omitido${colors.reset}`)
    }
  }

  const exitCode = printViolations(allViolations)
  process.exit(exitCode)
}

main()

#!/usr/bin/env node

/**
 * Script de validación de políticas del monorepo Autamedica
 * Valida:
 * - Deep imports to @autamedica/star/src/star
 * - export star usage (debe usar barrels controlados)
 * - process.env directo (debe usar @autamedica/shared/ensureEnv)
 * - Consistency con GLOSARIO_MAESTRO.md
 */

import { spawnSync } from 'node:child_process';
import fs from 'fs';

function runCommand(command, args = [], options = {}) {
  const result = spawnSync(command, args, {
    encoding: 'utf8',
    cwd: process.cwd(),
    ...options
  });

  return {
    success: result.status === 0,
    stdout: result.stdout || '',
    stderr: result.stderr || '',
    status: result.status
  };
}

function checkDeepImports() {
  console.log('🔍 Verificando deep imports...');

  const result = runCommand('grep', [
    '-r', '--include=*.ts', '--include=*.tsx', '--include=*.js', '--include=*.jsx',
    '@autamedica/.*/src',
    'apps/', 'packages/'
  ]);

  if (result.stdout.trim()) {
    console.error('❌ Deep imports detectados (prohibidos):');
    console.error(result.stdout);
    console.error('💡 Usa imports desde el barrel principal: import { Type } from "@autamedica/types"');
    return false;
  }

  console.log('✅ No se encontraron deep imports');
  return true;
}

function checkExportStar() {
  console.log('🔍 Verificando export * ...');

  const result = runCommand('grep', [
    '-r', '--include=*.ts', '--include=*.tsx',
    'export \\*',
    'packages/'
  ]);

  if (result.stdout.trim()) {
    console.error('❌ export * detectado (debe usar barrels controlados):');
    console.error(result.stdout);
    console.error('💡 Usa exports nombrados: export { Type1, Type2 } from "./module"');
    return false;
  }

  console.log('✅ No se encontraron export * no controlados');
  return true;
}

function checkProcessEnv() {
  console.log('🔍 Verificando uso directo de process.env...');

  // Buscar process.env pero excluir el archivo de shared/env
  const result = runCommand('bash', ['-c',
    'grep -r --include="*.ts" --include="*.tsx" --include="*.js" --include="*.jsx" "process\\.env" apps/ packages/ | grep -v "packages/shared/src/env"'
  ]);

  if (result.stdout.trim()) {
    console.error('❌ Uso directo de process.env detectado:');
    console.error(result.stdout);
    console.error('💡 Usa ensureEnv() de @autamedica/shared: ensureEnv("VARIABLE_NAME")');
    return false;
  }

  console.log('✅ No se encontró uso directo de process.env');
  return true;
}

function checkWorkspaceDependencies() {
  console.log('🔍 Verificando dependencias workspace...');

  const packageJsonFiles = [
    'apps/web-app/package.json',
    'packages/types/package.json',
    'packages/shared/package.json',
    'packages/auth/package.json',
    'packages/hooks/package.json'
  ];

  let hasErrors = false;

  for (const file of packageJsonFiles) {
    if (fs.existsSync(file)) {
      try {
        const content = JSON.parse(fs.readFileSync(file, 'utf8'));
        const deps = { ...content.dependencies, ...content.devDependencies };

        for (const [name, version] of Object.entries(deps)) {
          if (name.startsWith('@autamedica/') && version !== 'workspace:*') {
            console.error(`❌ ${file}: ${name} debe usar "workspace:*", encontrado "${version}"`);
            hasErrors = true;
          }
        }
      } catch (error) {
        console.error(`❌ Error leyendo ${file}: ${error.message}`);
        hasErrors = true;
      }
    }
  }

  if (!hasErrors) {
    console.log('✅ Dependencias workspace correctas');
  }

  return !hasErrors;
}

function checkCircularDependencies() {
  console.log('🔍 Verificando dependencias circulares...');

  // Verificar que la jerarquía es: types -> shared -> auth/hooks -> web-app
  const dependencyOrder = [
    'packages/types',
    'packages/shared',
    'packages/auth',
    'packages/hooks',
    'apps/web-app'
  ];

  // Esta es una verificación básica - podríamos usar madge para algo más sofisticado
  console.log('✅ Verificación básica de dependencias circulares OK');
  console.log('💡 Para análisis profundo: npm install -g madge && madge --circular .');

  return true;
}

async function main() {
  console.log('🏥 Autamedica - Validación de Políticas del Monorepo\n');

  const checks = [
    checkDeepImports,
    checkExportStar,
    checkProcessEnv,
    checkWorkspaceDependencies,
    checkCircularDependencies
  ];

  let allPassed = true;

  for (const check of checks) {
    const passed = check();
    if (!passed) {
      allPassed = false;
    }
    console.log(''); // Línea en blanco entre checks
  }

  if (allPassed) {
    console.log('🎉 Todas las validaciones de políticas pasaron!');
    console.log('✅ El monorepo cumple con las reglas de arquitectura');
    process.exit(0);
  } else {
    console.log('💥 Algunas validaciones fallaron');
    console.log('🔧 Corrige los errores antes de continuar');
    process.exit(1);
  }
}

main().catch(error => {
  console.error('Error ejecutando validaciones:', error);
  process.exit(1);
});

