async function generateReport(results) {
  section('RESUMEN DE VERIFICACIÓN');

  const totalChecks = Object.keys(results).length;
  const passedChecks = Object.values(results).filter(r => r).length;
  const failedChecks = totalChecks - passedChecks;

  console.log('\nResultados:');
  console.log(`  Total de verificaciones: ${totalChecks}`);
  console.log(`  ${colors.green}✅ Exitosas: ${passedChecks}${colors.reset}`);
  console.log(`  ${colors.red}❌ Fallidas: ${failedChecks}${colors.reset}`);

  const percentage = ((passedChecks / totalChecks) * 100).toFixed(1);

  console.log(`\n${colors.bold}Porcentaje de éxito: ${percentage}%${colors.reset}`);

  if (percentage === '100.0') {
    success('\n🎉 SISTEMA COMPLETAMENTE FUNCIONAL');
    success('Todos los componentes están integrados correctamente');
  } else if (percentage >= '80.0') {
    warning('\n⚠️  Sistema funcional con advertencias menores');
  } else {
    error('\n❌ Se encontraron problemas críticos');
    error('Revisar los errores anteriores');
  }

  return percentage >= 80.0;
}

// Función principal
async function main() {
  log('\n' + '='.repeat(60), 'cyan');
  log('SCRIPT DE VERIFICACIÓN DE INTEGRACIÓN SUPABASE', 'bold');
  log('AltaMedica - Portal de Pacientes', 'cyan');
  log('='.repeat(60) + '\n', 'cyan');

  const results = {};

  try {
    // Cargar variables de entorno
    const envVars = loadEnvVars();

    if (!envVars.NEXT_PUBLIC_SUPABASE_URL || !envVars.NEXT_PUBLIC_SUPABASE_ANON_KEY) {
      error('Variables de entorno de Supabase no encontradas');
      process.exit(1);
    }

    success('Variables de entorno cargadas');

    // Crear cliente de Supabase
    const supabase = createClient(
      envVars.NEXT_PUBLIC_SUPABASE_URL,
      envVars.NEXT_PUBLIC_SUPABASE_ANON_KEY
    );

    // Ejecutar verificaciones
    results.connection = await verifySupabaseConnection(supabase);
    results.tables = await verifyTables(supabase);
    results.seedData = await verifySeedData(supabase);
    results.rls = await verifyRLS(supabase);
    results.hooks = await verifyHookFiles();
    results.integration = await verifyIntegration();
    results.dataFlow = await testDataFlow(supabase);

    // Generar reporte final
    const allPassed = await generateReport(results);

    process.exit(allPassed ? 0 : 1);

  } catch (err) {
    error(`\nError fatal: ${err.message}`);
    console.error(err);
    process.exit(1);
  }
}

// Ejecutar
main();

#!/usr/bin/env node

/**
 * 🔍 AutaMedica Visual Analyzer
 * Análisis avanzado de estado visual de las aplicaciones
 */

const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const APPS = [
  { name: 'web-app', url: 'http://localhost:3000', port: 3000 },
  { name: 'doctors', url: 'http://localhost:3001', port: 3001 },
  { name: 'patients', url: 'http://localhost:3002', port: 3002 },
  { name: 'companies', url: 'http://localhost:3003', port: 3003 }
];

async function analyzeVisualState() {
  console.log('🔍 Analizando estado visual de aplicaciones...\n');

  const browser = await chromium.launch({ headless: true });

  for (const app of APPS) {
    console.log(`📱 Analizando ${app.name} (${app.url})...`);

    try {
      // Verificar que el servidor esté corriendo
      const response = await fetch(app.url);
      if (!response.ok) {
        console.log(`  ⚠️  HTTP ${response.status} - Servidor con problemas`);
        continue;
      }

      const page = await browser.newPage({
        viewport: { width: 1920, height: 1080 }
      });

      await page.goto(app.url, { waitUntil: 'networkidle' });
      await page.waitForTimeout(2000);

      // Análisis de contenido
      const pageAnalysis = await page.evaluate(() => {
        const stats = {
          title: document.title,
          hasH1: !!document.querySelector('h1'),
          hasNavigation: !!document.querySelector('nav'),
          buttonCount: document.querySelectorAll('button').length,
          linkCount: document.querySelectorAll('a').length,
          imageCount: document.querySelectorAll('img').length,
          hasErrors: !!document.querySelector('.error, [class*="error"]'),
          textVisible: document.body.innerText.length > 0,
          backgroundColor: getComputedStyle(document.body).backgroundColor,
          hasLoader: !!document.querySelector('[class*="loading"], .spinner'),
          contentHeight: document.body.scrollHeight,
          viewport: {
            width: window.innerWidth,
            height: window.innerHeight
          }
        };

        // Verificar si hay elementos principales visibles
        const mainElements = document.querySelectorAll('main, [role="main"], .main-content');
        stats.hasMainContent = mainElements.length > 0;

        // Verificar colores de tema si es patients app
        if (window.location.port === '3002') {
          const themeButtons = document.querySelectorAll('[class*="theme"], [data-theme]');
          stats.themeButtonsCount = themeButtons.length;

          // Verificar si los elementos tienen color
          const coloredElements = document.querySelectorAll('[style*="color"], [class*="text-"]');
          stats.coloredElementsCount = coloredElements.length;
        }

        return stats;
      });

      // Mostrar análisis
      console.log(`  ✅ Cargado correctamente`);
      console.log(`  📄 Título: "${pageAnalysis.title}"`);
      console.log(`  🎨 Fondo: ${pageAnalysis.backgroundColor}`);
      console.log(`  📏 Contenido: ${pageAnalysis.contentHeight}px de alto`);
      console.log(`  🔗 Elementos: ${pageAnalysis.buttonCount} botones, ${pageAnalysis.linkCount} enlaces`);

      if (pageAnalysis.hasMainContent) {
        console.log(`  ✅ Contenido principal detectado`);
      } else {
        console.log(`  ⚠️  Sin contenido principal detectado`);
      }

      if (pageAnalysis.textVisible) {
        console.log(`  ✅ Texto visible en la página`);
      } else {
        console.log(`  ❌ Sin texto visible`);
      }

      if (app.name === 'patients') {
        console.log(`  🎨 Temas: ${pageAnalysis.themeButtonsCount} selectores de tema`);
        console.log(`  🌈 Elementos coloreados: ${pageAnalysis.coloredElementsCount}`);
      }

      if (pageAnalysis.hasErrors) {
        console.log(`  ❌ Errores detectados en la página`);
      }

      if (pageAnalysis.hasLoader) {
        console.log(`  🔄 Elementos de carga detectados`);
      }

      await page.close();

    } catch (error) {
      console.log(`  ❌ Error: ${error.message}`);
    }

    console.log(''); // Espacio entre apps
  }

  await browser.close();
  console.log('📊 Análisis visual completado');
}

async function quickHealthCheck() {
  console.log('⚡ Health Check Rápido...\n');

  const results = [];

  for (const app of APPS) {
    try {
      const start = Date.now();
      const response = await fetch(app.url);
      const loadTime = Date.now() - start;

      results.push({
        app: app.name,
        status: response.status,
        ok: response.ok,
        loadTime,
        url: app.url
      });

    } catch (error) {
      results.push({
        app: app.name,
        status: 'offline',
        ok: false,
        loadTime: 0,
        url: app.url,
        error: error.message
      });
    }
  }

  // Mostrar resultados
  results.forEach(result => {
    const statusIcon = result.ok ? '✅' : '❌';
    const status = result.ok ? `HTTP ${result.status}` : result.status;
    const timing = result.loadTime > 0 ? ` (${result.loadTime}ms)` : '';

    console.log(`${statusIcon} ${result.app}: ${status}${timing}`);

    if (!result.ok && result.error) {
      console.log(`   └─ Error: ${result.error}`);
    }
  });

  console.log('');
  return results;
}

// CLI Interface
const command = process.argv[2];

switch (command) {
  case 'analyze':
    analyzeVisualState();
    break;
  case 'health':
    quickHealthCheck();
    break;
  case 'full':
    quickHealthCheck().then(() => analyzeVisualState());
    break;
  default:
    console.log(`
🔍 AutaMedica Visual Analyzer

Comandos:
  health    # Health check rápido de servidores
  analyze   # Análisis detallado del contenido visual
  full      # Health check + análisis completo

Ejemplos:
  # Verificar que los servidores estén corriendo
  node visual-analyzer.js health

  # Análisis completo del contenido
  node visual-analyzer.js analyze

  # Todo junto
  node visual-analyzer.js full
`);
}

#!/usr/bin/env node

/**
 * Watch ~/.claude/agentic-config.json for changes and auto-sync agents
 * Útil para desarrollo: mantiene agentes sincronizados en tiempo real
 */

import { watch } from 'fs';
import { join } from 'path';
import { homedir } from 'os';
import { execSync } from 'child_process';

const CONFIG_PATH = join(homedir(), '.claude', 'agentic-config.json');

console.log('👀 Watching for changes in:', CONFIG_PATH);
console.log('🤖 Agents will auto-sync when config changes...\n');

let timeout;

watch(CONFIG_PATH, (eventType, filename) => {
  if (eventType === 'change') {
    // Debounce: wait 500ms after last change
    clearTimeout(timeout);
    timeout = setTimeout(() => {
      console.log('\n📝 Config changed, re-registering agents...');
      try {
        execSync('node scripts/register-claude-agents.mjs', {
          cwd: '/root/Autamedica',
          stdio: 'inherit'
        });
        // Mantener también agentes equivalentes para ChatGPT/OpenAI
        try {
          execSync('node scripts/register-openai-agents.mjs', {
            cwd: '/root/Autamedica',
            stdio: 'inherit'
          });
        } catch (e) {
          console.error('❌ Error syncing OpenAI agents:', e.message);
        }
        console.log('✅ Agents synchronized!\n');
        console.log('👀 Watching for more changes...');
      } catch (error) {
        console.error('❌ Error syncing agents:', error.message);
      }
    }, 500);
  }
});

console.log('Press Ctrl+C to stop watching...');

